window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[6] = [{"id":493,"category_id":6,"category_code":"s6","source_id":1,"title":"تبسم رسول","content":"روزى پيامبر اكرم صلى الله عليه و آله ، به طرف آسمان نگاه مى كرد، تبسمى نمود. شخصى به حضرت گفت: \r\nيا رسول الله ما ديديم به سوى آسمان نگاه كردى و لبخندى بر لبانت نقش بست ، علت آن چه بود؟\r\nرسول خدا فرمود:\r\n- آرى ! به آسمان نگاه مى كردم ، ديدم دو فرشته به زمين آمدند تا پاداش ‍ عبادت شبانه روزى بنده با ايمانى را كه هر روز در محل خود به عبادت و نماز مشغول مى شد، بنويسند؛ ولى او را در محل نماز خود نيافتند. او در بستر بيمارى افتاده بود\r\nفرشتگان به سوى آسمان بالا رفتند و به خداوند متعال عرض كردند:\r\nما طبق معمول براى نوشتن پاداش عبادت آن بنده با ايمان به محل نماز او رفتيم . ولى او را در محل نمازش نيافتيم ، زيرا در بستر بيمارى آرميده بود.\r\nخداوند به آن فرشتگان فرمود:\r\nتا او در بستر بيمارى است ، پاداشى را كه هر روز براى او هنگامى كه در محل نماز و عبادتش بود، مى نوشتيد، بنويسيد. بر من است كه پاداش ‍ اعمال نيك او را تا آن هنگام كه در بستر بيمارى است ، برايش در نظر بگيرم.\r\n"},{"id":494,"category_id":6,"category_code":"s6","source_id":2,"title":"رعایت نوبت","content":"روزى پيامبر صلى الله عليه و آله در حال استراحت بود، فرزندشان امام حسن عليه السلام آب خواست ، حضرت نيز قدرى شير دوشيد و كاسه شير را به دست وى داد، در اين حال ، حسين عليه السلام از جاى خود بلند شد تا شير را بگيرد، اما رسول خدا صلى الله عليه و آله شير را به حسن عليه السلام داد.\r\nحضرت فاطمه عليهاالسلام كه اين منظره را تماشا مى كرد عرض كرد:\r\nيا رسول الله ! گويا حسن را بيشتر دوست دارى ؟\r\nپاسخ دادند:\r\n- چنين نيست ، علت دفاع من از حسن عليه السلام حق تقدم اوست ، زيرا زودتر آب خواسته بود. بايد نوبت را مراعات نمود.\r\n"},{"id":495,"category_id":6,"category_code":"s6","source_id":3,"title":"گریه ی پیامبر","content":"رسول خدا صلى الله عليه و آله شبى در خانه همسرشان امّ سلمه بود. نيمه شب از خواب برخاست و در گوشه تاريكى مشغول دعا و گريه زارى شد.\r\nامّ سلمه كه جاى رسول خدا صلى الله عليه و آله را در رختخوابش ‍ خالى ديد، حركت كرد تا ايشان را بيابد. متوجه شد رسول اكرم صلى الله عليه و آله در گوشه خانه ، جاى تاريكى ايستاده و دست به سوى آسمان بلند كرده اند. در حال گريه مى فرمود:\r\nخدايا! آن نعمت هايى كه به من مرحمت نموده اى از من نگير!\r\nمرا مورد شماتت دشمنان قرار مده و حاسدانم را بر من مسلط مگردان! \r\nخدايا! مرا به سوى آن بديها و مكروههايى كه از آنها نجاتم داده اى برنگردان! \r\nخدايا! مرا هيچ وقت و هيچ آنى به خودم وامگذار و خودت مرا از همه چيز و از هر گونه آفتى نگهدار!\r\nدر اين هنگام ، امّ سلمه در حالى كه به شدت مى گريست به جاى خود برگشت . پيامبر صلى الله عليه و آله كه صداى گريه ايشان را شنيدند به طرف وى رفتند و علت گريه را جويا شدند.\r\nامّ سلمه گفت: \r\n- يا رسول الله ! گريه شما مرا گريان نموده است ، چرا مى گرييد؟ وقتى شما با آن مقام و منزلت كه نزد خدا داريد، اين گونه از خدا مى ترسيد و از خدا مى خواهيد لحظه اى حتى به اندازه يك چشم به هم زدن به خودتان وانگذارد، پس واى بر احوال ما!\r\nرسول خدا صلى الله عليه و آله فرمودند:\r\n- چگونه نترسم و چطور گريه نكنم و از عاقبت خود هراسان نباشم و به خودم و به مقام و منزلتم خاطر جمع باشم ، در حالى كه حضرت يونس ‍ عليه السلام راخداوند لحظه اى به خود واگذاشت و آمد بر سرش آنچه نمى بايست .\r\n"},{"id":496,"category_id":6,"category_code":"s6","source_id":4,"title":"حجاب","content":"امّ سلمه نقل مى كند:\r\nدر محضر پيامبر صلى الله عليه و آله بودم . يكى از همسرانش به نام ميمونه نيز آنجا بود. در اين هنگام ، ابن امّ مكتوم كه نابينا بود به حضور رسول خدا صلى الله عليه و آله آمد. پيامبر صلى الله عليه و آله به من و ميمونه فرمود:\r\n! حجاب خود را در برابر ابن مكتوم رعايت كنيد\r\nپرسيدم: \r\n اى رسول خدا! آيا او نابينا نيست ؟ بنابراين حجاب ما چه معنى دارد؟\r\nپيامبر صلى الله عليه و آله فرمود:\r\n آيا شما نابينا هستيد؟ آيا شما او را نمى بينيد؟\r\nزنان نيز بايد چشمانشان را از نامحرم ببندند.\r\n"},{"id":497,"category_id":6,"category_code":"s6","source_id":5,"title":"سفارش پیامبر","content":"شخصى محضر رسول خدا صلى الله عليه و آله وارد شد و از ايشان درخواست نمود تا به او توصيه اى بنمايند.\r\nحضرت اين گونه توصيه فرمودند:\r\n- من به تو سفارش مى كنم براى خدا شريك قرار ندهى ، اگر چه در آتش ‍ بسوزى و شكنجه ببينى! \r\nپدر و مادرت را نيز اذيت مكن و به آنان نيكى كن ، زنده باشند يا مرده . اگر دستور دهند كه از خانواده و زندگيت دست بردارى چنين كن ! و اين نشانه ايمان است . آنچه كه اضافه دارى در اختيار برادر دينى ات بگذار!\r\nدر برخورد با برادر مسلمانت گشاده رو باش! \r\nبه مردم اهانت مكن و باران رحمتت را بر آنان ببار!\r\nهر كدام از مسلمانان را ديدار كردى سلام برسان! \r\nمردم را به سوى اسلام دعوت كن! \r\nبدان كه هر كارگشايى تو ثواب بنده آزاد كردن را دارد، بنده اى كه از فرزندان يعقوب است.\r\nبدان كه شراب و تمام مست كننده ها حرامند.\r\n"},{"id":498,"category_id":6,"category_code":"s6","source_id":6,"title":"بی نیازی","content":"شخصى محضر رسول خدا صلى الله عليه و آله رسيد تا چيزى درخواست كند. شنيد كه پيامبر صلى الله عليه و آله مى فرمايد:\r\nهر كه از ما بخواهد به او مى دهيم و هر كه بى نيازى پيشه كند خدايش ‍ بى نياز كند. مرد بدون آنكه خواسته اش را اظهار كند، از محضر پيغمبر صلى الله عليه و آله بيرون آمد. بار دوم نزد پيامبر گرامى آمد و بى پرسش ‍ برگشت . تا سه بار چنين كرد. روز سوم رفت و تيشه اى به عاريت گرفت ، بالاى كوه رفت و هيزم گرد آورد و در بازار به نيم صاع جو (تقريبا يك كيلو و نيم ) فروخت و آن را خود با خانواده اش خوردند و اين كار را ادامه داد تا توانست تبر بخرد، سپس دو شتر جوان و يك برده هم خريد و توانگر شد. بعد، نزد پيامبر صلى الله عليه و آله آمد و به آن حضرت گزارش داد. پيامبر خدا صلى الله عليه و آله فرمود\r\n- نگفتم هر كه از ما خواهشى كند به او مى دهيم و اگر بى نيازى پيشه كند، خدايش توانگر سازد.\r\n"},{"id":499,"category_id":6,"category_code":"s6","source_id":7,"title":"بیت المال","content":"يكى از خصوصيات حضرت على عليه السلام اين بود كه بيت المال را به طور مساوى ميان مردم تقسيم مى كرد و بين مسلمانان تبعيض قايل نمى شد؛ اين امر باعث شده بود، برخى از طرفداران تبعيض و انحصار طلب ها به معاويه بپيوندند.\r\nعده اى از دوستان على عليه السلام به حضور حضرت رسيدند و گفتند:\r\n- چنانچه افراد سياس و انحصار طلبها را با پول راضى كنى ، براى پيشرفت امور شايسته تر است . امام على عليه السلام از اين پيشنهاد خشمگين شد و فرمود:\r\n- آيا نظرتان اين است به كسانى كه تحت حكومت من هستند ظلم كنم و حق آنان را به ديگران بدهم و با تضيع حقوق آنان يارانى دور خود جمع نمايم ؟ به خدا سوگند! تا دنيا وجود دارد و تا آفتاب مى تابد و ستارگان در آسمان مى درخشند، اين كار را نخواهم كرد. اگر مال ، از آن خودم بود آن را به طور مساوى تقسيم مى كردم ، چه رسد به اينكه مال ، مال خداست. \r\nسپس فرمود:\r\n- اى مردم ! كسى كه كار نيك را در جاى نادرست انجام داد، چند روزى نزد افراد نااهل و تاريك دل مورد ستايش قرار مى گيرد و در دل ايشان محبت و دوستى مى آفريند؛ ولى اگر روزى حادثه بدى براى وى پيش ‍ بيايد و به ياريشان نيازمند شود، آنان بدترين و سرزنش كننده ترين دوستان خواهند شد.\r\n"},{"id":500,"category_id":6,"category_code":"s6","source_id":8,"title":"غنیمت","content":"زاذان نقل مى كند:\r\nمن با قنبر غلام امام على عليه السلام محضر اميرالمؤ منين وارد شديم قنبر گفت: \r\nيا اميرالمؤ منين چيزى براى شما ذخيره كرده ام ! حضرت فرمود:\r\n آن چيست ؟\r\nعرض كرد: تعدادى ظرف طلا و نقره ! چون ديدم تمام اموال غنائم را تقسيم كردى و از آنها براى خود بر نداشتى ! من اين ظرف ها را براى شما ذخيره كرده ام. \r\nحضرت على عليه السلام شمشير خود را كشيد و به قنبر فرمود:\r\n- واى بر تو! دوست دارى كه به خانه ام آتش بياورى ! خانه ام را بسوزانى ! سپس آن ظرف ها را قطعه قطعه كرد و نمايندگان قبايل را طلبيد، و آنها را به آنان داد، تا عادلانه بين مردم تقسيم كنند.\r\n"},{"id":501,"category_id":6,"category_code":"s6","source_id":9,"title":"شجاعت علی(ع)","content":"ابووائل نقل مى كند، روزى همراه عمربن خطاب بودم ، عمر برگشت ترسناك به عقب نگاه كرد.\r\nگفتم : چرا ترسيدى ؟\r\nگفت: \r\n- واى بر تو! مگر شير درنده ، انسان بخشنده ، شكافنده صفوف شجاعان و كوبنده طغيان گران و ستم پيشگان را نمى بينى ؟\r\nگفتم: \r\n. او على بن ابى طالب است\r\nگفت: \r\n- شما او را به خوبى نشناخته اى ! نزديك بيا از شجاعت و قهرمانى على براى تو بگويم ، نزديك رفتم ، گفت: \r\n- در جنگ احد، با پيامبر پيمان بستيم كه فرار نكنيم و هر كس از ما فرار كند، او گمراه است و هر كدام از ما كشته شود، او شهيد است و پيامبر صلى الله عليه و آله سرپرست اوست . هنگامى كه آتش جنگ ، شعله ور شد، هر دو لشكر به يكديگر هجوم بردند ناگهان ! صد فرمانده دلاور، كه هر كدام صد نفر جنگجو در اختيار داشتند، دسته دسته به ما حمله كردند، به طورى كه توان جنگى را از دست داديم و با كمال آشفتگى از ميدان فرار كرديم . در ميان جنگ تنها ايشان ماند. ناگاه ! على را ديدم ، كه مانند شير پنجه افكن ، راه را بر ما بست ، مقدارى ماسه از زمين بر داشت به صورت ما پاشيد، چشمان همه ما از ماسه صدمه ديد، خشمگينانه فرياد زد! زشت و سياه باد، روى شما به كجا فرار مى كنيد؟ آيا به سوى جهنم مى گريزيد؟\r\nما به ميدان برنگشتيم . بار ديگر بر ما حمله كرد و اين بار در دستش ‍ اسلحه بود كه از آن خون مى چكيد! فرياد زد:\r\n- شما بيعت كرديد و بيعت را شكستيد، سوگند به خدا! شما سزاوارتر از كافران به كشته شدن هستيد.\r\nبه چشم هايش نگاه كردم ، گويى مانند دو مشعل زيتون بودند كه آتش از آن شعله مى كشيد و يا شبيه ، دو پياله پر از خون . يقين كردم به طرف ما مى آيد و همه ما را مى كشد! من از همه اصحاب زودتر به سويش شتافتم و گفتم: \r\n- اى ابوالحسن ! خدا را! خدا را! عرب ها در جنگ گاهى فرار مى كنند و گاهى حمله مى آورند، و حمله جديد، خسارت فرار را جبران مى كند.\r\nگويا خود را كنترل كرد و چهره اش را از من برگردانيد. از آن وقت تاكنون همواره آن وحشتى كه آن روز از هيبت على عليه السلام بر دلم نشسته ، هرگز فراموش نكرده ام.\r\n"},{"id":502,"category_id":6,"category_code":"s6","source_id":10,"title":"سوال و جواب","content":"زنى خدمت حضرت فاطمه عليهاالسلام رسيد و گفت: \r\n- مادر ناتوانى دارم كه در مسائل نمازش به مساءله مشكلى برخورد كرده و مرا خدمت شما فرستاد كه سؤ ال كنم. \r\nحضرت فاطمه عليهاالسلام جواب آن مساءله را داد. آن زن همين طور مساءله ديگرى پرسيد تا ده مساءله شد. حضرت همه را پاسخ داد. سپس ‍ آن زن از كثرت سؤ ال خجالت كشيد و عرض كرد:\r\n اى دختر رسول خدا! ديگر مزاحم نمى شوم \r\nحضرت فرمود: نگران نباش ! باز هم سؤ ال كن ! با كمال ميل جواب مى دهم ، زيرا اگر كسى اجير شود كه بار سنگينى را بر بام حمل كند و در عوض آن ، مبلغ صد هزار دينار اجرت بگيرد، آيا از حمل بار خسته مى شود؟\r\nزن گفت: \r\n- نه ! خسته نمى شود، زيرا در برابر آن مزد زيادى دريافت مى كند\r\nحضرت فرمود:\r\n- خدا در برابر جواب هر مساءله اى بيشتر از اينكه بين زمين و آسمان پر از مرواريد باشد، به من ثواب مى دهد! با اين حال ، چگونه از جواب دادن به مساءله خسته شوم ؟ از پدرم شنيدم كه فرمود:\r\nعلماى شيعه من روز قيامت محشور مى شوند، و خداوند به اندازه علوم آنان و درجات كوششان در راه هدايت مردم ، برايشان ثواب و پاداش در نظر مى گيرد و به هر كدامشان تعداد يك ميليون حله از نور عطا مى كند. سپس منادى حق تعالى ندا مى كند: اى كسانى كه يتيمان (پيروان ) آل محمد را سرپرستى نموديد، در آن وقت كه دستشان به اجدادشان (پيشوايان دين ) نمى رسيد، كه در پرتو علوم شما ارشاد شدند و ديندار زندگى كردند. اكنون به اندازه اى كه از علوم شما استفاده كرده اند، به ايشان خلعت بدهيد!\r\nحتى به بعضى آنان صد هزار خلعت داده مى شود. پس از تقسيم خلعت ها، خداوند فرمان مى دهد: بار ديگر به علما خلعت بدهيد. تا خلعتشان تكميل گردد.\r\nسپس دستور مى رسد دو برابرش كنيد همچنين درباره شاگردان علما كه خود شاگرد تربيت كرده اند چنين كنيد...\r\nآنگاه حضرت فاطمه به آن زن فرمود:\r\nاى بنده خدا! يك نخ از اين خلعتها هزار هزار مرتبه از آنچه خورشيد بر آن مى تابد بهتر است . زيرا امور دنيوى تواءم با رنج و مشقت است اما نعمتهاى اخروى عيب و نقص ندارد.\r\n"},{"id":503,"category_id":6,"category_code":"s6","source_id":11,"title":"برتری علمی حضرت فاطمه(س)","content":"دو نفر زن ، كه يكى مؤمن و ديگرى از دشمنان اسلام بود، در مطلبى دينى با هم اختلاف نظر داشتند.\r\nبراى حل اختلاف ، محضر حضرت فاطمه عليهاالسلام رسيدند و موضوع را طرح كردند.\r\nچون حق با زن مؤ من بود، حضرت فاطمه عليهاالسلام گفتارش را با دليل و برهان تاءييد كرد و بدين وسيله زن مؤ من بر زن دشمن پيروز گشت و از اين پيروزى خوشحال شد.\r\nحضرت فاطمه عليهاالسلام به زن مؤ من فرمود:\r\nفرشتگان خدا بيشتر از تو شادمان گشتند و غم و اندوه شيطان و پيروانش ‍ نيز بيشتر از غم و اندوه زن دشمن مى باشد.\r\nامام حسن عسكرى عليه السلام مى فرمايد:\r\nدر عوض خدمتى كه فاطمه به اين زن مؤ من كرد، بهشت و نعمت هاى بهشتى اش را هزار هزار برابر آنچه قبلا تعيين شده بود، قرار دهيد و همين روش را درباره هر دانشمندى كه با علمش مؤ منى را تقويت كند - كه بر معاندى پيروز گردد - مراعات كنيد و ثوابش را هزار هزار برابر قرار دهيد!\r\n"},{"id":504,"category_id":6,"category_code":"s6","source_id":12,"title":"الجار ثم الدار!","content":"امام حسن عليه السلام مى فرمايد:\r\nمادرم زهرا عليهاالسلام را در شب جمعه ديدم تا سپيده صبح مشغول عبادت و ركوع و سجود بود و مؤ منين را يك يك نام مى برد و دعا مى كرد، اما براى خودش دعا نكرد عرض كردم: \r\n- مادر جان چرا براى خودتان دعا نمى كنيد؟\r\nفرمودند:\r\n(الجار ثم الدار) فرزندم اول همسايه ، بعد خويشتن \r\n"},{"id":505,"category_id":6,"category_code":"s6","source_id":13,"title":"خنده و گريه فاطمه عليهاالسلام","content":"عايشه - همسر پيامبر صلى الله عليه و آله وسلم - اظهار مى كند:\r\nفاطمه شبيه تر از هر كسى به رسول خدا صلى الله عليه و آله وسلم بود. هنگامى كه به حضور پيامبر صلى الله عليه و آله وسلم مى رسيد، حضرت با آغوش باز از او استقبال مى كرد و دست هايش را مى گرفت و در كنار خود مى نشاند، و هرگاه پيامبر صلى الله عليه و آله وسلم بر فاطمه عليهاالسلام وارد مى شد، ايشان برمى خاست و دست هاى حضرت را با اشتياق مى بوسيد.\r\nآن زمان كه رسول خدا صلى الله عليه و آله وسلم در بستر مرگ آرميده بود، فاطمه عليهاالسلام را به طور خصوصى پيش خود خواند، و آهسته با وى سخن گفت ، كمى بعد فاطمه عليهاالسلام را ديدم كه گريه مى كرد! سپس پيامبر صلى الله عليه و آله وسلم بار ديگر با او آهسته صحبت كرد. اين بار، فاطمه عليهاالسلام خنديد! با خود گفتم: \r\nاين نيز يكى از برترى هاى فاطمه عليهاالسلام بر ديگران است كه هنگام گريه و ناراحتى توانست بخندد.\r\nعلت را از فاطمه عليهاالسلام پرسيدم ، فرمود:\r\n- در اين صورت اسرار را فاش ساخته ام و فاش كردن اسرار ناپسند است \r\nپس از آنكه پيامبر صلى الله عليه و آله و سلم رحلت كرد، به فاطمه عليهاالسلام عرض كردم \r\n- علت گريه و سبب خنده شما در آن روز چه بود؟\r\nدر پاسخ فرمود:\r\n- آن روز، پيامبر صلى الله عليه و آله وسلم نخست به من خبر داد كه از دنيا مى رود، گريه كردم ! سپس به من فرمود: تو اولين كسى هستى كه از اهل بيتم به من مى پيوندى ، لذا شاد شدم و خنديدم.\r\n"},{"id":506,"category_id":6,"category_code":"s6","source_id":14,"title":"شجاع تر از پسر على عليه السلام","content":"در جنگ جمل ، حضرت على عليه السلام فرزندش محمد حنفيه را طلبيد و نيزه خود را به او داد و فرمود:\r\n! با اين نيزه به سپاه دشمن حمله كن\r\nمحمد حنيفه نيزه را گرفت و به دشمن حمله كرد، گروهى از سپاه دشمن جلوى او را گرفتند، او نتوانست پيش روى كند، به عقب برگشت و به خدمت پدر رسيد. در اين هنگام ، امام حسن عليه السلام نيزه را گرفت و به سوى دشمن شتافت . پس از مدتى ، با نيزه اى خون آلود نزد پدر آمد. هنگامى كه محمد حنفيه آن شجاعت را از امام عليه السلام مشاهده كرد، بر اثر احساس شكست ، سرخ و سرافكنده شد. حضرت على عليه السلام به او فرمود:\r\n ناراحت نباش ! او پسر پيامبر و تو پسر على هستى \r\n"},{"id":507,"category_id":6,"category_code":"s6","source_id":15,"title":"حمايت از حيوانات","content":"روزى امام حسن عليه السلام حين غذا خوردن ، جلوى سگى كه در نزديكى ايشان ايستاده بود، چند لقمه غذا انداخت. \r\nكسى پرسيد:\r\n يابن رسول الله ! اجازه مى دهيد سگ را دور كنم ؟\r\nحضرت فرمود:\r\n! به حيوان كارى نداشته باش \r\nمن از خدايم حيا مى كنم كه جاندارى نگاه به غذاى من كند و من غذايش ندهم و برانمش\r\n"},{"id":508,"category_id":6,"category_code":"s6","source_id":16,"title":"عزادار حسین","content":"هنگامى كه پيامبر صلى الله عليه و آله وسلم شهادت حسين عليه السلام و ساير مصيبت هاى او را به دختر خود، خبر داد؛ فاطمه عليهاالسلام سخت گريه نمود و عرض كرد:\r\n پدر جان ! اين گرفتارى چه زمانى رخ مى دهد؟\r\nرسول خدا فرمود:\r\n. زمانى كه من و تو و على در دنيا نباشيم \r\nآن گاه گريه فاطمه شديدتر شد. عرض كرد.\r\n- چه كسى بر حسينم گريه مى كند، و به عزادارى او قيام مى نمايد؟\r\nپيامبر فرمود:\r\n- فاطمه ! زنان امتم بر زنان اهل بيتم ، و مردان بر مردان گريه مى كنند و در هر سال ، عزادارى او را تجديد مى كنند. روز قيامت كه فرا رسد، تو براى زنان شفاعت مى كنى و من براى مردان ، و هر كه بر گرفتارى حسين گريه كند، دست او را مى گيريم و داخل بهشت مى كنيم . فاطمه جان ! تمام ديده ها روز قيامت گريان است ، مگر چشمى كه بر مصيبت حسين گريه كند! آن چشم براى رسيدن به نعمت هاى بهشت خندان است .\r\n"},{"id":509,"category_id":6,"category_code":"s6","source_id":17,"title":"نسخه اى براى گناه كردن","content":"مردى خدمت امام حسين عليه السلام رسيد، و عرض كرد كه شخص ‍ گنه كارى هستم و نمى توانم خود را از معصيت نگهدارم ، لذا نيازمند نصايح آن حضرت مى باشم . امام عليه السلام فرمودند:\r\nپنج كار را انجام بده ، بعد هر گناهى مى خواهى بكن \r\nاول : روزى خدا را نخور، هر گناهى مايلى بكن \r\nدوم : از ولايت خدا خارج شو، هر گناهى مى خواهى بكن \r\nسوم : جايى را پيدا كن كه خدا تو را نبيند، سپس هر گناهى مى خواهى بكن \r\nچهارم : وقتى ملك الموت براى قبض روح تو آمد اگر توانستى او را از خودت دور كن و بعد هر گناهى مى خواهى بكن \r\nپنجم : وقتى مالك دوزخ تو را داخل جهنم كرد، اگر امكان داشت داخل نشو و آن گاه هر گناهى مايلى انجام بده.\r\n"},{"id":510,"category_id":6,"category_code":"s6","source_id":18,"title":"وفای یاران","content":"در شب عاشورا اصحاب باوفاى امام حسين عليه السلام هر كدام با زبانى ، وفادارى خود را اعلام كردند. به محمد بن بشر خضرمى - يكى از ياران ايشان تازه خبر رسيد كه پسرش در مرز رى به دست كافران اسير شده است ، محمد گفت: \r\n- اجر و ثواب خود و پسرم را از خداوند مى خواهم . من دوست ندارم كه پسرم گرفتار باشد و من بعد از او زنده بمانم! \r\nامام حسين عليه السلام كه سخن او را شنيد، فرمود:\r\n- بيعتم را از تو برداشتم . آزادى ، برو براى آزادى پسرت كوشش كن \r\nمحمد بن بشر گفت: \r\n- درندگان مرا بدرند و زنده بخورند، اگر از تو جدا گردم \r\nامام حسين عليه السلام پنج لباس برد يمانى - كه قيمت آنها هزار دينار بود - به او داد و فرمود:\r\n- اينها را به پسرت ديگرت بده تا با دادن اين لباس ها به دشمن (به عنوان هديه ) برادرش را از اسارت آزاد سازد.\r\n"},{"id":511,"category_id":6,"category_code":"s6","source_id":19,"title":"عاقبت ابن زياد","content":"ابراهيم (پسر مالك اشتر) سرهاى بريده ابن زياد و سران دشمن را براى مختار فرستاد. مختار در حال غذا خوردن بود كه سرهاى بريده دشمنان را در كنار وى به زمين ريختند.\r\nمختار گفت: \r\n- سر مقدس حسين عليه السلام را هنگامى كه ابن زياد غذا مى خورد نزدش آوردند، اكنون حمد و سپاس خداوند را كه سر نحس ابن زياد در هنگام غذا خوردن نزد من آورده شده است! \r\nدر اين هنگام ، مار سفيدى در ميان سرها پيدا شد و درون سوراخ بينى ابن زياد رفت و از سوراخ گوش او بيرون آمد، و اين عمل چندين بار تكرار شد!\r\nمختار پس از صرف غذا برخاست و با كفشى كه در پايش بود به صورت نحس ابن زياد زد، سپس كفشش را نزد غلامش انداخت و گفت: \r\n- اين كفش را بشوى كه آن را بر صورت كافرى نجس نهادم \r\nمختار سرهاى نحس دشمنان را براى محمد حنفيه در حجاز فرستاد.\r\nمحمد حنفيه نيز سر ابن زياد را نزد امام سجاد عليه السلام فرستاد، امام عليه السلام در آن هنگام مشغول غذا خوردن بودند، فرمودند:\r\n- روزى كه سر مقدس پدرم را نزد ابن زياد آوردند او غذا مى خورد. از خداوند خواستم ، مرا زنده نگهدارد تا سر بريده ابن زياد را در كنار سفره غذا بنگرم . خداوند را سپاس كه اكنون دعايم مستجاب شد.\r\n"},{"id":512,"category_id":6,"category_code":"s6","source_id":20,"title":"طلب روزی حلال","content":"امام زين العابدين عليه السلام سحرگاه در طلب روزى از منزل خارج شد، عرض كردند:\r\n يابن رسول الله ! كجا مى رويد؟\r\nفرمود:\r\n- از منزل بيرون آمدم تا براى خانواده ام صدقه اى بدهم \r\nعرض كردند:\r\n- چطور به خانواده تان صدقه مى دهيد؟\r\nفرمود:\r\n- هركس از راه حلال روزى را به دست آورد (و براى خانواده خود خرج نمايد) در پيشگاه خداوند براى او صدقه محسوب مى شود!\r\n"},{"id":513,"category_id":6,"category_code":"s6","source_id":21,"title":"رهسپار آخرت","content":"زهرى مى گويد:\r\nدر شبى تاريك و سرد، على بن حسين عليه السلام را ديدم كه مقدارى آذوقه به دوش گرفته ، مى رود. عرض كردم: \r\n- يابن رسول الله ! اين چيست ، به كجا مى بريد؟\r\nحضرت فرمودند:\r\n- زهرى ! من مسافرم . اين توشه سفر من است . مى برم در جاى محفوظى بگذارم (تا هنگام مسافرت دست خالى و بى توشه نباشم!) \r\nگفتم: \r\n- يابن رسول الله ! اين غلام من است ، اجازه بفرما اين بار را به دوش ‍ بگيرد و هر جا مى خواهى ببرد.\r\nفرمودند:\r\n- تو را به خدا بگذار من خودم بار خود را ببرم ، تو راه خود را بگير و برو با من كارى نداشته باش! \r\nزهرى بعد از چند روز حضرت را ديد، عرض كرد:\r\n- يابن رسول الله ! من از آن سفرى كه آن شب درباره اش سخن مى گفتى ، اثرى نديدم \r\nفرمود:\r\n- سفر آخرت را مى گفتم و سفر مرگ نظرم بود كه براى آن آماده مى شدم \r\nسپس آن حضرت هدف خود را از بردن آن توشه در شب به خانه هاى نيازمندان توضيح داد و فرمود:\r\nآمادگى براى مرگ با دورى جستن از حرام و خيرات دادن به دست مى آيد\r\n"},{"id":514,"category_id":6,"category_code":"s6","source_id":22,"title":"شوخی با نامحرم","content":"ابوبصير رحمة الله مى گويد:\r\nدر كوفه بودم ، به يكى از بانوان درس قرائت قرآن مى آموختم . روزى در يك موردى با او شوخى كردم! \r\nمدت ها گذشت تا اينكه در مدينه به حضور امام باقر عليه السلام رسيدم . آن حضرت مرا مورد سرزنش قرار داد و فرمود:\r\n- كسى كه در حال خلوت گناه كند، خداوند نظر لطفش را از او برمى گرداند، اين چه سخنى بود كه به آن زن گفتى ؟\r\nاز شدت شرم ، سرم را پايين انداخته و توبه نمودم . امام باقر عليه السلام فرمود:\r\n. مراقب باش كه تكرار نكنى\r\n"},{"id":515,"category_id":6,"category_code":"s6","source_id":23,"title":"سفارشات امام باقر","content":"جابر جعفى نقل مى كند:\r\nبعد از خاتمه اعمال حج ، با جمعى به خدمت امام محمد باقر عليه السلام رسيديم . هنگامى كه خواستيم با حضرت وداع كنيم ، عرض ‍ كرديم توصيه اى بفرمايند!\r\nاظهار داشتند:\r\n-! اقوياى شما به ضعفا كمك كنند\r\nاغنيا از فقرا دلجويى نمايند!\r\nهر يك از شما خير خواه برادر دينى اش باشد. و آنچه براى خود مى خواهد براى او نيز بخواهد!\r\nاسرار ما را از نااهلان مخفى داريد، و مردم را بر ما مسلط نكنيد!\r\nبه گفته هاى ما و آنچه از ما به شما مى رسانند توجه كنيد؛ اگر ديديد موافق قرآن است ، آن را بپذيريد و چنانچه آن را موافق قرآن نيافتيد، بر زمين بياندازيد\r\nاگر مطلبى بر شما مشتبه شد، درباره آن تصميمى نگيريد و آن را به ما عرضه داريد تا آن طور كه لازم است براى شما تشريح كنيم. \r\nاگر شما چنين بوديد كه توصيه شد و از اين حدود تجاوز نكرديد و پيش ‍ از زمان قائم ما كسى از شما بميرد، شهيد از دنيا رفته است . هر كس قائم ما را درك كند و در ركاب او كشته شود، ثواب دو شهيد دارد و هر كس در ركاب او يكى از دشمنان ما را به قتل برساند، ثواب بيست شهيد خواهد داشت .\r\n"},{"id":516,"category_id":6,"category_code":"s6","source_id":24,"title":"ملاقات امام زمان(ع)","content":"عبدالحميد واسطى نقل مى كند، به امام محمد باقر عليه السلام عرض ‍ كردم: \r\nبه خدا قسم دكان هاى خود را به انتظار ظهور امام زمان (عج ) رها كرديم ، تا جايى كه اكنون چيزى نمانده از فقر و بيچارگى ، دست گدايى پيش مردم دراز كنيم! \r\nفرمود:\r\n اين عبدالحميد! آيا گمان مى كنى اگر كسى خود را وقف راه خدا كند، خداوند راه روزى را به روى او نمى گشايد؟ والله ! خداوند در رحمت خود را به روى او خواهد گشود\r\nرحمت خدا بر كسى كه خود را در اختيار ما گذاشته و ما را و امر ما را زنده نگه مى دارد\r\nعرض كردم: \r\n اگر من پيش از آنكه به ملاقات قائم شما مشرف گردم ، بميرم ، چگونه خواهم بود؟\r\nفرمود: هر كدام از شما كه مى گويد\r\nاگر قائم آل محمد (عج ) را ببينم به يارى او بر مى خيزم ، مانند كسى است كه در ركاب او شمشير بزند و كسى كه در ركاب وى شهيد گردد، مثل اين است كه دوبار شهيد شده است.\r\n"},{"id":517,"category_id":6,"category_code":"s6","source_id":25,"title":"نوشته ی سبز رنگ","content":"مردى از بزرگان جبل هر سال به زيارت مكه مشرف مى شد و هنگام برگشت در مدينه محضر امام صادق عليه السلام مى رسيد.\r\nيك بار قبل از تشرف به حج ، خدمت امام عليه السلام رسيد و ده هزار درهم به ايشان داد و گفت: \r\n. تقاضا دارم با اين مبلغ خانه اى برايم خريدارى نماييد\r\nسپس به قصد زيارت مكه معظمه از محضر امام عليه السلام خارج شد.\r\nپس از انجام مراسم حج ، خدمت امام صادق عليه السلام رسيد و حضرت او را در خانه خود جاى داد و نوشته اى به او مرحمت نمود و فرمود:\r\n- خانه اى در بهشت برايت خريدم كه حد اول آن به خانه محمد مصطفى صلى الله عليه و آله وسلم ، حد دومش به خانه على عليه السلام ، حد سوم به خانه حسن مجتبى عليه السلام و حد چهارم آن به خانه حسين بن على عليه السلام متصل است. \r\nمرد كه اين سخن را از امام شنيد، قبول كرد.\r\nحضرت آن مبلغ را ميان فقرا و نيازمندان از فرزندان امام حسن عليه السلام و امام حسين عليه السلام تقسيم كردند و مرد جبلى به وطن خود بازگشت. \r\nچون مدتى گذشت ، آن مرد مريض شد و بستگان خود را احضار نموده ، گفت: \r\n- من مى دانم آنچه امام صادق عليه السلام فرمود، حقيقت دارد. خواهش مى كنم اين نوشته را با من دفن كنيد!\r\nپس از مدت كوتاهى از دنيا رفت و بنابر وصيتش آن نوشته را با او دفن كردند. روز ديگر كه آمدند، ديدند مكتوبى با خط سبز روى قبر اوست كه در آن نوشته به خدا سوگند! جعفر بن محمد به آنچه وعده داده بود وفا نمود!\r\n"},{"id":518,"category_id":6,"category_code":"s6","source_id":26,"title":"یاری یکدیگر","content":"امام موسى بن جعفر عليه السلام فرمود:\r\n اى عاصم ! چگونه به يكديگر رسيدگى و به هم كمك مى كنيد؟\r\nعرض كرد:\r\n- به بهترين وجهى كه ممكن است مردم به حال يكديگر برسند\r\nفرمود:\r\n- اگر يكى از شما تنگدست شود و بيايد خانه برادر مؤ منش و او در منزل نباشد، آيا مى تواند بدون اعتراض كسى دستور دهد كيسه پول ايشان را بياورند و سر كيسه را باز كند و هر چه لازم داشت بردارد؟\r\nعرض كرد: نه ! اين طور نيست \r\nفرمود: پس آن طور كه من دوست دارم شما هنگام فقر و تنگدستى به هم رسيدگى و كمك نمى كنيد.\r\n"},{"id":519,"category_id":6,"category_code":"s6","source_id":27,"title":"امام و شراب!","content":"هارون پسر جهم نقل مى كند:\r\nيكى از سران سپاه منصور پسر خود را ختنه كرده بود.اوعده زيادى از اعيان و اشراف را براى وليمه دعوت كرد. امام صادق عليه السلام نيز از جمله دعوت شدگان بودند. سفره آماده شد و مهمانان بر سر سفره نشستند و مشغول غذا شدند. در اين ميان ، يكى از مهمانان آب خواست . به جاى آب ، جامى از شراب به دستش دادند. جام كه به دست او داده شد، فورا امام صادق عليه السلام نيمه كاره از سر سفره حركت كرد و از مجلس بيرون رفت . هر چه خواستند امام را دوباره برگردانند، برنگشت \r\nفرمود:\r\nاز رحمت الهى بدور و ملعون است آن كس كه بر كنار سفره اى بنشيند كه در آن شراب باشد.\r\n"},{"id":520,"category_id":6,"category_code":"s6","source_id":28,"title":"شمش طلا","content":"گروهى از اصحاب امام صادق عليه السلام خدمت حضرت نشسته بودند كه ايشان فرمودند:\r\n- خزانه هاى زمين و كليدهايش در نزد ماست ، اگر با يكى از دو پاى خود به زمين اشاره كنم ، هر آينه زمين آنچه را از طلا و گنج ها در خود پنهان داشته ، بيرون خواهد ريخت! \r\nبعد، با پايشان خطى بر زمين كشيدند. زمين شكافته شد، حضرت دست برده قطعه طلايى را كه يك وجب طول داشت ، بيرون آوردند!\r\nسپس فرمودند:\r\n! خوب در شكاف زمين بنگريد\r\nاصحاب چون نگريستند، قطعاتى از طلا را ديدند كه روى هم انباشته شده و مانند خورشيد مى درخشيدند.\r\nيكى از اصحاب ايشان عرض كرد:\r\n- يا بن رسول الله ! خداوند تبارك و تعالى اين گونه به شما از مال دنيا عطا كرده ، و حال آنكه شيعيان و دوستان شما اين چنين تهيدست و نيازمند؟\r\nحضرت در جواب فرمودند:\r\n- براى ما و شيعيان ما خداوند دنيا و آخرت را جمع نموده است . ولايت ما خاندان اهلبيت بزرگترين سرمايه است ، ما و دوستانمان داخل بهشت خواهيم شد و دشمنانمان راهى دوزخ خواهند گشت.\r\n"},{"id":521,"category_id":6,"category_code":"s6","source_id":29,"title":"انسان نماها","content":"ابوبصير يكى از شيعيان پاك و مخلص امام صادق عليه السلام مى گويد:\r\nمن با آن حضرت در مراسم حج شركت نمودم. \r\nهنگامى كه به همراه امام عليه السلام كعبه را طواف مى كرديم ، عرض ‍ كردم: \r\n فدايت شوم ، آيا خداوند اين جمعيت بسيار را كه در حج شركت نموده اند مى آمرزد؟\r\nامام صادق عليه السلام فرمود:\r\n-! اى ابا بصير! بسيارى از اين جمعيت كه مى بينى ، ميمون و خوك هستند\r\nعرض كردم: \r\n- آنها را به من نشان بده \r\nآن حضرت دستى بر چشمان من كشيد و كلماتى به زبان جارى نمود. ناگهان ! بسيارى از آن جمعيت را ميمون و خوك ديدم ، وحشت كردم ! سپس بار ديگر دستش را بر چشمان من كشيد، آن گاه دوباره آنان را همان گونه كه در ظاهر بودند ديدم . سپس فرمود:\r\n- اى ابا بصير! نگران مباش ! شما در بهشت ، شادمان هستيد و طبقات دوزخ جاى شما نيست. \r\nسوگند به خدا! سه نفر، بلكه دو نفر، بلكه يك نفر از شما شيعيان حقيقى در آتش دوزخ نخواهد بود.\r\n"},{"id":522,"category_id":6,"category_code":"s6","source_id":30,"title":"تجارت حلال","content":"روزى جوانى به حضور امام صادق عليه السلام آمد و عرض كرد:\r\n. سرمايه ندارم \r\nامام عليه السلام فرمود: درستكار باش ! خداوند روزى را مى رساند.\r\nجوان بيرون آمد. در راه ، كيسه اى پيدا كرد. هفتصد دينار در آن بود. با خود گفت : بايد سفارش امام عليه السلام را عمل نمايم ، لذا من به همه اعلام مى كنم كه اگر هميانى گم كرده اند نزد من آيند.\r\nبا صداى بلند گفت: \r\nهر كس كيسه اى گم كرده ، بيايد نشانه اش را بگويد و آن را ببرد.\r\nفردى آمد و نشانه هاى كيسه را گفت ، كيسه اش را گرفت و هفتاد دينار به رضايت خود به آن جوان داد. \r\nجوان برگشت به حضور حضرت ، قضيه را گفت. \r\nحضرت فرمود:\r\n- اين هفتاد دينار حلال بهتر است از آن هفتصد دينار حرام و آن را خدا به تو رساند. جوان با آن پول تجارت كرد و بسيار غنى شد.\r\n"},{"id":523,"category_id":6,"category_code":"s6","source_id":31,"title":"نان به نرخ روز","content":"امام صادق عليه السلام به معتب مسؤول خرج خانه خود فرمود:\r\n معتب اجناس در حال گران شدن است ما امسال در خانه چه مقدار خوراكى داريم ؟\r\n- معتب : عرض كردم \r\n- به قدرى كه چندين ماه را كفايت كند گندم ذخيره داريم \r\n-! آنها را به بازار ببر و در اختيار مردم بگذار و بفروش \r\n- يابن رسول الله ! گندم در مدينه ناياب است ، اگر اينها را بفروشيم ديگر خريدن گندم براى ما ميسر نخواهد شد.\r\n- سخن همين است كه گفتم ، همه گندم ها را در اختيار مردم بگذار و بفروش \r\nمعتب مى گويد: پس از آنكه گندم ها را فروختم و نتيجه را به امام اطلاع دادم حضرت فرمود\r\nبعد از اين ، نان خانه مرا روز به روز از بازار بخر؛ نان خانه من از اين پس ، بايد نيمى از گندم و نيمى از جو باشد و نبايد با نانى كه در حال حاضر توده مردم مصرف مى كنند، تفاوت داشته باشد.\r\nمن - بحمدالله - توانايى دارم كه تا آخر سال خانه خود را با نان گندم به بهترين وجهى اداره كنم ، ولى اين كار را نمى كنم تا در پيشگاه الهى اقتصاد و محاسبه در زندگى را رعايت كرده باشم.\r\n"},{"id":524,"category_id":6,"category_code":"s6","source_id":32,"title":"تپه ی توبره ها","content":"متوكل عباسى مى كوشيد با اتكاء بر نيروى نظامى خويش مخالفانش را بترساند.\r\nبه همين جهت ، يك بار لشگر خود را - كه به نود هزار تن مى رسيددستور داد كه توبره اسب خويشش را از خاك سرخ پر كنند و در صحراى وسيعى ، آنها را روى هم بريزند.\r\nسربازان به فرمان متوكل عمل كردند و از خاك هاى ريخته شده ، تپه بزرگ به وجود آمد، كه آنرا تپه توبره ها ناميدند. متوكل بر بالاى تپه رفت و امام هادى عليه السلام را به نزد خود فراخواند و گفت:\r\n شما را خواستم تا لشگر مرا تماشا كنى ! به علاوه ، او دستور داده بود همه ، لباس هاى جنگ بپوشند و سلاح بر گيرند و با بهترين آرايش و كاملترين سپاه از كنار تپه عبور كنند\r\nمنظورش ترسانيدن كسانى بود كه احتمال مى داد بر او بشورند و در اين ميان بيشتر از امام هادى عليه السلام نگران بود كه مبادا به پيروانش ‍ فرمان نهضت عليه متوكل را بدهد\r\nحضرت هادى عليه السلام به متوكل فرمود:\r\n- آيا مى خواهى من هم سپاه خود را به تو نشان دهم ؟\r\nمتوكل پاسخ داد:\r\n-! آرى \r\nامام دعايى كرد! ناگهان ميان زمين و آسمان از مشرق تا مغرب از فرشتگان مسلح پر شد. خليفه از مشاهده اين منظره غش كرد! وقتى كه بهوش آمد، امام هادى عليه السلام به او فرمود:\r\nما در كارهاى دنيا با شما مسابقه نداريم ما به كارهاى آخرت (امور معنوى ) مشغوليم ، آنچه درباره ما فكر مى كنى درست نيست.\r\n"},{"id":525,"category_id":6,"category_code":"s6","source_id":33,"title":"سخنرانی در مکه","content":"عبدالملك مروان ، خليفه اموى در مكه سخنرانى مى كرد. همين كه سخنانش به پند و موعظه رسيد، مردى از ميان جمعيت برخاست و گفت: \r\n- بس است ، بس است !! شما امر مى كنيد ولى خود عمل نمى كنيد و نهى مى كنيد، اما از كارهاى زشت نمى پرهيزيد، پند مى دهيد ولى پند نمى گيريد. آيا ما از كردار شما پيروى كنيم ، يا مطيع گفتار شما باشيم ؟!\r\nاگر بگوييد پيرو روش ما باشيد، چگونه مى توان از ستمگران پيروى كرد يا به چه دليل ما از گناهكارانى اطاعت كنيم كه اموال خدا را ثروت خود مى دانند و بندگان او را بنده خويش حساب مى كنند؟ و اگر بگوييد از دستورات ما اطاعت نماييد و نصيحت ما را بپذيريد، آيا ممكن است آن كس كه خود را پند نمى دهد، ديگرى را نصيحت كند؟ مگر اطاعت از كسى كه عادل نيست جايز است ؟\r\nاگر بگوييد، علم را در هر كجا يافتيد بگيريد و نصيحت را از هر كه باشد بپذيريد، شايد در ميان ما كسانى باشند كه بهتر از شما سخن بگويند و زيباتر حرف بزنند!\r\nاز خلافت دست برداريد و نظام قفل و بند را كنار گذاريد تا آنان كه در شهرها در به در گشته اند و در بيابان ها آواره كرده ايد، پيش بيايند و اين خلافت را به طور شايسته اداره كنند.\r\nبه خدا سوگند! ما هرگز از شما پيروى نكرده ايم و شما را مسلط بر مال و جان و دين خود نساخته ايم تا مانند ستمگران با ما رفتار كنيد ما به وضع زمان خود آگاهيم و منتظر پايان مدت حكومت شما، و تمام شدن همه رنج ها و محنت هاى خود هستيم. \r\nهر كدام از شما كه بر سرير حكومت تكيه زند مدت معينى دارد و به زودى پرونده اى كه همه كردار و اعمال كوچك و بزرگ در آن نوشته شده مى خواند و آن وقت خواهد فهميد كه ستمگران چه ظلم هايى روا داشته اند!\r\nدر اين هنگام ، يكى از ماءموران مسلح خليفه ، پيش آمده و او را گرفت ، ديگر از سرنوشت او خبرى نشد!\r\n"},{"id":526,"category_id":6,"category_code":"s6","source_id":34,"title":"چوب خلال","content":"احمد پسر حوارى مى گويد:\r\n- آرزو داشتم سليمان دارانى ، يكى از عرفا، را در خواب ببينم \r\nپس از يك سال ، او را در خواب ديدم. \r\nبه او گفتم: \r\n استاد! خداوند با تو چه كرد؟\r\nگفت: \r\n- اى احمد! از جايى مى آمدم ، قدرى هيزم در آنجا ديدم ، چوبى به اندازه چوب خلال از آنها برداشتم ، نمى دانم خلال كردم يا نه! \r\nاكنون يك سال است كه براى حساب همان چوب معطل هستم.\r\n"},{"id":527,"category_id":6,"category_code":"s6","source_id":35,"title":"کرم و قاضی","content":"در بين بنى اسرائيل قاضى اى بود كه ميان مردم عادلانه قضاوت مى كرد. وقتى كه در بستر مرگ افتاد، به همسرش گفت: \r\n- هنگامى كه مُردم ، مرا غسل بده و كفن كن و چهره ام را بپوشان و مرا بر روى تخت (تابوت ) بگذار، كه به خواست خدا، چيز بد و ناگوار نخواهى ديد.\r\nوقتى كه مُرد، همسرش طبق وصيت او رفتار كرد. پس از چند دقيقه كه روپوش را از روى صورتش كنار زد، ناگهان ! كرمى را ديد كه بينى او را قطعه قطعه مى كند. از اين منظره وحشت زده شد! روپوش را به صورتش ‍ افكند، و مردم آمدند و جنازه او را بردند و دفن كردند.\r\nهمان شب در عالم خواب ، شوهرش را ديد. شوهرش به او گفت: \r\nآيا از ديدن كرم وحشت كردى ؟\r\nزن گفت: \r\n! آرى \r\nقاضى گفت: \r\n- سوگند به خدا! آن منظره وحشتناك به خاطر جانب دارى من در قضاوت راجع به برادرت بود!\r\nروزى برادرت با كسى نزاع داشت و نزد من آمد. وقتى براى قضاوت نزد من نشستند، من پيش خود گفتم : خدايا حق را با برادر زنم قرار بده! \r\nوقتى كه به نزاع آنان رسيدگى نمودم ، اتفاقا حق با برادر تو بود، و من خوشحال شدم . آنچه از كرم ديدى ، مكافات انديشه من بود كه چرا مايل بودم حق با برادر زنم باشد و بى طرفى را حتى در خواهش ‍ قلبى ام به خاطر هواى نفس - حفظ نكردم.\r\n"},{"id":528,"category_id":6,"category_code":"s6","source_id":36,"title":"واژگونی یک شهر","content":"مردى از بنى اسرائيل كاخى زيبا و محكم ساخت و خوراك هاى مختلفى به عنوان غذا آماده نمود و تنها از توانگران شهر دعوت كرد و مستمندان را وانهاد. هنگامى كه بدون دعوت ، از مستمندان نيز كسانى آمدند، به آنان گفته شد اين غذا براى امثال شما نيست! \r\nخداوند دو فرشته به شكل مستمندان فرستاد و به آنان نيز همان حرف ها را گفتند. خداى تعالى به دو فرشته امر فرمود در قيافه توانگران در آن مجلس حاضر شوند!\r\nهنگامى كه در قيافه توانگران وارد مجلس شدند، آنها را گرامى داشتند و در صدر مجلس نشاندند.\r\nاز اين رو خداوند به هر دو فرشته امر نمود:\r\nآن شهر و هر كه در آن است را به زمين فرو برند.\r\n"},{"id":529,"category_id":6,"category_code":"s6","source_id":37,"title":"فرصت هدر رفته","content":"خداوند به يكى از پيامبران بنى اسرائيل وحى كرد كه مردى از امت او سه دعايش نزد من مستجاب است . پيامبر آن مرد را از اين مطلب آگاه ساخت . مرد نيز پيش همسر خود رفت جريان را به وى نقل كرد زن اصرار كرد كه يكى از دعاها را درباره ايشان انجام دهد. مرد هم پذيرفت. \r\nآنگاه زن گفت از خدا بخواه من از زيباترين زنان باشم. \r\nمرد دعا كرد زن زيباترين زمان خود گشت . چندان نگذشت شديدا مورد توجه پادشاهان هواپرست و جوانان ثروتمند و عياش قرار گرفت. \r\nبه شوهر پير و فقير خود اعتنا نمى كرد و روش ناسازگارى و بدرفتارى را به همسرش در پيش گرفت. \r\nمرد مدتى با او مدارا نمود هنگامى كه ديد روز به روز اخلاق او بدتر مى شود ديگر رفتارش قابل تحمل نيست ، دعا كرد خداوند او را به صورت سگى درآورد و دعا مستجاب شد... پس از اين ماجرا فرزندان آن زن دور پدر جمع شده گريه و ناله كردند و اظهار مى داشتند مردم مرا سرزنش مى كنند كه مادرمان به صورتى سگى در آمده و از پدر خواستند مادرشان بصورت اوليه بازگردد و مرد نيز دعا كرد. زن به حال اول بازگشت . و بدين گونه سه دعاى مستجاب آن مرد هدر رفت.\r\n"},{"id":530,"category_id":6,"category_code":"s6","source_id":38,"title":"مکافات عمل","content":"در زمان حضرت موسى پادشاه ستمگرى بود كه وى به شفاعت بنده صالح ، حاجت مؤ منى را به جا آورد! از قضا پادشاه و مؤ من هر دو در يك روز از دنيا رفتند! مردم جمع شدند و پادشاه را با احترام دفن نمودند و سه روز مغازه ها را بستند و عزادار شدند.\r\nاما جنازه مؤ من در خانه اش ماند و حيوانى بر او مسلط گشت و گوشت صورت وى را خورد! پس از سه روز حضرت موسى از قضيه با خبر شد.\r\nموسى در ضمن مناجات با خداوند، اظهار نمود: بارالهى ! آن دشمن تو بود كه با همه عزت و احترام فراوان دفن شد، و اين هم دوست توست كه جنازه اش در خانه ماند و حيوانى صورتش را خورد! سبب چيست ؟\r\nوحى آمد كه اى موسى ! دوستم از آن ظالم حاجتى خواست ، او هم بجا آورد، من پاداش كار نيك او را در همين جهان دادم. \r\nاما مؤمن چون از ستمگر كه دشمن من بود، حاجت خواست ، من هم كيفر او را در اين جهان دادم ، حال ، هر دو نتيجه كارهاى خودشان را ديدند.\r\n"},{"id":531,"category_id":6,"category_code":"s6","source_id":39,"title":"از ما حرکت از خدا برکت","content":"يكى از ياران رسول خدا صلى الله عليه و آله فقير شد. محضر رسول خدا صلى الله عليه و آله آمد و شرح حال خود را بيان كرد. پيغمبر صلى الله عليه و آله فرمود:\r\nبرو هر چه در منزل دارى اگر چه كم ارزش هم باشد بياور!\r\nآن مرد انصار رفت و طاقه اى گليم و كاسه اى را خدمت پيغمبر صلى الله عليه و آله آورد.\r\nحضرت آنها را در معرض فروش گذاشت و فرمود: چه كسى اينها را از من مى خرد؟\r\nمردى گفت : من آنها را به يك درهم خريدارم. \r\nحضرت فرمود: كسى نيست كه بيشتر بخرد!\r\nمرد ديگرى گفت : من به دو درهم مى خرم. \r\nپيغمبر صلى الله عليه و آله به ايشان فروخت و فرمود: اينها مال تو است. \r\nآن گاه دو درهم را به آن مرد انصار داد و فرمود: با يك درهم غذايى براى خانواده ات تهيه كن و با درهم ديگر تبرى خريدارى كن و او نيز به دستور پيغمبر صلى الله عليه و آله عمل كرد.\r\nتبرى خريد و خدمت پيغمبر صلى الله عليه و آله آورد. حضرت فرمود: اين تبر را بردار و به بيابان برو و با آن هيزم بشكن و هر چه بود ريز و درشت و تر و خشك همه را جمع كن ، در بازار بفروش. \r\nمرد به فرمايشات رسول خدا صلى الله عليه و آله عمل كرد. مدت پانزده روز تلاش نمود و در نتيجه وضع زندگى او بهتر شد.\r\nپيغمبر گرامى صلى الله عليه و آله به او فرمود: اين بهتر از آن است كه روز قيامت بيايى در حالى كه در سيمايت علامت زخم صدقه باشد.\r\n"},{"id":532,"category_id":6,"category_code":"s6","source_id":40,"title":"خدمت و جهاد","content":"جوانى محضر رسول خدا صلى الله عليه و آله رسيد و عرض كرد:\r\nيا رسول الله ! خيلى مايلم در راه خدا بجنگم. \r\nحضرت فرمود: در راه خدا جهاد كن ! اگر كشته شوى زنده و جاويد خواهى بود و از نعمتهاى بهشتى بهره مند مى شوى و اگر بميرى ، اجر تو با خداست و چنانچه زنده برگردى ، گناهانت بخشيده شده و همانند روزى كه از مادر متولد شده اى از گناه پاك مى گردى. \r\nعرض كرد: يا رسول الله ! پدر و مادرم پير شده اند و مى گويند، ما به تو انس ‍ گرفته ايم و راضى نيستند من به جبهه بروم. \r\nپيامبر صلى الله عليه و آله فرمود: در محضر پدر مادرت باش . سوگند به آفريدگارم ! يك شبانه روز در خدمت پدر و مادر بودن بهتر از يك سال جهاد در جبهه جنگ است.\r\n"},{"id":533,"category_id":6,"category_code":"s6","source_id":41,"title":"دین خدا","content":"ابن عباس (پسرعموى پيغمبر اسلام ) مى گويد:\r\nهرگاه پيغمبر خدا صلى الله عليه و آله كسى را مى ديد و وى توجه حضرت را به خود جلب مى كرد مى فرمود: او شغل و حرفه اى دارد؟ اگر مى گفتند: نه ! مى فرمود: از نظر من افتاد.\r\nوقتى از ايشان سؤ ال مى كردند: چرا؟\r\nحضرت مى فرمود:\r\n- به خاطر اينكه اگر آدم خداشناس شغلى نداشته باشد دين خدا را وسيله دنياى خود قرار مى دهد و از دين خود نان مى خورد.\r\n"},{"id":534,"category_id":6,"category_code":"s6","source_id":42,"title":"قوی ترین انسان","content":"روزى پيامبر اسلام از محلى مى گذشت ، مشاهده كرد گروهى از جوانان سرگرم مسابقه وزنه بردارى هستند. آنجا سنگ بزرگى بود كه هر كدام آن را به قدرى توانايى خود بلند مى كردند. رسول خدا صلى الله عليه و آله پرسيدند: چه مى كنيد؟ گفتند:\r\n- زورآزمايى مى كنيم تا بدانيم كدام يك از ما نيرومندتر است ؟ فرمود: مايليد من بگويم كدامتان از همه قويتر و زورمندتر است ؟\r\nعرض كردند: بلى ! يا رسول الله صلى الله عليه و آله . چه بهتر كه پيامبر سلام بگويد چه كسى از همه قويتر است ؟ پيامبر اسلام صلى الله عليه و آله فرمود:\r\n- از همه نيرومندتر كسى است كه هرگاه از چيزى خوشش آمد علاقه به آن چيز او را به گناه و خلاف حق وادار نكند و هرگاه عصبانى شد طوفان خشم او را از مدار حق خارج نكند. كلمه اى دروغ يا دشنام بر زبان نياورد و هرگاه قدرتمند گشت به زياده از اندازه حق خود دست درازى نكند.\r\n"},{"id":535,"category_id":6,"category_code":"s6","source_id":43,"title":"پیغمبر و شبان","content":"رسول خدا صلى الله عليه و آله با عده اى از بيابان عبور مى كردند. در اثناى راه به شترچرانى رسيدند. حضرت كسى را فرستاد تا مقدارى شير از او بگيرد.\r\nشتر چران گفت : شيرى كه در پستان شتران است براى صبحانه قبيله است و آنچه در ظرف دوشيده ام براى شام آنهاست. \r\nبا اين بهانه به حضرت شير نداد. پيغمبر خدا صلى الله عليه و آله او را دعا كرد و گفت : خدايا! مال و فرزندان او را زياد كن! \r\nسپس از آن محل گذشتند و به گوسفند چرانى رسيدند. پيامبر كسى را فرستاد از او شير بخواهد. چوپان گوسفندها را دوشيد و با آن شيرى كه در آن ظرف حاضر داشت همه را در ظرف فرستاده پيامبر صلى الله عليه و آله ريخت و يك گوسفند نيز براى حضرت فرستاد و عرض كرد:\r\n- فعلا همين مقدار آماده است ، اگر اجازه دهيد بيش از اين تهيه و تقديم كنم ؟\r\nرسول خدا صلى الله عليه و آله درباره او نيز دعا كرده ، گفت : خدايا! به اندازه نياز او روزى عنايت فرما!\r\nيكى از اصحاب عرض كرد:\r\n- يا رسول الله ! آن كس كه به شما شير نداد درباره او دعايى نمودى كه همه ما آن دعا را دوست داريم و درباره كسى كه به شما شير داد دعايى فرمودى كه هيچ يك از ما آن دعا را دوست نداريم! \r\nرسول خدا صلى الله عليه و آله فرمود: مال كم نياز زندگى را برطرف مى سازد، بهتر از ثروت بسيارى است كه آدمى را غافل نمايد.\r\nسپس اين دعا را نيز كردند:\r\nخدايا به محمد و اولاد او به اندازه كافى روزى لطف فرما\r\n"},{"id":536,"category_id":6,"category_code":"s6","source_id":44,"title":"کوچکی گناه","content":"پيامبر گرامى اسلام صلى الله عليه و آله در يكى از مسافرتها همراه جمعى از اصحاب خود در سرزمين خالى و بى آب و علفى فرود آمدند و به ياران خود فرمودند:\r\n- هيزم بياوريد تا آتش روشن كنيم \r\nاصحاب عرض كردند: يا رسول الله ! اينجا سرزمينى خالى است و هيچ گونه هيزمى در آن وجود ندارد.\r\nپيامبر صلى الله عليه و آله فرمود:\r\n- برويد هر كس هر مقدار مى تواند هيزم جمع كند و بياورد. ياران به صحرا رفتند و هر كدام هر اندازه كه توانستند، ريز و درشت ، جمع كردند و با خود آوردند. همه را در مقابل پيغمبر صلى الله عليه و آله روى هم ريختند. مقدار زيادى هيزم جمع شد.\r\nدر اين وقت رسول خدا صلى الله عليه و آله فرمود:\r\n- گناهان كوچك هم مانند اين هيزمهاى كوچك است . اول به چشم نمى آيد، ولى وقتى كه روى هم جمع مى گردند، انبوه عظيمى را تشكيل مى دهند.\r\nآنگاه فرمود: ياران ! از گناهان كوچك نيز بپرهيزيد. اگر چه گناهان كوچك چندان مهم به نظر نمى آيند؛ هر چيز طالب و جستجو كننده اى دارد. جستجوكنندگان ! آن چه را در دوران زندگى انجام داده ايد و هر آن چه بعد از مرگ آثارش باقى مانده است ، همه را مى نويسد و روزى مى بيند كه همان گناهان كوچك ، انبوه بزرگى را تشكيل داده است .\r\n"},{"id":537,"category_id":6,"category_code":"s6","source_id":45,"title":"طلا و نقره","content":"رسول خدا صلى الله عليه و آله فرمود:\r\n- وقتى مرا به معراج بردند، وارد بهشت شدم . در آنجا فرشتگانى ديدم كه با خشت طلا و خشت نقره ساختمانى مى سازند ولى گاهى دست از كار مى كشند از فرشتگان پرسيدم : شما چرا گاهى كار مى كنيد و گاهى از كار دست مى كشيد؟ سبب چيست ؟\r\nپاسخ دادند: هر وقت مصالح ساختمانى به ما برسد مشغول مى شويم و هرگاه نرسد از كار باز مى ايستيم. \r\nگفتم : مصالح ساختمانى شما چيست ؟\r\nجواب دادند:\r\n ((سبحان الله و الحمدلله و لا اله الا الله و الله اكبر)) \r\nوقتى مؤ من اين ذكر را مى گويد ما ساختمان را مى سازيم . وقتى كه ساكت مى شود ما نيز دست از كار مى كشيم.\r\n"},{"id":538,"category_id":6,"category_code":"s6","source_id":46,"title":"سفره ی افطار","content":"ام كلثوم دختر اميرالمؤ منين عليه السلام مى گويد:\r\nدر شب نوزدهم ماه رمضان دو قرص نان جو، يك كاسه شير و مقدارى نمك در يك ظرف براى افطار خدمت پدر آوردم . وقتى نمازش را به اتمام رساند. براى افطار آماده شد.\r\nهنگامى كه نگاهش به غذا افتاد به فكر فرو رفت . آنگاه سرش را تكان داد و با صداى بلند گريست و فرمود:\r\n- عزيزم ! براى افطار پدرت دو نوع خورش (شير و نمك )، آن هم در يك ظرف آماده ساخته اى ؟\r\nتو با اين عمل مى خواهى فرداى قيامت براى حساب در محضر خداوند بيشتر بايستم ؟\r\nمن تصميم دارم هميشه دنباله رو برادر و پسر عمويم رسول خدا صلى الله عليه و آله باشم . هرگز براى آن حضرت دو نوع خورش در يك ظرف آورده نشد تا آنكه چشم از جهان فرو بست. \r\nدختر عزيزم ! هر كس در دنيا خوردنيها، نوشيدنيها، و لباسهايش از راه حلال و پاك تهيه گردد، روز قيامت در دادگاه الهى بيشتر خواهد ايستاد و چنانچه از راه حرام باشد علاوه بر بيشتر ايستادن عذاب هم خواهد داشت زيرا كه در حلال اين دنيا حساب و در حرام آن عذاب است.\r\n"},{"id":539,"category_id":6,"category_code":"s6","source_id":47,"title":"ترس از گناه","content":"حضرت على عليه السلام مردى را ديد كه آثار ترس و خوف در سيمايش ‍ آشكار است . از او پرسيد:\r\n- چرا چنين حالى به تو دست داده است ؟\r\nمرد جواب داد:\r\n- من از خداى مى ترسم\r\nامام فرمود:\r\n- بنده خدا! (نمى خواهد از خدا بترسى ) از گناهانت بترس و نيز به خاطر ظلمهايى كه درباره بندگان خدا انجام داده اى . از عدالت خدا بترس و آنچه را كه به صلاح تو نهى كرده است در آن نافرمانى نكن ، آن گاه از خدا نترس ؛ زيرا او به كسى ظلم نمى كند و هيچ گاه بدون گناه كسى را كيفر نمى دهد.\r\n"},{"id":540,"category_id":6,"category_code":"s6","source_id":48,"title":"قطیفه بر دوش","content":"هارون پسر عنتره از پدرش نقل مى كند:\r\nدر فصل سرما در محضر مولا على عليه السلام وارد شدم . قطيفه اى كهنه بر دوش داشت و از شدت سرما مى لرزيد. گفتم : يا اميرالمؤ منين ! خداوند براى شما و خانواده تان بيت المال مانند ديگر مسلمانان سهمى قرار داده كه مى توانيد به راحتى زندگى كنيد. چرا اين اندازه به خود سخت مى گيريد و اكنون از سرما مى لرزيد؟\r\nفرمود: به خدا سوگند! از بيت المال شما حبه اى برنمى دارم و اين قطيفه اى كه مى بينيد همراه خود از مدينه آورده ام . غير از آن چيزى ندارم.\r\n"},{"id":541,"category_id":6,"category_code":"s6","source_id":49,"title":"درختان بهشتی","content":"پيامبر اسلام صلى الله عليه و آله فرمود:\r\nهر كس بگويد: سبحان الله خداوند در برابر آن درختى در بهشت براى او مى كارد.\r\nو هر كس بگويد: الحمد الله خداوند در برابر آن درختى در بهشت برايش ‍ مى كارد.\r\nو هر كس بگويد: لا اله الا الله خداوند در برابر آن درختى در بهشت براى او مى كارد.\r\nو هر كس بگويد: الله اكبر خداوند در برابر آن درختى در بهشت برايش ‍ مى كارد.\r\nدر اين وقت مردى از قريش به آن حضرت عرض كرد:\r\nيا رسول الله ! در اين صورت درختان ما در بهشت زياد خواهد بود، چون ما مرتب اين ذكرها را مى گوييم. \r\nرسول خدا صلى الله عليه و آله فرمود:\r\nبلى ! درست است لكن مواظب باشيد مبادا آنها را به آتش گناه بسوزانيد چون خداوند مى فرمايد:\r\nاى اهل ايمان ! خدا و رسولش را اطاعت كنيد و اعمالتان را باطل ننماييد.!\r\n"},{"id":542,"category_id":6,"category_code":"s6","source_id":50,"title":" بهترين آرزو","content":"ربيعه پسر كعب مى گويد:\r\nروزى پيغمبر خدا صلى الله عليه و آله به من فرمود:\r\nربيعه ! هفت سال مرا خدمت كردى ، آيا از من پاداش نمى خواهى ؟\r\nمن عرض كردم: \r\nيا رسول الله ! مهلت دهيد تا فكرى در اين باره بكنم. \r\nفرداى آن روز محضر رسول خدا صلى الله عليه و آله رفتم ، فرمود:\r\nربيعه حاجتت را بخواه! \r\nعرض كردم. \r\nاز خدا بخواه مرا همراه شما داخل بهشت نمايد.\r\nفرمود:\r\nاين درخواست را چه كسى به تو آموخت ؟\r\nعرض كردم: \r\nهيچ كس به من ياد نداد، لكن من فكر كردم اگر مال دنيا بخواهم كه نابود شدنى است و اگر عمر طولانى و فرزندان بخواهم سرانجام آن مرگ است.\r\nدر اين وقت پيغمبر صلى الله عليه و آله ساعتى سر بزير افكند، سپس ‍ فرمود:\r\nاين كار را انجام مى دهم ، ولى تو هم مرا با سجده هاى زياد كمك كن و بيشتر نماز بخوان .\r\n"},{"id":543,"category_id":6,"category_code":"s6","source_id":51,"title":"مزاح پيغمبر","content":"پيرزنى به حضور پيامبر اكرم صلى الله عليه و آله رسيد، علاقه من بود كه اهل بهشت باشد.\r\nپيامبر اكرم صلى الله عليه و آله به او فرمود:\r\nپيرزن به بهشت نمى رود.\r\nاو گريان از محضر پيامبر خارج شد.\r\nبلال حبشى او را در حال گريه ديد.\r\nپرسيد:\r\nچرا گريه مى كنى ؟\r\nگفت: \r\nگريه ام به خاطر اين است كه پيغمبر فرمود:\r\nپيرزن به بهشت نمى رود.\r\nبلال وارد محضر پيامبر شد حال پيرزن را بيان نمود.\r\nحضرت فرمود:\r\nسياه نيز به بهشت نمى رود.\r\nبلال غمگين شد و هر دو نشستند و گريستند.\r\nعباس عموى پيامبر آنها را در حال گريان ديد\r\nپرسيد:\r\nچرا گريه مى كنيد؟\r\nآنان فرمايش پيامبر را نقل كردند.\r\nعباس ماجرا را به پيامبر عرض كرد.\r\nحضرت به عمويش كه پيرمرد بود فرمود:\r\nپيرمرد هم به بهشت نمى رود.\r\nعباس هم سخت پريشان و ناراحت گشت.\r\nسپس رسول اكرم هر سه نفر را به حضورش خواست ، آنها را خوشحال نمود و فرمود:\r\nخداوند اهل بهشت را در سيماى جوان نورانى در حالى كه تاجى به سر دارند وارد بهشت مى كند، نه به صورت پير و سياه چهره و بدقيافه .\r\n"},{"id":544,"category_id":6,"category_code":"s6","source_id":52,"title":" نگاه خائنانه","content":"شخصى به پيغمبر صلى الله عليه و آله عرض كرد:\r\nفلانى به ناموس همسايه (خائنانه ) نگاه مى كند و اگر امكان آن را داشته باشد از اعمال خلاف عفت نيز پروا ندارد.\r\nرسول خدا صلى الله عليه و آله از اين قضيه سخت بر آشفت و فرمود:\r\nاو را نزد من بياوريد!\r\nشخص ديگرى گفت: \r\nاو از پيروان شما مى باشد و از كسانى است كه به ولايت شما و ولايت على عليه السلام معتقد است و نيز از دشمنان شما بيزار است.\r\nپيغمبر گرامى صلى الله عليه و آله فرمود:\r\nنگو او از پيروان شما است ، زيرا كه اين سخن دروغ است . چون پيروان ما كسانى هستند كه پيرو ما بوده و عملشان همانند عمل ما مى باشد.\r\nولى آنچه درباره اين مرد گفتى از اعمال و كردار ما نيست.\r\n"},{"id":545,"category_id":6,"category_code":"s6","source_id":53,"title":") پنج سفارش از رسول خدا(ص ","content":"مردى به نام (ابو ايوب انصارى ) محضر پيغمبر صلى الله عليه و آله رسيد و عرض كرد:\r\nيا رسول الله ! به من وصيتى فرما كه مختصر و كوتاه باشد تا آن را به خاطر سپرده ، عمل كنم. \r\nپيغمبر فرمود:\r\nپنج چيز را به تو سفارش مى كنم. \r\n از آنچه در دست مردم است نااميد باش ! چه اين كه ، براستى آن عين بى نيازى است \r\n. از طمع پرهيز كن ! زيرا طمع فقر حاضر است \r\n- نمازت را چنان بخوان كه گويا آخرين نماز تو است و زنده نخواهى ماند تا نماز بعدى را بخوانى. \r\n. بپرهيز از انجام كارى كه بعدا به ناچار از آن پوزش طلبى \r\n. براى برادرت همان چيزى را دوست بدار كه براى خودت دوست دارى\r\n"},{"id":546,"category_id":6,"category_code":"s6","source_id":54,"title":"ارزش دانش اندوزى","content":"رسول خدا صلى الله عليه و آله روزى وارد مسجد شد و مشاهده فرمود دو جلسه تشكيل يافته است. \r\nيكى ، جلسه علم و دانش است ، كه در آن از معارف اسلامى بحث مى شود و ديگرى جلسه دعا و مناجات است ، كه در آن خدا را مى خوانند و دعا مى كنند.\r\nپيمغبر صلى الله عليه و آله فرمود:\r\nاين هر دو جلسه خوب است و هر دو را دوست دارم ، آن عده دعا مى كنند و اين عده راه دانش مى پويند و به بى سوادان آگاهى و آموزش مى دهند، ولى من اين گروه دوم را بر گروه اول كه صرفا به دعا و مناجات مشغولند ترجيح مى دهم ، زيرا من خود از جانب خداوند براى تعليم و آموزش بر انگيخته شده ام. \r\nآنگاه رسول گرامى صلى الله عليه و آله به گروه تعليم دهندگان پيوست و با آنان در مجلس علم نشست.\r\n"},{"id":547,"category_id":6,"category_code":"s6","source_id":55,"title":" چهار خصلت خدا پسند","content":"خداوند به پيامبر اكرم صلى الله عليه و آله وحى كرد كه من از جعفر بن ابى طالب به خاطر چهار صفت قدر دانى مى كنم. \r\nپيغمبر صلى الله عليه و آله جعفر را خواست و موضوع را به ايشان خبر داد.\r\nجعفر عرض كرد:\r\nاگر خداوند به شما وحى نمى كرد، من هم اظهار نمى كردم. \r\nيا رسول الله ! من هرگز شراب ننوشيدم ، زيرا مى دانستم كه اگر بنوشم عقلم نابود مى شود.\r\nو هرگز دروغ نگفتم ، زيرا دروغ خلاف مروت و ضد كمال انسان است. \r\nو هرگز زنا نكرده ام ، زيرا ترسيدم با ناموسم همان عمل انجام بشود.\r\nو هرگز بت نپرستيدم ، زيرا مى دانستم كه بت پرستى منفعتى ندارد.\r\nرسول خدا دست مباركش را بر شانه وى زد و فرمود:\r\nسزاوار است كه خداوند به تو دو بال مرحمت كند، تا در بهشت پرواز كنى \r\n"},{"id":548,"category_id":6,"category_code":"s6","source_id":56,"title":" اطاعت از شوهر","content":"مردى از انصار قصد مسافرت داشت . به همسرش گفت : تا من ازمسافرت بر نگشته ام تو نبايد از خانه بيرون بروى. \r\nپس از مسافرت شوهر، زن شنيد پدرش بيمار است.\r\nكسى را نزد پيامبر اكرم صلى الله عليه و آله فرستاد و پيغام داد كه شوهرم مسافرت رفته و به من گفته است تا برنگشته ، از منزل خارج نشوم . اكنون شنيده ام پدرم سخت بيمار است ، اجازه فرماييد من به عيادتش ‍ بروم. \r\nپيغمبر صلى الله عليه و آله فرمود:\r\nدر خانه ات بنشين و از شوهرت اطاعت كن! \r\nچند روزى گذشت . زن شنيد كه مرض پدرش شدت يافته . بار دوم خدمت پيامبر صلى الله عليه و آله پيغامى فرستاد كه يا رسول الله ! اجازه مى فرماييد به عيادت پدر بروم ؟\r\nحضرت فرمود:\r\n! نه ! در خانه ات بنشين و از شوهرت اطاعت نما\r\nپس از مدتى شنيد پدرش فوت كرد. بار سوم كسى را فرستاد و پيغام داد كه پدرم از دنيا رفته ، اجازه فرماييد بروم در مراسم عزاداريش شركت كنم ، برايش نماز بخوانم ؟\r\nپيامبر صلى الله عليه و آله اين دفعه هم اجازه نداد و فرمود:\r\n! در خانه ات بنشين و از همسرت اطاعت كن \r\nپدرش را دفن كردند. پس از آن پيغمبر صلى الله عليه و آله كسى را به سوى آن زن فرستاد و فرمود:\r\nبه او بگوييد به خاطر اطاعت تو از همسرت ، خداوند گناهان تو و پدرت را بخشيد.\r\n"},{"id":549,"category_id":6,"category_code":"s6","source_id":57,"title":" عاقبت انديشى","content":"مردى خدمت رسول خدا صلى الله عليه و آله رسيد و عرض كرد:\r\nبه من نصيحتى بفرما؟\r\nرسول خدا صلى الله عليه و آله وسلم فرمود:\r\nاگر بگويم عمل مى كنى ؟\r\nمرد گفت : آرى! \r\nحضرت دو بار ديگر اين سؤ ال را تكرار كرد و در هر بار مرد جواب داد: بلى! \r\nپيامبر گرامى صلى الله عليه و آله وسلم پس از آن كه از او قول محكمى گرفت و او را به اهميت مطلب متوجه ساخت ، فرمود:\r\n: به تو سفارش مى كنم \r\n- هرگاه خواستى كارى انجام دهى ، عاقبت و سرانجام آن را در نظر بگير انديشه كن ! اگر سرانجامش هدايت و نجات است پس انجام بده وگرنه از آن بپرهيز! و آن را انجام مده! \r\nيعنى اگر رضاى خدا در آن كار باشد، بجاى آور و اگر رضاى خدا نباشد رهايش كن .\r\n"},{"id":550,"category_id":6,"category_code":"s6","source_id":58,"title":" مبارزه با خرافات","content":"هنگامى كه ابراهيم پسر رسول خدا صلى الله عليه و آله چشم از جهان فرو بست . در همان روز خورشيد گرفت. \r\nعده اى گفتند:\r\nخورشيد نيز به خاطر مرگ ابراهيم غمگين است و اين علامت عظمت رسول خداست. \r\nپيامبر صلى الله عليه و آله فورا پيش از دفن جنازه ابراهيم ، مردم را به مسجد دعوت كرد و بالاى منبر رفت و فرمود:\r\nاى مرم ! خورشيد و ماه دو نشانه از نشانه هاى خداست و به دستور او در سير و حركتند و به فرمان خدا مطيع مى باشند، هرگز به خاطر مرگ و زندگى كسى گرفته نمى شوند! هرگاه خورشيد و ماه گرفت ، نماز آيات بخوانيد!\r\nسپس از منبر پايين آمدند و نماز آيات را با جماعت خواندند آنگاه به على عليه السلام فرمود:\r\nپيكر فرزندم ابراهيم را براى دفن آماده كن! \r\nعلى عليه السلام جنازه ابراهيم را غسل داد و كفن كرد پس از آن مردم دفنش ‍ كردند.\r\n"},{"id":551,"category_id":6,"category_code":"s6","source_id":59,"title":" درس محكم كارى","content":"وقتى كه رسول خدا صلى الله عليه و آله پيكر فرزندش ، ابراهيم ، را به خاك سپرد چشمانش پر از اشك شد و فرمود:\r\nدل غمگين است و چشم اشك مى ريزد، ولى سخنى كه سبب خشم خدا شود نمى گويم.\r\nآنگاه فرمود: ابراهيم ! ما، در مرگ تو غمگينيم. \r\nسپس حضرت گوشه قبر را ديد كه به طور كامل درست نشده ، با دست مباركش آن را صاف كرد، پس از آن فرمود:\r\nهرگاه يكى از شما كارى را انجام داد، حتما آن را محكم و استوار انجام دهد.\r\n"},{"id":552,"category_id":6,"category_code":"s6","source_id":60,"title":" محبوب ترين اسمها","content":"جابر انصارى مى گويد:\r\nبه پيغمبر خدا صلى الله عليه و آله وسلم عرض كردم: \r\nدر شاءن على بن ابى طالب عليه السلام چه مى فرماييد؟\r\nفرمود:\r\nاو جان من است! \r\nعرض كردم: \r\nدر شاءن حسن و حسين عليه السلام چه مى فرماييد؟\r\nحضرت پاسخ داد: آن دو، روح منند و فاطمه ، مادر ايشان ، دختر من است . هر كه او را غمگين كند مرا غمگين كرده است و هر كه او را شاد كند، مرا شاد گردانيده است و خدا را گواه مى گيرم ، من در جنگم با هر كس كه با ايشان در جنگ است و در صلحم با هر كس كه با ايشان در صلح است. \r\nاى جابر! هرگاه خواستى دعا كنى و مستجاب گردد، خدا را به اسمهاى ايشان بخوان ، زيرا كه اسمهاى آنان نزد خداوند محبوب ترين اسمها است.\r\n"},{"id":553,"category_id":6,"category_code":"s6","source_id":61,"title":" حدود همسايه ","content":"مردى از انصار خدمت پيامبر خدا صلى الله عليه و آله آمد و عرض كرد:\r\nمن خانه اى در فلان محل خريده ام و نزديكترين همسايه ام آدمى است كه اميد خيرى از او ندارم و از شرش نيز خاطر جمع نيستم. \r\nرسول خدا صلى الله عليه و آله به على عليه السلام ، سلمان ، اباذر و (راوى مى گويد: چهارمى شايد مقداد باشد) دستور فرمود كه با صداى بلند در مسجد فرياد زنند كه هركس همسايه اش از آزار او آسوده نباشد، ايمان ندارد، آنان نيز در مسجد سه بار فرمايش حضرت را با صداى بلند به مردم اعلان كردند. سپس حضرت با دست اشاره كرد و فرمود:\r\nچهل خانه از چپ و راست و جلو و عقب همسايه محسوب مى شود.\r\n"},{"id":554,"category_id":6,"category_code":"s6","source_id":62,"title":" چاره فراق","content":"\r\nمردى از انصار خدمت پيغمبر اسلام صلى الله عليه و آله آمد و عرض كرد: يا رسول الله ! من طاقت فراق شما را ندارم . هنگامى كه به خانه مى روم به ياد شما مى افتم ، از روى محبت و علاقه اى كه به شما دارم ، دست از كار و زندگى برداشته ، به ديدارتان مى آيم ، تا شما را از نزديك ببينم ، آن گاه به ياد روز قيامت مى افتم كه شما وارد بهشت مى شويد در والاترين جايگاه آن قرار مى گيريد و من آن روز از جدايى شما اى رسول خدا چه كنم ؟\r\nبعد از صحبت هاى مرد انصارى ، اين آيه شريفه نازل شد:\r\nآنان كه از خدا و رسولش اطاعت كنند، در زمره كسانى هستند كه خدا برايشان نعمتها عنايت كرده : از پيغمبران ، راستگويان ، صادقان ، شهيدان و صالحان و اينان خوب رفيقانى هستند. \r\nرسول خدا صلى الله عليه و آله آن مرد را خواست و اين آيه را برايش خواند و اين مژده را به او داد كه پيروان راستين پيامبر صلى الله عليه و آله در بهشت ، كنار آن حضرت خواهند بود.\r\n"},{"id":555,"category_id":6,"category_code":"s6","source_id":63,"title":"حکومت بی ارزش","content":"على عليه السلام با سپاهيان اسلام براى سركوبى پيمان شكنان به سوى بصره حركت مى كردند. در نزديكى بصره به محل (ذى قار) رسيدند. در آنجا براى رفع خستگى و آماده سازى سپاه توقف نمودند. عبد الله بن عباس ‍ مى گويد:\r\nمن در آنجا به حضور امير المومنين على رسيدم ، ديدم (رئيس مسلمانان ، فرمانده كل قوا) خود كفش خويش را وصله مى زند.\r\nحضرت روى به من كرد و فرمود:\r\nابن عباس ! اين كفش چه قدر مى ارزد؟ قيمت آن چه قدر است ؟\r\nگفتم: \r\nارزشى ندارد.\r\nفرمود:\r\nسوگند به خدا! همين كفش بى ارزش از رياست و حكومت شما براى من محبوب تر است . مگر اين كه بتوانم با اين حكومت و رياست حق را زنده كنم و باطل را براندازم. \r\nآرى ! ارزش يك حكومت ، بسته به آن است كه در سايه اش حق زنده و باطل نابود گردد و گرنه چه ارزشى دارد؟\r\n"},{"id":556,"category_id":6,"category_code":"s6","source_id":64,"title":"جمجمه ی سخنگو","content":"به امام على عليه السلام خبر رسيد معاويه تصميم دارد با لشكر مجهز به سرزمين هاى اسلامى حمله كند.\r\nعلى عليه السلام براى سركوبى دشمنان از كوفه بيرون آمد و با سپاه مجهز به سوى صفين حركت كردند در سر راه به شهر مدائن (پايتخت پادشاهان ساسانى ) رسيدند و وارد كاخ كسرى شدند.\r\nحضرت پس از اداى نماز با گروهى از يارانش مشغول گشت ويرانه هاى كاخ انوشيروان شدند و به هر قسمت كاخ كه مى رسيدند كارهايى را كه در آنجا انجام شده بود به يارانش توضيح مى دادند به طورى كه باعث تعجب اصحاب مى شد و عاقبت يكى از آنان گفت: \r\nيا اميرالمؤ منين ! آنچنان وضع كاخ را توضيح مى دهيد گويا شما مدتها اينجا زندگى كرده ايد!\r\nدر آن لحظات كه ويرانه هاى كاخها و تالارها را تماشا مى كرند، ناگاه على عليه السلام جمجمه اى پوسيده را در گوشه خرابه ديد، به يكى از يارانش ‍ فرمود:\r\nاو را برداشته همراه من بيا!\r\nسپس على عليه السلام بر ايوان كاخ مدائن آمد و در آنجا نشست و دستور داد طشتى آوردند و مقدارى آب در طشت ريختند و به آوردند جمجمه فرمود: آن را در طشت بگذار. وى هم جمجمه را در ميان طشت گذاشت. \r\nآنگاه على عليه السلام خطاب به جمجمه فرمود:\r\nاى جمجمه ! تو را قسم مى دهم ! بگو من كيستم تو كيستى ؟\r\nجمجمه با بيان رسا گفت: \r\nتو اميرالمؤ منين ، سرور جانشينان و رهبر پرهيزگاران هستى و من بنده اى از بندگان خدا هستم. \r\nعلى عليه السلام پرسيد:\r\nحالت چگونه است ؟\r\nجواب داد:\r\nيا امير المومنين ! من پادشاه عادل بودم ، نسبت به زيردستان مهر و محبت داشتم ، راضى نبودم كسى در حكومت من ستم ببيند. ولى در دين مجوسى (آتش پرست ) به سر مى بردم . هنگامى كه پيامبر اكرم صلى الله عليه و آله به دنيا آمد كاخ من شكافى برداشت . آنگاه به رسالت مبعوث شد من خواستم اسلام را بپذيرم ويل زرق و برق سلطنت مرا از ايمان و اسلام باز داشت و اكنون پشيمانم. \r\nاى كاش كه من هم ايمان مى آوردم و اينك از بهشت محروم هستم و در عين حال به خاطر عدالت از آتش دوزخ هم در امانم. \r\nواى به حالم ! اگر ايمان مى آوردم من هم با تو بودم . اى اميرالمؤ منين و اى بزرگ خاندان پيغمبر!\r\nسخنان جمجمه پوسيده انوشيروان به قدرى دل سوز بود كه همه حاضران تحت تاءثير قرار گرفته با صداى بلند گريستند.\r\n"},{"id":557,"category_id":6,"category_code":"s6","source_id":65,"title":"پسندیده ترین صفت زن","content":"حضرت على عليه السلام مى فرمايد:\r\nدر محضر رسول خدا صلى الله عليه و آله بوديم ، فرمود:\r\nبه من بگوييد بهترين و پسنديده ترين چيز براى يك زن مسلمان چيست ؟\r\nما همگى از پاسخ عاجز مانديم. \r\nسپس از خدمت حضرت بيرون آمديم و من به خانه برگشتم ، قضيه را به فاطمه اطلاع دادم. \r\nزهراى مرضيه اظهار داشت: \r\nبهترين چيز براى يك زن مسلمان آن است كه مردهاى نامحرم را نبيند و مردهاى اجنبى هم او را نبينند.\r\nآنگاه خدمت پيامبر اسلام برگشتم و پاسخ فاطمه را به حضرت رساندم . پيغمبر صلى الله عليه و آله از شنيدن جواب به قدرى خوشحال شد كه فرمود:  \r\nحقا فاطمه پاره تن من و جزء وجود من است.\r\n"},{"id":558,"category_id":6,"category_code":"s6","source_id":66,"title":"بانگ اذان بلال","content":"هنگامى كه پيغمبر اسلام صلى الله عليه و آله چشم از جهان فرو بست بلال - اذان گوى پيغمبر صلى الله عليه و آله - از گفتن اذان خوددارى كرد و گفت: \r\nمن بعد از پيامبر اسلام صلى الله عليه و آله براى هيچ كس اذان نخواهم گفت. \r\nروزى فاطمه فرمود:\r\nدوست دارم صداى اذان گوى پدرم را بشنوم. \r\nوقتى كه سخن فاطمه به گوش بلال رسيد آماده گفتن اذان شد.\r\nهنگامى كه دوبار گفت: \r\nالله اكبر، الله اكبر،\r\nزهراى مرضيه خاطره دوران پدر بزرگوارش را به ياد آورد ديگر نتوانست از گريه خوددارى كند و بلند گريست. \r\nوقتى كه بلال گفت: \r\nاشهد ان محمد رسول الله \r\nفاطمه عليهاالسلام ضجه اى زد و بر زمين افتاد و غش كرد به طورى كه گمان كردند زهرا دنيا را وداع نمود\r\nمردم آمدند، گفتند: بلال اذان بگو! دختر پيغمبر صلى الله عليه و آله دنيا را وداع كرد.\r\nبلال اذان را ناتمام گذاشت . وقتى فاطمه عليهاالسلام به هوش آمد فرمود:\r\nبلال اذان را تمام كن! \r\nبلال پاسخ داد:\r\nاى بانوى بانوان دو جهان ! از اين كه هرگاه صداى اذان مرا مى شنوى چنين احساسات بر تو هجوم مى آورد، از جانت مى ترسم. \r\nفاطمه عليهاالسلام نيز او را بخشيد. \r\nبلال از آن وقت ديگر براى عموم اذان نگفت.\r\n"},{"id":559,"category_id":6,"category_code":"s6","source_id":67,"title":"سخن چین","content":"شخصى سخن چين ، به حضور امام حسن رسيد.\r\nعرض كرد:\r\nفلانى از شما بدگويى مى كند.\r\nامام به جاى تشويق چهره درهم كشيد و به او فرمود:\r\nتو مرا به زحمت انداختى. \r\nاز اين كه غيبت يك مسلمان را شنيدم بايد درباره خود استغفار كنم و از اين كه گفتى آن شخص با بدگويى از من ، مرتكب گناه شده بايستى براى او نيز دعا كنم.\r\n"},{"id":560,"category_id":6,"category_code":"s6","source_id":68,"title":"شوخی در عاشورا","content":"صبح عاشورا امام حسين عليه السلام دستور داد خيمه ها را زدند - يكى از خيمه ها را براى شستشو و نظافت تعيين گرديد.\r\nبُرير با عبدالرحمان انصارى در كنار خيمه نظافت ايستاده بودند تا سيدالشهداء بيرون آيد و آنها براى نظافت و استعمال نوره يكى پس از ديگرى وارد شوند.\r\nبرير در اين موقعيت حساس با عبدالرحمن به شوخى پرداخت و كارى مى كرد كه ايشان را بخنداند.\r\nعبدالرحمن گفت: \r\nاى برير! مزاح مى كنى ! و مى خندى ؟ اكنون وقت مزاح و خنده نيست . برير در پاسخ گفت: \r\nتمام خويشاوندانم مى دانند كه من اهل مزاح و سخن باطل نبوده ام ، نه در جوانى و نه در پيرى. \r\nاما اين شوخى و خنده را كه اكنون مى كنم به خاطر مژده آن نعمتى (بهشت ) است كه در پيش داريم و به آن خواهيم رسيد.\r\nسوگند به خدا! كه بين ما و هم آغوشى با حوريان بهشتى هيچ فاصله اى نيست جز اين كه يك حمله از طرف دشمن بشود و ما جان خويش را در يارى فرزند رسول خدا فدا كنيم چه قدر دوست دارم هر چه زودتر انجام گيرد.\r\n"},{"id":561,"category_id":6,"category_code":"s6","source_id":69,"title":"تجارت منصفانه","content":"امام عليه السلام غلامى به نام مصادف داشت هزار دينار به او داد براى تجارت به كشور مصر برود.\r\nغلام با آن پول كالاى خريد و با بازرگانان ديگر كه از همان كالا خريده بودند به سوى مصر حركت كردند، همين كه نزديك مصر رسيدند با كاروانى كه از مصر باز مى گشتند، رو به رو شدند و از آنان وضعيت كالاى خود را كه نيازمنديهاى عمومى بود - از لحاظ بازار مصر- پرسيدند.\r\nدر پاسخ گفتند:\r\nكالاى شما در مصر كمياب است و بازار خوبى دارد.\r\nغلام و همراهانش از كمبود متاعشان در مصر و نيز نياز مردم به آن ، آگاه گشتند. و با يكديگر هم قسم شدند و پيمان بستند، كه متاع را با سودى كمتر از صد در صد نفروشند.\r\nوقتى كه وارد مصر شدند، مطابق پيمان خود بازار سياه به وجود آوردند و كالا را به دو برابر قيمتى كه خريده بودند، فروختند.\r\nغلام با هزار دينار سود خالص به مدينه بازگشت و دو كيسه كه هر كدام هزار دينار داشت به امام صادق عليه السلام تسيلم نمود و عرض كرد:\r\nفدايت شوم ! يكى از كيسه ها اصل سرمايه است كه شما به من داديد و ديگرى سود خالص تجارت است. \r\nامام فرمود: اين سود زيادى است ، بگو ببينم چگونه اين را بدست آوردى ؟\r\nمصادف گفت : قضيه از اين قرار است كه در نزديك مصر آگاه شديم كه كالاى ما در آنجا كمياب است ، هم قسم شديم و پيمان بستيم كه به كمتر از صد در صد سود خالص نفروشيم و همين كار را كرديم. \r\nامام گفت : سبحان الله ! شما با ايجاد بازار سياه به زيان گروهى از مسلمانان هم قسم مى شويد كه كالايتان را به سودى كمتر از صد در صد خالص ‍ نفروشيد؟\r\nنه ! من همچو تجارت و سودى را نمى خواهم. \r\nآنگاه يكى از دو كيسه را برداشت و فرمود:\r\nاين اصل سرمايه من و ديگرى را نپذيرفت ، فرمود: اين سود - كه با بى انصافى بدست آمده - نيازى به آن ندارم. \r\nسپس فرمود: اى مصادف ! با شمشير جنگيدن ، از كسب حلال آسان تر است ، به دست آوردن مال از راه حلال بسيار سخت و دشوار است.\r\n"},{"id":562,"category_id":6,"category_code":"s6","source_id":70,"title":"سخن منطقی","content":"منصور دوانيقى (خليفه عباسى ) به امام صادق عليه السلام نوشت : چرا مانند ديگران نزد ما نمى آيى و با ما نمى نشينى ؟\r\nامام عليه السلام در پاسخ نوشت: \r\nما از دنيا چيزى نداريم كه براى آن از تو بترسيم و تو نيز از فضايل و امور آخرت چيزى ندارى كه به خاطر آن به تو اميدوار باشيم ، نه تو در نعمتى هستى كه بيايم به تو تبريك بگويم و نه خود را در بلا و مصيبت مى بينى كه بيايم به تو تسليت دهم . پس چرا نزد تو بيايم ؟\r\nمنصور نوشت: \r\nبياييد ما را نصيحت كنيد.\r\nامام عليه السلام جواب داد:\r\nهر كس اهل دنيا باشد تو را نصيحت نمى كند و هر كس اهل آخرت باشد نزد تو نخواهد آمد.\r\n"},{"id":563,"category_id":6,"category_code":"s6","source_id":71,"title":"اسراف ممنوع","content":"ابان پسر تلغب نقل مى كند:\r\nامام صادق عليه السلام فرمود:\r\nابان ! تو گمان مى كنى خداوند به كسى كه مال و ثروت داده ، به خاطر مقام و منزلت او در پيشگاه خدا بوده و او را خداوند دوست مى دارد؟\r\nو كسى را كه از عطاى خود محروم ساخت و زندگيش در تنگنا است ، به خاطر اين است كه او در نزد خدا بى ارزش است و خداوند او را دوست ندارد؟\r\nهرگز چنين نيست . زيرا ثروت و مال از آن خداست ، به عنوان امانت در اختيار مردم مى گذارد و آنان را آزاد گذاشته كه از روى ميانه روى بخورند و بياشامند و لباس تهيه نموده و ازدواج كنند و براى خود وسيله سوارى تهيه كرده و زندگى را به طور اقتصادى بگردانند.\r\nو هرگاه از مخارج معمولى اضافه آمد، از مستمندان و مؤ منان دستگيرى نموده و مشكلات زندگى آنان را برطرف سازند.\r\nهر كس در مال خداوند اين چنين شرعى و ميانه روى رفتار كند، هر اندازه استفاده نمايد و هر كارى انجام دهد، بر وى حلال است. \r\nهر آنچه مى خورد و مى آشامد و سوارى تهيه مى كند و ازدواج مى نمايد بر او حلال است. \r\nو كسى كه اسراف نموده و در موارد خلاف خروج مى كند برايش حرام خواهد بود.\r\nآنگاه فرمود:\r\n- اسراف نكنيد! چون خداوند اسراف كنندگان را دوست ندارد\r\nاى ابان ! تو فكر مى كنى خداوند از كرم و فضل خود به كسى به عنوان امانت مالى مى دهد او مى تواند اسبى به ده هزار درهم بخرد در صورتى كه اسب بيست درهمى هم او را كفايت مى كند و يا كنيزى به هزار دينار بخرد با اين كه بيست دينارى او را كافى است ؟\r\nسپس فرمود:\r\nزياده روى نكنيد خداوند اسراف كنندگان را دوست ندارد.\r\n"},{"id":564,"category_id":6,"category_code":"s6","source_id":72,"title":"کمک به مستمندان","content":"محمد پسر عجلان مى گويد\r\nخدمت امام صادق عليه السلام بودم ، كه يكى از شيعيان وارد شد و سلام كرد، حضرت از او پرسيد:\r\nبرادرانت در چه حالى بودند؟\r\nاو در پاسخ ، آنان را ستود و گفت: \r\nمردمان خوب و شايسته اى هستند.\r\nامام عليه السلام فرمود:\r\nرفت و آمد ثروتمندانشان با فقرا و احوال پرسى ايشان از همديگر چگونه بود؟\r\nمرد گفت: \r\nارتباطشان اندك است (روابط گرمى ندارند) و زياد احوال يكديگر را جويا نمى شوند.\r\nامام عليه السلام پرسيد:\r\nانفاق و دستگيرى ثروتمندان با تهيدستان چگونه بود؟\r\nمرد جواب داد:\r\nشما از اخلاق و صفاتى مى پرسيد كه در ميان مردم كمياب است. \r\nامام عليه السلام فرمودند:\r\nبنابراين آنان چگونه خود را شيعه مى نامند!\r\nشعيه حقيقى كسى است كه در راه كمك و يارى مستمندان گام بردارد و آنان را در مهر و محبت كردن فراموش نكند.\r\n"},{"id":565,"category_id":6,"category_code":"s6","source_id":73,"title":"احسان پیش از سوال","content":"اسحاق مى گويد:\r\nدر محضر امام صادق عليه السلام بودم و معلى بن خنيس نيز در خدمت امام حضور داشت  در اين وقت مردى از اهل خراسان وارد شد، گفت : پسر پيغمبر خدا! پولم كم شده و توان برگشت به خانه ام را ندارم مگر اينكه شما مرا يارى نماييد.\r\nامام صادق عليه السلام به چپ و راست نگاه كرد و فرمود:\r\nآيا مى شنويد برادر دينى تان چه مى گويد؟\r\nنيكى آن است كه پيش از سؤ ال كسى انجام داده شود، بخشش بعد از سؤ ال پاداش آبروريزى او است. \r\nپيغمبر خدا صلى الله عليه و آله فرمود:\r\nسوگند به آن خدايى كه دانه را مى شكافد و انسانها را مى آفريند، مرا حقيقتا پيامبر قرار داده است . آن مقدار كه سائل از سؤ ال كردن ، رنج مى برد بيشتر از آنست كه تو به او احسان مى كنى. \r\nسپس پنج هزار درهم جمع كردند و به او دادند.\r\n"},{"id":566,"category_id":6,"category_code":"s6","source_id":74,"title":"گنجشک فریادگر","content":"سليمان جعفرى كه از نسل حضرت ابى طالب است ، مى گويد: در ميان باغ در خدمت امام رضا عليه السلام بودم كه ناگاه گنجشكى آمد با حال اضطراب جلوى آن حضرت نشست و مرتب داد مى زد و فرياد مى كشيد.\r\nحضرت به من فرمود:\r\nفلانى مى دانى اين گنجشك چه مى گويد؟\r\nگفتم : خير!\r\nفرمود: مى گويد؛\r\nمارى در خانه مى خواهد جوجه هاى مرا بخورد.\r\nسپس فرمود:\r\nاين عصا را بردار و حركت كن و در فلان خانه مار را بكش! \r\nسليمان مى گويد:\r\nمن عصا را برداشتم و وارد آن خانه شدم ديدم مارى به سوى جوجه ها در حركت است او را كشته و به خدمت امام برگشتم.\r\n"},{"id":567,"category_id":6,"category_code":"s6","source_id":75,"title":"مصلحت","content":"صفوان بن يحيى مى گويد:\r\nدر مدينه محضر امام رضا بودم با عده اى از كنار شخصى كه نشسته بود رد شديم . آن مرد به امام اشاره كرد و به عنوان امامت گفت:\r\nاين پيشواى رافضيها (شيعيان ) است. \r\nبه حضرت عرض كردم : شنيديد آن مرد چه گفت ؟\r\nفرمود:\r\nآرى ، اما او مؤ منى است ، در راه تكميل ايمان گام بر مى دارد.\r\nشب هنگام امام عليه السلام براى اصلاح او دعا كرد. طولى نكشيد مغازه اش آتش گرفت و دزدان باقى مانده اموالش را به غارت بردند.\r\nسحرگاه همان شب آن مرد را ديدم متواضع و پريشان در كنار امام نشسته است . امام دستور داد به او كمك كردند.\r\nسپس خطاب به من كرد و فرمود:\r\nصفوان ! او مؤ منى است در راه تكميل ايمان قدم برمى داشت جزء آنچه ديدى به صلاح او نبود.\r\n"},{"id":568,"category_id":6,"category_code":"s6","source_id":76,"title":null,"content":"\""},{"id":569,"category_id":6,"category_code":"s6","source_id":77,"title":null,"content":"خدمت امام جواد عليه السلام نشسته بودم گوسفندى از خانه امام گم شده بود."},{"id":570,"category_id":6,"category_code":"s6","source_id":78,"title":null,"content":"يكى از همسايه هاى امام را به اتهام دزدى گرفته كشان كشان نزد حضرت جواد عليه السلام آوردند."},{"id":571,"category_id":6,"category_code":"s6","source_id":79,"title":null,"content":"امام فرمود:"},{"id":572,"category_id":6,"category_code":"s6","source_id":80,"title":null,"content":"واى بر شما او را رها كنيد! او دزدى نكرده است ، گوسفند در خانه فلان كس ‍ است ، برويد از خانه او بياوريد!"},{"id":573,"category_id":6,"category_code":"s6","source_id":81,"title":null,"content":"به همان خانه رفتند ديدند گوسفند آنجا است ، صاحب خانه را به اتهام دزدى دستگير كردند، لباسهايش را پاره كرده كتك زدند. وى قسم مى خورد كه گوسفند را ندزديده است. "},{"id":574,"category_id":6,"category_code":"s6","source_id":82,"title":null,"content":"او را خدمت امام آوردند فرمود:"},{"id":575,"category_id":6,"category_code":"s6","source_id":83,"title":null,"content":"چرا به او ستم كرده ايد، گوسفند خودش به خانه او داخل شده و اطلاعى نداشته است. "},{"id":576,"category_id":6,"category_code":"s6","source_id":84,"title":null,"content":"آنگاه امام از او دلجوى نمود و مبلغى در مقابل لباسها و كتكى كه خورده بود به او بخشيد."},{"id":577,"category_id":6,"category_code":"s6","source_id":85,"title":"دلجویی","content":"\""},{"id":578,"category_id":6,"category_code":"s6","source_id":86,"title":"نيازمندان در محضر امام حسن عسكرى (ع)","content":"محمد بن على مى گويد:\r\nتهى دست شديم زندگى بر ما خيلى سخت شد، پدرم به من گفت : برويم نزد امام عسگرى عليه السلام مى گويند مرد بخشنده است. \r\nگفتم: \r\nاو را مى شناسى ؟\r\nپدرم گفت: \r\nنه او را مى شناسم و نه تا به حال وى را ديده ام. \r\nبا هم به سوى خانه آن حضرت حركت كرديم ، پدرم در بين راه به من گفت: \r\nپانصد درهم نيازمنديم كاش امام مى داد، دويست درهم براى خريد لباس ، دويست درهم براى خريد آرد و صد درهمش را براى مخارج ديگر زندگى مى رسانيم. \r\nمحمد بن على مى گويد:\r\nمن با خود گفتم: \r\nاى كاش سيصد درهم نيز به من بدهد كه صد درهم براى خريد يك درازگوش و صد درهم براى مخارج و صد درهم نيز براى خريد لباس باشد، تا به جبل (قسمتهاى كوهستانى غرب ايران تا همدان و قزوين ) بروم. \r\nهنگامى كه به خانه امام عليه السلام رسيديم غلام آن حضرت بيرون آمد و گفت: \r\nعلى بن ابراهيم و پسرش وارد شوند. چون وارد شديم و سلام كرديم امام عليه السلام به پدرم فرمود:\r\nاى على ! چرا تا كنون نزد ما نيامدى ؟\r\nپدرم گفت:\r\nسرورم ! خجالت مى كشيدم با اين وضع شما را ديدار كنم . چون از محضر امام بيرون آمديم ، غلام آن حضرت به دنبال ما آمد و يك كيسه پول به پدرم داد و گفت: \r\nاين پانصد درهم است ! دويست درهم براى خريد لباس ، دويست درهم براى خريد آرد و صد درهم براى ساير مخارج. \r\nآنگاه كيسه ديگرى به من داد و گفت: \r\nاين سيصد درهم است ! با صد درهم آن درازگوش بخر! و با صد درهم آن لباس تهيه كن ! و صد درهمش براى مخارج ديگر تو باشد.\r\nسپس گفت: \r\nبه ايران نرو بلكه به سورا (شهرى در عراق يا محلى در بغداد بوده ) برو محمد بن على نيز به سورا رفت و در آنجا با زنى ازدواج نمود و روزانه چهار هزار دينار درآمد داشت . متاءسفانه در عقيده هفت امامى باقى ماند.\r\n"},{"id":579,"category_id":6,"category_code":"s6","source_id":87,"title":"سلیمان و خارپشت","content":"در قصص و تواریخ آورده اند که وقتی جبرئیل علیه السلام به نزد سلیمان پیامبر آمد، قدحی آب حیات آورد و گفت: آفریدگار تعالی ترا مخیر کرد، بدان که این جام بخوری، تا قیامت زندگانی یابی. سلیمان این معنی را با جن و انس و حیوانات مشورت کرد. همگی گفتند: بباید خورد تا حیات جاودانی یابی.\r\nسلیمان اندیشه کرد که هیچ جنسی از حیوانات باقی مانده که با وی مشورت نکرده باشم؟ او را یاد آمد که با خارپشت مشورت نکرده ام. پس اسب را به نزد خارپشت فرستاد و او را طلب کرد. خارپشت نیامد و امتناع نمود.\r\nحضرت سلیمان، سگ را بفرستاد. خارپشت بیامد.\r\nسلیمان گفت: پیش از آنکه در کار خود، تو را مشورت کنم، بگو اسب را که بعد از آدمی، هیچ جانوری شریف تر از وی نیست، به طلب تو فرستادم و نیامدی، و سگ خسیس ترین حیوانات است بفرستادم بیامدی؛ حکمت چه بود؟\r\nگفت: از آنکه اسب اگر چه حیوانی شریف است، اما وفا ندارد.ولی سگ اگر چه خسیس است، اما وفادار است که برای نانی که از کسی یابد همه عمر او را وفاداری کند. لاجرم به قول بی وفایان نیامدم و به اشارت وفاداری، بیامدم.\r\nپس سلیمان گفت: مرا جامی آب حیات فرستاده اند و مخیر گردانیده که اگر خواهم، بخورم و اگر خواهم رد کنم. همه نظر داده اند که بخورم. تو چه می گویی؟\r\nخارپشت گفت: این جام را تو تنها خواهی خورد، یا با فرزندان و دوستانت؟\r\nگفت: مرا تنها فرموده اند.\r\nخارپشت گفت: پس درست آن است که رد کنی و نخوری.\r\nگفت: چرا؟\r\nخارپشت گفت: چرا که چون ترا زندگانی دراز شود، همه دوستان، زن و فرزندانت پیش از تو بمیرند و ترا به غم هر یکی هزارغم و ماتم روی نماید. و چون یاران و دوستانت نباشند، حیات بی ایشان به چه کار آید؟\r\nسلیمان این رای را بپسندید و آن آب را رد کرد.\r\n"},{"id":580,"category_id":6,"category_code":"s6","source_id":88,"title":"داوود و زن نیازمند","content":"زنى به حضور حضرت داوود (ع) آمد و گفت: \r\nاى پیامبر خدا پروردگار تو ظالم است یا عادل؟\r\nداوود (ع) فرمود: \r\nخداوند عادلى است که هرگز ظلم نمى کند سپس فرمود: \r\nمگر چه حادثه اى براى تو رخ داده است که این سؤال را مى کنى؟\r\nزن گفت : من بیوه زن هستم و سه دختر دارم ، با دستم ریسندگى مى کنم ، دیروز شال بافته خود را در میان پارچه اى گذاشته بودم.\r\nو به طرف بازار مى بردم تا بفروشم و با پول آن غذاى کودکانم را تهیه سازم.\r\nناگهان پرنده اى آمد و آن پارچه را از دستم ربود و برد و تهیدست و محزون ماندم و چیزى ندارم که معاش کودکانم را تأمین نمایم. \r\nهنوز سخن زن تمام نشده بود که \r\nدر خانه داوود (ع) را زدند ، حضرت اجازه وارد شدن به خانه را داد.\r\nناگهان ده نفر تاجر به حضور داوود (ع) آمدند و هر کدام صد دینار (جمعاً هزار دینار) نزد آن حضرت گذاردند و عرض کردند:  \r\nاین پولها را به مستحقش بدهید.\r\nحضرت داوود (ع) از آن ها پرسید : علت این که شما دسته جمعى این مبلغ را به اینجا آورده اید چیست ؟\r\nعرض کردند : ما سوار کشتى بودیم ، طوفانى برخاست ، کشتى آسیب دید و نزدیک بود غرق گردد و همه ما به هلاکت برسیم.\r\nناگهان پرنده اى دیدیم ، پارچه سرخ بسته اى به سوى ما انداخت ، آن را گشودیم ، در آن شال بافته دیدیم ، به وسیله آن مورد آسیب دیده کشتى را محکم بستیم.\r\nو کشتى بى خطر گردید و سپس طوفان آرام شد و به ساحل رسیدیم و ما هنگام خطر نذر کردیم که اگر نجات یابیم هر کدام صد دینار بپردازیم.\r\nو اکنون این مبلغ را که هزار دینار از ده نفر ماست به حضورت آورده ایم تا هر که را بخواهى ، به او صدقه بدهى.\r\nحضرت داوود (ع) به زن متوجه شد و به او فرمود: \r\nپروردگار تو در دریا براى تو هدیه مى فرستد، ولى تو او را ظالم مى خوانى ؟\r\nسپس ‍هزار دینار را به آن زن داد و فرمود : این پول را در تأمین معاش کودکانت مصرف کن ، خداوند به حال و روزگار تو ، آگاهتر از دیگران است.\r\n"},{"id":581,"category_id":6,"category_code":"s6","source_id":89,"title":"حیا در کجاست؟","content":"گویند: حضرت آدم (ع) نشسته بود، شش نفر آمدند. سه نفر طرف راستش و سه نفر دیگر طرف چپ وی نشستند. از اینها سه نفر سفید و سه نفر سیاه بودند.\r\nآدم به یکی از سفیدها که سمت راست او نشسته بود، گفت: تو کیستی؟ گفت: عقلم. فرمود: جای تو کجاست؟ گفت: مغز.\r\nاز دومی پرسید: تو کیستی؟ گفت: مهر هستم. آدم (ع) پرسید: جای تو کجاست؟ گفت: در دل\r\nاز سومی پرسید: تو کیستی؟ گفت: حیا هستم. آدم (ع) سؤال کرد: جای تو کجاست؟ گفت: در چشم.\r\nسپس آدم (ع) به جانب چپ نگاه کرد و از یکی از سیاهان سؤال کرد: تو کیستی؟ گفت: من تکبر هستم. پرسید: جای تو کجاست؟ گفت: در مغز.\r\n آدم (ع) پرسید: با عقل در یک جا هستید؟ گفت: من که آمدم، عقل می رود.\r\nاز دومی سؤال کرد: تو کیستی؟ گفت: حسد هستم.\r\n آدم (ع) پرسید: جای تو کجاست؟ گفت: در دل. پرسید: با مهر در یک جا هستید؟ گفت: من که آمدم، مهر می رود.\r\nاز سومی سؤال کرد: تو کیستی؟ گفت: طمع هستم. آدم (ع) پرسید: جای تو کجاست؟ گفت: در چشم. پرسید: با حیا در یک جا هستید؟\r\n گفت: من که داخل شوم، حیا خارج می شود.\r\n"},{"id":582,"category_id":6,"category_code":"s6","source_id":90,"title":"بشر قوی تر است","content":"هنگاميكه نمرود نتوانست با آتشيكه افروخت ابراهيم خليل عليه السلام را بيازارد و خود را در مقابل او عاجز ديد خداوند ملكى را بصورت بشر بسوى او فرستاد كه او را نصيحت كند ملك پيش نمرود آمد و گفت خوبست بعد از اين همه ستم كه بر ابراهيم روا داشتى و او را از وطن آواره كردى و در ميان آتش بدنش را افكندى اكنون ديگر رو بسوى خداى آسمان و زمين آورى و دست از ستم و فساد بردارى زيرا خداوند را لشگرى فراوان است و ميتواند با ضعفترين مخلوقات خود ترا با لشگرت در يك آن هلاك كند.\r\nنمرود گفت در روى زمين كسى را بقدر من لشگر نيست و قدرتش از من فزونتر نباشد. اگر خداى آسمان را لشگرى هست بگو فراهم نمايد تا با آنها جنگ كنيم . فرشته گفت تو لشگر خويش را آماده كن تا لشگر آسمان بيايد. نمرود سه روز مهلت خواست و در روز چهارم آنچه ميتوانست لشگر تهيه كند آماده نمود و در ميان بيابانى وسيع با آن لشگر انبوه جاى گرفت . آن جمعيت فراوان در مقابل حضرت ابراهيم عليه السلام صف كشيدند نمرود به ابراهيم از روى تمسخر گفت لشگر تو كجا است ؟ ابراهيم جوابداد در همين ساعت خداوند خواهد فرستاد.\r\nناگاه فضاى بيابان را پشه هاى فراوانى فرا گرفتند و بر سر لشگريان نمرود حمله كردند هجوم اين لشگر ضعيف قدرت سپاه قوى نمرود را در هم شكست و آنها را بفرار وادار نمود و مقدارى از آن پشه ها بسر و صورت نمرود حمله كردند. نمرود بسيار نگران شد و بخانه برگشت باز همان ملك آمد و گفت ديدى لشگر آسمان را كه بيك آن لشگر ترا درهم شكستند با اينكه از همه موجودات ضعيفترند اكنون ايمان بياور و از خداوند بترس والا ترا هلاك خواهد كرد.\r\nنمرود باين سخنان گوش نداد. خداوند امر كرد به پشه ايكه از همه كوچكتر بود. روز اول لب پائين او را گزيد و در اثر آن گزش لب او ورم كرد و بزرگ شد و درد بسيارى كشيد. بار ديگر آمد لب بالايش را گزيد بهمان طريق تورم حاصل شد و بسيار ناراحت گرديد عاقبت همان پشه ماءمور شد كه از راه دماغ بمغز سرش وارد شود و او را آزار دهد بعد از ورود پشه نمرود بسر درد شديدى مبتلا شد.\r\nهرگاه با چيز سنگينى بر سر خود ميزد پشه از كار دست ميكشيد و نمرود مختصرى از سر درد راحت ميگرديد. از اينرو كسانيكه در موقع ورود به پيشگاه او برايش سجده ميكردند بهترين عمل آنها بعد از اين پيش آمد آن بود كه با چكش مخصوصى در وقت ورود قبل از هر كار بر سر او بزنند تا پشه دست از آزار او بردارد و مقربترين اشخاص آنكس بود كه از محكم زدن كوبه و چكش هراس نكند بالاخره با همين عذاب رخت از جهان بربست و نتيجه كفر و عناد خويش را مقدار مختصرى دريافت.\r\n"},{"id":583,"category_id":6,"category_code":"s6","source_id":91,"title":"پیرمرد بهشتی","content":"نس می گوید: روزی در محضر رسول اکرم(ص) نشسته بودیم که حضرت به سمتی اشاره نمود و فرمود: به زودی مردی از این راه می آید که اهل بهشت است. چیزی نکشید که پیرمردی از راه رسید، در حالی که آب وضوی خویش را با دست راست خشک می کرد. پیش آمد و سلام کرد. فردای آن روز و هم چنین دو روز بعد، پیرمرد از راه آمد و رسول اکرم(ص) همان جمله را تکرار کرد.\r\nعبد الله بن عمر بن عاص ـ که در مجلس ها حضور داشت و سخن نبی گرامی اسلام(ص) را شنیده بود ـ تصمیم گرفت که بداند، چه چیزو ی او را بهشتی ساخته و سببب رفعت معنویتش شده است. از پی او راه افتاد و به وی گفت: من از پدرم قهر کردم قسم یاد نموده ام که سه شبانه روز به ملاقاتش نروم. اگر موافقت می کنی به منزل شما بیایم و این مدت را نزد شما بگذرانم! پیرمرد قبول کرد و پسر عمرو بن عاص به خانه او رفت و سه شب در آن جا بود.\r\nعبد الله می گوید: در این سه شب ندیدم، که پیرمرد برای عبادت برخیزد و اعمال مخصوص انجام دهد. فقط موقعی که در بستر پهلو به پهلو می شد، ذکر خدا می گفت. او تمام شب را می آرامید و چون فجر طلوع می کرد، برای نماز صبح بر می خاست. در این مدت از او درباره کسی، جز خیر و خوبی سخنی نشنیدم. سه شبانه روز تمام شد و اعمال پیرمرد در نظرم ناچیز آمد. قصد داشتم او را تحقیر کنم، ولی خودم را نگاه داشتم. هنگام خداحافظی به او گفتم، بین من و پدرم تیرگی و کدورتی پیش نیامده بود. برای آن نزد تو آمدم که سه روز پیاپی از رسول اکرم(ص) شنیدم که تو از اهالی بهشت هستی. خواستم تو را بشناسم و از عبادات و اعمالت آگاه گردم. اکنون متوجه شدم که عمل خاصی نداری. نمی دانم چه چیز مقام تو را آن قدر بالا برده که پیامبر گرامی درباره تو چنین گفته است.\r\nپیرمرد پاسخ داد: جز آن چه از من دیدی، عملی ندارم.\r\nپسر عمرو بن عاص از وی جدا شد و چند قدمی بیش تر نرفته بود که پیرمرد، او را صدا زد و گفت: اعمال ظاهری من همان بود که دیدی. اما، در دلم نسبت به هیچ مسلمانی کینه و بد خواهی نیست و هرگز به کسی ـ که خداوند به او نعمتی عطاء نموده است ـ حسد نبرده ام.\r\nپسر عمرو بن عاص گفت: همین حسن نیت و خیرخواهی است که تو را، مشمول عنایات و الطاف الهی ساخته و ما نمی توانیم، چنین پاکدل و انسان دوست باشیم.\r\n"},{"id":584,"category_id":6,"category_code":"s6","source_id":92,"title":"حضرت سليمان و گنجشك","content":"حضرت سليمان عليه السلام گنجشكى را ديد كه به ماده خود مى گويد\r\n- چرا از من اطاعت نمى كنى و خواسته هايم را به جا نمى آورى ؟ اگر بخواهى تمام قبه و بارگاه سليمان را با منقارم به دريا بيندازم توان آن را دارم! \r\nسليمان از گفتار گنجشك خنديد و آنها را به نزد خود خواست و پرسيد:\r\nچگونه مى توانى چنين كارى بزرگى را انجام دهى ؟\r\nگنجشك پاسخ داد:\r\n- نمى توانم اى رسول خدا! ولى مرد گاهى مى خواهد در مقابل همسرش به خود ببالد و خويشتن را بزرگ و قدرتمند نشان بدهد از اين گونه حرفها مى زند. گذشته از اينها عاشق را در گفتار و رفتارش نبايد ملامت كرد.\r\nسليمان از گنجشك ماده پرسيد:\r\n- چرا از همسرت اطاعت نمى كنى در صورتى كه او تو را دوست مى دارد؟\r\nگنجشك ماده پاسخ داد:\r\n- يا رسول الله ! او در محبت من راستگو نيست زيرا كه غير از من به ديگرى نيز مهر و محبت مى ورزد.\r\nسخن گنجشك چنان در سليمان اثر بخشيد كه به گريه افتاد و سخت گريست . آن گاه چهل روز از مردم كناره گيرى نمود و پيوسته از خداوند مى خواست علاقه ديگران را از قلب او خارج نموده و محبتش را در دل او خالص گرداند.\r\n"},{"id":585,"category_id":6,"category_code":"s6","source_id":93,"title":"روزه","content":"پس از آنکه حضرت مریم علیها السّلام از دنیا رفت، حضرت عیسی علیه السّلام جنازه ی او را پس از تجهیز به خاک سپرد، سپس روح مادرش را دید و گفت: مادر! آیا هیچ آرزویی داری؟\r\nمریم علیها السّلام پاسخ داد: آری، آرزویم این است که در دنیا بودم و شب های سرد زمستانی را با مناجات و عبادت در درگاه خدا به بامداد می رساندم و روزهای گرم تابستان را روزه می گرفتم.\r\n"},{"id":586,"category_id":6,"category_code":"s6","source_id":94,"title":"مهر و قهر","content":"روزی حضرت عیسی (ع) از راهی می گذشت. ابلهی با وی دچار شد و سخنی پرسید. بر سبیل تلطّف، جوابش باز داد، اما آن شخص آغاز عربده و سفاهت نهاد؛ چنان که او نفرین می کرد، عیسی تحسین می نمود... \r\nعزیزی بدان جا رسید، گفت: ای روح الله، چرا زبون این ناکس شده ای و هر چند او قهر می کند، تو لطف می فرمایی و با آن که او جور و جفا پیش می برد، تو مهر و وفایش می نمایی؟! عیسی گفت: ای رفیق موافق! «کلّ اناء یترشّح بما فیه؛ از کوزه همان برون تراود که در اوست». از او آن صفت می زاید و از من این صورت می آید. من از وی در غضب نمی شوم و او از من صاحب ادب می شود. من از سخن او جاهل نمی گردم و او از خُلق و خوی من عاقل می گردد.\r\n"},{"id":587,"category_id":6,"category_code":"s6","source_id":95,"title":"دوستداران دنیا","content":"حضرت عيسي عليه السلام به همراهي مردي سياحت مي كرد پس از مدتي راه رفتن گرسنه شدند به دهكده اي رسيدند عيسي به آن مرد گفت : برو ناني تهيه كن و خود مشغول نماز شد آن مرد رفته سه گرده نان تهيه كرد و بازگشت مقداري صبر كرد تا نماز عيسي پايان پذيرد چون كمي به طول انجاميد يك گرده را خورد. عيسي آمده پرسيد گرده سوم چه شد گفت : همين دو گرده بود.\r\n پس از آن مقدار ديگري راه پيموده به دسته آهويي برخوردند حضرت عيسي يكي از آنها را پيش خواند آن را ذبح كرده خوردند بعد از خوردن عيسي گفت : قم باذن الله به اجازه خدا حركت كن آهو حركت كرد و زنده گرديد آن مرد در شگفت شده زبان به كلمه سبحان الله جاري كرد عيسي گفت : ترا سوگند مي دهم به حق آن كسي كه اين نشانه قدرت را براي تو آشكار كرد بگو نان سوم چه شد باز جواب داد دو گرده بيشتر نبود.\r\nدو مرتبه براه افتادند نزديك دهكده بزرگي رسيدند در آنجا سه خشت طلا افتاده بود رفيق عيسي گفت اينجا ثروت و مال زيادي است آن جناب فرمود: آري يك خشت از تو يكي از من خشت سوم را اختصاص مي دهم به كسي كه نان سوم را برداشته مرد حريص گفت : من نان سومي را خوردم ، عيسي از او جدا گرديده گفت : هر سه خشت مال تو باشد.\r\nآن مرد كنار خشتها نشسته به فكر برداشتن و بردن آنها بود، سه نفر از آنجا عبور نمودند او را با سه خشت طلا ديدند. همسفر عيسي را كشته و طلاها را برداشتند. چون گرسنه بودند قرار بر اين گذاشتند يكي از آن سه نفر از دهكده ي مجاور ناني تهيه كند تا بخورند شخصي كه براي نان آوردن رفت با خود گفت : نانها را مسموم كنم تا آن دو پس از خوردن بميرند، دو نفر ديگر نيز هم شدند كه رفيق خود را پس از برگشتن بكشند.\r\nهنگاميكه نان را آورد آن دو نفر او را كشته و خود با خاطري آسوده بخوردن نانها مشغول شدند چيزي نگذشت كه آنها هم به رفيق خود ملحق گشتند. حضرت عيسي در مراجعت چهار نفر را بر سر همان سه خشت مرده ديد گفت : ((هكذا تفعل الدنيا باهلها)) اينست رفتار دنيا با دوستداران خود\r\n"},{"id":588,"category_id":6,"category_code":"s6","source_id":96,"title":"تجاوز به ناموس مردم","content":"آورده اند كه حضرت عيسى (عليه السلام) از گورستانى عبور مى كرد. گورى را ديد كه آتش از او شعله ور مى شود. حضرت عيسى (عليه السلام ) دو ركعت نماز به جا آورد و عصا بر گور زد. گور شكافته شد. شخصى را در ميان آتش ديد.\r\nحضرت عيسى (عليه السلام) گفت : اى مرد چه كرده اى كه بدين عذاب سخت گرفتار شده اى ؟\r\nآن مرد گفت : يا روح الله ! من مردى بودم كه به ناموس مردم تجاوز مى كردم ، چون وفات كردم و مرا دفن كردند، از حضرت حق خطاب رسيد كه وى را بسوزانيد. از آن روز تا كنون مرا مى سوزانند\r\nحضرت عيسى (عليه السلام) نگاهى كرد، مارى سياه و عظيم الجثه در گور وى ديد، پرسيد: كه با اين مسكين چه مى كنى ؟\r\nآن مار گفت : تا وى را دفن كردند از وى غايب نبوده ام همراه با زهرى كه اگر قطره اى از آن به رود نيل و فرات بريزد جمله آب ، قاتل شود.\r\nشخص معذب گفت : يا روح الله ! از حق تعالى درخواست كن تا بر من رحم نمايد.\r\nحضرت عيسى (عليه السلام) نيز از خداوند طلب رحمت نمود. خطاب رسيد كه : هر كه از پس زنان مردم رود ما او را عذابى كنيم كه كس ديگر را چنين عذابى نكرده باشيم ، اما چون تو از ما درخواست رحمت كردى ، ما او را به تو بخشيديم. \r\nعيسى به آن مرد گفت : مى خواهى كه با من باشى ؟\r\nآن مرد گفت : يا روح الله ! عاقبت چه چيزى است ؟\r\nحضرت عيسى فرمود: عاقبت مرگ است. \r\nآن مرد گفت : نمى خواهم زيرا صد سال است كه مرده ام اما هنوز تلخى جان كندن در كام من است.\r\n"},{"id":589,"category_id":6,"category_code":"s6","source_id":97,"title":"رد کردن مومن از در خانه","content":"امام رضا (عليه السلام) فرمود: در زمان بنى اسرائيل (در عصر يوشع وصى حضرت موسى (عليه السلام)) چهار نفر مؤمن زندگى مى كردند، سه نفر از آنها روزى در خانه يكى از آنها جلسه داشتند، چهارمين مؤمن كه مستمند و ناتوان (مثلا به نام اسماعيل ) بود به سوى آن خانه اى كه آنها جلسه داشتند آمد، و در خانه را زد، غلام صاحب خانه بيرون آمد.\r\nاسماعيل گفت : آقايت كجاست ؟\r\nغلام (به دروغ ) گفت : خانه نيست! \r\nاسماعيل از آنجا رفت و غلام نيز نزد آقايش (صاحبخانه ) برگشت ، آقايش ‍ به غلام گفت : چه كسى بود؟\r\nغلام گفت : اسماعيل بود و من به او گفتم : آقا منزل نيست ، صاحبخانه و دو نفر همراه او (كه جلسه سه نفرى داشتند) آن غلام را سرزنش نكردند، و اندوهگين نشدند كه مؤمنى را از در خانه ، رد كرده اند، بلكه به ادامه جلسه خود پرداختند (گويى هيچ گناهى انجام نشده است.) \r\nبامداد فرداى آن روز، آن سه نفر از خانه بيرون آمدند و به سوى مزرعه يا باغى كه از آن يكى از آنها بود حركت مى كردند.\r\nاسماعيل كه نزد آن سه نفر مى آمد، نزديك خانه با آنها ملاقات نمود و به آنها سلام كرد و گفت : اجازه بدهيد من نيز همراه شما بيايم.\r\nآن سه نفر گفتند: مانعى ندارد تو نيز با ما بيا، ولى نسبت به پيشامد روز گذشته از او عذرخواهى نكردند و با هم چهار نفرى به راه افتادند، در مسير راه ، ناگاه قطعه ابرى ، بالاى سر آنها آمد و بر سر آنها سايه افكند، آنها گمان كردند كه آن ابر نشانه باران است ، به راه رفتن خود سرعت دادند تا باران آنها را فرا نگيرد ناگهان در ميان آن قطعه ابر، ندا كننده اى فرياد زد: اى آتش ، اينها را در كام خود بگير. من جبرئيل فرستاده خدا هستم همان دم آتشى (صاعقه اى ) از درون آن ابر به سوى آنها آمد و آن سه نفر را در كام خود گرفت و به هلاكت رسانيد.\r\nاسماعيل چهارمين نفر آنها، تنها و هراسان در بيابان ماند و در مورد هلاكت سه دوست خود، در تعجب فرو رفت ، و راز هلاكت آنها را نمى دانست ، به شهر بازگشت و به حضور يوشع بن نون (وصى حضرت موسى (عليه السلام)) رفت ، و ماجراى هلاكت آن سه نفر و آنچه را ديده و شنيده بود، براى يوشع نقل كرد.\r\nيوشع به اسماعيل گفت : آيا نمى دانى كه خداوند، بر آن سه نفر خشم كرد، پس از آن كه از آنها خشنود گرديد؟ و اين مجازات ، نتيجه آن كارى بود كه با تو كردند.\r\nاسماعيل گفت : مگر با من چه كردند؟\r\nيوشع ، جريان رد كردن او را از در خانه خود، بيان كرد.\r\nاسماعيل گفت : من آنها را حلال كردم و بخشيدم. \r\nيوشع گفت : اگر اين گذشت تو قبل از نزول عذاب بود به حال آنها سود داشت ولى اكنون سودى به حالشان ندارد و شايد بعدا (در عالم برزخ يا قيامت ) به حال آنها سودى داشته باشد.\r\n"},{"id":590,"category_id":6,"category_code":"s6","source_id":98,"title":"عذاب","content":"حضرت عيسي (ع ) را گذر بر سر قبري افتاد، از خداوند درخواست كرد كه صاحب قبر را زنده فرمايد. همينكه زنده شد از او سو ال كرد حال و وضع تو چگونه است ؟ عرض كرد من حمال و باربر بودم روزي هيمه اي براي كسي ميبردم ؛ خلالي از آن جدا كردم تا دندان خود را با آن ، خلال كنم از آن زمان كه مرده ام عذاب همان خلال را ميكشم."},{"id":591,"category_id":6,"category_code":"s6","source_id":99,"title":"موعظه","content":"مردى محضر حضرت عيسى عليه السلام آمد و عرض كرد:\r\n-. مرتكب زنا شده ام ، مرا از گناه پاك كن \r\nعيسى عليه السلام دستور داد كه اعلام كنند تا تمام مردم را تطهير گناهكار حاضر شوند و براى مجازات وى گودالى كندند. وقتى همه جمع شدند و گناهكار در گودال اجراى قانون الهى قرار گرفت . نگاهى به جمعيت انبوه مردم انداخت كه همه آماده مجازات او بودند. با صداى بلند گفت: \r\nاى مردم ! هر كس خودش آلوده به گناه است و بايد كيفر ببيند، حق ندارد در مجازات من شركت كند.\r\nبا شنيدن اين جمله همه رفتند. تنها حضرت عيسى عليه السلام و حضرت يحيى عليه السلام ماندند. در اين هنگام يحيى عليه السلام پيش آمد و به آن مرد نزديك شد و گفت:\r\n-! اى گناهكار! مرا موعظه كن \r\nمرد گفت: \r\nاى يحيى ! مواظب باش خودت را در اختيار هواى نفست مگذارى ! زيرا سقوط كرده و بدبخت خواهى شد.\r\nيحيى عليه السلام گفت: \r\nموعظه اى ديگر بگو!\r\nمرد گفت: \r\nهرگز خطاكارى را به خاطر لغزشش ملامت مكن ! بلكه در فكر نجات او باش! \r\nحضرت يحيى عليه السلام گفت: \r\nباز هم موعظه كن! \r\nمرد گفت: \r\nاز به كار بردن غضبت خوددارى نما\r\nدر اين وقت حضرت يحيى گفت: \r\n- موعظه هايت مرا كفايت مى كند\r\n"},{"id":592,"category_id":6,"category_code":"s6","source_id":100,"title":"راضى به سه بلا","content":"حضرت عيسى عليه السلام به مردى كه نابينا و ابرص (پيس ) و مفلوج بود گذر كرد و ديد، كه گوشت تنش از جذام فرو ريخته است و مى گويد: شكر خدائى را كه مرا از بلاهائى كه بسيارى از مردم بدان گرفتارند عافيت داد!\r\nحضرت عيسى فرمود: اى مرد! كدام بلاست كه تو را از آن عافيت داد؟ گفت : اى روح الله  من از كسى كه در دل وى آن معرفت كه در دلم خداى قرار داده ندارد، بهترم! \r\nفرمود: راست گفتى ، دستت را بده ، دست او را گرفت و بر اندامش دست مبارك خود را ماليد، درست اندام و نيكو چهره گرديد و خداوند بيماريهاى - او را به خاطر راضى بودن به بلاها - شفا داد. وى بعدا مصاحب حضرت عيسى شد و با او عبادت مى كرد.\r\n"},{"id":593,"category_id":6,"category_code":"s6","source_id":101,"title":"حماقت ؛ مرضى علاج ناپذير","content":"حضرت عيسى عليه السلام مى فرمايد:\r\nمن بيماران را معالجه كردم و آنان را شفا دادم كور مادرزاد و مرض پيسى را به اذن خدا مداوا نموده و مردگان را زنده كردم ولى آدم احمق را نتوانستم اصلاح و معالجه كنم.\r\nپرسيدند: يا روح الله ! احمق كيست ؟\r\nفرمود: شخصى خودپسند و خودخواه است كه هر فضيلت و امتيازى را از آن خود مى داند و هر گونه حق را در همه جا به خود نسبت مى دهد و براى ديگران هيچ گونه احترامى قائل نمى شود و اين گونه آدم احمق هرگز قابل مداوا و اصلاح نيست.\r\n"},{"id":594,"category_id":6,"category_code":"s6","source_id":102,"title":"چگونگى مرگ هارون","content":"\r\nطبرسى از ابن عباس روايت كرده كه گفت : از اميرالمؤ منين (عليه السلام ) پرسيدند يا على (عليه السلام ) چگونه بنى اسرائيل موسى را اذيت و آزار كردند ولى خداوند او را تبرئه كرد، حضرت فرمود: روزى موسى (عليه السلام ) به همراه برادرش هارون به مكانى مى رفتند، وقتى به كوهى رسيدند، خداى تعالى هارون را قبض روح كرد، موسى وقتى بازگشت و به بنى اسرائيل خبر داد كه هارون وفات كرده ، بنى اسرائيل به موسى (عليه السلام ) گفتند: هارون را بردى و به قتل رساندى اكنون آمده اى و به ما مى گويى او وفات كرده ، تو حسادت مى كردى بر هارون ، چرا كه ما او را بيشتر دوست مى داشتيم زيرا او از تو به ما ملايم تر و سازگارتر بود. \r\nخداوند موسى (عليه السلام ) را از آن تهمت و افترا منزه ساخت و تبرئه كرد آن گونه كه امر كرد تا جسد هارون را بيرون آورده و بر محافل بنى اسرائيل گردانيدند، هارون مى گفت : اى بنى اسرائيل ! برادرم مرا نكشت من به مرگ خود وفات كردم ، پس از آن فرشتگان او را بردند و به مكانى دفن كردند كه كسى بر آن اطلاع پيدا نكرد.\r\n"},{"id":595,"category_id":6,"category_code":"s6","source_id":103,"title":"فرعون","content":"فرعون لحظات آخر که داشت در نیل غرق می شدهر چقدر از موسی (ع) کمک خواست موسی جوابش رانداد.\r\nخداوند به موسی (ع) فرمود: موسی تو به فرعون جواب ندادی چون او را خلق نکردی وبنده ی تو نیست اما اگر او به من استغاثه می کرد دستش را می گرفتم وبه فریادش می رسیدم.\r\n"},{"id":596,"category_id":6,"category_code":"s6","source_id":104,"title":"فرعون و هامان","content":"سرانجام فرعون با هامان نشست ، و وعده هاي حضرت موسي را به او گفت و در اين باره به مشورت پرداخت. \r\nهامان ناپاك ، وقتي اين سخن را از فرعون شنيد ، چند بار فرياد زد و گريه كرد و با دست به سر و صورتش زد و گفت : اي شاه بزرگ ، اين چه فكري است كه وارد سر تو شده است ، و اين چه حال زشتي است كه مي خواهد ترا به تباهي بكشد! \r\nهمه جهان در تحت تسخير تو است ، اميران مشرق و مغرب ، ماليات هاي فراوان به سوي تو سرازير مي كنند ، و شاهان جهان لب به خاك پايت مي نهند . همه تو را به عنوان معبود و مقصود مي پرستند و در برابر شكوه تو ، خاموش و آرام هستند. \r\nسوختن تو در هزار آتش بهتر از آنست كه تو با اين عظمت ، خدايي خود را رها كني و بنده موسي گردي ؟ \r\nاگر تو اين كار را بكني ، بردگان تو ، سرور تو گردند و چشم دشمنان روشن شود . آري فرعون با مشورت و همنشيني با هامان خويش را خدا مردم و به هشدار موسي اعتنايي نكرد و عاقبت به عذاب حق گرفتار شد.\r\n"},{"id":597,"category_id":6,"category_code":"s6","source_id":105,"title":"توبه ی گنهکار","content":"در زمان حضرت موسى عليه السلام در بنى اسرائيل به جهت نيامدن باران قحطى شد مردم خدمت حضرت موسى رسيدند و گفتند: براى ما نماز استسقاء (نماز باران) بخوان. حضرت موسى عليه السلام برخواست كه با قوم خود براى دعاى باران بروند و بيشتر از هفتاد هزار نفر بودند هرچه دعا كردند باران نيامد.\r\nحضرت موسى عليه السلام عرض كرد: خدايا چرا باران نمى آيد، مگر قدر و منزلت من نزد تو از بین رفته؟\r\nخطاب رسيد: نه، ليكن ميان شما يک نفر است كه چهل سال مرا معصيت مى كند. به او بگو از جمعيت خارج شود تا باران رحمتم را نازل كنم.\r\nموسى عليه السلام عرض كرد: الهى صداى من ضعيف است، چگونه به هفتاد هزار جمعيت برسد؟\r\nخطاب شد: اى موسى تو بگو من صداى تو را به مردم مى رسانم حضرت موسى به صداى بلند صدا زد: اى كسى كه چهل سال است معصيت خدا را مى كنى از ميان ما برخيز و بيرون رو كه خداوند به جهت شومى و بدى تو باران رحمتش را از ما قطع كرده.\r\nآن مرد عاصى برخواست نگاهى به اطراف كرد، ديد كسى بيرون نرفت. فهميد خودش بايد بيرون برود با خود گفت چه كنم اگر برخيزم و از ميان مردم بروم كه مردم مرا مى بينند و مى شناسند و رسوا مى شوم و اگر نروم كه خدا باران نمى دهد همانجا نشست و از روى حقيقت توبه كرد و از كرده خود پشيمان شد. يكدفعه ابرها آمده و به هم متصل شد و چنان بارانى آمد كه تمام سيراب شدند.\r\nموسى عرض كرد: الهى كسى كه از ميان ما بيرون نرفت چگونه شد كه باران آمد؟\r\nبه شما باران دادم، به سبب آن كسى كه شما را منع كردم و گفتم از ميان شما بيرون برود\r\nموسى عليه السلام عرض كرد: خدايا! اين بنده را به من بنما!\r\nخطاب شد: اى موسى آن وقتى كه مرا معصيت مى كرد رسوايش نكردم، حال كه توبه كرده او را رسوا كنم؟ حاشا، من نمامين و سخن چينان را دشمن مى دارم، خود نمامى كنم؟\r\n"},{"id":598,"category_id":6,"category_code":"s6","source_id":106,"title":"هرچه تو میخواهی","content":"یه روز حضرت موسی به خداوند متعال عرض کرد: من دلم میخواد یکی از اون بندگان خوبت رو ببینم. خطاب اومد: برو تو صحرا. اونجا مردی هست داره کشاورزی میکنه. او از خوبان درگاه ماست.\r\nحضرت اومد دید یه مردی هست داره بیل میزنه و کار میکنه. حضرت تعجب کرد که او چطور به درجه ای رسیده که خداوند میفرماید از خوبان ماست. \r\nاز جبرئیل پرسید. جبرئیل عرض کرد: الان خداوند بلائی بر او نازل میکند ببین او چی کار میکنه. بلا ای نازل شد که آن مرد در یک لحظه هر دو چشمش رو از دست داد. فورا نشست. \r\nبیلش رو هم گذاشت جلوی روش \r\nگفت: مولای من تا تو مرا بینا می پسندیدی من داشتن چشم را دوست می داشتم. \r\nحال که تو مرا کور می پسندی من کوری را بیش از بینایی دوست دارم.\r\nحضرت دید این مرد به مقام رضا رسیده. \r\nرو کرد به آن مرد و فرمود: ای مرد من پیغمبرم و مستجاب الدعوه.\r\nمیخوای دعا کنم خدا چشاتو بهت برگردونه؟\r\nگفت: نه\r\nحضرت فرمود: چرا؟\r\n: گفت\r\nآنچه مولای من برای من اختیار کرده بیشتر دوست دارم تا آنچه را که خودم برای خودم بخواهم.\r\n"},{"id":599,"category_id":6,"category_code":"s6","source_id":107,"title":"مكافات عمل","content":"در زمان حضرت موسى پادشاه ستمگرى بود كه وى به شفاعت بنده صالح ، حاجت مؤ منى را به جا آورد! از قضا پادشاه و مؤ من هر دو در يك روز از دنيا رفتند! مردم جمع شدند و پادشاه را با احترام دفن نمودند و سه روز مغازه ها را بستند و عزادار شدند.\r\nاما جنازه مؤ من در خانه اش ماند و حيوانى بر او مسلط گشت و گوشت صورت وى را خورد! پس از سه روز حضرت موسى از قضيه با خبر شد.\r\nموسى در ضمن مناجات با خداوند، اظهار نمود: بارالهى ! آن دشمن تو بود كه با همه عزت و احترام فراوان دفن شد، و اين هم دوست توست كه جنازه اش در خانه ماند و حيوانى صورتش را خورد! سبب چيست ؟\r\nوحى آمد كه اى موسى ! دوستم از آن ظالم حاجتى خواست ، او هم بجا آورد، من پاداش كار نيك او را در همين جهان دادم. \r\nاما مؤ من چون از ستمگر كه دشمن من بود، حاجت خواست ، من هم كيفر او را در اين جهان دادم ، حال ، هر دو نتيجه كارهاى خودشان را ديدند.\r\n"},{"id":600,"category_id":6,"category_code":"s6","source_id":108,"title":"مژده ی جبرئيل","content":"ابراهيم خليل مهمان دوست بود هر وقت مهمان برايش نمى آمد، به جستجويش مى پرداخت. \r\nروزى براى يافتن مهمان از خانه بيرون رفته بود، هنگامى كه به منزل برگشت ، شخصى را در خانه ديد.\r\nپرسيد: تو كيستى ؟ و با اجازه چه كسى وارد خانه شده اى ؟\r\nاو سه بار جواب داد: با اجازه پروردگار به خانه وارد شده ام. \r\nابراهيم فهميد او جبرئيل است . خدا را شكر نمود.\r\nجبرئيل : خداوند مرا به سوى بنده اى كه او را براى خود خليل (دوست خالص ) انتخاب كرده ، فرستاد تا به او مژده بدهم. \r\nابراهيم : او كيست تا دم مرگ خدمتگزارش باشم ؟\r\nجبرئيل : او تو هستى. \r\nابراهيم : براى چه من خليل خدا شده ام ؟\r\nجبرئيل : زيرا تو هرگز از كسى چيزى نخواستى ، و هرگز نشد كسى چيزى بخواهد و تو به او نداده باشى.\r\n"},{"id":601,"category_id":6,"category_code":"s6","source_id":109,"title":"جود زینب","content":"روزى ميهمانى براى اميرالمؤ منين (ع ) رسيد. آن حضرت به خانه آمده و فرمود: اى فاطمه ، آيا طعامى براى ميهمان خدمت شما مى باشد؟ عرض كرد: فقط قرض نانى موجود است كه آن هم سهم دخترم زينب مى باشد. زينب (س ) بيدار بود، عرض كرد: اى مادر، نان مرا براى ميهمان ببريد، من صبر مى كنم . طفلى كه در آن وقت ، كه چهار يا پنج سال بيشتر نداشته اين جود و كرم او باشد، ديگر چگونه كسى مى تواند به عظمت آن بانوى عظمى پى ببرد؟ زنى كه هستى خود را در راه خدا بذل بنمايد، و فرزندان از جان عزيزتر خود را در راه خداوند متعال انفاق بنمايد و از آنها بگذرد بايستى در نهايت جود بوده باشد."},{"id":602,"category_id":6,"category_code":"s6","source_id":110,"title":"باغ ضروان","content":"در زمانهاي گذشته ، مردي صالح و رباني و عاقبت انديش در روستايش بنام (ضروان ) ، نزديك يمن زندگي مي كرد . او صاحب كشتزار و باغ پرميوه بود . او از رسيدگي به زندگي مستمندان و احسان به آنها دريغ نمي كرد ، به طوري كه از محصول باغ و كشت خود ، به اندازه كفاف برمي داشت و براي سپاس از نعمتهاي خداوند بقيه را به فقرا مي داد. \r\nخانه او كعبه فقرا بود و بيشتر نيازمندان براي تاءمين نيازهاي خود ، همواره سراغ او را مي گرفتند.\r\nاين مرد رباني هر وقت كه صلاح مي ديد ، فرزندان خود را به دور خود جمع مي كرد و آنها را به رسيدگي و فقراء وصيت مي كرد و مي گفت : همه نعمتها از آن خداست و براي كسب رضايت او انفاق در راهش را از ياد نبريد. \r\nفرزندان ، از اين نوع وصيتها زياد شنيده بودند ، اما به دارايي مغرور بودند . سرانجام مرگ اين مرد فرا رسيد و از دنيا رفت . فرزندان نصيحت پدر را به فراموشي سپردند و پيمان بستند كه محصول باغ و مزرعه را بين خود تقسيم كنند و به فقراء ندهند.\r\nفقراء طبق معمول سالهاي گذشته هر روز به نزد آنان در باغ مي آمدند اما فرزندان مرحوم چيزي از نعمتهاي ارزاني شده را نمي دادند. \r\nخداوند بر آن خيره سران غضب كرد . هنوز روز برداشت محصول نرسيده بود كه صاعقه اي آتشين بر مزرعه و باغ آنها افتاد و همه را سوزاند . آنها وقتي كه صبح به سوي باغ رفتند ، ديدند همه سوخته است.\r\n"},{"id":603,"category_id":6,"category_code":"s6","source_id":111,"title":"گشایش پس از صبر","content":"بانوي بينوايي ، يگانه پسرش به سفر رفته بود ، و سفر او طولاني شد . او سخت نگران شده بود و به حضور امام صادق عليه السلام آمد و گفت : پسرم به مسافرت رفته و سفرش بسيار طول كشيده و هنوز برنگشته و بسيار نگرانم. \r\nامام فرمود : اي خانم صبر كن ، در پرتو آن خود را نگهدار . آن بانو رفت و پس از چند روز انتظار باز پسرش نيامد ، كاسه صبرش لبريز گرديد و به محضر امام آمد و گفت : پسرم نيامده ، سفرش طول كشيد ، چه كنم ؟ امام فرمود : مگر نگفتم صبر و مقاومت كن . گفت : سوگند به خدا صبرم به درجه آخر رسيده و ديگر تاب و توان صبر را ندارم! \r\nفرمود : اكنون به خانه ات برو كه پسرت آمده است . او سراسيمه به سوي خانه اش رفت ، و ديد پسرش از مسافرت بازگشته است ، بسيار خوشحال شد و با خود گفت : مگر بر امام وحي نازل مي شود ، او از كجا فهيد كه پسرم آمده است ؟ ! بروم اين موضوع را از خودش بپرسم. \r\nنزد امام آمد و عرض كرد : آري همانگونه كه خبر داديد پسرم از سفر آمده آيا بر شما وحي نازل مي شود كه چنين خبر پنهان را داديد ؟ \r\nفرمود : من اين خبر را از يكي از گفتار رسول خدا بدست آوردم كه فرمود : (هنگامي كه صبر انسان به پايان رسيد ، گشايش كار او فرا مي رسد.)\r\nاز اينكه صبر تو به پايان رسيده بود ، دريافتم كه گشايش مشكل تو فراهم شده است . از اين رو به تو گفتم : برو كه پسرت آمده است ، و خبر من مطابق با واقع گرديد.\r\n"},{"id":604,"category_id":6,"category_code":"s6","source_id":112,"title":"فروتنی سلمان","content":"حضرت (سلمان ) مدتي در يكي از شهرهاي شام امير (فرماندار) بود . سيره او در ايام فرمانداري با قبل از آن هيچ تفاوت نكرده بود ، بلكه هميشه گليم مي پوشيد و پياده راه مي رفت و اسباب خانه خود را تكفل مي كرد. \r\nيك روز در ميان بازار مي رفت ، مردي را ديد كه يونجه خريده بود و منتظر كسي بود كه آن را به خانه اش ببرد . سلمان رسيد و آن مرد او را نشناخت و بي مزد قبول كرد بارش را به خانه اش برساند. \r\nمرد يونجه را بر پشت سلمان نهاد ، و سلمان آن را مي برد . در راه مردي آمد و گفت : اي امير اين را به كجا مي بري ؟ آن مرد فهميد كه او سلمان است در پاي او افتاد و دست او را بوسه مي داد و مي گفت : مرا ببخش كه شما را نشناختم. \r\nسلمان فرمود : اين بار را به خانه ات بايد برسانم و رسانيد ، بعد فرمود : اكنون من به عهد خود وفا كردم ، تو هم عهد كن تا هيچكس را به بيگاري (عمل بدون مزد) نگيري و چيزي را كه خودت مي تواني ببري به مردانگي تو آسيبي نمي رساند.\r\n"},{"id":605,"category_id":6,"category_code":"s6","source_id":113,"title":"بخشش","content":"نقل شده است يک نفر اهل سامرا به دليلى كينه ورزيد پسر بزرگ مرحوم ميرزاى شيرازى را مضروب ساخت ميرزا محمد به علت اين ضربت در گذشت.\r\nميرزاى شيرازى در اين واقعه عكس العملى از خود نشان نداد، دشمنان اسلام واقعه را مورد توجه قرار دادند و خواستند براى ايجاد فتنه‏اى در دنياى اسلام از آن بهره‏بردارى كنند، بدين منظورعده‏اى به سامرا آمدند و به خدمت ميرزا رسيدند و از وى در خواست كردند تا در مورد از دست رفتن فرزندش اقدام كند و دستوراتى بدهد.\r\nميرزاى بزرگ به شدت آنان را از خود راند و فرمود: مى ‏خواهم خوب بفهميد شما حق نداريد در هيچ كس از امور مربوطه به ما مسلمانان مداخله كنيد اين يک قضيه ساده است كه ميان دو برادر اتفاق افتاده آن عده از حضور ميرزا مرخص شدند.\r\nاين جريان در آن ايام در استانبول به پاپ عالى رسيد خليفه عثمانى از اين موضعگيرى مرجع شيعه شادمان شد و به والى بغداد دستور داد كه خود به حضور ميرزا برسد و از وى تشكر كند و از وقوع حادثه اعتذار جويد و ابراز تاسف نمايد.\r\n"},{"id":606,"category_id":6,"category_code":"s6","source_id":114,"title":"بر بام خانه","content":" (خليفه دوم ) شبي در كوچه ها جستجو مي كرد تا از وضع عمومي اطلاع به دست آورد . گذرش به در خانه اي افتاد كه صدايي مشكوك از آن بلند است. \r\nاز ديوار خانه بالا رفت و مشاهده كرد ، مردي با زني نشسته و كوزه از شراب در پيش خود نهاده اند . با درشتي خطاب كرد : در پنهاني معصيت مي كنيد خيال مي كنيد خدا سر شما را فاش نمي كند ؟! \r\nمرد رو به خليفه كرد و گفت : عجله نكن ، اگر من يك خطا كرده ام از تو سه خطا سر زده است . اول ، خداوند قرآن مي فرمايد (تجسس نكنيد)  تو تفحص و پي گيري كردي . دوم در قرآن فرمود : (از در خانه ها وارد شويد)  تو از ديوار وارد شدي. \r\nسوم فرمود : (هر گاه وارد خانه شديد سلام كنيد)  تو سلام نكردي . خليفه گفت : اگر ترا ببخشم تصميم بكار نيك مي گيري ؟ جواب داد : آري به خدا ديگر اين عمل را تكرار نخواهم كرد .\r\n گفت : اكنون آسوده باشيد شما را بخشيدم.\r\n"},{"id":607,"category_id":6,"category_code":"s6","source_id":115,"title":"اهمیت قرآن","content":"رسول خدا صلى الله عليه و آله و سلم مى خواست گروهى را به جهاد بفرستد، خواست از بين آنان شخصى را امير لشكر قرار دهد، از يكايك آنان پرسيد: كه از قرآن چقدر مى دانيد؟\r\nهر كدام مقدارى را گفتند: تا نوبت به جوانى كه از همه كم سن و سال تر بود رسيد. گفت : اى رسول خدا من سوره بقره را مى دانم . حضرت فرمود: تو را امير لشكر قرار دادم. \r\nگفتند: يا رسول الله صلى الله عليه و آله ، اين جوان را بر ما، پير مردها، امير مى كنى ؟ حضرت فرمود: ((معه سوره البقره )) او سوره بقره را مى داند و شما نمى دانيد. \r\nو جاى بسى تعجب است ، كه اگر جوانى سوره اى از قرآن را بداند و پيران آن را ندانند، استحقاق فرماندهى بر آنان را پيدا مى كند! اما اگر جوانمردى چون على (عليه السلام ) همه علم قرآن و تورات و انجيل و زبور را داشته باشد و به فرموده رسول خدا صلى الله عليه و آله و سلم ((انا مدينه العلم و على بابها)). چنين شخصى را به جرم اين كه جوان است ، از حق مسلم و خدادادى اش محروم كنند! و زير بار امامتش نروند.\r\n"},{"id":608,"category_id":6,"category_code":"s6","source_id":116,"title":"مسیحی و قرآن","content":"سیّد قطب، دانشمند روشنفكر و مفسر قرآن كریم در ذیل آیه 38 سوره یونس این چنین نقل می‌كند: ما شش نفر بودیم كه با یك كشتی مصری عازم نیویورك شدیم. از صد و بیست سرنشین، فقط ما مسلمان بودیم. روز جمعه‌ای به این فكر افتادم كه با اجازه ناخدای كشتی، نماز جمعه را برپا كنیم. هنگامی كه خطبه‌های نماز را می‌خواندم. مسافران دیگر كشتی، دور تا دور ما جمع شده بودند و به سخنان من گوش می‌دادند. بعد از نماز، خانمی مسیحی كه اهل یوگسلاوی بود و به شدت تحت تأثیر قرار گرفته بود، با چشمان پر از اشك جلو آمد و گفت: زبانی كه شما با آن سخن می‌گفتید آهنگ و اثر خاصی داشت. ولی در میان سخنان شما، گاهی جملاتی وجود داشت كه موسیقی و آهنگ ویژه‌ای داشت و اثر عمیق‌تری بر من می‌گذاشت. به گونه‌ای كه لرزه بر اندامم می‌افتاد و من احساس می‌كردم، شما لبریز از روح‌القدس شده‌اید. مدتی كه فكر كردم، فهمیدم آن خانم مسیحی از آیات قرآنی كه در خطبه‌ها می‌خواندم، شدیداً متأثّر شده بود. این نكته، اعجاب مرا برانگیخت كه چطور خانمی كه هیچ عربی نمی‌داند، این گونه تحت تأثیر موسیقی قرآن قرار می‌گیرد؟!"},{"id":609,"category_id":6,"category_code":"s6","source_id":117,"title":"اهانت به قرآن","content":"آیت‌الله شیخ مجتبی قزوینی، رحمه‌الله علیه، عارف و استاد بزرگ اخلاق و معنویت، فرمودند:از صحن مبارك حضرت رضا، (ع)، عبور می‌كردم، شخصی را دیدم كه در یكی از غرفه‌های اطراف صحن، مشغول تلاوت قرآن بود، شخصی به او نزدیك شد و با پایش به دست او زد، قرآن به روی زمین پرت شد و با پرخاش گفت: این چیست كه خودت را به آن سرگرم كرده‌ای؟ من از این حادثه خیلی ناراحت شدم و ناگهان آیه‌ای به قلبم خطور كرد و دیدم كه آن مرد، در همان لحظه، دلش درد گرفت و ناله‌اش بلند شد. من به آن شخص نزدیك شدم و به او گفتم: آیه‌ای از قرآن كریم در نظرم آمد و تو را این‌گونه دردمند و عاجز كرده است. آیا این دلیل بر حقانیت قرآن نیست؟ آن شخص شروع به التماس كرد تا او را از آن حالت جانكاه بدر آورم. برایش دعا كردم و حالش خوب شد. مدتی از این ماجرا سپری شد. تا این كه یك روز، شخصی با ظاهری خداپسند، نزد من آمد و گفت: آیا مرا می‌شناسی؟ گفتم: خیر. گفت: من همان فردی هستم كه آن حادثه برایم پیش آمد و از آن روز به بعد، به بركت نفس قدس و قرآنی شما، در طریق هدایت قرار گرفتم و زندگیم كاملاً دگرگون شده است."},{"id":610,"category_id":6,"category_code":"s6","source_id":118,"title":"مرد بی نیاز","content":"شخصی به یکی از خلفا مراجعه و درخواست کرد تا در بارگاه او به کاری گمارده شود.\r\nخلیفه از او پرسید: قرآن می دانی؟\r\nاو گفت: نمی دانم و نیاموخته ام.\r\nخلیفه گفت: از به کار گماردن کسی که قرآن خواندن نیاموخته، معذوریم.\r\nمرد بازگشت و به امید دست یافتن به مقام مورد علاقه خود، به آموختن قرآن پرداخت. مدتی گذشت تا این که از برکت خواندن و فهم قرآن به مقامی رسید که دیگر نه در دل آرزوی مقام و منصب داشت و نه تقاضای ملاقات و دیدار با خلیفه.\r\nپس از چندی، خلیفه او را دید و پرسید: چه شده که دیگر سراغی از ما نمی گیری؟ آن آزاد مرد پاسخ داد: چون قرآن یاد گرفتم، چنان توانگر شدم که از خلق و از عمل بی نیاز گشتم. خلیفه پرسید: کدام آیه تو را این گونه بی نیاز کرد؟ مرد پاسخ داد: (من یتق الله یجعل له مخرجاً و یرزقه من حیث لا یحتسب)\r\nهر كس تقوای الهی را پیشه كند، خدا راه بیرون رفتن از سختی ها را برای او می گشاید\r\n"},{"id":611,"category_id":6,"category_code":"s6","source_id":119,"title":"خدایا خوابی؟","content":"فرعون فرمان داد ، تا يك كاخ آسمان خراش براي او بسازند ، دژخيمان ستمگر او هم مردم را از زن و مرد براي ساختن آن كاخ و بيگاري گرفته بودند ، حتي زنهاي آبستن از اين فرمان استثناء نشده بودند. \r\nيكي از زنان جوان كه آبستن بود ، سنگي سنگين را براي آن ساختمان حمل مي كرد و چاره اي جز اين نداشت. \r\nزيرا همه تحت كنترل ماءموران خونخوار بودند ، اگر او از بردن آن سنگها شانه خالي مي كرد ، زير تازيانه جلادان به هلاكت مي رسيد. \r\nآن زن جوان در برابر چنين فشاري قرار گرفت و بار سنگين سنگ را همچنان حمل مي كرد ، ولي ناگهان حالش منقلب شد و بچه اش سقط گرديد...\r\nدر اين تنگناي سخت از اعماق دل غمبارش ناله كرد و در حالي كه گريه گلويش را گرفته بود ، گفت : اي خدا آيا خوابي ؟ آيا نمي بيني اين طاغوت زورگو با ما چه مي كند ؟ \r\nچند ماهي از اين ماجرا نگذشت كه همين زن در كنار رود نيل نشسته بود كه ناگهان نعش فرعون را در روبروي خود ديد \r\nآن زن صداي هاتفي را شنيد كه به او گفت : هان اي زن ، ما در خواب نيستيم ما در كمين ستمگران مي باشيم.\r\n"},{"id":612,"category_id":6,"category_code":"s6","source_id":120,"title":"رضایت مادر","content":"رسول خدا صلي الله عليه و آله و سلم بر بالين جواني كه در حال مرگ بود ، حاضر شد و فرمود : اي جوان كلمه توحيد (لا اله الا الله ) بر زبان بياور . جوان زبانش بند آمده بود و قادر بود اداي توحيد نبود. \r\nپيامبر صلي الله عليه و آله و سلم خطاب به حاضرين فرمود : آيا مادر اين جوان در اينجا حاضر است ؟ \r\nزني كه در بالاي سر جوان ايستاده بود گفت : آري ، من مادر او هستم. \r\nرسول خدا صلي الله عليه و آله و سلم فرمود : آيا تو از فرزندت راضي و خشنود هستي ؟ گفت : نه ، من مدت شش سال است كه با او حرف نزده ام. \r\nفرمود : اي زن او را حلال كن و از او راضي باش ! گفت براي رضايت خاطر شما او را حلال كردم ، خداوند از او راضي باشد. \r\nپيامبر صلي الله عليه و آله و سلم رو به آن جوان نمود و كلمه توحيد را به او تلقين نمود . جوان بعد از رضايت مادر زبانش باز شد و به يگانگي خدا اقرار كرد.\r\nپيامبر صلي الله عليه و آله و سلم فرمود : اي جوان چه مي بيني ؟ گفت : مردي بسيار زشت و بدبو را مشاهده مي كنم و اكنون گلوي مرا گرفته است . پيامبر دعايي به اين مضمون به جوان ياد داد و فرمود : بخوان : (اي خدايي كه عمل اندك را مي پذيري و از گناه و خطاي بزرگ درمي گذري از من نيز عمل اندك را بپذير و از گناه بسيار من درگذر ، چرا كه تو بخشنده و مهرباني.) \r\nجوان دعا را آموخت و خواند؛ سپس پيامبر صلي الله عليه و آله و سلم پرسيد : اكنون چه مي بيني ؟ گفت : اكنون مردي (ملكي ) را مي بينم كه صورتي سفيد و زيبا و پيكري خوشبو و لباسي زيبا بر تن دارد و با من خوش رفتاري مي كند وبعد از دنيا رحلت كرد.\r\n"},{"id":613,"category_id":6,"category_code":"s6","source_id":121,"title":"تعجب دو ملک","content":" (دو ملك ) را ماءمور كرد تا شهري را سرنگون كنند . چون به آنجا رسيدند مردي را ديدند كه خدا را مي خواند و تضرع مي كند . يكي از آن دو فرشته به ديگري گفت : اين دعا كننده را نمي بيني ؟ گفت : چرا ، ولكن امر خداست بايد اجراء شود. \r\nاولي گفت : نه ، از خدا سوال كنم ، و از حق مساءلت كرد كه : در اين شهر بنده اي ترا مي خواند و تضرع مي كند آيا عذاب را نازل كنيم ؟ \r\nفرمود : امري كه دادم انجام دهيد ، آن مرد هيچگاه براي امر من رنگش تغيير نكرده و از كارهاي ناشايست مردم خشمگين نشده است.(امر به معروف ونهی از منکر نکرده)\r\n"},{"id":614,"category_id":6,"category_code":"s6","source_id":122,"title":"ازدواج موسی (ع)","content":"خورشید، هنوز زردی خود را داشت که جوان، خسته و کوفته با لباس های خاک آلود، کنار چاه آب رسید. دلو بزرگ و سنگین را داخل چاه انداخت. صدای «شالاپ» خوردن دلو به آب، امید او را بیش تر کرد. با زحمت بسیار دلو را بالا کشید.\r\nآب خورده و نخورده، متوجه صدایی شد. پارس سگ ها و زنگولە گوسفندها، موسیقی موزونی در فضا پخش کرده بود.\r\nچوپانان از فرط خستگی، به جوان سلام نکردند. دلو را به چاه انداخته و سه نفری آن را بالا کشیدند. باز هم نگاهی به جوان نکردند.\r\nجوان، رنج خستگی هشت روز پیاده روی را احساس می کرد. هشت روز دوندگی برای این که جانش را از خطر نابودی نگه دارد.\r\nموسی در درگیری، قصد کشتن کسی را نداشت. فقط در دفاع از حق و نجات مظلوم، مشتی بر سینه ظالم زد. زدن همان و جان دادن ظالم همان.\r\nنفسش بند آمد. جوان، دیگر ماندن را صلاح ندانست. می دانست اگر او را بیابند، بی درنگ او را خواهند کشت. از شهر خارج شد. اینک پس از نظاره هشت طلوع خورشید، به این شهر رسیده که جوانانش آن قدر مرام ندارند که به غریبه سلام کنند.\r\nجوانمردی را یک کاسه سر کشیده اند که زودتر از دختران چوپان، سراغ آب می آیند. انگار نه انگار که این دختران چوپان، از صبح در این گرمای طاقت فرسا، با گوسفندان همدم شده اند، تا لقمه نانی به دست آورند.\r\nدختران با زحمت بسیار، جلوی گوسفندان را گرفته بودند. جوان بی رمق به سمت دختران آمد. با صلابت گفت: کار شما چیست؟ چرا پیش نمی روید و گوسفندان را سیراب نمی کنید؟\r\nدختران بدون خیره شدن به جوان، گفتند:\r\n«ما گوسفندان خود را سیراب نمی کنیم، تا چوپانان همگی از کنار چاه بروند»\r\nفکری در ذهن جوان در تلاطم است؛ مگر پدر یا بزرگ تری ندارند که مجبورند این زحمت را تحمل کنند؟\r\nدنبال جواب می گشت که دختران گفتند: «پدر ما، مرد پیری است که شکسته و رنجور شده» این حرف ها، جوان را سخت ناراحت و آزرده ساخت. نگاهی تند به مردان کنار چاه انداخت و با اقتدار، گوسفندان را به سمت چاه راند.\r\nغیرت، بازوانش را توانمند ساخته و بی رمقی را از یادش برده بود. دلو آب را به تنهایی بالا کشید و با شتاب بسیار، گوسفندان دختران را که هنوز عقب ایستاده بودند، سیراب کرد.\r\nدختران نمی دانستند با چه زبانی تشکر کنند. گوسفندان را گرفته و روانه خانه شان شدند.\r\nجوان باز، بی رمقی را احساس کرد. زیر سایه آمد و به نجوا لب گشود: خدایا هر خیر و نیکی بر من فرستی، به آن نیازمندم.\r\nدختران نزدیک خانه آمدند، پدر هنوز به انتظار، گام زدن آغاز نکرده بود که صدای گله، او را به آمدن دختران عزیزش، خبر می دهد.\r\nدختران خوشحال به سراغ پدر پیرشان می شتابند.\r\n«دخترانم، عزیزانم، امروز زودتر به خانه آمدید؟»\r\nدختران لب به سخن می گشایند:\r\nجوان صالح و مهربانی، لطف کرد و گوسفندان را از ما گرفت و سیراب کرد.\r\nپدر با خود اندیشید:خدایا! این جوان با مروت کیست که پا در سرزمین مدائن نهاده است؟ آن گاه به دختر بزرگش گفت: دخترم به سراغش برو و بگو پدرم تو را می خواند، تا مزد کارت را بدهد.\r\nدختر نزدیک چاه آمد. جوان هم چنان زیر سایه درخت نشسته بود، دختر نزدیک آمد و گفت: پدرمان می خواهد مزد شما را بدهد.\r\nجوان با خود گفت:\r\nعجب مردی، چه حق شناس! حاضر نیست زحمت انسانی، حتی به اندازە کشیدن چند دلو آب بدون پاداش بماند\r\nبه خانه رسیدند. شعیب که پدر دختران است، با خوشحالی به استقبال می آید. «خوش آمدی جوان». سفرە غذا از قبل گسترده شده بود. جوان که چشمش به سفره غذا افتاد، دعایی که زیر درخت زمزمه کرده بود یادش آمد: خدایا محتاج خیر توأم.\r\nپیرمرد، از حال و احوال جوان پرسید که از کجایی و در این جا چه می کنی؟ جوان که جانی دوباره گرفته بود، شروع به درد دل کرد.\r\nشعیب با آرامش گفت: نترس که نجات یافته ای و دیگر کسی به سوی تو راهی ندارد.\r\nموسی برای استراحت آماده شد، تا در این فضای معنوی، خستگی این چند روز را از تن بیرون کند. خانه را سکوت و آرامش فرا گرفته بود تا مرد خدا اندکی بیارامد.\r\nهمان دختری که واسطه شده بود، تا موسی را به شعیب برساند، نزد پدر زانوی ادب زد و گفت:\r\n«پدر، این جوان، قدرتمند و درست کار است. او را استخدام کن، تا کمک کارمان باشد»\r\nبرق شادی در چشمان پدر نمایان شد. اما تعجب کرد که دخترش از کجا به درست کاری و امین بودن جوان پی برده است. با مهربانی پرسید:\r\nدخترم، قدرتش را از کشیدن دلو، آن هم به تنهایی دانستی. اما امین بودنش را از کجا دریافتی؟\r\nدختر، نگاهی به پدر انداخت و گفت:\r\n«از این که با ما دختران، بگو و بخند نکرد و در کمکش درخواستی نداشت و به ما خیره نشد.\r\nموسی از بستر استراحت جدا نشده بود که شعیب، مساله ازدواج او را با دخترش مطرح کرد. عرق شرم، جبین موسی را شست و سکوتش، قلب شعیب را پر شعف ساخت. اینک موسی داماد این خانه شده است.\r\n"},{"id":615,"category_id":6,"category_code":"s6","source_id":123,"title":"عزیر پیامبر","content":"یکی از پیامبران بنی اسرائیل حضرت عُزیر(ع) بود که نام مبارکش یک بار در قرآن آمده است و نامش در لغت یهود،عذرا گفته می شود.پدر و مادرش در منطقە بیت المقدس زندگی می کردند.خداوند دو پسر دوقلو به آنها داد که نام یکی را عزیر و نام دیگری را عُذره گذاشتند.عزیر و عذره با هم بزرگ شدند تا به سی سالگی رسیدند.عزیر(ع) پس از آنکه ازدواج کرد به قصد سفر از خانه بیرون آمد.پس از خداحافظی با بستگانش،اندکی انجیر و آب و میوە تازه با خود برداشت تا در سفر از آن بهره بگیرد.در بین راه به آبادی رسید که به طور وحشتناکی درهم ریخته و ویران شده بود و حتی استخوان های ساکنان آنجا نیز پوسیده شده بود.\r\nهنگامی که عزیر(ع)با دیدن این منظره وحشتناک به فکر معاد و زنده شدن مردگان افتاد و با خود گفت:چگونه خداوند این مردگان را زنده می کند؟البته او این سخن را از روی انکار نگفت بلکه از روی تعجب گفت:\r\nاو در این فکر بود که خداوند جانش را گرفت و در ردیف مردگان قرار داد.پس از صد سال،خداوند عزیر(ع) را زنده کرد.فرشته ای از جانب خدا آمد و از او پرسید: چقدر در این بیابان خوابیده ای؟ او که گمان می کرد ساعاتی بیش در آنجا استراحت کرده باشد در جواب گفت:یک روز یا کمتر!\r\nفرشته به او گفت:تو صد سال در اینجا بوده ای.اکنون به غذا و آشامیدنی خود بنگر که چگونه به فرمان خدا در تمام این مدت سالم مانده و هیچ آسیبی ندیده است.اما برای اینکه باور کنی به الاغ خود بنگر و ببین که چگونه با مرگ ،اعضای آن از هم متلاشی شده است و اینک ببین که خداوند چگونه اجزای پراکنده و متلاشی شده آن را دوباره جمع آوری کرده و زنده می کند.با دیدن این منظره عزیر گفت:می دانم که خداوند بر هر چیزی توانا است.اینک مطمئن شدم و مسأله معاد را با تمام وجودم حس کردم و قلبم سرشار از یقین شد.\r\nآنگاه عزیر سوار بر الاغ خود شد و به سوی خانه اش حرکت کرد در مسیر راه می دید که همه چیز تغییر کرده است.وقتی به زادگاه خود رسید دید که خانه ها و آدمها تغییر کرده اند با دقت به اطراف خود نگاه کرد تا مسیر خانه خود را یافت و به نزدیک منزل خود آمد.در آنجا پیرزنی لاغر اندام و خمیده قامت و نابینا را دید از او پرسید:آیا منزل عزیر همین جا است؟ پیرزن گفت:آری همین جا است.سپس به دنبال این سخن گریه کرد و گفت:دهها سال است که عزیر مفقود شده و مردم او را فراموش کرده اند چطور تو نام عزیر را به زبان آوردی؟ عزیر گفت:من خود عزیر هستم.خداوند صد سال مرا از این دنیا برد و جزء مردگان در آورد و اینک بار دیگر مرا زنده کرده است.\r\nآن پیرزن مادر عزیر بود که با شنیدن این سخن پریشان شد و گفت:صد سال قبل عزیر گم شد.اگر تو واقعا عزیر هستی و راست می گویی(او مردی صالح و مستجاب الدعوه بود) دعا کن تا من بینا شوم و ضعف پیری از من برود.عزیر دعا کرد.پیرزن بینا شد و سلامتی خود را بازیافت و با چشم تیزبین خود پسرش را شناخت و دست و پای پسرش را بوسید و سپس او را نزد بنی اسراییل برد.بزرگ قوم بنی اسراییل به عزیر گفت:ما شنیدیم هنگامی که بخت النصر،بیت المقدس را ویران کرد و تورات را سوزاند فقط چند نفر انگشت شمار حافظ تورات بودند.یکی از آنها عزیر(ع) بود.\r\nاگر تو همان عزیر هستی تورات را از حفظ بخوان.عزیر تورات را بدون کم و کاست و از حفظ خواند.آنگاه او را تصدیق کردند و به او تبریک گفتند و با او پیمان وفاداری به دین خدا بستند.امام باقر(ع) گفته است عزیر و عذره هر دو از یک مادر؛دوقلو بدنیا آمدند.عزیر در سی سالگی از آنها جدا شد و صد سال به مردگان پیوست و سپس زنده شد و نزد خاندانش بازگشت.او بیست سال دیگر با برادرش زیست و سپس باهم از دنیا رفتند در نتیجه عزیر پنجاه سال و عذره صد و پنجاه سال عمر کردند.\r\n"},{"id":616,"category_id":6,"category_code":"s6","source_id":124,"title":"نعمت بلا","content":"يكى از شاگردان مرحوم شيخ رجبعلى خياط مى گفت بعد از فوت مرحوم شيخ ايشان را در خواب ديدم از او سوال كردم ، در چه حالى ؟ گفت : فلانى ، من ضرر كردم ! با تعجب گفتم : تو ضرر كردى ، چرا؟ فرمود: زيرا خيلى از بلاها كه بر من نازل مى شد با توسل آنها را دفع مى كردم اى كاش حرفى نمى زدم چون الان مى بينم براى آنهايى كه در دنيا بلاها را تحمل مى كنند در اينجا چه پاداشى مى دهند."},{"id":617,"category_id":6,"category_code":"s6","source_id":125,"title":"عبادت","content":"\r\nهنگامى كه در آفريقاى غربى جنگ واقع شد، عده زيادى در اين جنگ كشته شدند.\r\nپس از پايان جنگ راهبى كه در آن نواحى بود از صومعه خويش بيرون آمد و چشمش به مردى افتاد كه مانند مرده اى بر روى زمين خوابيده است. نزديك او رفت. پس از دقت زياد او را زنده يافت و با زحمت فراوان به صومعه خودش منتقلش كرد.مدتى به معالجه او اشتغال داشت تا اينكه بهبودى حاصل نمود. راهب در مدت معالجه بنا به عادت خود و رسوم مذهبى شبانه روز را به نماز و دعا و مناجات مى گذرانيد، ولى سرباز مجروح پس از بهبودى هم هيچ گونه عملى از اعمال دين را انجام نمى داد. روزى راهب پرسيد: تو چرا پروردگارت را عبادت نمى كنى؟\r\nسرباز جواب داد: آيا پروردگار موهومى را كه وجود ندارد عبادت كنم؟ راهب از شنيدن اين سخن ساكت شد و هيچ نگفت تا مدتى گذشت.\r\nيك روز براى گردش از صومعه خارج شدند و در ميان بيابان قدم مى زدند. چشم راهب بر اثر قدم هاى حيوانى افتاد. پرسيد: اين چه اثرى است؟ سرباز جواب داد: محل پاى حيوانى است.\r\nراهب گفت: در اين بيابان من حيوانى نديده ام.\r\nسرباز مجروح جواب داد: غيرممكن است همين اثر كافى است در اينكه ثابت كند قطعا در اينجا حيوانى بوده و از اين محل عبور كرده است.\r\nراهب گفت: اثر پائى بر وجود حيوان دلالت مى كند، آيا اين آثار بديعه و اين مخلوقات محيرالعقول و اين كرات درخشان و ستارگان فروزان ((و رفت و آمد شب و روز)) بر قادرى توانا و صانعى حى و دانا دلالت نمى كند؟\r\nسرباز مجروح شرمنده شد و ايمان آورد و از حسن راهنمائى راهب تشكر كرد.\r\n"},{"id":618,"category_id":6,"category_code":"s6","source_id":126,"title":"حرمله","content":"قاسم بن اصبغ نقل مى كند هنگامى كه پس از ماجراى عاشورا در كربلا سرهاى شهيدان را به كوفه آوردند ناگاه سواره زيبا چهره اى را ديدم كه بر اسبى سوار شده بود و سر بريده جوانى نورانى كه هم چون ماه شب چهارده مى درخشيد را به قسمت جلو گردن اسبش بسته - هرگاه اسب سرش را به زمين نزديك مى كرد آن سر بريده به زمين مى خورد از او پرسيدم اين سر كيست گفت سر بريده عباس فرزند على بن ابيطالب است. \r\nپرسيدم تو كيستى گفتى من حرمله بن كاهل اسدى هستم پس از چند روز حرمله را ديدم كه چره اش سياه تر از قير شده است به او گفتم من چند روز قبل كه سر بريده عباس (عليه السلام ) را حمل مى كردى تو را زيبا و سفيد روى ديدم كه در ميان عرب بى نظير بودى ولى اينك كسى نيست كه چهره اش سياه تر و زشت تر از چهره تو بشد، او گريه سختى كرد و گفت سوگند به خدا از آن وقتى كه آن سر بريده را حمل كردم تا كنون هر شب دو نفر نزد من مى آيند و بازوى مرا مى گيرند و مرا به سوى آتشى كه زبانه مى كشد مى برند و در درون آن مى افكنند و من بر اثر عذاب آن به اين شكل در آمده ام كه مى بينى حرمله در اين حال بود تا اين كه مختار روى كار آمد دستور داد حرمله را دستگير كردند و آوردند دست ها و پاهايش را بريدند و او را به آتش سوزاندند.\r\n"},{"id":619,"category_id":6,"category_code":"s6","source_id":127,"title":"محاسبه ی نفس","content":"شخصی به نام توبه، بیشتر اوقات شب و روز از نَفَس خود حساب می کشید. روزی وی عمر خود را حساب کرد و دید شصت سال از عمرش گذشته است. آن را به روز حساب کرد و دریافت مدت 21500 روز از عمرش گذشته است. سپس با خود گفت: «وای بر من! اگر روزی یک گناه بیشتر نکرده باشم، خدای خود را در حالی دیدار می کنم که بیش از 21000 گناه مرتکب شده ام.» این سخن را با خود گفت و آه و فغانی از دل برکشید و بی هوش بر زمین افتاد و از دنیا رفت."},{"id":620,"category_id":6,"category_code":"s6","source_id":128,"title":"معرفت نور","content":"رنست رُنان، دانشمند بزرگ فرانسوی می گوید: در کتاب خانه شخصی خود هزاران جلد کتاب سیاسی - اجتماعی و غیر آن دارم که آنها را بیش از یک بار نخوانده ام، ولی یک جلد کتاب است که همیشه مونس من است و هر گاه احساس خستگی روحی می کنم و می خواهم درهایی از معارف و کمال بر روی من باز شود، آن را مطالعه می کنم و هیچ گاه از زیاد خواندن آن خسته نمی شوم؛ این کتاب، «قرآن»، کتاب آسمانی مسلمانان است."},{"id":621,"category_id":6,"category_code":"s6","source_id":129,"title":"هدیه برای مرده ها","content":"برخی از صحابه رسول خدا(ص) از آن حضرت نقل کرده اند که فرمود: «هدیه بفرستید برای مردگان خود!» پرسیدند: هدیه مرده ها چیست؟ پیامبر فرمود: «صدقه و دعا» و افزود: «ارواح مؤمنان هر جمعه به آسمان دنیا و به مقابل خانه های خود می آیند و به آواز حزین و با گریه فریاد می کنند: «ای اهل من و ای پدر من و مادر من و خویشان من! بر ما به آنچه بود و در دست ما بود، مهربانی کنید، از آنچه عذاب و حساب آن بر ماست و سودش برای غیر ما و هر یک فریاد می کنند خویشان خود را که بر ما به درهمی یا قرص نانی یا جامه ای مهربانی کنید که خداوند بپوشاند شما را از جامه بهشت!» پس پیامبر گریست و اصحاب گریستند و آن حضرت از شدت گریه قدرت سخن گفتن نداشت. سپس فرمود: «اینها برادران دینی شمایند که پس از سرور و نعمت، در خاک پوسیده شدند. پس ندا می کنند بر خود و می گویند: «وای بر ما! اگر انفاق می کردیم آنچه را که در دست ما بود، در طاعت و رضای خداوند، به شما محتاج نبودیم.» پس با حسرت و پشیمانی فریاد می کنند: زود بفرستید صدقه مردگان را."},{"id":622,"category_id":6,"category_code":"s6","source_id":130,"title":"در برابر طاغوت","content":"\r\nعبدالله بن سليمان مى گويد:\r\nمنصور دوانيقى يكى از عمال خود بنام (شيبة بن غفال ) را فرماندار مدينه ساخت . شيبه روز جمعه در مسجد پيامبر صلى الله عليه و آله بر فراز منبر رفت و خطبه خواند و گفت: \r\nعلى بن ابى طالب ميان مسلمانان اختلاف انداخت و با مؤمنين جنگيد و خواست حكومت را به دست گيرد و نگذارد به اهلش برسد. ولى خداوند او را از حكومت محروم ساخت و در آرزوى خلافت از دنيا رفت و پس از او فرزندانش در فتنه انگيزى دنباله روى او بوده و خواهان حكومتند، بدون آن كه شايستگى داشته باشد، بدين جهت هر كدام در يك گوشه زمين كشته مى شوند و در خون خود مى غلطند.\r\nسخنان شيبه بر مردم بسيار گران آمد، اما هيچ كس نتوانست چيزى بگويد، در اين وقت مردى كه پيراهن پشمين بر تن داشت از جا برخاست و گفت: \r\nما خدا را ستايش مى كنيم و بر پيامبر او و همه انبياء درود مى فرستيم. \r\nآنچه از خوبيها گفتى ، ما سزاوار آنها هستيم و آنچه از زشتى بر زبان آوردى ، تو و آنكس كه تو را به اينجا فرماندار گمارده (منصور) به آن سزاوار تريد.\r\nولى آگاه باش ! درست دقت كن ! تو كه بر مركب ديگرى سوار شده اى و نان ديگرى را مى خورى ، سرافكندگى و شرمسارى سزاوار توست. \r\nسپس رو به مردم كرد و گفت: \r\nآيا شما را آگاه نسازم چه كسى ميزان اعمالش در قيامت سبكتر و از همه بيشتر زيانكار خواهد بود؟\r\nآنكس كه آخرتش را به دنياى ديگرى بفروشد و اين فرماندار فاسق چنين است . (او آخرت خود را به دنياى منصور فروخته است.) \r\nمردم همه آرام شدند و فرماندار بدون آنكه چيزى بگويد، از مسجد خارج شد.\r\nآنگاه پرسيدم : اين شخص كه در برابر فرماندار چنين كوبنده سخن گفت ، كيست ؟\r\nگفتند: امام جعفربن محمد صادق است.\r\n"},{"id":623,"category_id":6,"category_code":"s6","source_id":131,"title":"آیه ی مناسب","content":"سلطان محمود غزنوی، گوری برای خود ساخت و به یکی از ندیمان گفت: آیه مناسبی از قرآن پیدا کن که بر روی سنگ گور خود حک کنم. ندیم تأملی کرد و گفت: بگو بر روی آن بنویسند:\r\nهذِهِ جَهَنَّمُ الَّتی کُنْتُمْ تُوعَدُونَ -یس63\r\nاین دوزخی است که به شما وعده داده بودند.\r\n"},{"id":624,"category_id":6,"category_code":"s6","source_id":132,"title":"سلطان پابرهنه","content":"روزی سلطان سلیمان که از سلاطین عثمانی بود، قصد زیارت مرقد پاک امام علی علیه السلام را کرد. او نزدیکی حرم، از اسب پایین آمد تا با پای پیاده به حرم برود. در این میان، یکی از همراهان بر او خرده گرفت که شما شأن خود را با این عمل پایین آورید، ولی سلطان گفت: احترام امیرمؤمنان علی علیه السلام بر من واجب است. آن فرد اصرار کرد تا به قرآن تفأل زده شود. سلطان نیز چنین کرد و این آیه در اول صفحه نمایان شد:\r\nفَاخْلَعْ نَعْلَیْکَ إِنَّکَ بِالْوادِ الْمُقَدَّسِ طُوًی؛ طه:12\r\nکفش هایت را درآور؛ چرا که در مکان مقدسی هست.\r\n"},{"id":625,"category_id":6,"category_code":"s6","source_id":133,"title":"عذاب یک مرجع تقلید","content":"یکی از استادان شیخ مرتضی آقا تهرانی نقل می کرد که در خواب ، مرحوم آیت الله حاج شیخ عبدالکریم حائری رحمة الله را دیدم . پرسیدم :آیا شما در آن عالم عذاب هم می شوید ؟ فرمود : یک عذاب دارم و آن این حسرت و غصه است که چرا بیشتر به یاد خدا نبودم. دلم برای آن لحظاتی می سوزد که به یاد خدا نبودم .این بزرگ ترین عذاب برای من است."},{"id":626,"category_id":6,"category_code":"s6","source_id":134,"title":"شفای جوان","content":"جناب پروفسور نجابت که هم اکنون ساکن کشور آلمان می باشد در مصاحبه با یکی از شبکه های تلویزیونی داستان جالبی از شفا گرفتن جوانی که برای مداوا به ایشان مراجعه کرده بود را بیان کرد. ایشان فرمود: روزی جوانی به نام درویش به من مراجعه کرد. او به علت اصابت ترکش به گردنش قادر به میل کردن غذا نبود و به محض اینکه چیزی میل می کرد تمامی آنها از گردن او خارج می شد. او که در ایران نتوانسته بود به صورت کامل معالجه شود برای مداوا به کشور آلمان سفر کرد. ایشان می گوید: من تمامی تلاش خودم را کردم تا او را مداوا کنم و در این امر تقریبا 80% موفق شدم ولی متأسفانه به طور کامل بهبودی او بازنگشت. او از فرط گرسنگی مانند نی شده بود و اگر همینگونه پیش می رفت زندگی اش به خطر می افتاد. روزی او را صدا زدم و به او گفتم: آقا درویش، من تمام تلاش خودم را برای سلامتی تو انجام دادم و دیگر از علم طب برای تو کاری بر نمی آید و وجودت در اینجا بی فایده می باشد . تو باید وسایل خود را جمع کنی و به مشهد خدمت امام رضا علیه السلام بروی و خود را خدمت حضرت دخیل ببندی تا که ایشان تو را شفا دهند. ایشان می گوید: تقریبا شش ماه بعد من در مطب خود نشسته بودم که جوانی وارد شد و در مقابل من نشست . کمی به او نگاه کردم.در ابتدا او را نشناختم چرا که او با آن درویش شش ماه قبل بسیار تفاوت کرده بود.جوانی که از فرط لاغری جانی در بدن نداشت به جوان زیبا و رشیدی تبدیل شده بود. داستان را از او پرسیدم و او گفت: آقای دکتر،همانطور که شما دستور دادید من همان روز ساکم را بستم و رفتم به طرف مشهد که خودم را دخیل ببندم و شفای خود را از امام رئوف بگیرم و همینطور هم شد. به او گفتم حال چرا به اینجا آمده ای،او گفت: آمدم به خاطر راهنمایی که به من کردید و جان مرا نجات دادید از شما تشکر کنم."},{"id":627,"category_id":6,"category_code":"s6","source_id":135,"title":"مرد یک چشم","content":"مردی که یک چشمش نابینا بود،به امام جماعتی اقتدا کرد.امام در نماز این آیه را خواند:﴿ألم نجعل لهُ عینین﴾؛آیا برای او دو چشم قرار ندادیم؟ مرد نابینا گفت:به خدا قسم،نه؛تنها یک چشم است.ای امام!دیگر این دفعه دروغ گفتی."},{"id":628,"category_id":6,"category_code":"s6","source_id":136,"title":"سفر مشهد","content":"علامه جعفری می‌گوید: فردی تعریف می‌کرد تو یکی از زیارتام که مشهد رفته بودم به امام رضا گفتم یا امام رضا دلم میخواد تو این زیارت خودمو از نظر تو بشناسم که چه جوری منو می‌بینی. نشونه‌شم این باشه که تا وارد صحنت شدم از اولین حرف اولین کسی که با من حرف می‌زنه من پیامتو بگیرم.وارد صحن که شدم خانممو گم کردم. اینور بگرد، اونور بگرد، یه دفه دیدم داره میره. خودمو رسوندم بهش و از پشت سر صداش زدم که کجایی؟ روشو که برگردوند دیدم زن من نیست. بلافاصله بهم گفت: «خیلی خری!» حالا منم مات شده بودم که امام رضا عجب رک حرف میزنه. زنه دید انگار دست‌بردار نیستم دارم نگاش می‌کنم گفتش :نه فقط خودت، پدر و مادر و جد و آبادتم خرند!"},{"id":629,"category_id":6,"category_code":"s6","source_id":137,"title":"بچه حوری","content":"توی همه آنهایی که مرا بخاطر کم سن‌وسالی اذیت می‌کردند یکی خیلی مرا سوزاند. هیچ وقت یادم نمی‌رود. آمد جلوی همه ،خیلی آرام و ساده و بدون کنایه گفت :\"تو اگر شهید بشوی آن دنیا یک بچه حوری گیرت می‌آید."},{"id":630,"category_id":6,"category_code":"s6","source_id":138,"title":"عروج مولا","content":"شخصى به نام حبيب بن عمر مى گويد: به عيادت حضرت امير عليه السلام در همان بيمارى كه از دنيا رفت رفتم ، نگاهى به جراحت (سر) آن حضرت انداختم و گفتم: \r\nيا اميرالمؤمنين اين زخم شما چيز (مهمى ) نيست ، و بر شما خوفى نيست ، حضرت فرمود: اى حبيب به خدا قسم من همين ساعت از ميان شما مى روم. \r\nام كلثوم دختر حضرت با شنيدن اين جمله گريان شد، حضرت فرمود: دخترم چرا گريه مى كنى ؟ جواب داد: بابا شما فرمودى همين ساعت از من جدا مى شوى ، حضرت فرمود: دخترم گريه نكن ، به خدا قسم اگر آنچه پدرت مى بيند ببينى گريه نمى كنى! \r\nحبيب گفت : عرض كردم يا اميرالمؤمنين شما چه مى بينى ؟ حضرت فرمود: ملائكه آسمان و پيامبران را مى بينم كه كنار يكديگر ايستاده ، همگى منتظرند مرا در آغوش بگيرند و اينك اين برادرم محمد صلى اللّه عليه و آله و سلم است كه نزد من نشسته و مى فرمايد:\r\nيا على  بيا آنچه در مقابل تو است از حالتى كه تو در آنى بهتر است. \r\nراوى گويد: از منزل خارج نشدم تا آنكه حضرت از دنيا رفت. \r\nفردا صبح امام مجتبى عليه السلام بر منبر رفت و پس از حمد و ثناى الهى فرمود: اى مردم شب گذشته قرآن نازل شد (شب بيست و سوم رمضان ) و در اين شب عيسى بن مريم به آسمان برده شد و در همين شب يوشع بن نون كشته شد و در اين شب اميرالمؤمنين (ع ) از دنيا رفت. \r\nبه خدا قسم از اوصياء و نه كسانى كه بعد از او (على عليه السلام ) مى آيند، بر او در وارد شدن به بهشت سبقت نگيرند.\r\nهر گاه پيامبر اكرم صلى اللّه عليه و آله و سلم او را به جنگ مى فرستاد، جبرئيل در طرف راست ، و ميكائيل در طرف چپ ، او را يارى مى دادند.\r\nآنگاه حضرت فرمود: او از مال دنيا طلا و نقره اى (هيچ پولى ) باقى نگذارد، مگر هفتصد درهم كه از سهم او زياد آمده بود و مى خواست براى خانواده اش خدمتكارى بگيرد.\r\n"},{"id":631,"category_id":6,"category_code":"s6","source_id":139,"title":"سگ انگلیسی","content":"در زمانی که نصرت الدوله وزیر دارایی بود، لایحه ای به مجلس آورد که به موجب آن، دولت ایران یکصد قلاده سگ از انگلستان خریداری و وارد کند. او شرحی در باره خصوصیات این سگ ها بیان کرد و گفت: این سگ ها شناسنامه دارند، پدر و مادر دارند، نژادشان معلوم است و به محض آن که دزد را ببینند، او را می گیرند. مدرس، پس از شنیدن توضیحات شاهزاده نصرت الدوله، دست را بر روی میز کوبید و گفت: مخالفم!\r\nوزیر دارایی گفت: آخر چرا هر چه لایحه می آوریم شما مخالفت می کنید; دلیلش چیست؟\r\nمدرس که تبسمی بر لبانش نقش بسته بود، پاسخ داد: مخالفت من، هم دلیل دارد و هم به سود شماست. مگر نگفتید این سگ ها به محض دیدن دزد، او را می گیرند، خوب، آقای وزیر دارایی! با ورود این سگ ها به ایران اول کسی که گرفتار آنها می شود خود شما هستید; پس مخالفت من به نفع شماست!\r\n"},{"id":632,"category_id":6,"category_code":"s6","source_id":140,"title":"عدالت علی","content":"\r\nيكى از خصوصيات حضرت على عليه السلام اين بود كه بيت المال را به طور مساوى ميان مردم تقسيم مى كرد و بين مسلمانان تبعيض قائل نمى شد؛ اين امر باعث شده بود، برخى از طرفداران تبعيض و انحصار طلبها به معاويه بپيوندند.\r\nعده اى از دوستان على عليه السلام به حضور حضرت رسيدند و گفتند:\r\n- چنانچه افراد سياس و انحصار طلبها را با پول راضى كنى ، براى پيشرفت امور شايسته تر است . امام على عليه السلام از اين پيشنهاد خشمگين شد فرمود:\r\n- آيا نظرتان اين است به كسانى كه تحت حكومت من هستند ظلم كنم و حق آنان را به ديگران بدهم و با تضيع حقوق آنان يارانى دور خود جمع نمايم ؟ به خدا سوگند! تا دنيا وجود دارد و آفتاب مى تابد و ستارگان در آسمان مى درخشند، اين كار را نخواهم كرد. اگر مال ، از آن خودم بود آن را به طور مساوى تقسيم مى كردم ، چه رسد به اينكه مال ، مال خداست. \r\nسپس فرمود:\r\n- اى مردم ! كسى كه كار نيك را در جاى نادرست انجام داد، چند روزى نزد افراد نا اهل و تاريك دل مورد ستايش قرار مى گيرد و در دل ايشان محبت و دوستى مى آفريند؛ ولى اگر روز حادثه بدى براى وى پيش بيايد و به ياريشان نيازمند شود، آنان بدترين و سرزنش كننده ترين دوستان خواهند شد.\r\n"},{"id":633,"category_id":6,"category_code":"s6","source_id":141,"title":"یتیم نوازی","content":"در اطراف بصره مردي فوت شد ، چون بسيار آلوده بود كسي براي تشييع جنازه او حاضر نگشت . زنش چند نفر را پول داد تا آمدند جنازه را بردند به قبرستان تا بدون نماز دفن كنند. \r\nدر آن جا زاهدي مشهور كه به صدق و صفا مشهور بود ، آمد بر جنازه او نماز خواند و بعد جنازه را دفن كردند. \r\nاين خبر به مردم شهر رسيد ، مردم دسته دسته نزد زاهد آمدند و از نماز بر جنازه گناهكار سو ال كردند! \r\nزاهد گفت : من در خواب ديدم كه به من گفتند : برو فلان محل جنازه اي مي آيد كه فقط يك زن همراه اوست بر او نماز بخوان. \r\nاز زن او پرسيدم شوهرت چه عملي داشت كه خداوند به تو ترحم كرد ؟ گفت : شرب خمر مي نمود اين بدي او بود . فرمود : كار خويش چه بود ؟ زن گفت : هر وقت از مستي بهوش مي آمد گريه مي كرد و مي گفت : خدايا كدام گوشه جهنم مرا جاي خواهي داد؛ و صبح كه مي شد لباس خود را عوض مي كرد و غسل مي كرد و وضو مي گرفت و نماز مي خواند. \r\nديگر عمل خوبش ، هيچگاه خانه او خالي از دو يا سه يتيم نبود ، آنقدر كه به يتيمان مهرباني و شفقت مي كرد ، به اطفال خود نمي كرد.\r\n"},{"id":634,"category_id":6,"category_code":"s6","source_id":142,"title":"جوانمردی مولا","content":"اين ابى الحديد گويد: در جنگ صفين هنگامى كه سپاه معاويه شريعه فرات را محاصره كردند و راه آب را بر آن حضرت بستند و سران شام به معاويه گفتند: بگذار همه از تشنگى بميرند چنانكه عثمان را تشنه كشتند، على (عليه السلام ) و يارانش از آنان خواستندكه راه آب را باز كنند، سپاه معاويه گفتند: نه ، به خدا سوگندتو را قطره اى نمى دهيم تا از تشنگى بميرى چنانكه عثمان لب تشنه جان سپرد. حضرت چون ديد ناگزير همه از تشنگى خواهند مرد، با ياران خود بر سپاه معاويه حملاتى پى در پى انجام داد تا پس از كشتارى فراوان كه سرها و دستها از بدن جدا شدند، آنان را از جاى خود دور كرد و خودشان بر آب دست يافتند و ياران معاويه در زمين خشك و بى آبى قرار گرفتند، ياران و شيعيان عرض ‍ كردند: اى امير مؤمنان ، آب را از آنان دريغ ‌دار چنانكه آنان دريغ داشتند و قطره اى آب به آنان مده و با تيغ عطش آنان را از پاى درآر و همه را دستگير كن كه ديگر نيازى به جنگ نيست . فرمود: نه ، به خدا سوگند من با آنان مقابله به مثل نمى كنم ، قسمتى از آب را براى آنان آزاد كنيد. زيرا كه لبه تيز تيغ ما براى آنان كافى است ."},{"id":635,"category_id":6,"category_code":"s6","source_id":143,"title":"خزیمه","content":"خزيمه (ابرش ) پادشاه عرب بدون مشورت پادشاه روم كه از دوستان صميمي وي بود كاري انجام نمي داد رسول را به نزد او فرستاد ، و از او درباره فرزندانش مشورت و نظر خواست او در نامه اش نوشت : من براي هر يك از دختران و پسران خويش مالي زياد و ثروتي فراوان قرار دادم كه بعد از من درمانده و مستمند نشوند . صلاح شما در اين كار چيست ؟ \r\nپادشاه روم جواب فرستاد كه : ثروت ، معشوق بي وفاست و دوام ندارد ، بهترين خدمت به فرزندان اين است كه ، آنان را از مكارم اخلاق و خويهاي پسنديده برخوردار كنيد ، تا در دنيا سبب دوام دولت و در آخرت سبب غفران باشد.\r\n"},{"id":636,"category_id":6,"category_code":"s6","source_id":144,"title":"معجزه ی حرم","content":"آقای شیخ عبدالله موسیانی از حضرت آیت الله العظمی مرعشی نجفی نقل کردند: «شب زمستانی بود که من دچار بی خوابی شدم; خواستم حرم بروم; دیدم بی موقع است; آمدم خوابیدم و دست خود را زیر سرم گذاشتم که اگر خوابم برد، خواب نمانم; در عالم خواب دیدم خانمی وارد اطاق شد . قیافه او را به خوبی دیدم ولی آن را توصیف نمی کنم . او به من فرمود: «سید شهاب! بلند شو و به حرم برو، عده ای از زوار من پشت در حرم ازسرما هلاک می شوند، آنها را نجات بده .» ایشان می فرماید: «من به طرف حرم راه افتادم; دیدم پشت درشمالی حرم (طرف میدان آستانه) عده ای زوار اهل پاکستان یا هندوستان در اثر سردی هوا پشت در حرم دارند به خود می لرزند; در را زدم، حاج آقا حبیب - که جزو خدام حرم بود - با اصرار من در را باز کرد; من از مقابل (جلو) و آنها هم پشت سر من وارد حرم شدند و در کنار ضریح آن حضرت به زیارت و عرض ادب پرداختند; من هم آب خواستم و برای نماز شب و تهجد وضو ساختم."},{"id":637,"category_id":6,"category_code":"s6","source_id":145,"title":"سرلشکر ترک","content":"عصر خلافت واثق بود او سپاه عظيم را به فرماندهى يكى از سرلشگران براى سركوب اعراب شورشى اطراف مدينه به حجاز فرستاد. سپاه او وارد مدينه شدند امام هادى (عليه السلام ) به اطرافيان خود فرمود برويم تا از نزديك لشگر كشى اين فرمانده را بنگريم. \r\nابوهاشم مى گويد همراه امام هادى (عليه السلام ) سوار بر مركب از خانه بيرون آمديم و در كنار عبور لشگر واثق ايستاديم يكى از سرلشگران سوار بر اسب از نزد ما عبور كرد امام هادى (عليه السلام ) چند جمله به زبان تركى به او فرمود:\r\nهمان دم ديدم آن سرلشگر ترك از اسبش پياده شد و سم مركب امام هادى (عليه السلام ) را بوسيد من تعجب كردم خود را به آن نظامى ترك نزديك نمودم به او گفتم تو را قسم مى دهم بگو بدانم امام هادى (عليه السلام ) به تو چه گفت كه تو اين گونه شيفته آن حضرت شدى سرلشگر ترك گفت آيا اين شخص پيغمبر است گفتم نه گفت او مرا به نامى صدا زد كه در كودكى در شهرهاى ترك نشين مرا به آن نام مى خواندند و تا اين ساعت هيچ كس به آن اطلاع نداشت.\r\n"},{"id":638,"category_id":6,"category_code":"s6","source_id":146,"title":"آیت الله نخودکی","content":"در آن روزي که آية الله نخودکي وفات کرد، يکي از زنان مسيحي در وفات آية الله نخودکي بسيار گريه و ناله مي‌کرد. به او گفتند: تو مسيحي هستي و آية الله نخودکي روحاني مسلمان، چرا در مرگ او چنين مي‌کني. آن زن گفت: اين دو دخترم مريض بودند و پزشکان گفتند: اين دو زنده نمي‌مانند. حتي پزشکان آمريکايي هم جواب کردند و رفته رفته حال اين دو دختر سخت‌تر شد و به حال جان کندن افتادند. همسايه ما وقتي حال مرا پريشان ديد گفت: تو براي شفاي اين دو دختر برو نزد آية الله نخودکي و از او شفا بگير. به روستاي نخودک رفتم، به خانه آن جناب رسيدم و عرض حال کردم. آية الله نخودکي گفت: اين دو انجير را بگير و به آن زن مسلمان که همسايه توست و تو را به اينجا هدايت کرده بده تا با وضو به دخترانت بخوراند. گفتم: آنان قادر به خوردن نيستند. آية الله نخودکي گفت: در آب حل کنند و به او بخورانند. به شهر بازگشتم و انجيرها را به آن زن مسلمان دادم. او انجيرها را در آب حل کرد و در دهان دخترانم ريخت. دخترانم پس از چند لحظه چشم گشودند و شفا يافتند."},{"id":639,"category_id":6,"category_code":"s6","source_id":147,"title":"بشر حافی","content":"روزي حضرت كاظم عليه السلام از در خانه (بشر حافي ) در بغداد مي گذشت كه صداي ساز و آواز و رقص را از آن خانه شنيد. \r\nناگاه كنيزي از آن خانه بيرون آمد و در دستش خاكروبه بود و بر كنار در خانه ريخت . امام فرمود : اي كنيز صاحب اين خانه آزاد است يا بنده ؟ عرض كرد : آزاد است . فرمود : راست گفتي اگر بنده بود از مولاي خود مي ترسيد. \r\nكنيز چون برگشت (بشر حافي ) بر سر سفره شراب بود و پرسيد : چرا دير آمدي ؟ كنيز جريان ملاقات را با امام نقل كرد. \r\nبشر حافي با پاي برهنه بيرون دويد و خدمت آن حضرت رسيد و عذر خواست و اظهار شرمندگي نمود و از كار خود توبه كرد.\r\n"},{"id":640,"category_id":6,"category_code":"s6","source_id":148,"title":"جن برادر انس","content":"امام باقر عليه السلام فرمود : جماعتي از مسلمين به سفري رفتند و راه را گم كردند تا بسيار تشنه شدند. \r\nاز جاده به كناري رفتند و كفن پوشيدند و خود را به ريشه هاي درختان (مرطوب ) چسبانيدند. \r\nپيرمردي سفيد پوشي نزد آنها آمد و گفت : برخيزيد ، باكي بر شما نيست ، اين آب است . آنها برخاستند و آشاميدند و سير آب گشتند. \r\nگفتند : اي پيرمرد خدا ترا رحمت كند تو كيستي ؟ گفت : من از طايفه جني هستم كه با رسول خدا صلي الله عليه و آله بيعت كردند . از پيامبر صلي الله عليه و آله شنيدم كه مو من برادر مو من ، و چشم و راهنماي اوست ، شما نبايد با بودن من از تشنگي از بين برويد.\r\n"},{"id":641,"category_id":6,"category_code":"s6","source_id":149,"title":"مادر شیطانها","content":"سيد نعمت الله جزايري در كتابش نقل مي كند : كه در يك سال قحطي شد ، در همان وقت واعظي در مسجد بالاي منبر مي گفت : كسي كه بخواهد صدقه بدهد ، هفتاد شيطان ، به دستش مي چسبند و نمي گذارند كه صدقه بدهد. \r\nمو مني اين سخن را شنيد و با تعجب به دوستانش گفت : صدقه دادن كه اين حرفها را ندارد ، من اكنون مقداري گندم در خانه دارم ، مي روم آنرا به مسجد آورده و بين فقراء تقسيم مي كنم. \r\nبا اين نيت از جا حركت كرد و به منزل خود رفت . وقتي همسرش از قصد او آگاه شد شروع كرد به سرزنش او ، كه در اين سال قحطي رعايت زن و بچه خود را نمي كني ؟ شايد قحطي طولاني شد ، آن وقت ما از گرسنگي بميريم و . . . خلاصه بقدري او را ملامت و وسوسه كرد تا سرانجام مرد مو من دست خالي به مسجد برگشت. \r\nاز او پرسيدند چه شد ؟ ديدي هفتاد شيطان به دستت چسبيدند و نگذاشتند.  \r\nمرد مو من گفت : من شيطانها را نديدم ولي مادرشان را ديدم كه نگذاشت اين عمل خير را انجام بدهم. \r\nپيامبر فرمود يا علي آيا مي داني كه صدقه از ميان دستهاي مومن خارج نمي شود مگر اينكه هفتاد شيطان به طريق مختلف او را وسوسه مي كنند، تا صدقه ندهد. \r\n"},{"id":642,"category_id":6,"category_code":"s6","source_id":150,"title":"برخورد با مردم","content":"مرحوم شيخ طوسى رضوان اللّه تعالى عليه در كتاب رجال خود آورده است: \r\nدر يكى از روزها، عدّه اى از دوستان امام رضا عليه السلام در منزل آن حضرت گرد يكديگر جمع شده بودند و يونس بن عبدالرّحمن نيز كه از افراد مورد اعتماد حضرت و از شخصيّت هاى ارزنده بود، در جمع ايشان حضور داشت. \r\nهنگامى كه آنان مشغول صحبت و مذاكره بودند، ناگهان گروهى از اهالى بصره اجازه ورود خواستند.\r\nامام عليه السلام ، به يونس فرمود: داخل فلان اتاق برو و مواظب باش هيچ گونه عكس العملى از خود نشان ندهى ؛ مگر آن كه به تو اجازه داده شود.\r\nآن گاه اجازه فرمود و اهالى بصره وارد شدند و بر عليه يونس ، به سخن چينى و ناسزاگوئى آغاز كردند.\r\nو در اين بين حضرت رضا عليه السلام سر مبارك خود را پائين انداخته بود و هيچ سخنى نمى فرمود؛ و نيز عكس العملى ننمود تا آن كه بلند شدند و ضمن خداحافظى از نزد حضرت خارج گشتند.\r\nبعد از آن ، حضرت اجازه فرمود تا يونس از اتاق بيرون آيد.\r\nيونس با حالتى غمگين و چشمى گريان وارد شد و حضرت را مخاطب قرار داد و اظهار داشت: \r\nياابن رسول اللّه ! من فدايت گردم ، با چنين افرادى من معاشرت دارم ، در حالى كه نمى دانستم درباره من چنين خواهند گفت ؛ و چنين نسبت هائى را به من مى دهند.\r\nامام رضا عليه السلام با ملاطفت ، يونس بن عبدالرّحمان را مورد خطاب قرار داد و فرمود: اى يونس ! غمگين مباش ، مردم هر چه مى خواهند بگويند، اين گونه مسائل و صحبت ها اهميّتى ندارد، زمانى كه امام تو، از تو راضى و خوشنود باشد هيچ جاى نگرانى و ناراحتى وچود ندارد.\r\nاى يونس ! سعى كن ، هميشه با مردم به مقدار كمال و معرفت آن ها سخن بگوئى و معارف الهى را براى آن ها بيان نمائى. \r\nو از طرح و بيان آن مطالب و مسائلى كه نمى فهمند و درك نمى كنند، خوددارى كن.\r\nاى يونس ! هنگامى كه تو دُرّ گرانبهائى را در دست خويش دارى و مردم بگويند كه سنگ يا كلوخى در دست تو است ؛ و يا آن كه سنگى در دست تو باشد و مردم بگويند كه درّ گرانبهائى در دست دارى ، چنين گفتارى چه تاءثيرى در اعتقادات و افكار تو خواهد داشت ؟\r\nو آيا از چنين افكار و گفتار مردم ، سود و يا زيانى بر تو وارد مى شود؟\r\nيونس با فرمايشات حضرت آرامش يافت و اظهار داشت : خير، سخنان ايشان هيچ اهميّتى برايم ندارد.\r\nامام رضا عليه السلام مجدّدا او را مخاطب قرار داد و فرمود:\r\nاى يونس ، بنابر اين چنانچه راه صحيح را شناخته ، همچنين حقيقت را درك كرده باشى ؛ و نيز امامت از تو راضى باشد، نبايد افكار و گفتار مردم در روحيّه ، اعتقادات و افكار تو كمترين تاثيرى داشته باشد؛ مردم هر چه مى خواهند، بگويند.\r\n"},{"id":643,"category_id":6,"category_code":"s6","source_id":151,"title":"پاسخ ابوذر","content":"روايت شده يك نامه بدست ابوذر رسيد كه اين نامه از راه دور آمده، شخصى تقاضاى موعظه كرده چون ابوذر را كاملا می‏شناخت كه مورد علاقه رسول الله است، ابوذر يك جمله نوشت و آن اين است: با آن كسى كه بيش از همه مردم او را دوست می‏دارى با او بدى و دشمنى مكن، فرستاد آن شخص نامه را خواند سر در نياورد كه مقصود ايشان از اين جمله چيست؟\r\nاين معلوم و روشن است كه انسان با دوست خود دشمنى نمی‏كند، اين چطور جمله است، از طرفى فكر كرد كه گوينده اين كلام ابوذر است چاره نيست بايد توضيح خواست.\r\nابوذر نوشت مقصودم از محبوب‏ترين افراد همان خودت هستى، يعنى: با خودت دشمنى مكن چون هر گناه كه انسان میكند صدمه‏اش بر خودش وارد می‏شود.\r\n"},{"id":644,"category_id":6,"category_code":"s6","source_id":152,"title":"امیر تیمور گورگان","content":"امير تيمور گورگان  در هر پيشامدي آن قدر ثبات قدم داشت كه هيچ مشكلي سد راه وي نمي شد . علت را از او خواهان شدند ، گفت: \r\nوقتي از دشمن فرار كرده بودم و به ويرانه اي پناه بردم ، در عاقبت كار خويش فكر مي كردم ؛ ناگاه نظرم بر موري ضعيف افتاد كه دانه غله اي از خود بزرگتر را برداشته و از ديوار بالا مي برد. \r\nچون دقيق نظر كردم و شمارش نمودم ديدم ، آن دانه شصت و هفت مرتبه بر زمين افتاد ، و مورچه عاقبت آن دانه را بر سر ديوار برد . از ديدار اين كردار مورچه چنان قدرتي در من پديدار گشت كه هيچگاه آنرا فراموش نمي كنم. \r\nبا خود گفتم : اي تيمور تو از موري كمتري نيستي ، برخيز و درپي كار خود باش ، سپس برخاستم و همت گماشتم تا به اين پايه از سلطنت رسيدم.\r\n"},{"id":645,"category_id":6,"category_code":"s6","source_id":153,"title":"ایمان زن وحجاب","content":"در زمان يكى از خلفاى بنى عباس بر اثر ندادن ماليات بر اهل بلخ غضب كرد مردى را طلب كرد بعنوان فرماندار آن شهر روانه كرد و گفت: تا مى‏توانى بر مردم آنجا سخت بگيريد و ترحم بر آناتن روا مداريد تا اينكه ماليات را بدهند.\r\nفرماندار روانه شد به شهر بلخ و فرمانى صادر گرديد كه هرچه زودتر ماليات را بدهيد و الا عقوبت و زندان جاى شماست با اين گفتار در ميان مردم سر و صداها بلند شد و ديگر آرامش نداشتند مردم فلك زده بلخ هرچه فكر كردند چاره نديدند تا اينكه شورا كردند كه بروند دامن عيال فرماندار را بگيرند تا شايد راه چاره‏اى پيدا شود.\r\nعده‏اى حركت كردند به طرف عيال فرماندار و مطلب را اظهار كردند كه ما بيچاره‏ايم قدرت دادن ماليات را نداريم، اين وضع رقت بار زنهاى بى سرپرست تاثيرى در روحيه آن زن با ايمان ايجاد كرد، زن با ديدن اين منظره پيراهن مرصع به جواهر كه براى مجالس عروسى تهيه كرده بود به شوهر داد به جاى ماليات مردم بلخ به نزد خليفه عباسى فرستاد كه از مردم آن شهر بگذرد البته قيمت پيراهن زيادتر از ماليات بود، فرماندار پيراهن را آورد پيش خليفه نهاد، خليفه گفت: اين چيست؟ گفت: خراج ماليات بلخ است كه عيالم به جاى ماليات داده است.\r\nآنها تهى دست بودند پس شما قبول نماييد، خليفه از جريان وضع مردم باخبر شد كه قادر به دادن ماليات نيستند و زن فرماندار پيراهن خود را براى ماليات فرستاده، خليفه اين زن را بسيار تحسين كرد و دستور داد بكلى ماليات عفو شود و پيراهن را برگرداند به خود زن، وقتى كه فرماندار پيراهن را به زن خود برگرداند و گفت: خليفه از عمل شما تحسين كرد و احترام گذاشت و ماليات را بخشيد، بعد زن سوال كرد: آيا سلطان بر اين پيراهن نگاه كرد يا نه؟ گفت: بلى.\r\nزن گفت: پيراهنى كه نظر نامحرم بر آن افتاده باشد من ديگر نمى‏پوشم ولى آن را بفروشيد تا در بلخ مسجدى بنا كرد مسجد فعلى از پول همان پيراهن است، بعد از تكميل بنا، ثلث پول زياد آمد آن را نيز زير يكى از ستون‏هاى مسجد پنهان كردند كه هر وقت مسجد محتاج به تعمير باشد از آن پول استفاده كنند، عفت يك زن چقدر عالى است.\r\n"},{"id":646,"category_id":6,"category_code":"s6","source_id":154,"title":"سفره ی افطار","content":"ام كلثوم دختر اميرالمؤمنين (عليه السلام ) مى گويد:\r\nدر شب نوزدهم ماه رمضان دو قرص نان جو، يك كاسه شير و مقدارى نمك در يك ظرف براى افطار خدمت پدرم آوردم . وقتى نمازش را به اتمام رساند، براى افطار آماده شد.\r\nهنگامى كه نگاهش به غذا افتاد به فكر فرو رفت . آنگاه سرش را تكان داد و با صداى بلند گريست و فرمود:\r\n- عزيزم ! براى افطار پدرت دو نوع خورش (شير و نمك )، آن هم در يك ظرف آماده ساخته اى ؟\r\nتو با اين عمل مى خواهى فرداى قيامت براى حساب در محضر خداوند بيشتر بايستم ؟\r\nمن تصميم دارم هميشه دنباله رو برادر و پسر عمويم رسول خدا صلى الله عليه و آله باشم \r\nهرگز براى آن حضرت دو نوع خورش در يك ظرف آورده نشد تا آنكه چشم از جهان فرو بست. \r\nدخترم عزيزم ! هر كس در دنيا خوردنيها، نوشيدنيها و لباسهايش از راه حلال و پاك تهيه گردد، روز قيامت در دادگاه الهى بيشتر خواهد ايستاد و چنانچه از راه حرام باشد علاوه بر بيشتر ايستادن عذاب هم خواهد داشت زيرا كه در حلال اين دنيا حساب و در حرام آن عذاب است.\r\n"},{"id":647,"category_id":6,"category_code":"s6","source_id":155,"title":"معاوضه ی طلا و گندم","content":"ابن هشام كلبى يكى از پايه گذاران تاريخ اسلامى مى‏نويسد: در كشور يمن سيل قبرى را نمايان كرد جنازه زنى را ديدند در حالتى كه هفت در سفيد و گوهر گرانمايه از گلويش آويزان بوده و در هر يك از دست و پاهايش هفت عدد از دستبند و النگو و خلخال وجود داشت و در هر انگشت انگشترى بود كه دانه‏هاى مرواريد قيمتى آراسته شده بود و يك تابوت و صندوقى پر از مال نقود و مال نقود و مال در بالاى سرش قرار گرفته بود و در آن صندوق نيز لوحى وجود داشت و اين كلمات سودمند و پر منفعت در آن نوشته شده بود:\r\nبه نام تو اى خالق جهان و پروردگار عالميان و معبود حمير يعنى قبيله ای كه سلاطين يمن از آن قبيله بوده ‏اند من تاجر دختر ذى شغرم كسان, خودم را براى آوردن طعام و نزد يوسف و عزيز مصر اعزام نمودم وليكن درنگ كردند به يكى از نزديكانم يك مد يعنى ده سير نقره و سيم سكه دادم كه به اندازه آن آرد تهيه كند اما پيدا نكرد.\r\nدوباره يك مد طلا و زر دادم تا معادل آن خوراك و غذا آماده نمايد باز هم ميسر نشد و مرتبه سوم يك مد لؤلؤ شاهوار و مرواريد ناب به او دادم اين دفعه نيز دست خالى مراجعت نمودم لذا از گرسنگى خشك شدم و هلاك گرديدم.\r\nهر كس كه از احوالم باخبر و آگاه گردد از سرگذشت من درس عبرت بگيرد و بداند هر زنى كه مثل من زر و زيور در بر داشته باشد نمى‏ميرد مگر مانند من.\r\nسيوطى نقل كرده كه در سال چهارصد شصت هجرى قحطى و گرسنگى در مملكت مصر اتفاق افتاد و زنى از قاهره پايتخت كشور مصر بيرون آمد و با خود يك مد گوهر برداشته بود و فرياد مى‏كرد كيست كه گوهر را با ده سير گندم معاوضه نمايد؟\r\nهيچ كس به او نگاه نكرد و توجهى به حرف ننمود، طلا و جواهر فراوان ليكن گندم خوراك اوليه مردم بسيار ناياب است.\r\n"},{"id":648,"category_id":6,"category_code":"s6","source_id":156,"title":"تلاش در راه بی نیازی","content":"\r\nعبدالاعلى مى گويد:\r\nدر بين راه مدينه به حضرت صادق عليه السلام برخورد كردم . روز بسيار گرمى بود، گفتم :\r\nفدايت شوم با آن مقامى كه پيش خداوند دارى و از خويشان رسول خدا عليه السلام مى باشى ، چرا در اين گرما خود را اين چنين به زحمت انداخته اى ؟\r\nامام عليه السلام فرمود:\r\nعبدالاعلى ! من براى جستجوى روزى بيرون آمدم تا از مثل تو بى نياز شوم.\r\n"},{"id":649,"category_id":6,"category_code":"s6","source_id":157,"title":"احترام مهمان","content":"حضرت امام حسن عسكري عليه السلام فرمود: دو نفر كه يكي پدر و ديگري پسر او بود به عنوان مهماني به خانه علي عليه السلام آمدند حضرت از جاي خويش براي آنها حركت كرد ايشان را در بالاي مجلس نشانيد و خود در مقابل آنها نشست ، آنگاه دستور داد غذا بياورند پس از صرف خوراك قنبر طشت و آفتابه و حوله آورد خواست دست پدر را بشويد علي عليه السلام از جا بلند شد و آفتابه را از دست قنبر گرفت تا دست پدر را بشويد ولي آن مرد خويش را به خاك افكنده عرض كرد يا علي تو مي خواهي آب بر دست من بريزي خداوند مرا بدان حال ببيند؟ فرمود: بنشين خدا مي بيند ترا در حاليكه يكي از برادرانت كه با تو فرقي ندارد مشغول خدمت تو است . نشست علي عليه السلام فرمود: قسم مي دهم به حق بزرگي كه بر گردنت دارم طوري . آرام و آسوده بنشين چنانكه اگر قنبر بر دستت آب مي ريخت آسوده بودي. \r\nهنگاميكه دست او را شست آفتابه را به محمد بن حنفيه داد فرمود: اگر اين پسر تنها آمده بود دست او را مي شستم ولكن خداوند دوست ندارد بين پدر و پسريكه در يك محل و مجلس هستند تسويه باشد اكنون پدر دست پدر را شست تو هم پسر جان دست پسر را بشوي محمد بن حنفيه دست او را شستشو داد. امام حسن عسكري عليه السلام فرمود: هر كس علي عليه السلام را پيروي كند در اين كار شيعه حقيقي خواهد بود.\r\n"},{"id":650,"category_id":6,"category_code":"s6","source_id":158,"title":"بارش باران با استخوان","content":"در زمان حكومت معتمد عبّاسى به جهت نيامدن باران ، خشكسالى شد و همه جا را قحطى فرا گرفت ، لذا خليفه دستور داد كه مردم نماز باران به جاى آورند تا رحمت الهى نازل گردد.مردم سه روز مرتّب نماز باران خواندند ولى خبرى از بارش باران نشد، تا آن كه نصارى به همراه يكى از راهبان حركت كردند و چون به بيابان رسيدند، راهب دست به سوى آسمان بلند كرد و در اين هنگام ابرى بالا آمد و شروع به باريدن كرد.همچنين روز دوّم ، نيز نصارى به همراه همان راهب حركت كردند و چون راهب دست به سوى آسمان بلند كرد - همانند روز قبل - ابرى نمايان گشت و باران فرود آمد.\r\nبه همين علّت مسلمان هاى ظاهر بين كه شاهد اين صحنه مرموز بودند، نسبت به دين مبين اسلام و نيز ولايت امام در شكّ و ترديد قرار گرفتند و عدّه اى از آن ها مرتّد شدند و از اسلام برگشتند.\r\nوقتى اين خبر تاءسّف بار به معتمد - خليفه عبّاسى - رسيد، فورا دستور داد تا امام حسن عسكرى عليه السلام را احضار نمايند، هنگامى كه حضرت نزد خليفه آمد، معتمد گفت : امّت جدّت را درياب كه در حال هلاكت بى دينى قرار گرفته اند.\r\nامام حسن عسكرى عليه السلام در مقابل ، به معتمد عبّاسى فرمود: چندان مهمّ نيست ، اجازه بده كه بار ديگر نصارى براى آمدن باران بيرون بروند و دعا نمايند، من به حول و قوّه الهى ، شكّ و ترديد را از دل مردم بيرون خواهم كرد.\r\nمعتمد دستور داد تا بار ديگر مردم براى آمدن باران دعا كنند، نصارى نيز به همراه راهب حركت كردند و چون راهب دست خود را به سمت آسمان بلند كرد، بارش باران شروع شد.\r\nپس امام عليه السلام فرمود: آنچه كه در دست راهب است از او بگيريد.\r\nهمين كه ماءمورين آن را از دست راهب گرفتند، ديدند قطعه استخوان انسانى است ، آن را خدمت امام عليه السلام آوردند.\r\nحضرت استخوان را در دست خود گرفت و سپس به راهب دستور داد: براى آمدن باران دعا كن. \r\nاين بار هر چه راهب دست خود را به سوى آسمان بلند كرد و دعا خواند، ديگر خبرى از باران نشد.\r\nتمامى مردم از اين ماجرى در حيرت و تعجّب قرار گرفته و با يكديگر مشغول صحبت چون و چرا شدند.\r\nو معتمد عبّاسى به امام عليه السلام خطاب كرد و اظهار داشت: \r\nياابن رسول اللّه ! اين چه معمّاى مرموزى بود؟!\r\nو چرا ديگر باران قطع شد و ديگر باران نيامد؟!\r\nامام حسن عسكرى عليه السلام فرمود: اين استخوان يكى از پيغمبران الهى است و اين راهب آن را در دست خود مى گرفت و به سمت آسمان بلند مى كرد و به وسيله آن استخوان ، رحمت الهى فرود مى آمد.\r\n"},{"id":651,"category_id":6,"category_code":"s6","source_id":159,"title":"پرداخت بدهی","content":"یکی از اصحاب و دوستان امام حسن عسکری(ع) به نام ابوهاشم جعفری حکایت کرد: روزی امام(ع) سوار مرکب سواری خود شد و به سمت صحرا و بیابان حرکت کرد و من نیز همراه حضرت سوار شدم و به راه افتادم و حضرت جلوی من حرکت می کرد، چون مقداری راه رفتیم ناگهان به فکرم رسید که بدهی سنگینی دارم و بدون آنکه سخنی بگویم، در ذهن و فکر خود مشغول چاره‌اندیشی بودم.\r\nدر همین بین امام(ع) متوجه من شد و فرمود: ناراحت نباش، خداوند متعال آن را اداء خواهد کرد و سپس خم شد و با عصایی که در دست داشت، روی زمین خطی کشید و فرمود: ای ابوهاشم! پیاده شو و آن را بردار و ضمناً مواظب باش که این جریان را برای کسی بازگو نکنی، وقتی پیاده شدم، دیدم قطعه‌ای طلا داخل خاک‌ها افتاده است، آن را برداشتم و در خورجین نهادم و سوار شدم و به همراه امام(ع) به راه خود ادامه دادم، باز مقدار مختصری که رفتیم، با خود گفتم: اگر این قطعه طلا به اندازه بدهی من باشد که خوب است، ولی من تهیدست هستم و توان تامین مخارج زندگی خود و خانواده‌ام را ندارم، مخصوصاً که فصل زمستان است و اهل منزل آذوقه و لباس مناسب ندارند، در همین لحظه بدون آنکه حرفی زده باشم، امام(ع) مجدداً نگاهی به من کرد و خم شد و با عصای خود روی زمین خطی کشید و فرمود: ای ابوهاشم! آن را بردار و این اسرار را به کسی نگو، پس چون پیاده شدم، دیدم قطعه‌ای نقره روی زمین افتاده است، آن را برداشتم و در خورجین کنار آن قطعه طلا گذاشتم و سپس سوار شدم و به راه خود ادامه دادیم، پس از اینکه مقداری دیگر راه رفتیم، به سوی منزل بازگشتیم و امام عسکری(ع) به منزل خود تشریف برد و من نیز رهسپار منزل خویش شدم.\r\n   بعد از چند روزی طلا را به بازار برده و قیمت کردم، به مقدار بدهی‌هایم بود -نه کم و نه زیاد- و آن قطعه نقره را نیز فروختم و نیازمندی‌های منزل و خانواده‌ام را تهیه و تأمین کردم.\r\n"},{"id":652,"category_id":6,"category_code":"s6","source_id":160,"title":"پزشک نصرانی","content":"یكی از دوستان و اصحاب حضرت ابوالحسن ، امام هادی صلوات اللّه علیه - به نام زید بن علی - حكایت كند: روزی از روزها سخت مریض شدم ، تا حدّی كه دیگر نتوانستم حركت كنم ، لذا پزشكی نصرانی را بر بالین من آوردند و او برایم داروئی را تجویز كرد و گفت : این دارو را به مدّت دَه روز مصرف می كنی تا مریضی ات برطرف و بهبودی حاصل شود. پس از آن كه پزشك نصرانی از منزل خارج شد، نیمه شب بود و كسی از طرز استفاده آن داروی اطّلاعی نداشت . و من در حالی كه متحیّر بودم ، ناگاه شخصی جلوی منزل ما آمد و اجازه ورود خواست . همین كه وارد منزل شد، متوجّه شدیم كه آن شخص غلام امام هادی علیه السلام می باشد. سپس آن غلام به من گفت : مولا و سرورم فرمود: آن پزشك داروئی را كه به تو داد و گفت مدّتی آن را مصرف كن تا خوب بشوی ؛ ولی ما این نوع دارو را فرستادیم ، چنانچه آن را یكبار مصرف نمائی ، انشاءاللّه به إ ذن خداود متعال خوب خواهی شد. زید گوید: با خود گفتم : همانا امام هادی علیه السلام بر حقّ است و باید به دستورش عمل كنم .\r\n به همین جهت ، داروئی را كه حضرت فرستاده بود مورد استفاده قرار دادم و چون آن را مصرف كردم ، در همان مرتبه اوّل عافیت یافتم و داروی پزشك نصرانی را تحویلش دادم . فردای آن روز پزشك نصرانی مرا دید و چون حالم خوب و سالم بود و ناراحتی نداشتم ، علّت بازگرداندن داروهایش را و نیز علّت سلامتی مرا جویا شد؟ پس تمام جریان را كه امام هادی علیه السلام برایم داروئی فرستاد و اظهار نمود با یك بار مصرف خوب خواهم شد، همه را برای پزشك نصرانی تعریف كردم . بعد از آن ، پزشك نصرانی نزد امام علی هادی علیه السلام حاضر شد و توسّط حضرت هدایت و مسلمان گردید و سپس اظهار داشت : ای سرور و مولایم ! این نوع درمان و دارو از مختصّات حضرت عیسی مسیح علیه السلام بوده است و كسی از آن اطّلاعی ندارد، مگر آن كه همانند او باشد.\r\n"},{"id":653,"category_id":6,"category_code":"s6","source_id":161,"title":"قدرت امام","content":"متوكل فكر همه جا را كرده بود و مي‌خواست به گونه‌اي ماهرانه آبروي امام را بريزد. به شعبده باز هندي گفت: - مي‌تواني كاري بكني كه علي بن محمد كنف شود؟!\r\n - چه جور كاري؟ - نمي‌دانم! هر كاري كه مي‌تواني انجام بده تا سرافكنده شود. اگر چنين كني، هزار دينار به تو مي‌دهم. شعبده باز از شنيدن پاداش «هزار دينار» دست و پاي خود را گم كرد. پول چنان او را سرمست كرده بود كه سر از پا نمي‌شناخت. نقشه‌اش را به متوكل گفت. متوكل قهقهه سر داد و گفت: - آفرين، آفرين بر تو! ببينم چه مي‌كني! به دستور شعبده‌باز نان‌هاي سبكي پختند و سر سفره‌ي ناهار گذاشتند. از امام دعوت كرد براي صرف ناهار به قصر بيايد. وقتي امام وارد شد و سر سفره نشست، شعبده‌باز كنار امام نشست و منتظر ماند. بفرماييد. بخوريد. بسم الله. امام به محض اين كه دست به سوي نان دراز كرد، شعبده‌باز با حركاتي عجيب و تكان دادن دست‌هايش، نان را به عقب پرتاپ كرد. حضرت دست به سمت نان ديگري دراز كرد. دوباره نان به هوا بلند شد و عقب‌تر افتاد. اين كار سه بار تكرار شد. حاضران كه از درباريان و دوستان متوكل بودند، از خنده روده بر شده بودند و نيششان تا بنا گوش باز بود.\r\n امام فهميد هدف چيست. آن گاه برخاست و همه را از نظر گذراند. آن گاه به شير نري كه يال و كوپال مهيبي داشت و روي پشتي نقش بسته بود، اشاره كرد و گفت: - او را بگير. امام به شعبده‌باز اشاره كرد. شيري واقعي و خشمناك از پشتي بيرون جهيد و به شعبده‌باز حمله كرد. اين كار به قدري با سرعت انجام شد كه امكان حركتي به هيچ كس نداد. شير درنده او را دريد و خورد. سپس به جاي اولش بازگشت و دوباره به پشتي نقش بست! برخي از حاضران از ديدن صحنه‌ي وحشتناك خورده شدن شعبده‌باز توسط شير، نزديك بود قالب تهي كنند. چند نفري غش كرده بودند. گروهي زبانشان بند آمده بود و نمي‌دانستند چه بگويند. اصلا انتظارش را نداشتند و آنچه را ديده بودند، باور نمي‌كردند. متوكل كه اوضاع را خراب ديد، برخاست و به حضور حضرت آمد و عرض كرد: اي علي بن محمد! حقا كه تو از او شعبده‌بازتري! آفرين! خواستيم مزاح كرده باشيم. حال بنشين غذايمان را بخوريم. واقعا كه دست بالاي دست بسيار است! - به خدا قسم! شعبده‌بازي نبود. اين، قدرت خدا بود و ديگر هيچگاه شعبده‌باز را نخواهيد ديد. واي بر متوكل! آيا دوستان خدا را به دشمنانش مي‌فروشي؟ آيا دشمنان را بر ما ترجيح مي‌دهي؟! امام اين سخنان را گفت و رفت. خون شعبده‌باز روي زمين ريخته بود و حاضران هنوز به حال عادي باز نگشته بودند؛ حتي از نزديك شدن به عكس بي‌جان شير وحشت داشتند.\r\n"},{"id":654,"category_id":6,"category_code":"s6","source_id":162,"title":"سفر بدون بازگشت","content":"چهار سال و چند ماه از عمر امام جواد (ع) می گذشت ، همراه پدرش ‍ حضرت رضا (ع) برای انجام عمره به مكه رفتند، یكی از غلامان حضرت رضا به نام موفق نیز با آنها بود، همان سالی بود كه حضرت رضا (ع) ناگزیر شد كه از حجاز به خراسان بیاید. حضرت رضا (ع) با حالت مخصوصی گریان ، در كنار كعبه ایستاده بود و با خانه خدا وداع می كرد و پس از طواف به مقام ابراهیم (ع) رفت و در آنجا به نماز ایستاد. موفق ، می گوید: حضرت جواد (ع) كنار حجر اسماعیل رفت و در آنجا نشست و به راز و نیاز مشغول شد، نشستن آن حضرت طول كشید و به حضور آن حضرت رفتم و عرض كردم : فدایت گردم برخیز. حضرت جواد (ع) فرمود: نمی خواهم از اینجا جدا گردم ، مگر اینكه خدا بخواهد آن حضرت این سخن را گفت ، اما بسیار غمگین به نظر می رسید. نزد حضرت رضا (ع) رفتم و گفتم : حضرت جواد (ع) كنار حجر اسماعیل (ع) نشسته و نمی خواهد برخیزد امام رضا (ع) نزد حضرت جواد (ع) آمد و فرمود: قم یا حبیبی : ای محبوب دلم برخیز. حضرت جواد (ع) عرض كرد: نمی خواهم از این مكان برخیزم ، امام رضا (ع) فرمود: ای محبوب قلبم چرا برنمی خیزی ؟ حضرت جواد (ع) عرض كرد: چگونه برخیزم با اینكه شما را دیدم به گونه ای با كعبه ، خانه خدا، وداع می كردی كه دیگر به اینجا باز نمی گردی . اما رضا (ع) فرمود: ای محبوب دلم برخیز.\r\nآنگاه حضرت جواد در حالی غمگین بود، برخاست و همراه پدر حركت كرد. آری امام جواد (ع) با اینكه كودك بود، از حالات پدر دریافت كه او می خواهد به سفری برود كه بازگشت در آن نیست ، از فراق و غربت پدر غمگین بود، می خواست كنار كعبه بیشتر بنشیند و برای پدر دعا كند، ولی چه می تواند كرد كه طاغوت زمان (ماءمون) حضرت رضا (ع)را با اجبار به خراسان برد و بین حضرت جواد (ع) با پدر، فراقی جانكاه پیش آمد كه حدود سه سال طول كشید، وبعد كه امام جواد (ع) حدود هفت ساله بود، كنار جنازه مسموم شده پدر آمد.\r\n"},{"id":655,"category_id":6,"category_code":"s6","source_id":163,"title":"قاضی حسود","content":"داستان (( ابوليلاى قاضى )) در زمان حضرت جواد (عليه السلام ) شنيدنى است ، قاضى ابو ليلا در زمان متوكل عباسى قاضى القضات و در راس دستگاه قضايى خلافت به اصطلاح اسلامى آن روز بوده است ، مغازه دار نزديك منزل قاضى ، (( زرقا )) نامى بود و قاضى با زرقا رفيق بود، روزى به زرقا رسيد در حالى كه قاضى سخت پريشان بود زرقا پرسيد جناب قاضى چرا امروز اين قدر ناراحت هستى ؟ گفت اگر بدانى در محضر خليفه چه مصيبتى بر من وارد آمد؟ دزدى را آوردند كه سرقتش ثابت شده بود، در اجراى حد از من پرسيد چه مقدار از دستش را بايد قطع كرد، من گفتم در قرآن مجيد خداوند مى فرمايد: دست دزد را بايد قطع كرد و دست را در آيه وضو تا (( مرفق )) يعنى (( آرنج )) بايد شست ، لذا دستش را از مرفق بايد قطع كرد.\r\nخليفه از قضات ديگر كه در مجلس حاضر بودند، پرسيد و آنان گفتند از بند دست بايد قطع كرد، چون خداوند دست را در دو آيه تيمم از مچ شمرده است . خليفه رو به امام شيعه ها حضرت جواد (عليه السلام ) كرد، و از او سؤ ال كرد. حضرت فرمود: ديگران پاسخ را گفتند، خليفه گفت شما هم بفرماييد حضرت مجددا فرمود: ديگران گفتند، خليفه اصرار كرد و به ناچار حضرت فرمود: (( بايد انگشتان او را قطع كرد؛ چون خداوند مى فرمايد: مساجد براى خداست و مساجد جمع مسجد، جاهايى است كه در حال سجده به زمين گذاشته مى شود، اين دزد وقتى مى خواهد نماز بخواند در سجده بايد هفت عضوش بر زمين برسد: دو كف دستش را كه بايد به زمين بگذارد نبايد قطع شود بلكه بايد تنها انگشتانش را قطع كرد تا اين را فرمود، خليفه گفت : احسنت ! مرحبا! و فورا دستور داد مطابق فرموده امام جواد (عليه السلام ) عمل كنند و دست دزد را از انگشتانش قطع كردند.\r\nدر اين وقت مثل اينكه عالم را بر سر من خراب كردند. كه چگونه جوان 25 ساله را بر من مقدم داشت ، پريشان شدم و با خود گفتم كه تا او را نكشم رها نمى كنم ، با اينكه مى دانم هر كسى اين جوان را به قتل برساند به آتش مى رود ولى بر تصميم خود اصرار مى كردم !!\r\nزرقا گويد او را نصيحت كردم اما او نپذيرفت ؛ روز بعد قاضى نزد خليفه مى رود و به طور خصوصى مى گويد آيا فهميدى ديروز چه كردى ؟ كسى كه قسمت اعظمى از مسلمانان او را امام مى دانند خليفه بحق پيغمبر مى دانند و تو را باطل مى شمارند به جاى اينكه او را محو كنى ، جلوه دادى و تقويت نمودى ! آنانى كه مى گفتند او بر حق است اكنون مى گويند ديديد خود خليفه هم فهميد و گفته او را بر ديگران مقدم داشت اين چه اشتباه بزرگى بود كه كردى ؟ اين قدر در گوش خليفه خواند تا او را راضى به قتل حضرت جواد (عليه السلام ) كرد و متوكل عباسى لعنت الله عليه دستور داد تا حضرت را به شهادت برسانند و بالاخره در روز آخر ذيقعده از سال 220 هجرى قمرى حضرت را مسموم كردند.\r\n"},{"id":656,"category_id":6,"category_code":"s6","source_id":164,"title":"پرهیز از تبعیض","content":"يكي از اهالي بلخ گويد: من در سفر امام رضا عليه السلام به خراسان همراه او بودم، روزي همه غلامان خود را كه اهل سودان و جاهاي ديگر بودند بر سر سفره غذا دعوت كرد تا با آنها غذا بخورد.\r\nعرض كردم: فدايت شوم اگر غلامان را جدا كني و سفره ديگري داشته باشند بهتر است.\r\nحضرت فرمود: ساكت باش! پروردگار تبارك و تعالي يكتاست و پدر و مادر ما (آدم و حوا) يكي هستند و پاداش هر كس هم به اعمال اوست.\r\n"},{"id":657,"category_id":6,"category_code":"s6","source_id":165,"title":"مهمان","content":"مهماني بر امام رضا عليه السلام وارد شد، حضرت نزد او نشسته بود و با وي صحبت مي كرد به گونه اي كه بخشي از شب را با يكديگر مي گذراندند، در اين هنگام چراغ روشنايي داراي مشكل و خرابي شد.\r\nمهمان امام رضا عليه السلام كه خرابي چراغ رامشاهده مي كرد دست برد تا آن را اصلاح كند.\r\nدر اين هنگام حضرت مانع كار او شد و خود ان را درست كرد و سپس فرمود:\r\nانا قوم لا مستخدم اضيافنا\r\nما خانداني هستيم كه مهمانان خود را به خدمت نمي گيريم.\r\n"},{"id":658,"category_id":6,"category_code":"s6","source_id":166,"title":"امام و حمام","content":"امام رضا عليه السلام وارد حمام عمومي شد، شخصي در حمام بود كه امام عليه السلام را نمي شناخت به او گفت: بدن مرا كيسه بكش. امام عليه السلام شروع كرد بدن وي را كيسه مي زد كه مردم او را شناختند و آن مرد از كاري كه كرده بود شرمنده گرديد و از آن حضرت معذرت خواهي مي كرد. اما امام عليه السلام او را دلداري مي داد و به كار خود ادامه مي داد."},{"id":659,"category_id":6,"category_code":"s6","source_id":167,"title":"امر به معروف","content":"وقتي كه امام كاظم عليه السلام وفات كرد در نزد وكيلان حضرت اموالي بسياري بود و بعضي به خاطر طمع در مال آن حضرت وفات امام را منكر شدند و مذهب (وافقيه ) را تشكيل دادند. \r\nدر نزد زياد قندي هفتاد هزار هزار اشرفي ، نزد علي بن ابي حمزه سي هزار اشرفي بود . يونس بن عبدالرحمان مردم را به امامت حضرت رضا عليه السلام مي خواند ، و مذهب وافقي را باطل مي دانست . آنان براي او پيغام دادند : براي چه مردم را به حضرت رضا عليه السلام دعوت مي نمايي ، اگر مقصد تو پول است ترا از مال بي نياز مي كنيم . زياد قندي و علي بن ابي حمزه ضامن شدند كه ده هزار اشرافي به او بدهند تا ساكت شود و حرفي نزند. \r\nيونس بن عبدالرحمان )گفت : از امام باقر عليه السلام و صادق عليه السلام روايت كرده ايم كه فرمودند : هر گاه بدعت در ميان مردم ظاهر شد ، بر پيشواي مردم لازم است كه علم خود را ظاهر كند (تا مردم را از منكرات باز دارند) ، و اگر اين عمل را نكند خداوند نور ايمان را از او مي گيرد.\r\n"},{"id":660,"category_id":6,"category_code":"s6","source_id":168,"title":"هلاکت سگ خلیفه","content":"\r\nراويان حديث و تاريخ ‌نويسان آورده اند:\r\nدر آن زمانى كه حضرت ابوالحسن ، امام موسى كاظم صلوات اللّه عليه را از بصره به زندان بغداد منتقل كردند، حضرت به طور دائم مورد انواع شكنجه هاى روحى و جسمى قرار مى گرفت. \r\nو پس از مدّتى در اختيار سندى بن شاهك يهودى با بدترين و شديدترين وضعيّت قرار گرفت .\r\nتا آن كه در نهايت هارون الرّشيد با توجّه به فضائل و مناقب ؛ و نيز موقعيّت اجتماعى امام عليه السلام ، از روى حسادت و ترس ، به فكر مسموم كردن و قتل آن حضرت افتاد.\r\nبه همين جهت مقدارى رطب و خرماى تازه را تهيّه كرده و يكى از آن ها را به وسيله نخ و سوزن درون آن را به طورى آغشته به زهر كرد، كه يقين كرد خورنده خرما، سالم نمى ماند؛ و سپس در طَبَقى سينى و يا بشقاب گذاشت و روى خرماها را پوشاند.\r\nپس از آن ، به يكى از ماءمورين خود دستور داد تا طبق خرما را نزد حضرت موسى بن جعفر عليهما السلام برده و بگويد: اميرالمؤمنين ، هارون الرّشيد مقدارى از آن ها را تناول كرده ؛ و نيز اين مقدار را براى شما فرستاده است تا ميل نمائيد.\r\nو افزود: مواظب باش كه تمامى خرماها را ميل كند و كسى ديگر حقّ خوردن از آن ها را ندارد.\r\nهنگامى كه ماءمور هارون ، خرماها را نزد امام كاظم عليه السلام آورد و پيام خليفه را به حضرتش رسانيد، حضرت يكى از خرماها را - كه آغشته به زهر بود - برداشته و در دست گرفت ؛ و با دست ديگر مشغول خوردن بقيّه گرديد.\r\nدر همين اثناء، سگ مخصوص هارون الرّشيد - كه هارون بيش از هر چيز و هركس به آن علاقه مند بود و آن را به انواع جواهرات و زيورآلات زينت كرده بود - خود را رهانيد و از جايگاه مخصوص خود بيرون شد و مستقيم داخل زندان امام عليه السلام گرديد؛ و خواست كه نزديك آن حضرت برود و آن خرماى زهرآلود را دهن بزند و بخورد.\r\nحضرت آن خرماى مسموم را كه در دست خويش گرفته بود، در حضور غلام خليفه ، نزد آن سگ انداخت و سگ هم سريع آن را خورد؛ و چندان زمانى نگذشت كه سگ روى زمين افتاد و با سر و صدا، شروع به ناليدن كرد و مُرد.\r\nسپس امام عليه السلام به ناچار باقيمانده خرماها را ميل نمود؛ و بعد از آن ، ماءمور خليفه ، نزد هارون بازگشت و گفت : تمامى خرماها را آن شخص ‍ زندانى خورد.\r\nهارون سؤال كرد: او را در چه حالتى ديدى ؟\r\nپاسخ داد: در وضعيّتى خوب ، بدون آن كه تغييرى در بدن و جسم او ظاهر گردد.\r\nو چون خبر مسموم شدن و مردن سگ به هارون رسيد بسيار غمگين و اندوهناك شد و بر بالين لاشه سگ مرده آمد و بسيار افسوس ‍ خورد.\r\nسپس بازگشت و ماءمورى را كه خرماها را نزد امام موسى كاظم عليهما السلام آورده بود، احضار كرد و شمشير برهنه خود را دست گرفت و او را مخاطب قرار داد و گفت : چنانچه حقيقت را بيان نكنى تو را به قتل مى رسانم.\r\nماءمور گفت : من رطب ها را نزد موسى بن جعفر عليه السلام بردم و پيام شما را نيز به او رساندم و سپس بالاى سر او ايستادم تا مشغول خوردن آن خرماها شد.\r\nدر همين بين ، كه ناگهان سگ شما فرا رسيد و خواست نزديك آن شخص ‍ زندانى برود و از دستش خرمائى بگيرد.\r\nو زندانى ناچار شد و خرمائى را كه در دست داشت ، نزد سگ انداخت و سگ آن را خورد و درجا افتاد؛ و موسى بن جعفر عليه السلام بقيّه خرماها را ميل نمود.\r\nهارون الرّشيد با شنيدن اين خبر بسيار افسرده خاطر گشت و گفت : بهترين رطب را براى او تهيّه كرديم ، ولى حيف كه به هدف خود نرسيديم و بلكه سگ از دست ما رفت.\r\nو سپس افزود: هر چه تلاش مى كنيم تا از وجود موسى بن جعفر نجات يابيم ، ممكن نمى شود.\r\nو در پايان با تهديد به غلام گفت : مواظب باش كه اين خبر در بين افراد منتشر نگردد.\r\n"},{"id":661,"category_id":6,"category_code":"s6","source_id":169,"title":"طی الارض","content":"مرحوم شيخ صدوق و ديگر بزرگان آورده اند:\r\nپس از آن كه چون هارون الرّشيد حضرت ابوالحسن ، امام موسى كاظم عليه السلام را از زندان بصره به بغداد منتقل كرد، تحويل شخصى به نام سندى بن شاهك يهودى داده شد.\r\nو در زندان بغداد، حضرت بسيار تحت كنترل و فشار بود؛ و زير انواع شكنجه هاى روحى و جسمى قرار گرفت ، تا جائى كه حتّى دست و پا و گردن آن امام مظلوم عليه السلام را نيز به وسيله غل و زنجير بستند.\r\nامام حسن عسكرى عليه السلام در اين باره فرموده است: \r\nجدّم ، حضرت موسى بن جعفر عليه السلام سه روز پيش از شهادتش ، زندان بان خود - مسيّب - را طلبيد و اظهار نمود:\r\nمن امشب به مدينه جدّم ، رسول خدا صلى الله عليه و آله مى روم تا با آن حضرت تجديد عهد و ميثاق نمايم و آثار امامت را تحويل امام بعد از خودم دهم.\r\nمسيّب عرض كرد: اى مولاى من ! شما در ميان اين غل و زنجير و آن همه ماءمورين اطراف زندان ، چگونه قصد چنين كارى را دارى ؟\r\nو من چگونه زنجيرها و درب هاى زندان را باز كنم ، در حالى كه كليد قفل ها نزد من نيست ؟!\r\nامام عليه السلام فرمود: اى مسيّب ! ايمان و اعتقاد تو نسبت به خداوند متعال و هچنين نسبت به ما اهل بيت عصمت و طهارت سُست است. \r\nو سپس حضرت افزود: همين كه مقدار يك سوّم از شب سپرى گرديد، منتظر باش كه چگونه خارج خواهم شد.\r\nمسيّب گويد: من آن شب را سعى كردم كه بيدار بمانم و متوجّه حركات امام موسى كاظم عليه السلام باشم ؛ ولى خسته شدم و خواب چشمانم را فرا گرفت ؛ و لحظه اى در حال نشسته ، خوابم برد.\r\nناگهان متوجّه شدم كه حضرت با پاى مباركش مرا حركت مى دهد، پس ‍ سريع از جاى خود برخاستم ؛ و هر چه نگاه كردم اثرى از ديوار و ساختمان و زندان نديدم ، بلكه خود را به همراه حضرت در زمينى هموار مشاهده نمودم. \r\nو چون گمان كردم كه آن حضرت مرا نيز به همراه خود از آن ساختمان ها بيرون آورده است ، گفتم : ياابن رسول اللّه ! مرا نيز از شرّ اين ظالم نجات بده. \r\nحضرت اظهار نمود: آيا مى ترسى تو را به جهت من از بين ببرند و بكُشند؟\r\nو سپس افزود: اى مسيّب ! در همين حالى كه هستى ، آرام باش ، من پس از مدّتى كوتاه باز مى گردم. \r\nمسيّب با تعجّب سؤال كرد: ياابن رسول اللّه ! غل و زنجيرى كه بر دست و پاى شما بود، چگونه گشودى ؟!\r\nامام عليه السلام فرمود: خداوند متعال به جهت ما اهل بيت ، آهن را براى حضرت داود عليه السلام ملايم و نرم كرد؛ و اين كار براى ما نيز بسيار سهل و ساده است. \r\nآن گاه حضرت از نظرم ناپديد گشت و با ناپديد شدنش ديوارها و ساختمان زندان با همان حالت قبل نمايان گرديد.\r\nو چون ساعتى گذشت ناگهان ديدم ديوارها و ساختمان زندان به حركت درآمد و در همين حالت ، مولا و سرورم حضرت موسى بن جعفر عليهما السلام را ديدم كه به زندان بازگشته است و همانند قبل غل و زنجير بر دست و پاى مبارك حضرت بسته مى باشد.\r\nاز ديدن اين معجزه ، بسيار تعجّب كردم و به سجده افتادم. \r\nبعد از آن امام عليه السلام به من فرمود: اى مسيّب ! برخيز و بنشين ؛ و ايمان خود را تقويت و كامل گردان ، و سپس افزود: من سه روز ديگر از اين دنيا و محنت هاى آن خلاص خواهم شد و به سوى خداوند متعال و مهربان رهسپار مى گردم.\r\n"},{"id":662,"category_id":6,"category_code":"s6","source_id":170,"title":"زنده شدن گاو","content":"علىّ بن مغيره - كه يكى از راويان حديث و از اصحاب امام موسى كاظم عليه السلام مى باشد - حكايت می كند:\r\nروزى در مِنى و عرفات بوديم كه امام موسى كاظم عليه السلام در مسير راه به زنى برخورد كرد، كه مشغول گريه و زارى بود؛ و نيز كودكان خردسالش در اطراف او گريان بودند.\r\nامام كاظم عليه السلام به طور ناشناس نزديك رفت و علّت گريه آنها را جويا شد؟\r\nزن اظهار داشت : اى بنده خدا! من داراى فرزندانى خردسال هستم ؛ و تنها سرمايه زندگى براى امرار معاش ما يك گاو بود كه ساعتى قبل مرد؛ به همين جهت ، گريان هستم چون ديگر وسيله امرار معاش نداريم. \r\nحضرت فرمود: دوست دارى آن را زنده كنم ؟\r\nزن عرضه داشت : بلى \r\nپس حضرت كنارى رفت و دو ركعت نماز خواند و دست خود را به سوى آسمان بالا برد و لبهاى مبارك خود را حركت داد و زمزمه اى نود، كه من نفهميدم چه دعائى را خواند.\r\nپس از آن ، امام عليه السلام از جاى بر خاست و به سمت گاو مرده آمد و با پاى مبارك خود بر پهلوى گاو زد.\r\nناگهان گاو زنده گرديد و بلند شد و سر پا ايستاد،\r\nهمين كه زن چشمش به گاو افتاد - كه زنده شده است - سراسيمه كنان فرياد كشيد: اين شخص ، عيسى بن مريم است. \r\nو چون امام كاظم عليه السلام داد و فرياد آن زن را شنيد، سريع حركت نمود و خود را در بين جمعيّت پنهان كرد، تا كسى آن حضرت را نشناسد.\r\n"},{"id":663,"category_id":6,"category_code":"s6","source_id":171,"title":"عنایت به شیعیان","content":"روزى هارون الرشيد مقدارى لباس از جمله جبّه زرباف سياه رنگى را - كه پادشاه روم به هارون فرستاده بود - به عنوان قدردانى به على بن يقطين ، هديه كرد.\r\nعلى بن يقطين تمام آن لباسها، همراه همان جبه و مبلغى پول و خمس اموال خود را كه معمولا به حضرت مى داد، به محضر امام كاظم فرستاد. امام عليه السلام پول و لباسها را قبول كرد اما جبه را به وسيله آورنده بازگرداند و نامه اى به على بن يقطين نوشت و در آن تاءكيد كرد جبه را نگهدار و آن را هرگز از دست مده ! چون به زودى به آن نيازمند خواهى شد.\r\nعلى بن يقطين علت برگرداندن جبه را نفهميد و به شك افتاد در عين حال آن را محفوظ نگه داشت. \r\nچند روز گذشت ، على به يكى از غلامان خدمتگزارش خشمناك شد و او را از كار بركنار كرد. غلام متوجه بود على بن يقطين هوادار امام كاظم است ، ضمنا از فرستادن هديه ها نيز باخبر بود لذا پيش هارون رفت و از او سخن چينى كرد، گفت: \r\nعلى بن يقطين موسى بن جعفر را امام مى داند و هر سال خمس اموال خود را به ايشان مى فرستد، به طورى كه جبه اى را كه خليفه براى احترام از وى داده بود همراه خمس اموال فرستاد.\r\nهارون الرشيد بسيار غضبناك شد گفت: \r\nبايد اين قضيه را كشف كنم اگر صحت داشته باشد على را خواهم كشت . همان لحظه دستور داد على را بياوريد همين كه آمد، گفت: \r\nجبه اى را كه به تو دادم چه كردى ؟\r\nگفت : نزد من است آن را عطر زده ، در جعبه اى در بسته محفوظ نگه مى دارم ، هر صبح و شام در جعبه باز كرده به عنوان تبرك آن را مى بوسم و دوباره به جايش مى گذارم. \r\nهارون گفت : هم اكنون آن را بياور!\r\nعلى گفت : هم اكنون حاضرش مى كنم ، به يكى از غلامان خود گفت: \r\nبرو كليد فلان اتاق را از كنيز كليددار بگير اتاق را كه باز كردى فلان صندوق را بگشا! جعبه اى را كه رويش مهر زده ام بياور! طولى نكشيد غلام جعبه مهر شده را آورد و در مقابل هارون گذاشت . دستور داد جعبه را باز كردند.\r\nهنگامى كه هارون جبه را با آن كيفيت ديد كه عطرآگين است خشمش فرو نشست ، به على بن يقطين گفت: \r\nجبه را به جايش بازگردان و به سلامت برو! هرگز حرف سخن چينان را درباره تو نخواهم پذيرفت و نيز دستور داد به على جايزه بدهند.\r\nسپس امر كرد به سخن چين هزار تازيانه بزنند در حدود پانصد تازيانه زده بودند كه از دنيا رفت.\r\n"},{"id":664,"category_id":6,"category_code":"s6","source_id":172,"title":"شیعه ی واقعی","content":"محمد بن ابى عمير از پرورش يافتگان مكتب اهل بيت عليهم السلام و از روات مورد وثوق و اعتماد است . او مدتى بشغل بزازى اشتغال داشت و داراى تمكن مالى بود ولى بر اثر پيش آمدهائى اموالش از دست رفت و به فقر و بى چيزى مبتلا گرديد.\r\n از مردى ده هزار درهم طلب داشت . مديون براى آنكه بدهى خود را بپردازد خانه مسكونى خويش را به ده هزار درهم فروخت و با پول آن روانه خانه ابن ابى عمير شد. در را كوبيد، ابن ابى عمير از منزل بيرون آمد. مديون ، پولها را تسليم وى نمود و گفت اين مبلغى است كه از شما به ذمه من است .\r\n پرسيد اين پول را چگونه بدست آوردى ؟ آيا از كسى ارث برده اى ؟ گفت نه ، آيا شخصى بتو بخشيده است ؟ جواب داد نه ، آيا متاعى داشتى كه فروخته اى ؟ باز هم پاسخ نفى داد و گفت خانه مسكونيم را براى اداء دين خود فروخته ام و پولش را براى شما آورده ام . ابن ابى عمير گفت : ذريح محاربى از امام صادق عليه السلام حديث كرده كه فرموده است: \r\nمرد مديون بجهت اداء دين ، از منزل مسكونيش رانده نميشود.\r\nسپس گفت بخدا قسم با آنكه هم اكنون آنقدر در مضيقه مالى هستم كه حتى به يك درهم احتياج دارم اما اين پول را نميگيرم.\r\n"},{"id":665,"category_id":6,"category_code":"s6","source_id":173,"title":"راه نجات","content":"على بن ابى حمزه ميگويد: دوستى داشتم كه در ديوان بنى اميه منشى بود. روزى بمن گفت از امام صادق (ع ) استجازه كن ، تا بمحضر مباركش شرفياب شوم . اجازه گرفتم ، در موعد مقرر حضور امام آمد سلام كرد و نشست سپس ‍ گفت من در ديوان بنى اميه عضويت داشتم ، در حكومت آنان اموال بسيارى گرد آوردم و در اين كار از مقررات اسلام ديده فروبستم و بى پروا هر مال غير مشروعى را طلب ميكردم . امام عليه السلام فرمود: اگر بنى اميه در اداره امور خود كسانى را در خدمت خويش نمى يافتند حقوق اهل بيت رسول اكرم را پايمال نمى نمودند.\r\nسپس دوستم سؤ ال كرد: آيا براى من راه نجاتى هست ؟ حضرت در پاسخ از او پرسيد: اگر بگويم عمل ميكنى ؟ جواب داد عمل ميكنم . امام عليه السلام فرمود: بايد از تمام اموالى كه در اداره آنها بدست آورده اى دل برگيرى و از خود دور كنى ، قسمتى را كه ميدانى از آن كيست به صاحبش برگردانى و آنرا كه نميدانى به مستمندان صدقه بدهى و با انجام اين وظيفه ، من بهشت جاودان و سعادت ابدى را براى تو ضمانت ميكنم . دوست من پس از شنيدن سخنان امام (ع ) مدتى دراز ساكت شد و درباره دستور امام فكر كرد سرانجام تصميم گرفت و با قاطعيت بعرض رساند كه دستورتان انجام شده است. \r\nعلى بن ابى حمزه ميگويد: آن مرد در معيت ما بكوفه برگشت و فرموده امام را در مورد تمام اموالى كه در اختيار داشت حتى جامه اى كه در برش بود اجراء نمود و همه آنها را رد كرد و ما از رفقا و دوستان پولى جمع آورى كرديم ، از آن پول لباسى براى او خريديم و باقيمانده آنرا براى مصارف روزانه اش تسليم وى نموديم. \r\nاو با اجراء برنامه درمانى امام صادق عليه السلام بيمارى اخلاقى خود را علاج نمود، غريزه حرص و طمع خويش را مهار كرد از بندگى مال آزاد شد، بسلامت فكر و پاكى اخلاق نائل آمد، و از خوى تجاوزكارى بحقوق دگران رهائى يافت. \r\nپس از جريان چند ماهى بيش نگذشت كه مريض شد و بسترى گرديد و دوستان مكرر از وى عيادت كردند. روزى نزد او رفتم ديدم در حال احتضار است و لحظات آخر زندگى را ميگذراند، چشم گشود و بمن نگاهى كرد و گفت : على بن ابى حمزه ، امام صادق بوعده خود وفا كرد و سپس ديده بربست و از دنيا رفت. \r\nابى حمزه ميگويد از كوفه بمدينه بازگشتم حضور امام صادق عليه السلام رسيدم تا چشم آنحضرت بمن افتاد فرمود على بن ابى حمزه بخدا قسم وعده اى را كه بدوستت داده بوديم وفا كرديم . عرض كردم راست است ، والله او خود در موقع مرگ اين مطلب را به من اعلام كرد.\r\n"},{"id":666,"category_id":6,"category_code":"s6","source_id":174,"title":"خانه مؤ منين در بهشت","content":"هشام بن حكم نقل ميكند كه مردى از كوهستان خدمت حضرت صادق عليه السلام آمده و ده هزار درهم بايشان داد و گفت تقاضاى من اينست كه خانه اى خريدارى فرمائيد تا از حج كه برگشتم با عيال و اطفال خود در آنجا مسكن كنم و بعزم مكه معظمه خارج شد. چون مراجعت نمود حضرت او را در منزل خود جاى داد و طومارى باو لطف كرد.\r\nفرمود خانه اى برايت در بهشت خريدم كه حد اول آن متصل است بخانه محمد مصطفى صلى الله عليه و آله و حد دوم بمنزل على مرتضى عليه السلام و حد سوم بخانه حسن مجتبى و حد چهارم بخانه حسين بن على عليه السلام. \r\nمرد كوهستانى كه اين سخن را شنيد گفت قبول كردم و راضى شدم حضرت مبلغ را ميان تنگدستان از فرزندان امام حسن و امام حسين عليهماالسلام تقسيم كردند و كوهستانى بمحل خود بازگشت. \r\nچون مدتى گذشت آن مرد مريض شد و بستگان خود را احضار نموده گفت من ميدانم آنچه حضرت صادق عليه السلام فرموده راست است و حقيقت دارد خواهش ميكنم اين طومار را با من دفن كنيد. پس از زمان كوتاهى از دنيا رفت ، بنا بوصيتش طومار را با او دفن كردند، روز ديگر كه آمدند ديدند همان طومار بر روى قبر اوست و به خط سبز روى آن نوشته شده خداوند بآنچه ولى او حضرت صادق عليه السلام وعده داده بود وفا كرد.\r\n"},{"id":667,"category_id":6,"category_code":"s6","source_id":175,"title":"یک ماه اعتکاف","content":"در محضر امام صادق نشسته بود، ناگهان مردى از اهل مكه وارد مجلس شد و گرفتاریى كه برایش پیش آمده بود شرح داد، معلوم شد موضوع كرایه اى در كار است و كار به اشكال و بن بست كشیده است . امام به صفوان دستور داد:((فورا حركت كن و برادر ایمانى خودت را در كارش مدد كن.)) \r\nصفوان حركت كرد و رفت و پس از توفیق در اصلاح كار و حل اشكال ، مراجعت كرد. امام سؤ ال كرد: چطور شد؟\r\nخداوند اصلاح كرد.\r\nبدانكه همین كار به ظاهر كوچك كه حاجتى از، كسى برآوردى و وقت كمى از تو گرفت ، از هفت شوط طواف دور كعبه محبوبتر و فاضلتر است.\r\nبعد امام صادق به گفته خود چنین ادامه داد: مردى گرفتارى داشت و آمد حضور امام حسن و از آن حضرت استمداد كرد. امام حسن بلافاصله كفشها را پوشیده و راه افتاد. در بین راه به حسین بن على رسیدند در حالى كه مشغول نماز بود. امام حسن به آن مرد گفت : تو چطور از حسین غفلت كردى و پیش او نرفتى \r\nگفت : من اول خواستم پیش او بروم و از او در كارم كمك بخواهم ، ولى چون گفتند ایشان اعتكاف كرده اند و معذورند، خدمتشان نرفتم. \r\nامام حسن فرمود: اما اگر توفیق برآوردن حاجت تو برایش دست داده بود، از یك ماه اعتكاف برایش بهتر بود.\r\n"},{"id":668,"category_id":6,"category_code":"s6","source_id":176,"title":"برکات صدقه","content":"يكى از پسران امام صادق عليه السلام نامش محمد بود. گاهى از مخارج زندگيش چيزى زياد مى آورد، امام فرمود: چقدر از مخارج زندگيت زياد آمده ؟ عرض كرد: چهل دينار، فرمود: آن را در راه خدا صدقه بده . عرض ‍ كرد: غير از پولى ندارم ، اگر صدقه بدهم چيزى برايم نمى ماند.\r\nفرمود: برو آن را صدقه بده ، خداوند عوضش را مى دهد، آيا نمى دانى كه هر چيزى كليدى دارد و كليد رزق صدقه است!! \r\nمحمد نصيحت پدر را پذيرفت و آن چهل دينار اضافى را صدقه داد. از اين جريان ده روز بيشتر نگذشت كه چهار هزار دينار براى امام آوردند، امام به محمد فرمود: پسر جانم ! ما براى خدا، چهل دينار داديم ، خداوند به جاى آن ، چهار هزار، دينار (صد برابر) به ما عنايت فرمود.\r\n"},{"id":669,"category_id":6,"category_code":"s6","source_id":177,"title":"عزت نفس","content":"مفضّل با فشار سخت زندگی روبرو شده بود ،فقر وتنگ دستی ، داشتن قرض و مخارج سنگین زندگی اورا آزار می داد،درمحضر امام صادق (ع)لب به شکایت گشود وبیچارگی های خود را موبه موتشریح کرد \"فلان مبلغ قرض دارم،فلان مشکل دارم ،متحیّرم چه کنم و....\"خلاصه در آخر کلامش از امام  صادق(ع) در خواست دعا کرد . امام  (ع)به کنیزش دستور دادند یک کیسه اشرافی که منصور برای وی فرستاده بود بیاورند ،بعد این کیسه را در اختیارمفضّل قرار می دهد،مفضّل رو به امام(ع) خطاب کرده می گوید: \"آقا مقصودم آنچه در حضور شما گفتم دعا بود.\"\r\nحضرت می فرمایند : بسیار خوب دعا هم می کنم ،امّا این را بدان؛ هرگز سختی های خود را برای مردم تشریح نکن اولین اثرش این است که وانمود می شود تو در میدان زندگی زمین خورده ای واز روزگار شکست یافته ای،در نظر ها کوچک می شوی وشخصیّت واحترامت از میان می رود.\r\n"},{"id":670,"category_id":6,"category_code":"s6","source_id":178,"title":"اثبات خدا","content":"روزی مردی خدمت امام جعفر صادق علیه السلام رفت و عرض کرد: ای پسر رسول خدا، خدا را برایم ثابت کن.\r\nامام به او فرمود: آیا تا به حال به مسافرت رفته ای؟\r\nمرد عرض کرد: بلی، امام فرمود: سوار کشتی شده ای؟\r\nمرد گفت: بلی\r\nامام فرمود: آیا تا به حال اتفاق افتاده که کشتی شما غرق شود و کشتی دیگری برای نجات شما موجود نباشد و تو نیز شنا بلد نباشی که بتوانی خودت را نجات دهی؟\r\nمرد گفت: بلی.\r\nامام فرمود: آن موقع به چه چیز امید داری؟\r\nمرد عرض کرد: وقتی از همه جا مایوس و نا امید می شدم و می فهمیدم که دیگر کسی نیست که مرا نجات دهد ته قلبم نوری می تابید و امیدوار می شدم که دستی از غیب بیرون آید و مرا نجات دهد.\r\nامام لبخندی زد و فرمود: همان نیرویی که امیدوار بودی تو را نجات دهد در حالی که هیچ وسیله ای برای نجات تو باقی نمانده بود، همان خداست که در نا امیدی ها و بلاها به داد انسان می رسد و او را نجات می دهد.\r\n"},{"id":671,"category_id":6,"category_code":"s6","source_id":179,"title":"کبوتر بازان","content":"روزي نامه اي به امضاي عده اي از بزرگان شيعه به دست امام صادق عليه السلام رسيد كه چند نفر از آنان خود حامل نامه بودند. \r\nشكايت درباره رفاقت (مفضل بن عمر) وكيل امام صادق عليه السلام در كوفه با عده اي كبوتربازان و به ظاهر بي بند و بار بود. \r\nامام عليه السلام پس از خواندن نامه ، نامه اي دربسته به وسيله همان چند نفر براي مفضل فرستاد . از حسن اتفاق موقعي نامه رسيد كه امضاء كنندگان در خانه او بودند. \r\nاو نامه را در حضور آنان باز كرد و خواند و سپس به دست آنها داد . آنان از مضمون نامه مطلع شدند كه امام در اين نامه تنها دستور چند قلم معامله به مفضل داده كه انجامش مستلزم رقمي درشت پول نقد مي باشد ، و مفضل بايد آن را تهيه كند؛ و درباره رفاقت مفضل با آنان در نامه امام هيچ اشاره اي نشده بود. \r\nچون مساءله پول بود ، آنها سر بزير انداخته و گفتند : بايد پيرامون اين پول زياد فكر كنيم و بعد عذرخواهي هم كردند. \r\nمفضل كه زيرك بود آنها را به صرف غذا دعوت كرد و نگذاشت از خانه بيرون روند؛ آنگاه پي كبوتر بازان فرستاد و آنان آمدند ، و در حضور آن عده براي اينان نامه امام را خواند. \r\nكبوتر بازان بدون عذر تراشي رفتند و هنوز مهمانان مشغول غذا خوردن بودند كه پولهاي زياد (از هزار درهم تا ده هزار درهم ) را جمع و آن را تسليم مفضل كردند و رفتند! \r\nدر اين موقع مفضل به امضاء كنندگان رو كرد و گفت : شما از من مي خواهيد امثال اين جوانان را راه ندهم با اينكه امكان اصلاح اينان زياد است و در چنين مواردي باري از دين را به دوش كشند. \r\nشما مي پنداريد كه خدا محتاج به نماز و روزه شماست كه به آن مغرور شده ايد ، اما از گذشت مالي عذر تراشي مي كنيد و پاسخ امام را نمي دهيد!! \r\nاينان كه رفاقت مفضل با كبوتربازان را خوار و كوچك مي شمردند ، جوابي نداشتند بدهند ، از جاي بلند شدند و رفتند.\r\n"},{"id":672,"category_id":6,"category_code":"s6","source_id":180,"title":"قطع طواف","content":"ابان بن تغلب گفت : به همراه امام صادق عليه السلام مشغول طواف كعبه بودم . در اثناء طواف يكي از دوستانم از من خواست كه كنار بروم و به حرف و خواسته اش گوش بدهم . من دلم نمي خواست كه از حضرت جدا بشوم ، لذا توجهي به او نكردم . در دور بعدي طواف آن شخص به من اشاره كرد كه به سوي او بروم اين بار امام صادق عليه السلام اشاره او را ديد و به من فرمود : اي ابان آيا او با تو كاري دارد ؟ گفتم : آري . فرمود : او كيست ؟ عرض كردم : از دوستان من است ، فرمود : او هم مو من و شيعه مي باشد ؟ گفتم:  آري ، فرمود : پس به سوي او برو و خواسته اش را برآورده كن.\r\nعرض كردن : آيا طواف را قطع كنم ؟ فرمود : آري گفتم : آيا اگر طواف واجب هم باشد مي توان آن را به جهت برآوردن حاجت مو من قطع كرد و نيمه كاره رها نمود ؟ فرمود : آري. \r\nمن طواف را قطع كرده و نزد آن شخص رفتم . سپس نزد امام آمدم و از حضرت خواستم حق مو من بر مو من را بيان كند.\r\n"},{"id":673,"category_id":6,"category_code":"s6","source_id":181,"title":"سفارشات امام باقر(ع)","content":"جابر جعفى نقل مى كند:\r\nبعد از خاتمه اعمال حج ، با جمعى به خدمت امام محمد باقر عليه السلام رسيديم . هنگامى كه خواستيم با حضرت وداع كنيم ، عرض ‍ كرديم توصيه اى بفرمايند\r\nاظهار داشتند:\r\n- اقوياى شما به ضعفا كمك كنند\r\nاغنيا از فقرا دلجويى نمايند\r\nهر يك از شما خير خواه برادر دينى اش باشد. و آنچه براى خود مى خواهد براى او نيز بخواهد\r\nاسرار ما را از نااهلان مخفى داريد، و مردم را بر ما مسلط نكنيد\r\nبه گفته هاى ما و آنچه از ما به شما مى رسانند توجه كنيد؛ اگر ديديد موافق قرآن است ، آن را بپذيريد و چنانچه آن را موافق قرآن نيافتيد، بر زمين بياندازيد\r\nاگر مطلبى بر شما مشتبه شد، درباره آن تصميمى نگيريد و آن را به ما عرضه داريد تا آن طور كه لازم است براى شما تشريح كنيم. \r\nاگر شما چنين بوديد كه توصيه شد و از اين حدود تجاوز نكرديد و پيش ‍ از زمان قائم ما كسى از شما بميرد، شهيد از دنيا رفته است . هر كس قائم ما را درك كند و در ركاب او كشته شود، ثواب دو شهيد دارد و هر كس در ركاب او يكى از دشمنان ما را به قتل برساند، ثواب بيست شهيد خواهد داشت.\r\n"},{"id":674,"category_id":6,"category_code":"s6","source_id":182,"title":"نجات حتمی","content":"روزى از روزها حضرت سجّاد، امام زين العابدين عليه السّلام مشغول نماز بود؛ و فرزندش محمد باقر سلام اللّه عليه - كه كودكى خردسال بود - كنار چاهى كه در وسط منزلشان قرار داشت ، ايستاده بود و چون مادرش ‍ خواست او را بگيرد، ناگهان كودك به داخل چاه افتاد.\r\nمادر فريادزنان ، بر سر و سينه خود مى زد و براى نجات فرزندش كمك مى طلبيد، و مى گفت : ياابن رسول اللّه ! شتاب نما و به فريادم برس كه فرزندت در چاه افتاد، بچّه ات غرق شد و...\r\nامام سجّاد عليه السّلام با اين كه داد و فرياد همسر خود را مى شنيد، امّا دركمال آرامش و متانت به نماز خود ادامه داد؛ و لحظه اى ارتباط خود را با پروردگار متعال و معبود بى همتاى خويش قطع و بلكه سست نكرد.\r\nهمسر آن حضرت ، چون چنين حالتى را از شوهر خود ملاحظه كرد، با حالت افسردگى و اندوه گفت: \r\nشما اهل بيت رسول اللّه چنين هستيد! و نسبت به مسائل دنيا و متعلّفات آن بى اعتنا مى باشيد.\r\nپس از آن كه حضرت با كمال اعتماد و اطمينان خاطر، نماز خود را به پايان رسانيد، بلند شد و به سمت چاه حركت كرد و چون كنار چاه آمد، لب چاه نشست و دست خود را داخل آن برد و فرزند خود، محمد باقر عليه السّلام را گرفت و بيرون آورد.\r\nهنگامى كه مادر چشمش به فرزند خود افتاد كه مى خندد و لباس هايش ‍ خشك مى باشد؛ آرام شد و آن گاه امام سجّاد عليه السّلام به او فرمود: اى زن ضعيف و سست ايمان ! بيا فرزندت را بگير.\r\nزن به جهت سلامتى بچّه اش ، خوشحال ولى از طرفى ، به جهت سخن شوهرش غمگين و گريان شد.\r\nامام سجّاد عليه السّلام فرمود: من تمام توجّه و فكرم در نماز به خداوند متعال بود؛ و خداى مهربان بچّه ات را حفظ كرد و از خطر نجات داد.\r\n"},{"id":675,"category_id":6,"category_code":"s6","source_id":183,"title":"پاسخ کریمانه","content":"روزی مردی مسیحی قصد داشت تا با مسخره کردن امام باقر (ع) ایشان را خشمگین کند و به این وسیله برای خود و برخی از رهگذران نادان، اسباب خنده و شادی فراهم نماید. برای اجرای نقشه اش، سر راه امام قرار گرفت. وقتی امام به نزدیکش رسید، در حالی که نیش خندی به لب داشت، با صدای بلند گفت: سؤالی دارم. امام آماده شنیدن سؤال شد. مرد با بی ادبی گفت: آیا تو بقر هستی؟ و خنده احمقانه ای سر داد تا رهگذرانی هم که سؤالش را شنیده بودند، بخندند. امام باقر (ع) بدون این که ذرّه ای عصبانی شود، به آرامی گفت: نه، من باقر هستم.\r\nمرد مسیحی که به هدف خود نرسیده بود، سعی کرد به امام طعنه بزند. بنابر این از آن حضرت پرسید: آیا تو فرزند یک آشپز هستی؟ امام باقر (ع) با این که به قصد زشت او پی برده بود، با حوصله این طور پاسخ گفت: آشپزی حرفه مادرم بود (داشتن حرفه آشپزی که عیب نیست) \r\nمرد نادان که دیگر نمی دانست چه بگوید، با بی شرمی پرسید: آیا تو پسر آن زنِ بد اخلاقی؟ امام آخرین سؤال بی ادبانه او را به بهترین شکل پاسخ داد: اگر تو راست می گویی، خداوند او را بیامرزد و اگر تو دروغ می گویی، خداوند تو را بیامرزد!\r\nاز پاسخ مؤدّبانه امام، مرد مسیحی مات و مبهوت شد. انگار دنیا را بر سرش خراب کردند. از رفتار خود بسیار شرمنده شد و با خود اندیشید: این شخص، بنده برگزیده خداست وگرنه هر انسان معمولی با سخنان توهین آمیز من، از کوره در می رفت و عصبانی می شد. بی تردید، دین اسلام، دین حق و حقیقت است که چنین انسان بزرگی، امام و پیشوای آن است. او به دلیل اخلاق و رفتار بزرگوارانه امام باقر (ع) همان جا به دین اسلام گروید و مسلمان شد.\r\n"},{"id":676,"category_id":6,"category_code":"s6","source_id":184,"title":"مصلح باید دانا باشد","content":" (عبدالملك ) گويد : بين حضرت باقر عليه السلام و بعضي فرزندان امام حسن عليه السلام اختلافي پيدا شد ، من خدمت امام رفتم و خواستم در اين ميان سخني بگويم تا شايد اصلاح شود.\r\nامام فرمود : تو چيزي در بين ما مگو ، زيرا مثل ما با پسر عمويمان مانند همان مردي است كه در بني اسراييل زندگي مي كرد ، و او را دو دختر بود يكي از آن دو را به مردي كشاورز و ديگري را به شخصي كوزه گر شوهر داده بود. \r\nروزي براي ديدن آنها حركت كرد؛ اول پيش آن دختري كه زن كشاورز بود رفت و از او احوال پرسيد : دختر گفت : پدرجان شوهرم زراعت فراواني كرده اگر باران بيايد حال ما از تمام بني اسراييل بهتر است. \r\nاز منزل آن دختر به خانه ديگر دخترش رفت و از احوالش پرسيد ، گفت : پدر ، شوهرم كوزه زيادي ساخته اگر خداوند مدتي باران نفرستد تا كوزه هاي او خشك شود حال ما از همه نيكوتر است. \r\nآن مرد از خانه دختر خود خارج شد در حالي كه مي گفت : خدايا تو خودت هر چه صلاح مي داني بكن ، در اين ميان مرا نمي رسد كه به نفع يكي درخواستي بكنم ، هرچه صلاح است آنها را انجام ده. \r\nامام فرمود : شما نيز نمي توانيد بين ما سخني بگوييد ، مبادا در اين ميان بي احترامي به يكي از ما شود ، وظيفه شما به واسطه پيامبر صلي الله عليه و آله نسبت به ما احترام نسبت به همه ما است.\r\n"},{"id":677,"category_id":6,"category_code":"s6","source_id":185,"title":"اطعام شیعیان","content":"سدير يكي از شاگردان امام باقر عليه السلام بود. او مي گويد: امام باقر عليه السلام به من فرمود: اي سدير آيا روزانه يك برده آزاد مي كني؟\r\nعرض كردم: نه\r\nامام عليه السلام فرمود: در هر ماه چطور؟\r\nعرض كردم: نه\r\nحضرت فرمود: درهر سال چطور؟\r\nعرض كردم: نه\r\nامام عليه السلام گفت: سبحان الله، آيا دست يكي از شيعيان ما را مي گيري و به خانه ببري و به او غذا دهي تا سير شود؟ به خدا سوگند اين كار بهتر از آزاد كردن برده اي است كه از فرزندان حضرت اسماعيل باشد.\r\n"},{"id":678,"category_id":6,"category_code":"s6","source_id":186,"title":"دو پرنده","content":"جابر بن يزيد جعفي حكايت كند:\r\nدر يكي از سال ها، به همراه حضرت باقرالعلوم عليه السلام رهسپار مكه معظمه شدم.\r\nدر بين راه، دو پرنده به سمت ما آمدند و بالاي كجاوه امام محمد باقر عليه السلام نشستند و مشغول سر و صدا شدند، من خواستم آن ها را بگيرم تا همراه خود داشته باشم، ناگهان حضرت با صداي بلند، فرمود: اي جابر! آرام باش و پرندگان را به حال خود واگذار، آن ها به ما اهل بيت عصمت و طهارت پناه آورده اند.\r\nعرضه داشتم: مولاي من! مشكل و ناراحتي آن ها چيست، كه اين چنين به شما پناهنده شده اند؟\r\nحضرت فرمود: آن ها مدت سه سال است كه در اين حوالي لانه دارند و هرگاه تخم مي گذارند تا جوجه شود، ماري در اطراف آن ها هست كه مي آيد و جوجه هاي آن ها را مي خورد.\r\nاكنون پرندگان به ما پناهنده شده تا از خداوند بخواهم كه آن مار را به هلاكت رساند؛ و من نيز در حق آن مار نفرين كردم و به هلاكت رسيد؛ و پرندگان در امان قرار گرفتند.\r\nجابر گويد: سپس به راه خود ادامه داديم تا نزديك سحر و اذان صبح به بياباني رسيديم؛ و من پياده شدم و افسار شتر حضرت را گرفتم؛ و چون حضرت فرود آمد، در گوشه اي خم شد و مقداري از شن ها را كنار زد و در حال كنار زدن شن ها، چنين دعايي را بر لب هاي خود زمزمه مي نمود: خداوندا! ما را سيراب و تطهير و پاك گردان.\r\nناگهان سنگ سفيدي نمايان شد و امام عليه السلام آن سنگ را كنار زد و چشمه اي زلال و گوارا آشكار گرديد، و از آن آب آشاميدم و نيز براي نماز وضو گرفتيم.\r\nو بعد از خواندن نماز، سوار شديم و به راه خود ادامه داديم تا آن كه صبحگاهان به روستايي رسيديم، كه نخلستاني كنار آن روستا بود، در آن جا فرود آمديم؛ و حضرت كنار نخل خرمايي - كه از مدتها قبل خشك شده بود - آمد و خطاب به آن كرد و اظهار داشت: اي درخت خرما! از آنچه خداوند متعال در درون شاخه هاي تو قرار داده است، ما را بهره مند ساز.\r\nجابر افزود: ناگهان ديدم درخت خرما، سرسبز و پربار شد و خود را در مقابل امام عليه السلام خم كرد؛ و ما به راحتي از ثمره آن مي چيديم و مي خورديم.\r\nدر همين اثنا، يك مرد عرب بيابان نشين كه در آن حوالي بود، وقتي اين معجزه را مشاهده كرد، به حضرت خطاب كرد و گفت: سحر و جادو كرديد؟\r\nامام عليه السلام در پاسخ، به آن عرب خطاب نمود و به آرامي اظهار داشت:\r\nاي مرد! به ما نسبت ناروا مده، چون كه ما از اهل بيت رسالت هستيم؛ و هيچ كدام از ما ساحر و جادوگر نبوده و نيستيم، بلكه خداوند متعال از اسامي مقدسه خود كلماتي را به ما آموخته است كه هر موقع هر چه را بخواهيم و اراده كنيم، به وسيله آن كلمات، خداوند متعال را مي خوانيم و تقاضا ميكنيم، آن گاه دعاي ما به لطف او مستجاب خواهد.\r\n"},{"id":679,"category_id":6,"category_code":"s6","source_id":187,"title":"جذامیها","content":"در مدینه چند نفر بیمار جذامى بود. مردم با تنفر و وحشت از آنها دورى مى كردند. این بیچارگان بیش از آن اندازه كه جسما از بیمارى خود رنج مى بردند، روحا از تنفر و انزجار مردم رنج مى كشیدند. و چون مى دیدند دیگران از آنها تنفر دارند خودشان با هم نشست و برخاست مى كردند.\r\nیك روز، هنگامى كه دور هم نشسته بودند غذا مى خوردند، على بن الحسین زین العابدین از آنجا عبور كرد. آنها امام را به سر سفره خود دعوت كردند. امام معذرت خواست و فرمود:((من روزه دارم ، اگر روزه نمى داشتم پایین مى آمدم . از شما تقاضا مى كنم فلان روز مهمان من باشید)). این را گفت و رفت. \r\nامام در خانه دستور داد، غذایى بسیار عالى و مطبوع پختند. مهمانان طبق وعده قبلى حاضر شدند. سفره اى محترمانه برایشان گسترده شد. آنها غذاى خود را خوردند و امام هم در كنار همان سفره غذاى خود را صرف كرد.\r\n"},{"id":680,"category_id":6,"category_code":"s6","source_id":188,"title":"آزار امام سجاد(ع)","content":"مردى شجاع در مدينه بود كه همه را مى خندانيد و با مسخرگى رزق و معيشت خود را در مى آورد.\r\nجماعتى گفتند: خوب است امام سجاد را دعوت كنيم و قدرى او را بخندانى ؛ شايد از گريه هاى زياد لحظه اى ساكت شود.\r\nجمع شدند و رفتند خدمت امام ، كه در راه حضرت را ديدند، با دو نفر از غلامان مى آمد. آن شخص عباى امام را از شانه اش جمع كرد و به شانه اش ‍ انداخت و همراهان شروع به خنده كردند.\r\nامام فرمود: اين كيست ؟ گفتند: مردى است كه مردم را مى خنداند و از آنها پول مى گيرد.\r\nفرمود: به او بگوييد، روز قيامت آنان كه عمر خود را به بطالت گذرانيدند زيان مى برند.\r\nبعد از اين كلام آن شخص دست از اذيت و حركات ناشايست كشيد و به راه راست هدايت يافت.\r\n"},{"id":681,"category_id":6,"category_code":"s6","source_id":189,"title":"چقدر حاجی کم است؟","content":"موسم حجّ بود، امام سجّاد(ع ) نيز به مكّه مشرف شده بودند، يكى از همراهان آن حضرت نگاهى به صحراى عرفات انداخت ، ديد چندين هزار، هزار نفر در آن صحرا موج مى زنند با خوشحالى به امام (ع ) عرض ‍ كرد:\r\nالحمد للّه ، چقدر امسال حاجى زياد است! \r\nامام (ع ) در جواب فرمودند: چقدر فرياد زياد است و چقدر حاجى كم است ؟\r\nآن شخص مى گوند: من نمى دانم امام چه كرد و چه بينشى به من داد و چه چشمى را در من بيناى كرد، كه يك وقت به من فرمود: حالا نگاه كن . تا نگاه كردم ، ديدم صحرايى است پر از حيوان ، يك باغ وحش كامل ، فقط يك عده انسانها هم در لابلاى آن همه حيوانات حركت ميكردند، حضرت فرمودند: حالا مى بينى باطن قضيه اين است\r\n"},{"id":682,"category_id":6,"category_code":"s6","source_id":190,"title":"تربت سیدالشهداء","content":"شيخ حر عاملى صاحب وسايل الشيعه ، در كتاب ديگر خود، اثبات الهداه نقل مى كند، طبيب معروف مسيحى به نام يوحنا مى گويد:\r\nدر دربار موسى بن عيسى يك از فرمانروايان مسلمان ، سخن از درمان به وسيله تربت كربلا، پيش آمد.\r\nيكى از مردان قبيله بنى هاشم حضور داشت و گفت : ما بيماران لاعلاج را از اين راه درمان مى كنيم. \r\nموسى بن عيسى كه يك آدم ضد اهل بيت عصمت و طهارت بود دستور داد تا قدرى تربت حضرت سيدالشهداء را حاضر كنند، او در حضور همگان به عنوان جسارت و نيز به منظور اثبات بى پايگى مدعاى هاشميان قدرى از آن را به نشيمن گاه خود ريخت ، ناگهان فرياد سوختم ، سوختم او بالا گرفت ، در آن دم طشتى آوردند، جگر و كبد او در طشت ريختند، طبيب مسيحى از معالجه آن ناتوان شد و پس از چندى آن طبيب به زيارت امام شتافت در حالى كه مسيحى بود ولى ديرى نپايد كه مسلمان شد.\r\nدر دربار شاه عباس ، دانشمند مسيحى مذهب كه از ميهمانان عرفانى مسيحى در دربار شاه عباس بود مى گفت : مى توانم از ما فى الضمير افراد خبر دهم. \r\nشيخ بهايى كه در جلسه حاضر بود گفت : بگو در ميان دستم چه چيزى است ؟\r\nاو پس از لحظه اى گفت : مى دانم چيست ، ولى در حيرتم كه از كجا به دست آورده اى ؟ زيرا در ميان كف تو قطعه اى از بهشت جاى دارد.\r\nشيخ بهايى گفت : آرى قدرى از تربت امام حسين (عليه السلام) است. \r\nآرى : طبيب مسيحى ، مسلمان مى شود ولى موسى بن عيسى ، عاقبت به شر و بدبخت مى شود.\r\n"},{"id":683,"category_id":6,"category_code":"s6","source_id":191,"title":"رعایت ادب","content":"روزى امام حسن و امام حسين عليه السلام از محلى مى گذشتند. پيرمردى را ديدند كه مشغول وضو است . ولى به طور صحيح وضو نمى گيرد، آداب و شرايط آن را بجا نمى آورد. - چون آموختن آدم جاهل واجب است - از اين رو تصميم گرفتند به طور غير مستقيم با كمال ادب ، صحيح وضو گرفتن را به او بياموزند.\r\nنخست با يكديگر به بحث و گفتگو پرداختند طورى كه پيرمرد سخنانشان را بشنود.\r\nيكى گفت: \r\nوضوى تو صحيح نيست وضوى من درست است. \r\nديگرى گفت: \r\nنه ، وضوى تو درست نيست وضوى من صحيح است. \r\nسپس نزد پيرمرد آمدند و گفتند:\r\nما در حضور شما وضو مى گيريم نگاه كن ! و ببين ! كداميك از ما خوب وضو مى گيريم و درباره ما داور باش! \r\nهر دو وضوى درست و كاملى جلوى چشم پيرمرد گرفتند.\r\nآنگاه از پيرمرد پرسيدند:\r\nوضوى كداميك از ما صحيح تر و بهتر است ؟ پيرمرد متوجه شد كه وضوى صحيح چگونه است و منظور اصلى آن دو كودك آموختن او است . با كمال فروتنى اظهار داشت: \r\nعزيزان ! وضوى هر دوى شما خوب و صحيح است من پيرمرد نادان هنوز درست وضو گرفتن را نمى دانم و شما بخاطر محبت و دل سوزى كه بر امت جدتان داريد، مرا آگاه ساختيد و وضوى درست و صحيح را به من آموختيد، سپاسگزارم.\r\n"},{"id":684,"category_id":6,"category_code":"s6","source_id":192,"title":"آشنای دیروز","content":"ايام حج فرا رسيده بود. امام حسن و امام حسين - عليهما السلام - و عبدالله بن جعفر به همراه قافله اى براى انجام اعمال حج ، مدينه را ترك كردند. در بين راه از قافله عقب مانده و آن را گم كردند، خرج و خوراك آنها نيز با قافله بود، تشنه و گرسنه شدند و چيزى نداشتند كه بخورند، به سراغ خيمه اى كه در آن بيابان به چشم مى خورد رفتند، پيرزنى را در آنجا يافتند. به او گفتند: ما تشنه هستيم آيا نوشيدنى در نزد تو هست ؟ زن گفت : فقط گوسفندى دارم كه مى توانيد آن را بدوشيد و از شير آن استفاده كنيد. آنها از شير آن گوسفند نوشيدند. سپس گفتند: ما گرسنه نيز هستيم ، آيا غذايى نزد تو هست ؟ زن گفت : همان گوسفند را كه تنها دارايى من است سر ببريد تا برايتان غذا بپزم . يك نفر از آنها برخواست و گوسفند را ذبح كرد و پوست آن را كند و پيرزن غذا پخت و آنها خوردند و برخاستند تا بروند، به هنگام خداحافظى گفتند: ما از طايفه قريش هستيم ، اگر از سفر حج سالم مراجعت كرديم ، تو نزد ما بيا تا نيكى تو را جبران كنيم . اين را بگفتند و رفتند.\r\nچيزى نگذشت كه شوهر آن زن به خيمه بازگشت و زن جريان ميهمانان و ذبح گوسفند را براى او تعريف كرد. مرد عصبانى شد و گفت : چرا گوسفند مرا براى عده اى كه نمى شناختى كشتى ؟ مدتى از جريان گذشت . فقر و تنگدستى آن زن و مرد را آزار مى داد تا اين كه سرانجام مجبور شدند به مدينه روند تا سر و سامانى به زندگى خود دهند. وارد مدينه شدند و به حفر چاه و جارى كردن آب مشغول شدند و با مزدى كه مى گرفتند زندگى مى گذراندند. روزى آن پيرزن از كوچه اى عبور مى كرد، امام حسن (ع ) جلوى در خانه اش نشسته بود و او را شناخت ، ولى پيرزن آن حضرت را نشناخت . حضرت غلام خود را دنبال آن زن فرستاد، آن زن آمد، به او فرمود:\r\nآيا مرا مى شناسى ؟\r\nزن گفت : نه ،\r\nحضرت فرمود: من ميهمان آن روز تو هستم كه از گوسفندت براى ما غذا فراهم كردى! \r\nزن گفت : ولى من به ياد نمى آورم \r\nحضرت فرمود: مانعى ندارد، اگر تو مرا نمى شناسى من تو را مى شناسم . آنگاه دستور داد هزار گوسفند براى او خريدارى كردند و هزار دينار هم پول نقد به او داد، و او را با غلامش نزد امام حسين (ع ) فرستاد. امام حسين (ع ) به زن فرمود:\r\nبرادرم حسن چقدر به تو كمك كرد؟\r\nزن گفت : هزار دينار و هزار گوسفند. امام حسين نيز دستور داد همان مقدار به او كمك كرد.\r\nسپس او را با غلام خود به منزل عبدالله بن جعفر فرستاد، عبدالله گفت: \r\nامام حسن و امام حسين - عليهما السلام - چقدر به تو كمك كرده اند؟\r\nزن گفت : روى هم دو هزار دينار و دو هزار گوسفند. عبدالله دستور داد دو هزار دينار و دو هزار گوسفند به او دادند، سپس گفت : اگر اول نزد من آمده بودى آن دو بزرگوار را به زحمت نمى انداختى (و همه اين مقدار را من به تو مى دادم)\r\nزن با آن همه مال و ثروت نزد شوهر خود بازگشت.\r\n"},{"id":685,"category_id":6,"category_code":"s6","source_id":193,"title":"پاداش دسته گل","content":"يكى از كنيزان امام حسين عليه السلام خدمت حضرت رسيد، سلام كرد و دسته گلى تقديم آن حضرت نمود.\r\nحضرت هديه آن كنيز را پذيرفت و در مقابل به او فرمود:\r\nتو را در راه خدا آزاد كردم. \r\nانس كه ناظر اين برخورد انسانى بود از آن حضرت با شگفتى پرسيد:\r\nچگونه در مقابل يك دسته گل بى ارزش او را آزاد كردى ؟! - چون ارزش ‍ مادى يك كنيز به صدها دينار طلا مى رسيد.\r\nحضرت با تبسمى حاكى از رضايت خاطر بود فرمود:\r\nخداوند اينگونه ما را ادب كرده ، چون در قرآن كريم مى فرمايد\r\nاذا حييتم بتحيه فحيوا باحسن منها او ردوها \r\nاگر كسى به شما نيكى كرد او را نيكى و رفتار شايسته ترى پاسخ دهيد.\r\nو من فكر كردم ، از هديه اين كنيز بهتر اين است كه در راه خدا آزادش ‍ كنم.\r\n"},{"id":686,"category_id":6,"category_code":"s6","source_id":194,"title":"انفاق نان جو","content":"حسن و حسين عليهماالسلام مريض شدند. پيامبر گرامى صلى الله عليه و آله با چند تن از ياران به عيادتشان آمدند. گفتند:\r\n-. يا على ! خوب بود نذرى براى شفاى فرزندانت مى كردى \r\nعلى عليه السلام و فاطمه عليهماالسلام نذر كردند، اگر عزيزان شفا يابند، سه روز روزه بگيرند. خود حسن و حسين عليهماالسلام و فضه كه خادمه آنها بود نيز نذر كردند كه سه روز روزه بگيرند. چيزى نگذشت كه خداوند به هر دو شفاى عنايت فرمود. روز اول را روزه گرفتند در حالى كه غذايى در خانه نداشتند. حضرت على عليه السلام سه صاع (تقريبا سه كيلو) جو قرض كرد. حضرت زهرا عليهاالسلام يك قسمت آن را رد كرد. پنج عدد نان پخت . وقت غروب سفره انداختند و پنج نفر كنار سفره نشستند. هنگام افطار سائلى بر در خانه آمد و گفت : سلام بر شما اى خاندان پيامبر صلى الله عليه و آله ! من مستمندى از مستمندان مسلمين هستم . طعامى به من دهيد كه خداوند به شما از طعامهاى بهشتى عنايت كند. خاندان على عليه السلام همگى غذاى خويش را به او دادند و تنها با آب افطار كردند و خوابيدند. روز دوم را نيز روزه گرفتند. فاطمه عليهاالسلام پنج عدد نان جو آماده كرد و در سفره گذاشت . موقع افطار يتيمى آمد و گفت : - سلام بر شما اى خاندان محمد صلى الله عليه و آله ! من يتيمى مسلمانم ، به من غذايى دهيد كه خداوند به شما از غذاى بهشتى مرحمت كند. همه سهم خود را به او دادند و باز با آب افطار كردند. روز سوم را نيز روزه گرفتند. زهرا عليهاالسلام غذايى (نان جو) آماده كرد. هنگام افطار اسيرى به در خانه آمد و كمك خواست . بار ديگر همه غذاى خويش را به اسير دادند و تنها با آب افطار كرده و گرسنه خوابيدند. صبح كه شد على عليه السلام دست حسن و حسين عليهماالسلام را گرفته و محضر پيامبر رسيدند. در حاليكه بچه ها از شدت گرسنگى مى لرزيدند. وقتى كه پيامبر صلى الله عليه و آله آنها را در چنان حالى ديد فرمود: يا على ! اين حالى را كه در شما مى بينم برايم بسيار ناگوار است . سپس برخاست و با آنان به سوى فاطمه عليهاالسلام حركت كردند. وقتى كه به خانه وارد شدند. ديدند فاطمه عليهاالسلام در محراب عبادت ايستاده ، در حالى كه از شدت گرسنگى بسيار ضعيف گشته و ديدگانش به گودى نشسته . رسول خدا صلى الله عليه و آله او را به آغوش ‍ كشيد و فرمود: از وضع شما به خدا پناه مى برم . در اين وقت جبرئيل نازل گشت و گفت : اى رسول خدا! خداوند به داشتن چنين خاندانى تو را تهنيت مى كند.\r\n"},{"id":687,"category_id":6,"category_code":"s6","source_id":195,"title":"آفرین پسرم","content":"عبداللّه بن عمیر کلبی، یکی از افرادی است که در کربلا هم زنش همراهش بود و هم مادرش. مرد خیلی قوی و شجاعی بود. وقتی می خواهد به میدان برود، زن او مانع می شود و می گوید: کجا می روی؟ من را به کی می سپاری؟ (تازه عروسی کرده بود) پس من چه کنم؟ فوراً مادر ش آمد جلو و گفت: پسرم! مبادا حرف زنت را بشنوی، امروز روز امتحان تو است، اگر امروز خود را فدای حسین نکنی، شیر پستانم را به تو حلال نخواهم کرد. این مرد بزرگ می رود می جنگد تا شهید می شود. بعد همین زن، عمود خیمه ای را برمی دارد و به دشمن حمله می کند. اباعبد الله(ع) فریاد می کند: ای زن! برگرد، خدا بر زنان جهاد را واجب نکرده است. امر آقا را اطاعت می کند، ولی دشمن رذالت می کند. سر این مرد بزرگ را از بدن جدا کرده و برای مادرش پرتاب می کنند… سر جوانش را بغل می گیرد، به سینه می چسباند، می بوسد [و می گوید:] مرحبا پسرم! آفرین پسرم! حالا دیگر من از تو راضی شدم و شیرم را به تو حلال کردم. بعد آن را به طرف لشکر دشمن می اندازد و می گوید: ما چیزی را که در راه خدا داده ایم پس نمی گیریم."},{"id":688,"category_id":6,"category_code":"s6","source_id":196,"title":"عنايت حسين به زوار قبرش","content":"بعضي از موثقين اهل علم در نجف اشرف نقل كردند از مرحوم عالم زاهد شيخ حسين بن شيخ مشكور كه فرمود در عالم رويا ديدم در حرم مطهر حضرت سيدالشهدا(ع ) مشرف هستم و يك نفر جوان عرب وارد حرم شد و با لبخند به آن حضرت سلام كرد و حضرت هم با لبخند جوابش را دادند . فردا شب كه شب جمعه بود به حرم مطهر مشرف شدم و در گوشه اي از حرم توقف كردم ناگاه همان عرب را كه در خواب ديده بودم وارد حرم شد و چون مقابل ضريح مقدس رسيد با لبخند به آن حضرت سلام كرد ولي حضرت سيدالشهدا(ع ) را نديدم و مراقب آن بودم تا از حرم خارج شد عقبش رفتم و سبب لبخندش را به امام (ع ) پرسيدم و تفصيل خواب خود را برايش نقل كردم و گفتم چه كرده اي كه امام (ع ) با لبخند به تو جواب مي دهد گفت مرا پدر و مادر پيري است و در چند فرسخي كربلا ساكن هستيم و شبهاي جمعه كه براي زيارت مي آيم يك هفته پدرم را سوار بر الاغ كرده مي آوردم و هفته ديگر ماردم را مي آوردم تا اين كه شب جمعه اي كه نوبت پدرم بود چون او را سوار كردم مادرم گريه كرد و گفت : مرا هم بايد ببري شايد هفته ديگر زنده نباشم . گفتم : باران مي بارد هوا سرد است مشكل است نپذيرفت ناچار پدر را سوار كردم و مادر را به دوش كشيدم و با زحمت بسيار آنها را به حرم رسانيدم و چون در آن حالت با پدر و مادر وارد حرم شدم حضرت سيدالشهداء را ديدم و سلام كردم آن بزرگوار به رويم لبخند زد و جوابم را داد و از آن وقت تا به حال هر شب جمعه كه مشرف مي شوم حضرت را مي بينم و با تبسم جوابم را مي دهد . از اين داستان دانسته ميشود چيزي كه شخص را مورد عنايت بزرگان دين قرار مي دهد و رضايت آنها را جلب مي كند صدق و اخلاق و محبت ورزي و خدمتگزاري به اهل ايمان خصوصا والدين و بالاخص زوار قبر حضرت ابي عبدالله صلوات الله عليه است."},{"id":689,"category_id":6,"category_code":"s6","source_id":197,"title":"یاری مومن","content":"ميمون بن مهران گفت : نزد امام حسن عليه السلام نشسته بودم كه مردي آمد و گفت : اي فرزند پيامبر صلي الله عليه و آله فلان شخص از من طلبي دارد ولي من پولي ندارم ، براي همين او مي خواهد مرا زنداني كند. \r\nامام فرمود : در حال حاضر مالي ندارم كه بدهي تو را بدهم ؛ او عرض كرد : پس شما كاري كنيد كه او مرا زنداني نكند. \r\nامام در حالي كه در مسجد مشغول عبادت (اعتكاف ) بود ، كفشهاي خود را به پا كرد . من گفتم اي فرزند رسول خدا مگر فراموش كرديد كه در حال اعتكاف هستيد (و نبايد از مسجد خارج شد) ؟ فرمود: \r\nفراموش نكرده ام اما از پدرم شنيده ام كه رسول الله مي فرمود : كسي كه در بر آوردن حاجت برادر مسلمان خود بكوشد ، مانند كسي است كه نه هزار سال ، روز را به روز و شب را به عبادت مشغول بوده است.\r\n"},{"id":690,"category_id":6,"category_code":"s6","source_id":198,"title":"مرد لطیفه گو","content":"مرد لطيفه گويى از دوستان امام حسن عليه السلام بود. مدتى نزد آن حضرت نيامده بود. روزى خدمت امام عليه السلام رسيد. حضرت پرسيد:\r\nچگونه صبح كردى ؟ (حالت چطور است ؟)\r\nگفت: \r\nيابن رسول الله ! حال من برخلاف آن چيزى است كه خودم و خدا و شيطان آن را دوست مى داريم. \r\nامام عليه السلام خنديد و فرمود:\r\nچطور؟ توضيح بده! \r\nگفت: \r\nخداوند مى خواهد از او اطاعت كنم و معصيت كار نباشم . اما من چنين نيستم. \r\nو شيطان دوست دارد، خدا را معصيت كرده و به دستوراتش عمل نكنم ولى من اين طور هم نيستم. \r\nو خودم دوست دارم هميشه در دنيا باشم ، اين چنين هم نخواهم بود. روزى از دنيا خواهم رفت. \r\nناگاه شخصى برخواست و گفت: \r\nيابن رسول الله ! چرا ما مرگ را دوست نداريم ؟\r\nامام فرمود:\r\nبه خاطر اين كه شما آخرت خود را ويران و اين دنيا را آباد كرده ايد،\r\nبدين جهت دوست نداريد از جاى آباد به جاى ويران برويد.\r\n"},{"id":691,"category_id":6,"category_code":"s6","source_id":199,"title":"داوری امام حسن (ع)","content":"عصر خلافت امام علي (ع) بود، قصابي را كه چاقوي خون آلود در دست داشت، در خرابه اي ديدند و در كنار او جنازه خون آلود شخصي افتاده بود؛ قرائن نشان مي داد كه كشنده او همين قصاب است، او را دستگير كرده و به حضور امام علي (ع) آوردند. \r\nامام علي (ع) به قصاب گفت: در مورد كشته شدن آن مرد، چه نظر داري ؟ قصاب گفت: من او را كشته ام.\r\nامام بر اساس ظاهر جريان ، و اقرار قصاب ، دستور داد تا قصاب را ببرند و به عنوان قصاص، اعدام كنند. در اين حال كه ماءمورين، او را به قتلگاه مي بردند، قاتل حقيقي با شتاب به دنبال مأمورين دويد و به آنها گفت: عجله نكنيد و اين قصاب را به حضور امام علي (ع) بازگردانيد. ماءمورين او را به حضور علي (ع) باز گرداندند، قاتل حقيقي به حضور علي (ع) آمد و گفت : اي امير مؤمنان! سوگند به خدا، قاتل آن شخص اين قصاب نيست، بلكه او را من كشته ام.\r\n امام به قصاب فرمود: چه موجب شد كه تو اعتراف نمودي من او را كشته ام ؟ قصاب گفت: من در يك بن بستي قرار گرفتم كه غير از اين چاره اي نداشتم، زيرا افرادي مانند اين مأمورين، مرا كنار جنازه بخون آغشته با چاقوي خون آلود بدست ديدند، همه چيز بيانگر آن بود كه من او را كشته ام، از كتك خوردن ترسيدم و اقرار نمودم كه من كشته ام، ولي حقيقت اين است كه من گوسفندي را نزديك آن خرابه كشتم، سپس ادرار بر من فشار آورد، در همان حال كه چاقوي خون آلود در دستم بود، به آن خرابه براي تخلّي رفتم، جنازه بخون آغشته آن مقتول را در آنجا ديدم، در حالي كه دهشت زده شده بودم، برخاستم، در همين هنگام اين گروه به سر رسيدند و مرا به عنوان قاتل دستگير نمودند. اميرمؤمنان علي (ع) فرمود: اين قصاب و اين شخص كه خود را قاتل معرفي مي كند را به حضور امام حسن (ع) ببريد تا او قضاوت نمايد. \r\nمأمورين آنها را نزد امام حسن (ع) آوردند و جريان را به عرض ‍ رساندند. امام حسن (ع) فرمود: به امير مؤمنان علي (ع) عرض كنيد، اگر اين مرد قاتل ، آن شخص را كشته است، در عوض جان قصاب را حفظ نموده است، آنگاه هم قاتل و هم آن قصاب را آزاد نمود، و ديه مقتول را از بيت المال به ورثه او عطا فرمود. به اين ترتيب، ارفاق و تشويق اسلام شامل حال آن قاتل شد كه مردانگي كرد و موجب نجات يك نفر بي گناه گرديد، و با اين كار جوانمردانه اش، تا حدود زيادي گناه خود را جبران نمود.\r\n"},{"id":692,"category_id":6,"category_code":"s6","source_id":200,"title":"پايه تخت و انگشتر بهشتى","content":"روزى حضرت فاطمه زهراء سلام اللّه عليها از پدر خود، رسول خدا صلّلى اللّه عليه و آله تقاضاى يك انگشتر نمود؟\r\nپيامبر اسلام به دخترش فرمود: آيا مى خواهى تو را به چيزى كه از انگشتر بهتر است ، راهنمائى كنم ؟\r\nهر موقع كه نماز شب را خواندى ، خواسته خود را از خداوند در خواست نما كه برآورده خواهد شد.\r\nپس چون حضرت زهراء سلام اللّه عليها حاجت خود را از خداوند متعال طلب كرد، ندائى شنيد:\r\nاى فاطمه ! آنچه مى خواستى برآورده شد و هم اكنون زير سجّاده جانماز مى باشد.\r\nحضرت زهراء سلام اللّه عليها، سجّاده را بلند نمود و انگشترى از ياقوت زير آن بود؛ برداشت و بسيار خوشحال گشت و خوابيد. در خواب ديد كه وارد بهشت شده است و سه ساختمان قصر زيبا، حضرت را جلب توجّه كرد؛ لذا سؤ ال نمود كه اين قصرها براى كيست ؟\r\nپاسخ شنيد: براى فاطمه ، دختر محمّد صلّلى اللّه عليه و آله مى باشد، حضرت داخل يكى از آن قصرها شد كه بسيار مجهّز و زيبا بود، در اين ، بين چشمش به تختى افتاد كه سه پايه داشت ، سؤ ال نمود: چرا اين تخت سه پايه دارد؟\r\nگفته شد: چون صاحبش از خداوند انگشترى خواست ؛ پس يكى از پايه هاى اين تخت براى او انگشترى ساخته شد.\r\nچون صبح شد، حضور پدرش رسول خدا آمد و جريان خوابش را بيان نمود، حضرت رسول صلّلى اللّه عليه و آله فرمود: فاطمه جان ! دنيا براى شما و پيروان شما آفريده نشده است ؛ بلكه آخرت براى شماها خواهد بود و بهشت وعده گاه ما و شما مى باشد.\r\nو سپس افزود: اين دنيا ارزشى ندارد، بى وفا و از بين رفتنى است و غرورآور و فريبنده خواهد بود.\r\nهنگامى كه حضرت زهراء سلام اللّه عليها به منزل خويش آمد، آن انگشتر را زير جانمازش نهاد و از آن منصرف گرديد.\r\nو چون شب فرا رسيد خوابيد، در خواب ديد كه وارد بهشت شده است و همين كه عبورش در آن قصر به همان تخت افتاد، ديد كه بر چهار پايه استوار گشته است ، وقتى علّت را جويا شد.\r\nگفتند: صاحبش انگشتر را برگردانيد و تخت به همان حالت اوّليّه خود چهار پايه بازگشت.\r\n"},{"id":693,"category_id":6,"category_code":"s6","source_id":201,"title":"شب عروسی","content":"شب عروسى زهرا است . براى زهرا فقط يك پيراهن نو خريده اند به عنوان پيراهى شب زفاف و يك پيراهن قبلى هم داشته است. \r\nسائلى در شب زفاف مى آيد در خانه زهرا صدا مى كند: من عريانم كسى نيست مرا بپوشاند؟\r\nديگران متوجه اين سائل نمى شوند كه چيزى به او بدهند. زهرا كه عروس ‍ اين خانه است و به اصطلاح معروف عروسى است كه به تخت است مى بيند كسى متوجه نيست فورا تنها حركت مى كند مى رود در خلوت اين لباس نو را از تنش مى كند و لباس كهنه خودش را مى پوشد و لباس نو را تقديم سائل مى كند.\r\nوقتى مى آيد، مى پرسند پيراهنت كو؟\r\nمى گويد: در راه خدا دادم. \r\nبراى زهرا اينها چه عظمتى و چه اهميّتى دارد؟ لباس يعنى چه ؟ تشكيلات و دبدبه يعنى چه ؟ زهرا اگر دنبال فدك مى رود از باب اين است كه اصلا احقاق حق را واجب مى داند و الا فدك چه ارزشى دارد؟\r\nچون اگر نمى رفت دنبال فدك ، تن به ظلم داده بود و انظلام و ظلم پذيرى بود، والا صد مثل فدك را آنها در راه خدا مى دادند. چون انظلام نبايد كرد زهرا حق خودش را مطالبه مى كند، يعنى ارزش فدك براى حضرت زهرا از جنبه حقوقى بود نه از جنبه اقتصادى و مادى . از جنبه اقتصادى و مادى ارزشش فقط اين قدر بود كه اگر فدك داشته باشم ، به ديگران بتوانم برسم.\r\n"},{"id":694,"category_id":6,"category_code":"s6","source_id":202,"title":"تسبیحات حضرت زهرا","content":"\r\nاميرالمؤ منين عليه السلام به يكى از اصحاب فرمود:\r\n مى خواهى از وضع خود و فاطمه عليهاالسلام براى تو صحبت كنم ؟\r\nفاطمه در خانه من آن قدر آب آورد كه آثار مشك بر سينه اش پيدا بود و آن قدر آسياب كرد كه دست هايش پينه بست و چنان در نظافت و پاك كردن خانه و پختن غذا زحمت كشيد كه لباسهايش كثيف و مندرس شد و او بسيار صدمه ديد!\r\nبه همين خاطر به فاطمه توصيه كردم خوب است محضر رسول خدا صلى الله عليه و آله و سلم برسى و جريان را بيان نمايى ، شايد جهت كمك به تو خادمى بفرستد تا از اين همه زحمت خلاص شوى ! فاطمه عليهاالسلام اين توصيه مرا قبول كرد و نزد پيامبر صلى الله عليه و آله وسلم رفت ، اما چون ايشان را مشغول صحبت با اصحاب مى بيند، بدون آنكه خواسته اش را بگويد، باز مى گردد.\r\nرسول خدا صلى الله عليه و آله و سلم كه متوجه شده بودند فاطمه براى حاجتى آمده و بدون هيچ گونه صحبتى به خانه خود برگشته ، فرداى آن روز به منزل ما تشريف آوردند، و پس از سلام در كنار ما نشستند و آن گاه فرمودند:\r\n- فاطمه جان ! ديروز به چه منظور پيش من آمدى ؟\r\nفاطمه عليهاالسلام از خجالت نتوانست حاجتش را بگويد: من عرض ‍ كردم: \r\n- يا رسول الله ! آن قدر آب آورده كه بند مشك در سينه اش اثر گذاشته و آن قدر آسياب گردانيده كه دست هايش تاول كرده و... لذا گفتم محضر شما برسد شايد خادمى به ايشان مرحمت نماييد تا زحمت هايش كمتر شود.\r\nرسول خدا فرمود:\r\nمى خواهى مطلبى به شما بياموزم كه از خادم بهتر است . وقتى كه خواستى بخوابي 33 مرتبه بگوييد سبحان الله و 33 مرتبه بگوييد الحمد لله و 34 مرتبه بگوييد الله اكبرکه درمجموع100 مرتبه است ولى در نامه اعمال هزار حسنه (ثواب ) دارد.\r\nفاطمه جان ! اگر اين ذكرها را هر روز صبح بگويى خداوند خواسته هاى دنيا و آخرتت را برآورده خواهد كرد. فاطمه زهرا در جواب سه مرتبه گفت: \r\nاز خدا و پيغمبر راضى هستم .\r\n"},{"id":695,"category_id":6,"category_code":"s6","source_id":203,"title":"تابوت زیبا","content":"اسماء دختر عمیس گوید: در لحظات آخر عمر فاطمه (علیهاالسلام) در حضورش بودم به من فرمود: این تابوتها ناپسند است ، زیرا جسد را خوب نمی پوشاند، من عرض كردم در مهاجرت به حبشه ، تابوتهائی دیده ام كه جسد را به خوبی می پوشانند، فاطمه (علیهاالسلام) فورا فرستاد چند چوب درخت خرما آوردند، و من با آنها تابوت خوبی ساختم ، فاطمه (علیهاالسلام) خوشحال شد و فرمود: ما احسن هذا و اجمله لاتعرف به المرثه من الرجل . به به این تابوت چه زیبا و نیكو است، كه جسد مرد و زن در آن تشخیص ‍ داده نمی شود..."},{"id":696,"category_id":6,"category_code":"s6","source_id":204,"title":"زهد فاطمه","content":"از زهد و پارسائی فاطمه (علیهاالسلام) اینكه : روزی پیامبر (صلی الله علیه وآله) دید فاطمه (علیهاالسلام) آنچه داشت در راه خدا به مستمندان داد، فرمود: خاندان محمد (صلی الله علیه وآله) را با دنیای مادی چه كار؟ كه ایشان برای آخرت آفریده شده اند، اگر دنیا به اندازه پر مگسی ارزش داشت ، خداوند یك جرعه آب به كافر نمی داد. در این هنگام پیامبر (صلی الله علیه وآله) فرمود: فداها ابوها: پدرش به قربانش باد."},{"id":697,"category_id":6,"category_code":"s6","source_id":205,"title":"داستانی در مورد فدک","content":"ابن ابی الحدید معتزلی كه از علمای معروف و برجسته اهل تسنن است می گوید: من از استادم (علی بن فارقی) مدرس مدرسه بغداد پرسیدم آیا فاطمه (ع) از ادعای مالكیت فدك راست می گفت ؟. گفت : آری. \r\nگفتم : پس چرا خلیفه اول ، فدك را به او نداد، در حالی كه فاطمه (ع) نزد او را راستگو بود؟. او لبخندی زد و كلام زیبا و لطیف و طنز گونه ای گفت ، در حالی كه او هرگز عادت به شوخی نداشت ، گفت : اگر ابوبكر، فدك را به مجرد ادعای فاطمه (ع) به او می داد، فردا به سراغش می آمد و ادعای خلافت برای همسرش ‍ می كرد! و وی را از مقامش كنار می زد و او هیچگونه عذر و دفاعی از خود نداشت ، زیرا با دادن فدك پذیرفته بود كه فاطمه (ع) هر چه را ادعا كند راست می گوید، و نیازی به بینه و گواه ندارد. سپس ابن ابی الحدید می افزاید: این یك واقعیت است ، هر چند استاد، آن را به عنوان مزاح ، مطرح كرد. این اعتراف صریح از این دو دانشمند اهل تسنن حاكی است كه داستان فدك ، یك داستان سیاسی و آمیخته با خلافت بوده ، نه داستان صرفا اقتصادی.\r\n"},{"id":698,"category_id":6,"category_code":"s6","source_id":206,"title":"دوری از تجملات","content":"به نقل امام سجاد(علیه السلام) اسماء بنت عمیس گفت : حضرت زهرا (علیها السلام) گردنبندی از طلا به گردن داشت كه علی (علیه السلام) آن را از غنیمت جنگی به دست آورده بود. رسول خدا (صلی الله علیه وآله) بر او وارد شد، وقتی گردنبند را دید به اشاره فرمود: طوری نباشد كه مردم بگویند فاطمه (علیها السلام) خود را به تجملات زنهای كسری و قیصر آراسته است ، فاطمه (علیها السلام) مطلب را دریافت ، بی درنگ رفت و گردنبند را فروخت و با پول آن برده ای خرید و آزاد كرد. پیامبر (صلی الله علیه وآله) وقتی كه این موضوع را شنید خوشحال شد."},{"id":699,"category_id":6,"category_code":"s6","source_id":207,"title":"اهل بهشت","content":"مردى به همسرش گفت : برو خدمت حضرت فاطمه زهرا عليهاالسلام از او بپرس آيا من از شيعيان شما هستم يا نه ؟\r\nآن زن خدمت حضرت زهرا عليهاالسلام رسيد و مطلب را پرسيد. حضرت فاطمه عليهاالسلام فرمود:\r\n- به همسرت بگو اگر آنچه را كه دستور داده ايم بجا مى آورى و از آنچه كه نهى نموده ايم دورى مى جويى از شيعيان ما هستى وگر نه شيعه ما نيستى. \r\nزن به منزل برگشت و فرمايش حضرت زهرا عليهاالسلام را براى همسرش ‍ نقل كرد. مرد با شنيدن جواب حضرت سخت ناراحت شد و فرياد كشيد:\r\n- واى بر من ! چگونه ممكن است انسان به گناه و خطا آلوده نباشد؟\r\nبنابراين من هميشه در آتش جهنم خواهم سوخت ، زيرا هركس از شيعيان ايشان نباشد هميشه در جهنم خواهد بود.\r\nزن بار ديگر محضر فاطمه عليهاالسلام رسيد و ناراحتى و سخنان همسرش ‍ را نزد آن حضرت بازگو نمود.\r\nحضرت زهرا عليهاالسلام فرمود:\r\n- به همسرت بگو؛ آن طور كه فكر مى كنى نيست . چه اينكه شيعيان ما بهترين هاى اهل بهشتند ولى هركس ما را و دوستان ما را دوست بدارد دشمن دشمنان باشد و نيز دل و زبان او تسليم ما شود، ولى در عمل با اوامر و نواهى ما مخالفت كرده ، مرتكب گناه شود، گرچه از شيعيان واقعى ما نيست اما در عين حال او نيز در بهشت خواهد بود، منتهى پس از پاك شدن گناه. \r\nآرى ! به اين طريق است كه به گرفتاريهاى (دنيوى ) و يا به شكنجه مشكلات صحنه قيامت و يا سرانجام در طبقه اول دوزخ كيفر ديده ، پس از پاك شدن از آلودگيهاى گناه به خاطر ما از جهنم نجات يافته ، در بهشت و در جوار رحمت ما منزل مى گيرد.\r\n"},{"id":700,"category_id":6,"category_code":"s6","source_id":208,"title":"چهار سفارش مهم","content":"حضرت فاطمه زهرا(س) می فرماید: در حالی که بستر خود را پهن کرده بودم، رسول خدا(ص) بر من وارد شد و فرمود: ای فاطمه، سر به بستر خواب مگذار مگر این که چهار عمل را انجام دهی: قرآن را ختم کن، پیامبران را شفیع خود قرار بده، اهل ایمان را از خویش راضی گردان و یک حج و عمره انجام بده.\r\nپدرم این چهار دستور را داد و مشغول نماز شد. من هم در حالی که انجام این چهار کار را مشکل می دیدم، به فکر فرو رفتم و صبر کردم که نماز پدرم تمام شود و برای انجام آن اعمال راهنمایی بگیرم. وقتی نماز حضرتش به پایان رسید، عرض کردم: ای رسول خد، چهار دستور به من دادی که برای انجام آن در این وقت کم توانایی ندارم. آن حضرت لبخندی زد و بعد فرمود:\r\nاگر (قل هو الله احد) را سه مرتبه بخوانی، مثل این است که یک ختم قرآن انجام داده ای\r\nو اگر بر من و پیامبران قبل از من صلوات بفرستی، همه ما روز قیامت شفیعان تو هستیم\r\nو اگر برای اهل ایمان از خداوند آمرزش بخواهی، همه آنان از تو رضایت مند خواهند شد\r\nو اگر بگویی: (سبحان الله والحمدلله ولا اله الا الله والله اکبر) مانند این است که حج و عمره انجام داده ای.\r\n"},{"id":701,"category_id":6,"category_code":"s6","source_id":209,"title":"مهربانی با همسر","content":"روزى على (عليه السلام) در شدت گرماى بعد از ظهر به طرف منزل آمدند، زنى را ديد كه بر در خانه ايستاده است، به حضرت على (عليه السلام) عرض كرد: شوهرم به من ستم مى‏كند، تهديد مى‏كند قسم ياد كرده من را بزند.\r\nحضرت فرمودند: صبر كنيد شدت گرما تخفيف پيدا كند به خواست خداوند با تو می‏آيم و به كارت رسيدگى خواهم كرد، زن با نگرانى و ناراحتى عرض كرد: با طول غيبت من از منزل خشم شوهرم شديدتر می شود و كار سخت‏تر می شود، حضرت با شنيدن اين سخن سر فرو برد و چند لحظه فكر كرد.\r\nپس از آن سربرداشت و فرمود: بخدا قسم بدون كمترين تاخير بايد حق مظلوم گرفته شود، اين سخن را گفت و پرسيد: منزلت كجا است؟ با زن حركت كرد تا در خانه‏اش رسيدند.\r\nدر خانه حضرت ايستاد و از بيرون در با صداى بلند سلام كرد، جوانى از خانه بيرون آمد حضرت به وى فرمود: از خدا بترس، تو زنت را ترسانده‏اى او را از منزل بيرون كرده‏ اى، جوان با خشونت و با  بی ادبى گفت: كار همسر من به تو چه ربطى دارد؟ بخدا قسم براى گفته تو زنم را آتش خواهم زد.\r\nعلى (عليه السلام) از شنيدن سخنان جوان كه از خودسرى و قانون شكنى او حكايت می‏كرد سخت بر آشفت، شمشير از نيام كشيد و فرمود: من تو را امر به معروف و نهى از منكر میكنم و فرمان الهى را ابلاغ می‏نمايم، تو با من از گناه سخن میگويى و از امر حق سرپيچى مى‏كنى، در اين بين سخن آن حضرت با آن جوان رد و بدل می شد، كسانى كه از آن كوچه عبور مى‏كردند، اطراف على (عليه السلام) جمع شدند و به عنوان امير المومنين به آن حضرت سلام میكردند، جوان آن حضرت را شناخته بود از سلام مردم متوجه شد كه با شخص اول مملكت سخن میگويد، تكان خورد و به خود آمد و با شرمندگى سر را بطرف دست على (عليه السلام) فرود آورد و گفت: يا امير المومنين از لغزش من درگذر، به خدا قسم امرت را اطاعت مى‏كنم و حداكثر تواضع را نسبت به همسرم معمول خواهم داشت.\r\nحضرت شمشير خود را در غلاف فرو برد و به زن نيز توصيه كرد كه با شوهرت طورى رفتار كن كه در چنين كارهايى خشونتى وارد نشود.\r\n"},{"id":702,"category_id":6,"category_code":"s6","source_id":210,"title":"شیرینی عسل","content":"يك روز آقا رئيس اسلام ، خاتم الانبياء، محمّد مصطفى (ص )، با آقا اميرالمؤ منين على (ع )، در ميان نخلستانها نشسته بودند. كه يك وقت سر و كله زنبورِ عسلى ظاهر شد، و شروع كرد، دور پيغمبر اكرم (ص ) چرخيدن. \r\nپيغمبر (ص ) فرمود:\r\nيا على ! مى دانى اين زنبور چه مى گويد.\r\nحضرت على (ع ) فرمود: خير.\r\nآقا رسول اكرم (ص ) فرمودند:\r\nاين زنبور امروز ما را مهمانى كرده و مى گويد: يك مقدار عسل در فلان محل گذاشته ام ، آقا اميرالمؤ منين (ع ) را بفرستيد، تا آن را از آن محل بياورد.\r\nآقا اميرالمؤ منين على (ع ) بلند شدند و آن عسل را از آن محل آوردند.\r\nحضرت رسول خدا(ص ) فرمود:\r\nاى زنبور، غذاى شما كه از شكوفه گل تلخ است . به چه علّتى آن شكوفه به عسل شيرين تبديل مى شود؟\r\nزنبور گفت : يا رسول اللّه ، شيرينى اين عسل ، از بركت ذكر وجود مقدّس ‍ شما، و (آل ) شماست ، چون هر وقت ، مقدارى از شكوفه استفاده مى كنيم ، همان لحظه به ما الهام مى شود كه سه بار بر شما صلوات بفرستيم. \r\nوقتى كه مى گوئيم : اَللّهُمَّ صَلِّ عَلى مُحَمَّدٍ وَ آلِ مُحَمَّد به بركت صلوات بر شما، عسل ما شيرين مى شود.\r\n"},{"id":703,"category_id":6,"category_code":"s6","source_id":211,"title":"نامه ی اعمال","content":"امام على (عليه السلام ) در حال عبور از محلى ، چشمش به عده اى از جوانان افتاد، كه سخنان لغو و بيهوده مى گفتند و مى خنديدند. حضرت فرمودند: آيا نامه عملتان را با اين چيزها سياه مى كنيد؟ گفتند: يا على (عليه السلام ) آيا اينها را هم مى نويسند؟\r\nحضرت فرمود: آرى ! حتى دميدن نفس را هم مى نویسند.\r\n"},{"id":704,"category_id":6,"category_code":"s6","source_id":212,"title":"دشمن علی(ع)","content":"از ابى هريره منقول است كه صبح با رسول اكرم صلى‏الله عليه و آله نماز خوانديم حضرت رو به اصحاب كرده بود صحبت مى‏فرمودند، كه مردى از انصار رسيد، گفت: يا رسول الله گذار من بر در خانه فلان شخص افتاد كه سگى دارد سر راه من گرفته جامه مرا پاره كرده و ساق مرا مجروح ساخته مرا از نماز صبح محروم كرد.\r\nروز ديگر شخص ديگر آمد و به همان طريق شكوه كرد از آن سگ كه جامه مرا پاره كرده و ساق مرا مجروح كرده و به نماز نرسيدم و ناراحت شدم.\r\nحضرت رسول صلى‏الله عليه و آله برخاسته متوجه منزل آن شخص شد، فرمود: سگ عقور را بايد كشت چون به در خانه رسيد در را بكوفت، صاحب خانه بيرون آمد گفت: يا رسول الله چه چيز شما را به خانه من آورده و حال آنكه من بر دين شما نيستم اگر كارى با من بود دستور مى‏داديد من مى‏آمدم من چه شخصى هستم كه شما منزل من بياييد.\r\nحضرت فرمود شما سگى درنده داريد و هر روز يكى را مجروح مى‏سازد او را بياوريد من او را به قتل برسانم آن مرد به خانه دويد ريسمانى در گردن سگ كرده كشان كشان بيرون آورد چون چشم آن سگ به رسول الله صلى‏الله عليه و آله افتاد به قدرت الهى به زبان آمد و گفت: السلام عليك يا رسول الله، چه چيز شما را به اينجا آورده و سبب قتل من چيست؟ حضرت فرمودند: ديروز فلانى را، امروز فلانى را جامه دريده، پاهاى ايشان را مجروح نموده‏ايد و از نماز ساخته‏ايد.\r\nآن سگ به زبان فصيح گفت: يا رسول الله مرا كار به مومنان نيست و اين شخص از جمله منافقان و دشمنان امير المومنين هستند چون به خانه خود مى‏روند پسر عم تو را ناسزا مى‏گويند و سب مى‏كنند و اگر آنها چنين نبودند معترض نمى‏شدم لكن آنها را به قدر امكان ايذا مى‏كنم.\r\nچون رسول خدا صلى‏الله عليه و آله اين كلمات را از آن حيوان شنيد به صاحب سگ سفارش نمود با محبت رفتار نمايد.\r\nحضرت حركت كرد و خواست كه برگردد آن مرد بدست پاى حضرت افتاد و گفت: يا رسول الله سگ من شهادت به رسالت تو داده باشد من كمتر از سگ باشم كه به شما ايمان نياورم يا رسول خدا دست مبارك را به من بدهيد تا مسلمان شوم دست حضرت را گرفت و شهادتين را به زبان جارى كرد و گفت: اشهد ان لااله الا الله و اشهد ان محمد رسول الله و اشهد ان على ولى الله و جميع آنهايى كه در خانه بودند همگى مسلمان شدند.\r\nيك حيوان درنده دشمنان على بن ابى طالب را پاره مى‏كند و دوستان آن بزرگوار را اذيت نمى‏كند.\r\n"},{"id":705,"category_id":6,"category_code":"s6","source_id":213,"title":"قضاوت علی(ع)","content":"امیرالمومنین علیه السلام به وشاء فرمود: به محلتان برو! زن و مردی را بر در مسجد می بینی با هم نزاع می كنند آنان را به نزد من بیاور، وشاء می گوید بر در مسجد رفتم دیدم زن و مردی با هم مخاصمه می كنند، نزدیك رفتم و به آنان گفتم امیرالمومنین شما را می طلبد، پس همگی به نزد آن حضرت رفتیم . علی علیه السلام به جوان فرمود: با این زن چكار داری؟ \r\nجوان : یا امیرالمومنین ! من این زن را با پرداخت مهریه ای به عقد خود در آوردم و چون خواستم به او نزدیك شوم ، خون دید و من در كار خود حیران شدم . امیرالمومنین علیه السلام به جوان فرمود: این زن بر تو حرام است و تو هرگز شوهر او نخواهی شد. مردم از شنیدن این سخن در اضطراب و متعجب شدند. علی علیه السلام به زن فرمود: مرا می شناسی؟ \r\nزن : نامتان را شنیده ، ولی تاكنون شما را ندیده بودم . علی علیه السلام تو فلان زن دختر فلان و از نوادگان فلان نیستی؟ زن : آری ، بخدا سوگند. حضرت امیر: آیا به فلان مرد، فرزند فلان در پنهانی بطور عقد غیر دائم ، ازدواج نكردی و پس از چندی پسر زاییدی و چون از عشیره و بستگانت بیم داشتی طفل را در آغوش كشیده و شبانه از منزل بیرون شدی و در محل خلوتی فرزند را بر زمین گذارده و در برابرش ایستاده و عشق و علاقه ات نسبت به او در هیجان بود،دوباره برگشتی و فرزند را بغل كردی و باز به زمین گذاردی و طفل ، گریه می كرد و تو ترس رسوایی داشتی ، سگهای ولگرد اطرافت را گرفته و تو با تشویش و ناراحتی می رفتی و بر می گشتی ، تا این كه سگی بالای سر پسرت آمد و او را گاز گرفت و تو بخاطر شدت علاقه ای كه به فرزند داشتی سنگی به طرف سگ انداخته سر فرزندت را شكستی ، كودك صیحه زد و تو می ترسیدی صبح شود و رازت فاش گردد، پس برگشتی و اضطراب خاطر و تشویش فراوان داشتی ، در این هنگام دست به دعا برداشته و گفتی : بار خدایا! ای نگهدارنده ودیعه ها. زن گفت : بله ، بخدا سوگند همین بود تمام سرگذشت من و من از گفتار شما بسی در شگفتم . پس امیرالمومنین علیه السلام رو به جوان كرد و فرمود: پیشانیت را باز كن ، و چون باز كرد آن حضرت جای شكستگی پیشانی جوان را به زن نشان داد و به او فرمود: این جوان پسر توست و خداوند با نشان دادن آن علامت به او نگذاشت به تو نزدیك گردد؛ و همان گونه از خدا خواسته بودی فرزندت را حفظ كند، او را برایت نگهداشت ، پس شكر و سپاس ‍ خدای را به جای بیاور.\r\n"},{"id":706,"category_id":6,"category_code":"s6","source_id":214,"title":"رقابت جاهلانه","content":"پس از گذشت دهها سال از عصر جاهليت ، زماني كوفه دچار قحطي گرديد و مردم به مضيقه افتادند. يكي از روزها (غالب ) پدر فرزدق شاعر كه رييس قبيله بني تميم بود براي غذاي خانواده خود شتري كشت و طعام زيادي تهيه كرد، چند ظرف غذا براي افراد قبيله خود فرستاد و يك ظرف هم براي سحيم بن وثيل رييس قبيله بني رياح . سحيم از عمل غالب ، سخت خشمگين شد و آنرا هتك خود پنداشت بهمين جهت ظرف غذا را بزمين ريخت و آورنده غذا را كتك زد و گفت من نيازي بطعام غالب ندارم و اكنون كه او شتري كشته من نيز چنين ميكنم و شتري كشت . بر اثر اينكار بين آن دو رقابت آغاز گرديد فرداي آنروز غالب دو شتر كشت و سحيم نيز دو شتر. روز سوم غالب سه شتر كشت و سحيم هم سه شتر، روز چهارم غالب صد شتر كشت و سحيم كه آن تعداد شتر در اختيار نداشت آنروز حتي يك شتر هم نكشت ولي از اين شكست و عقب نشيني ناراحت شد و آنرا بدل گرفت تا فرصت مناسبي فرا رسد و آن شكست را جبران نمايد.\r\nدوران قحطي سپري شد و وضع مردم كوفه بحال عادي برگشت ، در يكي از روزها كساني از قبيله بني رياح ، به سحيم گفتند تو با عملت ما را دچار ننگ و بدنامي كردي . چرا آنروز همانند غالب صد شتر نكشتي ما حاضر بوديم بجاي هر يك شتر به شما دو شتر بدهيم  ما عذر آورد كه آنروز شترهاي من در بيابانها پراكنده بودند و صد شتر در دسترس نداشتم . سپس يك روز سيصد شتر كشت و در اختيار عموم قرار داد و اعلام نمود تمام مردم و همه خانواده ها ميتوانند رايگان از گوشت شترها استفاده كنند و هر قدر ميخواهند ببرند و براي خود غذا تهيه نمايند.\r\nاين قضيه در زمان حكومت علي عليه السلام اتفاق افتاد و درباره حليت گوشت شترها استفاء شد. آنحضرت به حرمت آنها حكم داد و فرمود اين شترها را براي تاءمين غذا و رفع نياز مردم نكشته اند بلكه مقصود از اينكار تنها مفاخره و مباهاه بوده است . بر اثر اين حكم شرعي ، مردم مسلمان از بردن و خوردن آن گوشتها خودداري كردند، لاشه شترها را در مركز زباله شهر كوفه انداختند و طعمه سگها، عقابها، كركسها و ديگر پرندگان وحشي شد.\r\n"},{"id":707,"category_id":6,"category_code":"s6","source_id":215,"title":"احمد جامی","content":"روزى احمد جامى بر بالاى منبر رفت و گف ت : اى مردم هر چه مى خواهيد از من بپرسيد. ناگهام زنى از پشت پرده فرياد زد كه : اى مرد ادعاى بيهوده نكن زيرا خداوند رسوايت خواهد كرد. هيچ كس جز على (عليه السلام) نمى تواند بگويد كه پاسخ تمام سؤ الات را مى داند شيخ احمد گفت : اگر سؤ الى دارى بپرس تا جواب بدهم. \r\nزن گفت : آن مورچه اى كه بر سر راه سليمان نبى آمد، نر بود يا ماده ؟\r\nشيخ گفت : آيا سؤ ال ديگرى نداشتى اين ديگر چه سؤ الى است ؟ من كه در آن زمان نبوده ام كه ببينم نر بوده است يا ماده . زن گفت : نيازى نيست كه تو در آن زمان بوده باشى ، اگر با قرآن آشنايى داشتى جواب را مى دانستى . در قرآن سوره نمل آمده است كه ((قالت نمله )) از اين مشخص مى شود كه مورچه نر بوده است يا ماده . مردم به جهل شيخ و زيركى زن خنديدند.\r\nشيخ گفت : بگو اى زن آيا با اجازه شوهرت در اين جلسه شركت كرده اى يا بدون اجازه او؟ اگر با اجازه آمده اى كه خدا شوهرت را لعن كند و اگر بى اجازه آمده اى خداوند خودت را لعن كند. زن گفت : بگو ببينم آيا ام المؤمنين جناب عايشه با اجازه پيامبر به جنگ امام زمان خود على (عليه السلام ) آمده بود و يا بدون اجازه ؟\r\nپس شيخ بيچاره نتوانست جواب گويد و از منبر به زير آمد و به منزل رفت و چند روزى از غصه رسوايى بيمار شد.\r\n"},{"id":708,"category_id":6,"category_code":"s6","source_id":216,"title":"سرى بريده در محراب","content":"در كتب شيعه و سنى نقل شده كه: روزى عمر از براى نماز به مسجد النبى رفت ديد يك جوانى سربريده در ميان محراب گذاشته شده است، هر چه تفحص از قاتل نمودند چيزى به دست نيامد.\r\nقصه را به على (عليه السلام) تذكر دادند آن حضرت فرمودند: قاتل فعلا معلوم نمى‏شود برويد مقتول را دفن نماييد، من بعدا قاتل را معرفى مى‏كنم بر حسب امر حضرت جنازه را دفن نمودند و در حدود سه ماه از اين قضيه گذشت، باز عمر از براى نماز صبح رفت به مسجد ديد بچه نوزاد در ميان قنداق توى محراب گذاشته‏اند هر چه تفحص كردند مادرش معلوم نشد.\r\nقضيه را به على (عليه السلام) تذكر دادند فرمود: بچه را به دايه بدهيد شير بدهد تا من مادر او را معرفى مى‏كنم، تا اينكه عيد فطر رسيد على (عليه السلام) به دايه فرمود: بچه را زينت دهيد، فردا كه عيد فطر است او را قنداق مى‏كنى و بر روى دست مى‏گيرى و در مصلى و در ميان صفوف زنها گردش مى‏كنى تا اينكه زنى درشت اندام تا چشمش به اين بچه مى‏افتند بى اختيار او را از تو مى‏گيرد و مى‏بوسد و اشكش بر جبين بچه جارى مى‏شود و مى‏گويد: آه براى تو اى بچه بى گناه و مظلوم و داد از پدر ظالم تو.\r\nدر اين حال آن زن را بياوريد پيش من، دايه بر حسب دستور حضرت روز عيد فطر بچه را در ميان صفوف زنان گردش مى‏داد آن زن آمد بچه را بوسيد و گفت: اى بچه بى گناه و مظلوم و داد از پدر ظالم تو، گرفت بچه را و گريه كرد در اين هنگام دست او را گرفت و گفت: حضرت على (عليه السلام) تو را خاسته، آن زن گلوبندى طلا به او داد و گفت: مرا رها كنيد، او را رها كرد و آمد پيش على (عليه السلام) گفت: من كسى را نديدم.\r\nفرمود دروغ مى‏گوى، هر چه گفته‏ام درست است ولكن تو گلوبند گرفتى و او را رها كردى، خواست او را تاديب كند، از او وساطت كردند، رها كرد و فرمود: ديگر به آن زن پيدا نمى‏كنى تا سال آينده و حالا بچه راببريد، سال ديگر دو روز به عيد فطر مانده بياوريد پيش من، بچه را بردند.\r\nسال آينده روز معين آوردند، على (عليه السلام) مثل گذشته دستور فرمود: كه در ميان صفها زنى مى‏آيد از تو بچه را مى‏گيرد و مى‏بوسد و حرف‏هاى سال گذشته را به زبان جارى مى‏كند و آن زن را پيش من بياوريد، اگر اين دفعه نياوريد تو را عقوبت سخت خواهم كرد، دايه طبق فرمان حضرت آن بچه را از دست اين زن گرفت، بوسه زد زن را آورد پيش حضرت على (عليه السلام) فرمود: به چه جهت اين بچه را از دست اين زن گرفتى و بوسيدى و گريه كردى؟\r\nگفت: او را زيبا ديدم، فرمود: چرا گريه كردى؟ دلم سوخت بحال او كه پدر و مادر ندارد.\r\nحضرت فرمود: كسى به تو نگفته از كجا مى‏دانيد، زن ساكت شد ناچار اقرار كرد كه اين طفل مال من است، چون بعد از يكسال ديدم طاقت نياوردم.\r\nحضرت فرمود: چرا در مسجد گذاشته بودى تا پدر او را معرفى نكنى تو را رها نمى‏كنم و من از اوضاع شما باخبرم لكن خودت بايد داستان خود را نقل كنى، گت: ناچارم بگويم، من دختر مردى از انصار مى‏باشم و پدرم در يكى از جنگهاى اسلامى شهيد شد و مادر هم ندارم، لذا از تنهايى شب و روز گريه مى‏كردم تا اينكه يك روزى زن مقدسه وارد منزل من شد و از حال من آگاه شد، خيلى گريه كرد و گفت: تو را تنها نمى‏گذارم و من مادر تو هستم.\r\nمدتى شب و روز پيش من بود مثل اين زن در تقوى نديده بودم، تا روزى مى‏خواست حمام برود، به من گفت: نور چشم من اگر مى‏ترسى و تنها هستى من دخترى به سن تو دارم پيش تو مى‏آورم، من هم قبول كردم وقتى كه آورد درب حياط را به روى ما بست كه كسى وارد نشود.\r\nچون زن رفت و اين دختر چادر را از سرش برداشت ديدم يك مرد جوانى است و دست بى‏عفتى به طرف من دراز كرد و هر چه قسم دادم فايده نكرد تا اينكه خواسته خود را عملى كرد و بسيار من ناراحت شدم و صبر كردم تا اين جوان خوابيد سرش را از بدن جدا كردم و جنازه او را در محراب مسجد گذاشتم و اين بچه از او است، آوردم در محراب گذاشتم كه تلف نشود، پس از يكسال او را ديدم طاقت نياوردم و لذا او را بغل گرفتم و بوسيدم.\r\nحضرت على (عليه السلام) فرمودند: زن را به من نشان بدهيد، زن را آوردند حضرت او را تعزير كرد.\r\n"},{"id":709,"category_id":6,"category_code":"s6","source_id":217,"title":"هوس","content":"\r\nروزى حضرت على (ع ) از درب دكان قصابى مى گذشت. \r\nقصاب به آن حضرت عرض كرد:\r\nيا اميرالمؤ منين ! گوشتهاى بسيار خوبى آورده ام . اگر ميخواهيد ببريد.\r\nفرمود: الا ن پول ندارم كه بخرم. \r\nعرض كرد من صبر مى كنم پولش را بعدا بدهيد.\r\nفرمود: من به شكم خود مى كويم كه صبر كند اگر نمى توانستم به شكم خود بگويم از تو مى خواستم كه صبر كنى ولى حالا كه ميتوانم به شكم خود مى گويم كه صبر كند.\r\nآرى ، خاصيت نفس اماره اين است كه اگر تو او را وادار و مطيع خود نكنى او تو را مشغول و مطيع خود خواهد ساخت . ولى على (ع ) كه در ميدان جنگ مغلوب عمرو بن عبدودها و مرحب ها نمى شود، به طريق اولى و صد چندان بيشتر هرگز بر خود نمى پسندد كه مغلوب يك ميل و هواى نفس گردد.\r\n"},{"id":710,"category_id":6,"category_code":"s6","source_id":218,"title":"دعا به اسم اعظم","content":"ابوعمره كه معروف به زاذان بوده عجمی و ایرانی بود. وی از یاران مخصوص امیرالمؤمنین علی،‌(ع) گردید. سعد خفاف می‌گوید: شنیدم زاذان با این كه عجمی است، با صدای بسیار خوب و غمگین قرآن می‌خواند، به او گفتم: تو آیات قرآن را خیلی خوب می‌خوانی، از چه كسی آموخته‌ای؟ \r\nلبخندی زد و گفت: روزی امام علی،‌(ع) از كنار من عبور كرد، من شعر می‌خواندم و صوت عالی داشتم به گونه‌ای كه آن حضرت از صدای من تعجب كرد و فرمود: ای زاذان چرا قرآن نمی‌خوانی؟ عرض كردم: قرائت قرآن را نمی‌دانم، جز آن مقداری كه در نماز، بر من واجب است. آن حضرت به من نزدیك شد، و در گوشم سخنی فرمود كه نفهمیدم چه بود، پس فرمود: دهانت را باز كن، دهانم را گشودم، آب دهانش را به دهانم مالید، سوگند به خدا، قدمی از حضورش برنداشتم كه در همان دم، دریافتم همه قرآن را به طور كامل حفظ هستم. پس از این جریان، به هیچ كس، نیازی در یادگرفتن قرآن، پیدا نكردم. \r\nسعد می‌گوید: این قصه را برای امام باقر،‌(ع)، نقل كردم، فرمود: زاذان راست می‌گوید، چرا كه امیرالمؤمنین علی برای زاذان، به اسم اعظم خدا، دعا كرد، و چنین دعایی رد خور ندارد.\r\n"},{"id":711,"category_id":6,"category_code":"s6","source_id":219,"title":"عشق سوزان","content":"\r\nمرد سياه چهره اى به حضور على عليه السلام رسيد عرض كرد:\r\nيا اميرالمؤ منين من دزدى كرده ام مرا پاك كن ! حدى بر من جارى ساز!\r\nپس از آن كه سه بار اقرار به دزدى كرد، امام عليه السلام چهار انگشت دست راست او را قطع نمود. از محضر على عليه السلام بيرون آمد و به سوى خانه خود رهسپار گرديد با اين كه ضربه سختى خورده بود در بين راه با شور شوق خاص فرياد مى زد:\r\nدستم را اميرالمؤ منين ، پيشواى پرهيزگاران و سفيدرويان ، آن كه رهبر دين و آقاى جانشينان است ، قطع كرد.\r\nمردم از هر طرف اطرافش را گرفته بودند، او همچنان در مدح على سخن مى گفت. \r\nامام حسن و امام حسين از گفتار مرد با خبر شدند آمدند او را مورد محبت قرار دادند، سپس محضر پدر گراميشان رسيدند و عرض كردند:\r\nپدر جان ! ما در بين راه مرد سياه چهره اى كه دستش را بريده بودى ، ديديم تو را مدح مى كرد.\r\nامام عليه السلام دستور داد او را به حضورش آوردند. حضرت به وى عنايت نمود و فرمود:\r\nمن دست تو را قطع كردم ، تو مرا مدح و تعريف مى كنى ؟\r\nعرض كرد:\r\nيا اميرالمؤ منين ! عشق با گوشت و پوست و استخوانم آميخته است ، اگر پيكرم را قطعه قطعه كنند، عشق و محبت شما از دلم يك لحظه بيرون نمى رود. شما با اجراى حكم الهى پاكم نمودى. \r\nامام عليه السلام درباره او دعا كرد، آنگاه انگشتان بريده اش را بجايشان گذاشت ، انگشتان پيوند خورد و مانند اول سالم شد.\r\n"},{"id":712,"category_id":6,"category_code":"s6","source_id":220,"title":"دروغ کوچک","content":"\r\nاسماء دختر عميس مى گويد:\r\nمن شب زفاف عايشه را آماده كرده به نزد پيغمبر (صلى الله عليه و آله ) بردم و عده اى از زنان همراه من بودند. به خدا سوگند! نزد حضرت غذايى جز يك ظرف شير نبود. رسول خدا مقدارى از آن خورد. سپس ظرف شير را به دست عايشه داد، عايشه حيا نمود بگيرد. به او گفتم : دست پيغمبر را رد نكن ! عايشه با شرم ظرف شير را گرفت و مقدارى خورد\r\nآنگاه پيامبر فرمود: ظرف شير را به همراهان خود بده! \r\nآنها گفتند: ما اشتها نداريم.\r\nپيامبر خدا فرمود:\r\nهرگز گرسنگى و دروغ را با هم جمع نكنيد.\r\nاسماء گفت : يا رسول الله ! اگر يكى از ما بگويد اشتها نداريم ، اين دروغ حساب مى شود؟\r\nپيامبر فرمود: بلى ! دروغ در نامه عمل انسان نوشته مى شود. حتى دروغ كوچك در نامه اعمال به عنوان دروغ كوچك ثبت مى گرد.\r\n"},{"id":713,"category_id":6,"category_code":"s6","source_id":221,"title":"ریزش گناهان","content":"\r\nابوعثمان مى گويد:\r\nمن با سلمان فارسى زير درختى نشسته بودم ، او شاخه خشكى را گرفت و تكان داد همه برگهايش فرو ريخت . آنگاه به من گفت : نمى پرسى چرا چنين كردم ؟\r\nگفتم : چرا اين كار را كردى ؟\r\nدر پاسخ گفت: \r\nيك وقت زير درختى در محضر پيامبر (صلى الله عليه و آله ) نشسته بودم ، حضرت شاخه خشك درخت را گرفت و تكان داد تمام برگهايش فرو ريخت . سپس فرمود:\r\nسلمان ! سؤ ال نكردى چرا اين كار را انجام دادم ؟\r\nعرض كردم : منظورت از اين كار چه بود؟\r\nفرمود: وقتى كه مسلمان وضويش را به خوبى گرفت ، سپس نمازهاى پنچگانه را بجا آورد، گناهان او فرو مى ريزد، همچنان كه برگهاى اين درخت فرو ريخت.\r\nآن فقیر کجاست؟\r\n امیرمؤمنان علی(ع) در مسجد کوفه اعتکاف کرده بود که بادیه نشینی هنگام افطار به محضر او رسید. حضرت مقداری آرد جو همراه داشت. به او تعارف کرد و او نتوانست میل کند. از آن جا به خانه حسن و حسین(علیهم السلام) رفت و با آن ها غذا خورد. به هنگام غذا گفت: فقیری را دیدم که دلم برایش سوخت و نمی توانم چیزی تناول کنم و از آن ها خواست مقداری غذا برای آن فقیر ببرند.\r\nامام حسن(ع) پرسید: آن فقیر کجا و کیست؟ آن مرد داستان را تعریف کرد. صدای گریه امام حسن(ع) بلند شد و فرمود: او پدرم علی(ع) امیرمؤمنان و خلیفه مسلمانان است.\r\n"},{"id":714,"category_id":6,"category_code":"s6","source_id":222,"title":"مولا و غلام قاتل","content":"\r\nغلامى را نزد عمر آوردند، غلام ، مولاى خود را کشته بود، عمر دستور داد او را بکشند. امیرالمومنین علیه السلام از قضیه خبردار گردیده غلام را به حضور طلبید و به او فرمود: آیا مولایت را کشته اى ؟\r\nغلام : آرى. \r\nامیرالمومنین علیه السلام : چرا؟\r\nغلام : با من عمل خلاف نمود.\r\nعلى علیه السلام از اولیاى مقتول پرسید؛ آیا کشته خود را به خاک سپرده اید؟\r\nگفتند: آرى. \r\nفرمود: چه وقت ؟\r\nگفتند: همین الان. \r\nحضرت امیر به عمر رو کرده و فرمود: غلام را بازداشت کن و او را عقوبت نده و به اولیاى مقتول بگو پس از سه روز دیگر بیایند.\r\nچون پس از سه روزه آمدند، على علیه السلام دست عمر را گرفت و به اتفاق اولیاى مقتول به جانب گورستان رهسپار شدند، و چون به قبر آن مرد رسیدند، آن حضرت به اولیاى مقتول فرمود: این قبر کشته شماست ؟ گفتند: آرى. \r\nفرمود: آن را حفر کنید! آن را حفر کردند تا به لحد رسیدند آنگاه به آنان فرمود: میت خود را بیرون بیاورید، آنها هر چه نگاه کردند جز کفن میت چیزى ندیدند. جریان را به آن حضرت عرضه داشتند.\r\nامیرالمومنین علیه السلام دوبار تکبیر گفت و فرمود: به خدا سوگند نه من دروغگو هستم و نه کسى که به من خبر داده است ، شنیدم از رسول خدا صلى الله علیه و آله که فرمود: هر کس از امتم که کردار قوم لوط را مرتکب شود، پس از مردن سه روز بیشتر در قبر نمى ماند و زمین او را به قوم لوط که به عذاب الهى هلاک شدند مى رساند، و در روز قیامت با آنان محشور مى گردد.\r\n"},{"id":715,"category_id":6,"category_code":"s6","source_id":223,"title":"پیشگویی","content":"در نهج البلاغه آمده است كه امام على (ع ) وقتى تصميم گرفتند به جنگ خوراج بروند، اشعث بن قيس كه آن وقت از اصحاب بود، با عجله و شتابان جلو آمد و گفت : يا اميرالمؤ منين ، صبر كنيد، عجله نكنيد، براى آنكه يكى از خويشاوندان من مطلبى دارد و مى خواهد به عرض شما برساند.\r\nحضرت فرمودند بيايد.\r\nآمد عرض كرد: يا اميرالمؤ منين . من منجم هستم و متخصص سعد و نحس ايام . در حسابهاى خودم به اينجا رسيدم كه شما اگر الآن حركت كنيد و به جنگ برويد قطعا شكست خواهيد خورد و با اكثريت اصحابتان كشته خواهيد شد.\r\nحضرت در جواب فرمودند: هر كس كه گفته تو را تصديق كند. پيغمبر را تكذيب كرده است  .اين حرفها چيست كه شما مى گوييد؟...سپس به اصحاب فرمودند: بگوييد به نام خدا، به خدا اعتماد و توكل كنيد، حركت كنيد، عليرغم نظر منجم الان حركت كنيد و برويد.\r\nرفتند و بعد معلوم شد كه در هيچ جنگى به اندازه اين جنگ ، على (ع ) فاتح نشده است.\r\n"},{"id":716,"category_id":6,"category_code":"s6","source_id":224,"title":"دوست واقعی","content":"مسلم مجاشعی جوانی بود از اهل مدائن كه در زمان فرمانداری حذیفه بن یمان در مدینه به حذیفه گرائید. به وسیله حذیفه از دوستان فدائی امیرمؤ منان گردید.\r\nدر جنگ جمل امیرمؤمنان برای اتمام حجت با مردم بصره و لشگرعایشه قرآنی به دست گرفت و فرمود: كیست كه این قرآن را ببرد و بر این مردم عرضه كند و ایشان را به حكم آن بخواند! مسلم جوان ، قرآن را از امام گرفت و به میدان رفت. \r\nامام در این هنگام فرمود: همانا این جوان از كسانی است كه خداوند دل او را هدایت و ایمان پر كرده ، اما او كشته می شود و من بخاطر ایمانش به او علاقه فراوان دارم و این لشگرهم پس از كشتن او رستگار نمی شوند.\r\nمسلم سپاه عایشه و مردم بصره را به حكم قرآن دعوت كرد، ولی آنها دست راستش را قطع كردند، او قرآن به دست چپ گرفت ، دست چپ او را قطع كردند، قرآن را با دست های بریده بر سینه چسبانید و خون بر آن جاری بود كه سپاه دشمن یكباره بر او حمله كردند و او را قطعه قطعه نمودند و شكمش را دریدند.\r\n"},{"id":717,"category_id":6,"category_code":"s6","source_id":225,"title":"زنی در نکاح فرزندش","content":"در زمان خلافت عمر، جوانى به نزد او آمد و از مادرش شكايت كرد. و ناله سر مى داد كه: \r\n- خدايا! بين من و مادرم حكم كن \r\nعمر از او پرسيد:\r\n- مگر مادرت چه كرده است ؟ چرا درباره او شكايت مى كنى ؟\r\nجوان پاسخ داد: مادرم نه ماه مرا در شكم خود پرورده و دو سال تمام نيز شير داده . اكنون كه بزرگ شده ام و خوب و بد را تشخيص مى دهم ، مرا طرد كرده و مى گويد: تو فرزند من نيستى ! حال آنكه او مادر من و من فرزند او هستم. \r\nعمر دستور داد زن را بياورند. زن كه فهميد علت اظهارش چيست ، به همراه چهار برادرش و نيز چهل شاهد در محكمه حاضر شد.\r\nعمر از جوان خواست تا ادعايش را مطرح نمايد.\r\nجوان گفته هاى خود را تكرار كرد و قسم ياد كرد كه اين زن مادر من است . عمر به زن گفت: \r\n- شما در جواب چه مى گوييد؟\r\nزن پاسخ داد: خدا را شاهد مى گيرم و به پيغمبر سوگند ياد مى كنم كه اين پسر را نمى شناسم . او با چنين ادعاى مى خواهد مرا در بين قبيله و خويشاوندانم بى آبرو سازد. من زنى از خاندان قريشم و تا بحال شوهر نكرده ام و هنوز باكره ام. \r\nدر چنين حالتى چگونه ممكن است او فرزند من باشد؟\r\nعمر پرسيد: آيا شاهد دارى ؟\r\nزن پاسخ داد: اينها همه گواهان و شهود من هستند.\r\nآن چهل نفر شهادت دادند كه پسر دروغ مى گويد و نيز گواهى دادند كه اين زن شوهر نكرده و هنوز هم باكره است. \r\nعمر دستور داد كه پسر را زندانى كنند تا درباره شهود تحقيق شود. اگر گواهان راست گفته باشند، پسر به عنوان مفترى مجازات گردد.\r\nماءموران در حالى كه پسر را به سوى زندان مى بردند، با حضرت على عليه السلام برخورد نمودند، پسر فرياد زد:\r\n- يا على ! به دادم برس . زيرا به من ظلم شده و شرح حال خود را بيان كرد. حضرت فرمود: او را نزد عمر برگردانيد. چون بازگردانده شد، عمر گفت : من دستور زندان داده بودم . براى چه او را آورديد؟\r\nگفتند: على عليه السلام دستور داد برگردانيد و ما از شما مكرر شنيده ايم كه با دستور على بن ابى طالب عليه السلام مخالفت نكنيد.\r\nدر اين وقت حضرت على عليه السلام وارد شد و دستور داد مادر جوان را احضار كنند و او را آوردند. آن گاه حضرت به پسر فرمود: ادعاى خود را بيان كن.\r\nجوان دوباره تمام شرح حالش را بيان نمود.\r\nعلى عليه السلام رو به عمر كرد و گفت: \r\n- آيا مايلى من درباره اين دو نفر قضاوت كنم ؟\r\nعمر گفت : سبحان الله ! چگونه مايل نباشم و حال آنكه از رسول خدا صلى الله عليه و آله شنيده ام كه فرمود:\r\n- على بن ابى طالب عليه السلام از همه شما داناتر است \r\nحضرت به زن فرمود: درباره ادعاى خود شاهد دارى ؟\r\nگفت : بلى ! چهل شاهد دارم كه همگى حاضرند. در اين وقت شاهدان جلو آمدند و مانند دفعه پيش گواهى دادند.\r\nعلى عليه السلام فرمود: طبق رضاى خداوند حكم مى كنم . همان حكمى كه رسول خدا صلى الله عليه و آله به من آموخته است. \r\nسپس به زن فرمود: آيا در كارهاى خود سرپرست و صاحب اختيار دارى ؟\r\nزن پاسخ داد: بلى! \r\nاين چهار نفر برادران من هستند و در مورد من اختيار دارند. آن گاه حضرت به برادران زن فرمود:\r\n- آيا درباره خود و خواهرتان به من اجازه و اختيار مى دهيد؟\r\nگفتند: بلى ! شما درباره ما صاحب اختيار هستيد.\r\nحضرت فرمود: به شهادت خداى بزرگ و شهادت تمامى مردم كه در اين وقت در مجلس حاضرند. اين زن را به عقد ازدواج اين پسر درآوردم و به مهريه چهارصد درهم وجه نقد كه خود آن را مى پردازم . (البته عقد صورت ظاهرى داشت.) \r\nسپس به قنبر فرمود: سريعا چهارصد درهم حاضر كن. \r\nقنبر چهارصد درهم آورد. حضرت تمام پولها را در دست جوان ريخت . فرمود: اين پولها را بگير و در دامن زنت بريز و دست او را بگير و ببر و ديگر نزد ما برنگرد مگر آنكه آثار عروسى در تو باشد، يعنى غسل كرده برگردى. \r\nپسر از جاى خود حركت كرد و پولها را در دامن زن ريخت و گفت: \r\n- برخيز! برويم \r\nدر اين هنگام زن فرياد زد: آتش! آتش!  \r\nاى پسر عموى پيغمبر آيا مى خواهى مرا همسر پسرم قرار بدهى ؟\r\nبه خدا قسم ! اين جوان فرزند من است . برادرانم مرا به شخصى شوهر دادند كه پدرش غلام آزاد شده اى بود اين پسر را من از او آورده ام . وقتى بچه بزرگ شد به من گفتند:\r\n- فرزند بودن او را انكار كن و من هم طبق دستور برادرانم چنين عملى را انجام دادم ولى اكنون اعتراف مى كنم كه او فرزند من است . دلم از مهر و علاقه او لبريز است \r\nمادر دست پسر را گرفت و از محكمه بيرون رفتند.\r\nعمر گفت: \r\n- ((اگر على نبود من هلاك شده بودم .))\r\n"},{"id":718,"category_id":6,"category_code":"s6","source_id":226,"title":"عاقبت طمع ورزى","content":"بعد از آنكه لقمان از بردگى نجات يافت ، روى به تجارت آورد و مال بسيار اندوخت . هر كس احتياجى داشت بدون ضمانت به وى قرض مى داد. در همان حال لقمان ، طلبى از رئيس قبيله اى داشت ؛ پس پسر خود را براى اخذ آن طلب ، به مسافرت فرستاد، اما قبل از رفتن پسر را پند داد و گفت : در بين راه به درختى برخورد مى كنى كه در كنار چشمه اى قرار دارد؛ درخت بسيار پربرگ و سرسبز و خرمى است . در پاى آن درخت فرود نيا! بعد از آن به شهرى خواهى رسيد و بزرگ آن شهر تقاضاى ازدواج با دخترش را به تو مى كند، حذر كن و قبول منما! چون به نزديك مديون رسيدى ، صاحبخانه شب از تو مى خواهد كه بر تختى بخوابى كه كنار درياست . مبادا كه بر آن بخوابى ! اگر پيرى روشن ضمير با تو همراه شد هر چه گفت : سخنش را بپذير.\r\nاين بگفت و با پسر وداع كرد. پسر در راه به پيرمردى برخورد كرد كه شخصى حكيم به نظر مى رسيد. با هم همسفر شدند. چون به چشمه آب رسيدند، پير گفت : پياده شو استراحتى كنيم.\r\nپسر گفت : پدرم از من خواسته است در اين مكان پياده نشوم. \r\nپير گفت : مشكلى نيست ، پياده شو.\r\nپسر به ياد حرف پدر افتاد كه اگر پيرى به تو دستور داد، اطاعت كن ، بنابراين پياده شد.\r\nبعد از استراحت در زير درخت به خواب رفت . مارى از درخت پايين آمد و قصد پسر كرد. پير عصايش را بر گردن مار گذاشت ؛ او را كشت و سرش را جدا كرد و در كيسه خود گذاشت چون پسر از خواب بيدار شد، پير گفت : هدف پدرت از منع اقامت در اين مكان ، اين مار بوده است. \r\nدر ادامه راه به شهرى رسيدند. بر بزرگ شهر وارد شدند و چندى آنجا ماندند. دختر رئيس قوم به پسر لقمان علاقه پيدا كرد و پدرش به پسر تقاضاى ازدواج داد. پسر قبول نكرد.\r\nپير گفت : اين دختر صاحب زيبايى و مال و جاه است . خوب است كه ازدواج با او را قبول كنى. \r\nپسر طبق دستور لقمان ، سخن پير را پذيرفت و دختر را به نكاح خود درآورد. شب زفاف پير، سر مار را به جوان داد و گفت : در زير دامن عروس ، اين سر مار را دود كن و منتظر بمان ! شب ، جوان دستور پير را به كار بست. \r\nبا رسيدن دود سر مار به زرى دامن عروس ، ناله اى كرد و بيهوش شد و بعد كرم بزرگى از او جدا شد و در دم مرد.\r\nپس از چند لحظه ، عروس به هوش آمد. چند روزى را با عروس به خوبى گذرانيدند و سپس راهى شهر ديگر شدند.\r\nچون به خانه شخص طرف معامله رسيدند، ضيافت پر شكوهى به افتخار پسر لقمان برپا نمودند.\r\nهنگامى كه شب فرا رسيد، آن مرد قدرتمند و صاحب مال از پسر لقمان خواست كه بر تختى كه در كنار دريا است بخوابد. پسر لقمان قبول نكرد، اما پير از او خواست كه بخوابد.\r\nپسر لقمان بر آن تخت خوابيد و پسر صاحبخانه هم صد متر آن طرف تر بر تخت ديگرى خوابيده بود. پير از پسر لقمان خواست برخيزد و تخت ها را جابه جا كند. بدين ترتيب تخت پسر لقمان را با تخت پسر صاحبخانه عوض كردند.\r\nاز خصوصيات اين نابكار اين بود كه هر كس به دنبال طلب خود مى آمد، اول به او احترام مى گذاشت ؛ اما شب او را در دريا غرق مى كرد، آن شب هم آن شخص آمد و به خيال خود پسر لقمان را در دريا انداخت. \r\nچون صبح شد، مشاهده كرد كه پسر خودش بوده نه پسر لقمان . عزا در آن خانه به پا شد. پسر لقمان طلب خويش بگرفت و حركت نمود. به شهر اول رسيد همسرش را با اموال بسيار برداشت و به سوى ديار خويش رهسپار شد.\r\n"},{"id":719,"category_id":6,"category_code":"s6","source_id":227,"title":"وصیت لقمان","content":"\r\nلقمان حكيم در توصيه به فرزندش اظهار نمود:\r\nفرزندم ! دل بسته به رضاى مردم و مدح و ذم آنان مباش ؛ زيرا هر قدر انسان در راه تحصيل آن بكوشد به هدف نمى رسد و هرگز نمى تواند رضايت همه را به دست آورد فرزند به لقمان گفت: \r\n- معناى كلام شما چيست ؟ دوست دارم براى آن مثال يا عمل و يا گفتارى را به من نشان دهى. \r\nلقمان از خواست با هم بيرون بروند بدين منظور از منزل همراه درازگوشى خارج شدند. پدر سوار شد و پسر پياده دنبالش به راه افتاد در مسير با عده اى برخورد نمودند. بين خود گفتند: اين مرد كم عاطفه را ببين كه خود سوار شده و بچه خويش را پياده از پى خود مى برد. چه روش زشتى است ! لقمان به فرزند گفت: \r\n- سخن اينان را شنيدى . سوار بودن من و پياده بودن تو را بد دانستند؟\r\nگفت : بلى! \r\n- پس فرزندم ! تو سوار شو و من پياده به دنبالت راه مى روم پسر سوار شد و پدر پياده حركت كرد باز با گروهى ديگر برخورد نمودند آنان نيز گفتند: اين چه پدر بد و آن هم چه پسر بى ادبى است اما بدى پدر بدين جهت است كه فرزند را خوب تربيت نكرده لذا او سوار است و پدر پياده به دنبالش راه مى رود در صورتى كه بهتر اين بود كه پدر سوار مى شد تا احترامش محفوظ باشد اما اينكه پسر بى ادب است به خاطر اينكه وى عاق بر پدر شده است از اين رو هر دو در رفتار خود بد كرده اند.\r\nلقمان گفت : سخن اينها را نيز شنيدى ؟\r\nگفت : بلى! \r\nلقمان فرمود:\r\n- اكنون هر دو سوار شويم هر دو سوار شدند در اين حال گروهى ديگر از مردم رسيدند آنان با خود گفتند: در دل اين دو آثار رحمت نيست هر دو سوار بر اين حيوان شده اند و از سنگينى وزنشان پشت حيوان مى شكند اگر يكى سواره و ديگرى پياده مى رفت ، بهتر بود. لقمان به فرزند خود فرمود: شنيدى ؟\r\nفرزند عرض كرد: بلى! \r\nلقمان گفت : حالا حيوان را بى بار مى بريم و خودمان پياده راه مى رويم مركب را جلو انداختند و خودشان به دنبال آن پياده رفتند باز مردم آنان را به خاطر اينكه از حيوان استفاده نمى كنند سرزنش كردند.\r\nدر اين هنگام لقمان به فرزندش گفت: \r\n- آيا براى انسان به طور كامل راهى جهت جلب رضاى مردم وجود دارد؟ بنابراين اميدت را از رضاى مردم قطع كن و در انديشه تحصيل رضاى خداوند باش ؛ زيرا كه اين كار آسانى بوده و سعادت دنيا و آخرت در همين است.\r\n"},{"id":720,"category_id":6,"category_code":"s6","source_id":228,"title":"شیخ انصاری","content":"استاد اعظم «شیخ مرتضی انصاری» یکی از مراجع بزرگ تقلید بود که در سال 1281 هجری قمری در نجف اشرف از دنیا رفت و مرقد شریفش در همان جا قرار دارد. از وی چندین اثر گران بها به یادگار مانده است که دو کتاب معروف او به نام های «مکاسب» و «رسائل» از دروس سطح حوزه هستند.\r\nروزی یکی از مقلّدان او که از بازرگانان محترم و متدیّن بود، در مسیر راه خود به مکه برای انجام حج، به نجف اشرف و حضور شیخ انصاری آمد و مبلغی تقدیم کرد و گفت: \"این مبلغ از مال خالص (خمس داده شده) من است، آن را بردارید و برای خود خانه ای بخرید تا از مستأجری راحت شوید.\"\r\nشیخ پول را پذیرفت و آن تاجر به مکه رفت. پس از مدتی با آن پول مسجد خوبی در نجف اشرف بنا کرد که اکنون به مسجد «ترک» معروف است و از زمان تأسیس تاکنون، همواره محل درس و بحث علما و مراجع تقلید بوده است.\r\nآن تاجر در بازگشت از مکه، به نجف اشرف نزد شیخ انصاری آمد و پس از احوال پرسی عرض کرد: «آیا خانه را خریدید؟» شیخ گفت: «آری خریدم». پس وی را با خود به کنار مسجد برد و آن را به او نشان داد و فرمود: این مسجد را با پولی که دادی بنا کردم.\r\nتاجر گفت: «من آن پول را برای خانه داده بودم، نه مسجد». شیخ گفت: «چه خانه ای بهتر از این مکان مقدس که عبادت خدا در آن انجام می شود. ما به زودی از این دنیا کوچ می کنیم و اگر من با آن پول خانه می خریدم بعد از من به ورثه منتقل می شد، در حالی که این خانه (مسجد) باقی و ثابت است و به کسی منتقل یا بخشیده و یا فروخته نمی شود.\r\nتاجر از این عمل نیک انسانی و اجتماعی شیخ انصاری شاد شد و علاقه اش به وی فزونی یافت.\r\n"},{"id":721,"category_id":6,"category_code":"s6","source_id":229,"title":"پند و عبرت","content":"ابوسعید ابوالخیر با جمعی از اصحاب از کنار دهی در نیشابور به طرف مقصدی می گذشتند.\r\nمردی کنّاس مشغول خالی کردن چاه مستراح بود، اصحاب از بوی تعفن کثافات دماغ خود را گرفتند و به سرعت از آن محل گذشتند، ولی مشاهده کردند شیخ نیامد.\r\nچون نظر کردند دیدند شیخ با حالت تفکر کنار کثافات ایستاده. فریاد زدند: استاد! بیا.\r\nفرمود: می آیم، پس از مدتی تأمل در کنار کثافات به سوی اصحاب روان شد، چون به آنان رسید، عرضه داشتند: ای راهنما! برای چه کنار کثافات ایستادی؟\r\nفرمود: چون شما دماغ خود گرفتید و به سرعت حرکت خود افزودید، آوازی از کثافات و فضولات برخاست که هان ای روندگان! دیروز ما با حالتی طیب و طاهر و پاکیزه و رنگ و بویی بسیار عالی بر سر بازار به صورت سبزیجات و میوه جات و حبوبات قرار داشتیم و شما بنی آدم به خاطر به دست آوردن ما، بر سر و بار یکدیگر می زدید و به انواع حیله ها و خدعه ها متوسل می گشتید و از هیچ گونه تقلب و زوری خودداری نمی کردید، چون ما را به دست آوردید خوردید، ما بر اثر چند ساعت همنشینی با شما تبدیل به این حال گشته و به این سیه روزی افتادیم، به جای این که ما از شما فرار کنیم، شمایی که باعث این تیره بختی برای ما شدید، شما از ما فرار می کنید؟! ای اف بر شما!!\r\nمن کنار کثافات ایستاده و به پند و نصیحت آنان گوش فرا داده تا شاید عبرتی از آنان بگیرم!\r\n"},{"id":722,"category_id":6,"category_code":"s6","source_id":230,"title":"کفن کهنه","content":"ادیبی را وقت احتضار رسید گفت: مرا در کفن کهنه کفن کنید تا چون نکیر و منکر آیند، چنان تصور کنند که من مدت زیادی است که مرده ام و از من سئوال نکنند!!"},{"id":723,"category_id":6,"category_code":"s6","source_id":231,"title":"ارزش کار خالصانه","content":"\r\nآقای قدس می گوید:\r\n: روزی آقا (مرحوم بهجت)در رابطه با پاداش عمل صالح اگر چه اندک باشد، فرمود\r\nیکی از علمای نجف روزی در مسیر راهش به فقیری یک درهم صدقه داد ( البته بیشتر ازآن نداشت ) شب در خواب دید او را به باغی مجلل و دارای قصری بسیار عالی و زیبا دعوت کرده اند که نظیر آن را کسی ندیده بود. پرسید این باغ و قصر از آن کیست؟ گفتند: ازآن شماست تعجب کرد که من در برابر این همه تشریفات، عملی انجام نداده ام. به او گفتند: تعجب کردی؟ گفت:آری. گفتند: تعجب نکن. این پاداش آن یک درهم شماست. که خالصانه و با حسن عمل انجام گرفته است.\r\n"},{"id":724,"category_id":6,"category_code":"s6","source_id":232,"title":"بزرگواری اهل بیت(ع)","content":"آقای قدس می گوید: روزی آقای بهجت در رابطه با بزرگواری و اغماض ائمه اطهار ـ صلوات الله علیهم ـ فرمودند:\r\n در نزدیکی نجف اشرف، در محل تلاقی دو رودخانه فرات و دجله آبادیی است به نام «مصیب»، که مردی شیعه برای زیارت مولای متقیان امیر المؤمنین علیه السلام از آنجا عبور می کرد و مردی از اهل سنت که در سر راه مرد شیعه خانه داشت همواره هنگام رفت و آمد او چون می دانست وی به زیارت حضرت علی علیه السلام می رود او را مسخره می کرد.\r\nحتی یک بار به ساحت مقدس آقا جسارت کرد، و مرد شیعه خیلی ناراحت شد. چون خدمت آقا مشرف شد خیلی بی تابی کرد و ناله زد که: تو می دانی این مخالف چه می کند.\r\nآن شب آقا را در خواب دید و شکایت کرد آقا فرمود: او بر ما حقی دارد که هر چه بکند در دنیا نمی توانیم او را کیفر دهیم. شیعه می گوید عرض کردم: آری، لابد به خاطر آن جسارتهایی که او می کند بر شما حق پیدا کرده است؟! حضرت فرمودند: بله او روزی در محل تلاقی آب فرات و دجله نشسته بود و به فرات نگاه می کرد، ناگهان جریان کربلا و منع آب از حضرت سید الشهدا علیه السلام به خاطرش افتاد و پیش خود گفت: عمر بن سعد کار خوبی نکرد که اینها را تشنه کشت، خوب بود به آنها آب می داد بعد همه را می کشت، و ناراحت شد و یک قطره اشک از چشم او ریخت، از این جهت بر ما حقی پیدا کرد که نمی توانیم او را جزا بدهیم.\r\nآن مرد شیعه می گوید: از خواب بیدار شدم، به محل برگشتم، سر راه آن سنی با من برخورد کرد و با تمسخر گفت: آقا را دیدی و از طرف ما پیام رساندی؟! مرد شیعه گفت: آری پیام رساندم و پیامی دارم. او خندید و گفت: بگو چیست؟ مرد شیعه جریان را تا آخر تعریف کرد. وقتی رسید به فرمایش امام علیه السلام که وی به آب نگاهی کرد و به یاد کربلا افتاد و ...، مرد سنی تا شنید سر به زیر افکند و کمی به فکر فرو رفت و گفت: خدایا، در آن زمان هیچ کس در آنجا نبود و من این را به کسی نگفته بودم، آقا از کجا فهمید. بلافاصله گفت: أشهد أن لا إله إلا الله، و أن محمداً رسول الله، و أن علیاً أمیرالمؤمنین ولیّ الله و وصیّ رسول الله و شیعه شد.\r\n"},{"id":725,"category_id":6,"category_code":"s6","source_id":233,"title":"امیر تواضع","content":"سلمان فارسی، امیر شهر مدائن بود. روزی مردی از اهل شام که کاه با خود حمل می کرد، به مدائن رسید. نگاه خسته اش را به این سو و آن سو گرداند تا شاید کسی را بیابد که بار کاه را بردارد. وقتی او را دید، صدا زد و گفت: های! این بار را بردار! سلمان دسته کاه را بلند کرد و بر سر گذاشت و به سوی خانه مرد به راه افتاد.\r\nدر بین راه، مردم، سلمان را دیدند که برای آن مرد کاه حمل می کند. کسی از میان مردم با تعجب و سرزنش به آن مرد گفت: هیچ می دانی این که بار تو را بر دوش دارد سلمان است؟!\r\nرنگ از روی مرد پرید، بی درنگ جستی زد تا بار را از سلمان بگیرد و در همان حال از امیر عذر خواست و گفت: ای مهربان، به خدا من تو را نشناختم، چرا چنین کردی؟ و بار را در چنگ گرفت، اما سلمان بار را از بالای سر پایین نگذاشت و گفت: تا کاه ها را به خانه ات نرسانم، آن را بر زمین نخواهم گذاشت.\r\n"},{"id":726,"category_id":6,"category_code":"s6","source_id":234,"title":"آن الاغ رام","content":"در سفرى كه مدرس به اصفهان داشت پس از آن مدتى كوتاه به شهرضا رهسپار شد و در آستانه امامزاده شهرضا اقامت نمود. مردم دسته دسته به ديدارش مى شتافتند. روزى يكى از مراجعين كه سابقه دوستى با آقا را داشت از مدرس پرسيد: در مبارزه با عوامل ستم براى خودتان چه كرديد. مدرس پاسخ داد: كوشيده ام روش اجدادم را دنبال كنم ، دنبال مظاهر دنيوى نبوده و نيستم و زندگى طلبگى را هنوز هم ادامه مى دهم . ولى در خصوص ‍ مبارزه با رضاخان بايد بگويم كه او آلت دست است و عوامل خارجى براى مقاصد خود، او را روى كار مى آورند و من در حد توان و تا موقعى كه جان دارم با ايادى استكبار مبارزه مى كنم و اين را وظيفه شرعى خود مى دانم. \r\nدر اين هنگام مردى به ديدن مدرس آمد كه در سالهاى جوانى با آقا انس ‍ داشت و به غلام معروف بود. مدرس دست وى را گرفت و پهلوى خود نشانيد و گفت : آق غلام يادت مى آيد وقتى كه هنگام خرمنها بود الاغها را مى برديم آب بدهيم و آن الاغ كه لگد مى زد سوار نمى شديم و چند پشته سوار الاغ رام مى شديم ؟ حالا مردم بايد بدانند كه اگر رام شدند سوارشان مى شوند. مردم بايد بيدار باشند و به بيگانگان و متجاوزين و اعوان و انصار آن ها سوارى ندهند.\r\n"},{"id":727,"category_id":6,"category_code":"s6","source_id":235,"title":"قناعت","content":"ابو وايل گفت در خدمت اباذر به خانه سلمان رفتيم . هنگام غذا سلمان گفت اگر رسول خدا صلي الله عليه و آله از تكلف رنج و زحمت انداختن خود نهي نكرده بود براي شما چيزي تهيه مي كردم ، پس از آن مقداري نان و نمك آورد. ابوذر گفت : اگر با اين نمك نعنا همراه مي شد خيلي بهتر بود. سلمان آفتابه ي خود را به گرو گذاشت و مقداري نعنا تهيه نمود، پس از آنكه خورديم ابوذر گفت : (الحمدلله الذي قنعنا) سپاس مر خدايي را است كه ما را قانع ساخت . سلمان گفت : اگر قانع بوديد آفتابه من بگرو نمي رفت."},{"id":728,"category_id":6,"category_code":"s6","source_id":236,"title":"خطا پوشی","content":"آیة الله مروی (ره)، از علمای بزرگ دوره قاجاریه، روزی در مسجد با جوانی مواجه گردید که مدّعی بود برای درس طلبگی آمده است. آن عالم بزرگوار برای تفقّد حال او، وارد حجره اش شد و سپس برای وضو گرفتن، قبای خود را به دیوار آویزان نمود. ساعتی که درون جیب قبا بود نظر جوان را به خود جلب کرد و آن را ربود. شیخ پس از مراجعت و فهمیدن موضوع، کنار جوان نشست و از او خواست به سبب پاک بودنش برای وی دعایی کند به این مضمون که: خدا گوش های شدیداً سنگین شیخ را شفا بدهد، زیرا وی مضطرب بود مبادا صدای زنگ ساعتِ ربوده شده از درون جیب جوان به گوش آید و موجب رسوایی اش گردد.\r\nاتفاقاً این چنین شد و رنگ جوان پرید، اما ماجرای دعایش برای شیخ به یادش آمد و گفت: خدایا شکر تو که گوش های آقا نمی شنود وگرنه به کلی آبرویم می رفت؛ با این روش او متنبّه شد.\r\n"},{"id":729,"category_id":6,"category_code":"s6","source_id":237,"title":"بوی عطر عجیب","content":"حضرت حجة الاسلام حاج آقا محقق فرمود: مرحوم آخوند ملا علی همدانی(رض) فرمودند: یک روز پیرمردی برای حساب خمس و زکات پیش من آمد. متوجه شدم که از آن پیرمرد بوی عطر عجیبی بر مشامم میرسد که تا به حال نظیر آن را استشمام نکردهام. از آن پیرمرد پرسیدم که ای پیرمرد از چه عطری استفاده میکنی؟ گفت: حضرت آیت الله، این بوی خوش داستانی دارد که تا به حال برای کسی نگفتهام اما حال برای شما تعریف میکنم. یک شب در عالم خواب محضر مقدس رسول الله(ص) شرفیاب شدم، آن حضرت نشسته بودند و حدود ده یا بیست نفر اطراف ایشان حضور داشتند و من هم در آن مجلس بودم. حضرت فرمودند: کدام یک از شما بر من زیاد صلوات میفرستید؟ من خواستم بگویم من بر شما زیاد صلوات میفرستم اما ساکت شدم و چیزی نگفتم. حضرت برای بار دوم پرسیدند. باز هم کسی جواب نداد. ناگهان یک وقت دیدم که وجود نازنین حضرت رسول ایستادند و به من فرمودند: شما زیاد بر من صلوات میفرستی و آن وقت لبان مرا بوسیدند. و از آن وقت است که دهان من بوی خوش میدهد."},{"id":730,"category_id":6,"category_code":"s6","source_id":238,"title":"طمع","content":"شبلي يكي از عارفان وارسته بود ، روزي با همراهان وارد مكتب خانه اي شد نگاه به شاگردان كرد ، ديد هنگام چاشت است و ملاي مكتب به آنها اجازه داده تا غذايي كه با خود آورده اند بخورند ، در اين ميان ديد دو كودك كنار هم نشسته اند ، از وضع لباس و غذاي آنها پيدا است كه يكي فقيرزاده ، و ديگري از خانواده مرفهي است ، به نگاه خود ادامه داد ، ديد فقيرزاده به نام روغني و حلواي ثروتمند زاده نگاه كرد و طمع نمود و به او گفت : از نان و حلواي خود كمي به من بده ، ثروتمندزاده در پاسخ او گفت : اگر سگ من بشوي و مثل سگ ، عوعو كني ، به تو مي دهم.\r\nفقير زاده پيشنهاد او را پذيرفت ، عوعو مي كرد و كم كم از ثروتمند زاده نان و حلوا مي گرفت ، شبلي به همراهان گفت : ببينيد ، اگر آن فقير زاده قناعت داشت ، خود را سگ نمي كرد تا كمي حلوا بگيرد ، و اين درس را بياموزيد كه طمع موجب ذلت و خواري است.\r\n"},{"id":731,"category_id":6,"category_code":"s6","source_id":239,"title":"گدایی در نیمه شب","content":"یکی  از سیره⁯های آیت الله العظمی شیخ جعفر کاشف الغطاء (ره) این بود ه که دیگران و از جمله اهل منزل را برای نماز شب بیدار می⁯کرده است. فرزند ایشان (شیخ حسن) می⁯گوید: عادت شیخ جعفر(ره) آن بود كه هر شب وقت سحر بیدار بود و مى⁯آمد دمِ در اتاق⁯ها و عیال و اطفال همه را بیدار مى⁯كرد و مى⁯گفت: برخیزید و نماز شب بخوانید، و همه بر مى خاستند. \r\nدر یكى از شب⁯ها كه ایشان براى تهجّد و نماز شب برخاسته بود، فرزند جوانش را از خواب بیدار كرده و فرمود: برخیز به حرم مطهّر مشرّف شده و در آنجا نماز بخوانیم. فرزند جوان كه برخاستن از خواب در آن ساعتِ شب برایش سخت بود، در مقام اعتذار برآمد و گفت: من فعلاً مهیّا نیستم شما منتظر من نشوید؛ بعداً مشرّف مى⁯شوم. \r\nپدر فرمود: نه، من این جا ایستاد⁯ه⁯ام؛ برخیز، آماده شو كه با هم برویم. آقا زاده، به ناچار از جا برخاست و بعد از وضو گرفتن، با هم راه افتادند. هنگامی که كنار درب صحنِ مطهّر رسیدند، در آن⁯جا مرد فقیرى را دیدند كه نشسته و دست نیاز به طرف مردم دراز كرده است.\r\nآن عالم بزرگوار ایستاد و به فرزندش فرمود: این شخص در این وقتِ شب براى چه این جا نشسته است؟\r\nفرزند گفت: براى گدایی و تكّدى از مردم. \r\nآقا شیخ جعفر فرمود: آیا چه مقدار ممكن است از رهگذران، عاید او گردد؟\r\nفرزند مبلغ ناچیزی را گفت. (مثلا یک درهم)\r\nمرحوم كاشف الغطاء فرمود: فرزندم! درست فكر كن و ببین این آدم براى به⁯دست آوردن مبلغ بسیار اندك و كم ارزش دنیا (که آن را هم شاید به⁯دست بیاورد)، در این وقت شب از خواب و آسایش خود دست برداشته و آمده در این گوشه نشسته و دست تذلّل به سوى مردم دراز كرده! آیا تو، به اندازه این شخص، به وعده⁯هاى خدا درباره شب⁯خیزان و متهجّدان اعتماد ندارى ؟\r\nگفته اند آن فرزند جوان از شنیدن این گفتار پدرِ زنده دل خود چنان تكان خورد و تنبّه یافت كه تا آخر عمر از شرف وسعادت بیدارى آخر شب برخوردار بود و نماز شبش ‍ ترك نشد.\r\n"},{"id":732,"category_id":6,"category_code":"s6","source_id":240,"title":"دقت در داوری","content":"روزی لقمان در کنار چشمه ای نشسته بود. مردی که از آن جا می گذشت از او پرسید: چند ساعت دیگر به ده بعدی خواهم رسید؟ لقمان گفت: راه برو. آن مرد پنداشت که لقمان نشنیده است. دوباره سؤال کرد: مگر نشنیدی؟ پرسیدم چند ساعت دیگر به ده بعدی خواهم رسید؟ لقمان گفت: راه برو. آن مرد پنداشت که لقمان دیوانه است و رفتن را پیشه کرد. هنوز چند قدمی راه نرفته بود که لقمان به بانگ بلند گفت: ای مرد، یک ساعت دیگر بدان ده خواهی رسید. مرد گفت: چرا اول نگفتی؟ لقمان گفت: چون راه رفتن تو را ندیده بودم، نمی دانستم تند می روی یا کُند. حال که دیدم دانستم که یک ساعت دیگر به ده خواهی رسید."},{"id":733,"category_id":6,"category_code":"s6","source_id":241,"title":"نماز شب","content":"علاّمه سیّد محمد حسین طباطبایی می‌فرماید:\r\nچون به نجف اشرف برای تحصیل مشرّف شدم از نقطه نظر قرابت و خویشاوندی، گاه⁯گاهی به محضر مرحوم آیت الله حاج میرزا علی آقا قاضی شرفیاب می‌شدم، تا این⁯كه یك روز جلو در مدرسه‌ای ایستاده بودم كه مرحوم قاضی از آنجا عبور می‌كردند، چون به من رسیدند دست خود را روی شانه من گذاردند و گفتند:\r\n«ای فرزند! دنیا میخواهی نماز شب بخوان، آخرت می‌خواهی نماز شب بخوان» \r\nاین سخن آن⁯قدر در من اثر كرد كه از آن به بعد تا زمانی كه به ایران مراجعت كردم، پنج سال تمام در محضر قاضی روز و شب به⁯سر می‌بردم و آنی از ادارك فیض ایشان دریغ نمی‌كردم.\r\n"},{"id":734,"category_id":6,"category_code":"s6","source_id":242,"title":"نماز جماعت با امام زمان(عج)","content":"در كتاب گنجينه ى دانشمندان يكى از شاگردان خاص ميرزا جواد ملكى تبريزى مى گويد:\r\nشبى در شاهرود خواب ديدم كه در صحرايى صاحب الامر (عج) با جماعتى تشريف داشتند و گويا به نماز جماعت ايستادند. نزديك رفتم كه جمال مباركش را زيارت كنم و دست شريفش را ببوسم ؛ شيخ بزرگوارى را ديدم كه در كنار آن حضرت ، و آثار بزرگوارى و وقار از سيمايش پيدا بود. هنگامى كه بيدار شدم درباره ى آن شيخ فكر كردم و در انديشه ى اين معنا رفتم كه او كيست كه تا اين اندازه به امام عصر (عج) مربوط و نزديك است. \r\nبراى يافتن به مشهد مشرف شدم، وى را نديدم. در تهران آمدم ، به او برخورد نكردم . به قم مسافرت كردم و در مدرسه ى فيضيه او را در يكى از حجره ها مشغول تدريس ديدم . پرسيدم اين آقا كيست ؟ گفتند: آقاى حاج ميرزا جواد آقا ملكى است . خدمتش رسيدم ، از من تفقد زيادى كرد و فرمود: كى آمدى ؟ گويا مرا ديده و شناخته و از قضيه آگاهند.\r\nاز آن پس ، ملازمتش را اختيار كرده و او را چنان يافتم كه ديده بودم و مى خواستم.\r\n"},{"id":735,"category_id":6,"category_code":"s6","source_id":243,"title":"زنده نگه داشتن سنت","content":"حجة السلام والمسلمین قدس، یکی از شاگردان آیت الله بهجت می گوید:\r\n آقا همیشه سفارش می کردند برای احیای شریعت نگذارید سنتها فراموش شود وعرفیات یا بدعتها جای آن را بگیرد.\r\nروزی فرمودند:\r\n مرحوم حاج شیخ مرتضی طالقانی ( ازاستادان اخلاق و علمای بزرگ نجف، که استاد اخلاق آقا نیز بوده است ) همراه با عده ای از علما از جمله آیت الله العظمی خوئی به افطار دعوت بودند، وقتی غذا آماده می شود و همگی سر سفره می نشینند حاج شیخ مرتضی طالقانی می فرماید: نمک در سفره نیست و اقدام به تناول غذا نمی کنند. با اینکه بین مجلس افطاریه تا آشپزخانه بسیار فاصله بوده ( و ظاهراً از خانه ای دیگر غذا می آورده اند ). به هر حال مرحوم طالقانی دست به غذا دراز نمی کند و دیگران حتی آیت الله خوئی نیز به احترام ایشان غذا شروع نمی کنند و طول می کشد تا نمک را بیآورند. بعد از ختم جلسه و هنگام رفتن، آیت الله خوئی خطاب به ایشان می فرماید: حضرت آقا، اگر شما به این اندازه به ظاهر سنت مقید هستید که اگر کمی نمک تناول نکنید غذا نمی خورید، پس در این گونه مجالس کمی نمک با خود همراه داشته باشید تا مردم را منتظر نگذارید. آقای طالقانی فوراً دست به جیب برده و کیسه کوچکی را درآورده و می فرماید: با خودم نمک داشتم ولی می خواستم سنت اسلامی پیاده شود و متروک نباشد.\r\n"},{"id":736,"category_id":6,"category_code":"s6","source_id":244,"title":"احیایی شریعت","content":"\r\nحجة السلام والمسلمین قدس، یکی از شاگردان آیت الله بهجت می گوید:\r\n آقا همیشه سفارش می کردند برای احیای شریعت نگذارید سنتها فراموش شود وعرفیات یا بدعتها جای آن را بگیرد.\r\nروزی فرمودند:\r\n مرحوم حاج شیخ مرتضی طالقانی ( ازاستادان اخلاق و علمای بزرگ نجف، که استاد اخلاق آقا نیز بوده است ) همراه با عده ای از علما از جمله آیت الله العظمی خوئی به افطار دعوت بودند، وقتی غذا آماده می شود و همگی سر سفره می نشینند حاج شیخ مرتضی طالقانی می فرماید: نمک در سفره نیست و اقدام به تناول غذا نمی کنند. با اینکه بین مجلس افطاریه تا آشپزخانه بسیار فاصله بوده ( و ظاهراً از خانه ای دیگر غذا می آورده اند ). به هر حال مرحوم طالقانی دست به غذا دراز نمی کند و دیگران حتی آیت الله خوئی نیز به احترام ایشان غذا شروع نمی کنند و طول می کشد تا نمک را بیآورند. بعد از ختم جلسه و هنگام رفتن، آیت الله خوئی خطاب به ایشان می فرماید: حضرت آقا، اگر شما به این اندازه به ظاهر سنت مقید هستید که اگر کمی نمک تناول نکنید غذا نمی خورید، پس در این گونه مجالس کمی نمک با خود همراه داشته باشید تا مردم را منتظر نگذارید. آقای طالقانی فوراً دست به جیب برده و کیسه کوچکی را درآورده و می فرماید: با خودم نمک داشتم ولی می خواستم سنت اسلامی پیاده شود و متروک نباشد.در گذشته گاه چنین بود كه یكی از صاحبان قدرت و مقام، به عنوان گردش یا شكار از شهر خارج می‌شد و عده‌ای از رجال كشوری و لشكری به همراهش حركت می‌كردند.\r\nروزی برای عبد الملك بن مروان چنین پیش آمد: از مركز مملكت خارج شد و جمعی از خواص با او از شهر خارج شدند. پس از آنكه مقداری راه پیمودند، عبدالملك ركاب زد، از همراهان جدا شد و اسب او را به نقطه دور دستی رساند. در بیابان به یك مرد اعرابی رسید. عنان كشید و توقف كرد تا با او صحبت كند. گفت: عبد الملك بن مروان را می‌شناسی؟ پاسخ داد: آری، او ستمگری است غیر قابل هدایت. گفت: وای بر تو! من عبد الملك بن مروانم.\r\nعبد الملك تصور می‌كرد اگر اعرابی او را بشناسد، از تندگویی خودداری می‌كند و از آنچه گفته است، عذر می‌خواهد؛ ولی بر خلاف انتظار همچنان پیر مرد به تندگویی ادامه داد.\r\nاو گفت: نه خداوند به تو عمر طولانی دهد و نه مال و ملك بخشد كه مال خدا را خوردی و حرمت او را تضییع نمودی.\r\nعبد الملك كه خشمگین شده بود، گفت: وای بر تو! من قادرم به تو ضرر بزنم و قدرت دارم به تو نفع برسانم. اعرابی جواب داد: خداوند نفع تو را روزی من ننماید و خداوند اضرارت را از من برگرداند. هر دو ساكت شدند. وقتی سواران همراه عبد الملك نزدیك رسیدند، اعرابی گفت: آنچه بین من و تو گذشت، از سواران خود پنهان بدار كه به گفته رسول گرامی صلی الله علیه وآله مجالست امانت است.\r\n"},{"id":737,"category_id":6,"category_code":"s6","source_id":245,"title":"نسبت سلمان","content":"امام باقرعلیه السلام فرمودند: «سلمان فارسی با جمعی از قریش در مسجد نشسته بود، آنان به افتخارات نسبی و رفعت خانوادگی آغاز سخن كردند و هر یك خود را معرّفی نمودند تا نوبت به سلمان رسید. عمر به وی گفت: بگو تو كیستی؟ پدرت كیست و اصلت از كجاست؟ سلمان گفت: من فرزند بنده خدا هستم. گمراه بودم، خداوند به وسیله حضرت محمّدصلی الله علیه وآله مرا هدایت كرد. فقیر بودم، خداوند توسط محمّدصلی الله علیه وآله مرا غنی ساخت. برده بودم، خداوند بوسیله پیامبرصلی الله علیه وآله مرا آزاد كرد. این است حسب و نسب من."},{"id":738,"category_id":6,"category_code":"s6","source_id":246,"title":"ندای رحیل","content":"ملّا محمدتقی مجلسی گوید: شش ماه قبل از مرگ شیخ بهایی، به همراه او برای زیارت قبر بابا ركن الدین به قبرستان تخت فولاد رفتیم. در كنار قبر بودیم كه شیخ بهایی صدایی از قبر شنید كه: «شیخنا در فكر خود باش!» او به ما نگاه كرد و گفت این صدا را شنیدید؟ گفتیم: نه. شروع به گریه كرد و متوجّه مرگ و آخرت گردید.\r\nپس از اصرار زیادی كه به او كردیم تا ما را از آنچه شنیده است خبر دهد، فرمود: خبر شدم كه خود را برای مرگ آماده كنم.\r\nشش ماه پس از این خبر، ایشان فوت كرد و من به همراه پنجاه هزار نفر دیگر بر او نماز گذاردیم.\r\n"},{"id":739,"category_id":6,"category_code":"s6","source_id":247,"title":"سفر ابدی","content":"علاّمه محمدتقی جعفری در مورد استادش، عارف بزرگ شیخ مرتضی طالقانی، می‌گوید: در حوزه نجف حدود یك سال و نیم از محضر وی استفاده كردم. دو روز به مسافرت ابدی‌اش مانده بود. مثل هر روز به محضرش شتافتم. فرمود: برای چه آمدی آقا؟\r\nعرض كردم: آمده‌ام كه درس بفرمایید. فرمود: آقاجان! درس تمام شد، برخیز و برو. چون دو روز به ماه محرم مانده بود، عرض كردم: آقا! هنوز دو روز به محرم مانده است. فرمود: آقاجان به شما می‌گویم درس تمام شد، من مسافرم خر طالقان رفته پالانش مانده، روح رفته جسدش مانده. این جمله را به پایان رساند و بعد كلمه «لا اله الّا اللّه‌» را تكرار كرد و اشك از چشمانش سرازیر شد.\r\nدر این هنگام متوجّه شدم شیخ از سفر ابدی خویش خبر می‌دهد. و این در حالی بود كه هیچ گونه نشانی از كسالت و ناخوشی نداشت.\r\nعرض كردم: آقا! حالا یك چیزی بفرمایید تا مرخص شوم. فرمود: آقا! فهمیدی؟ متوجه شدی؟ بشنو:\r\nتا رسد دستت به خود، شو كارگر چون فتی از كار، خواهی زد به سر\r\nفردای آن روز در مدرسه صدر اصفهانی بودم. خبر آمد كه شیخ مرتضی طالقانی به ابدیت پیوست.\r\n"},{"id":740,"category_id":6,"category_code":"s6","source_id":248,"title":"جوال باف","content":"در احوال شیخ ابو العباس جوالیقی چنین نوشته اند: «وی در آغاز مردی جوال باف بود. روزی وقت عصر، با شاگرد خود حساب جوالهای خویش می‌كرد و یكی از آنها در آن میان ناپدید بود. زمانی كه به نماز مشغول شد، ناگهان به خاطرش آمد كه آن جوال را به چه كسی داده است. پس از اتمام نماز، شاگرد خود را از وضع جوال گم شده آگاه ساخت. شاگرد گفت:‌ای استاد! نماز می‌گذاردی یا پی جوال می‌گشتی؟ استاد از سخن شاگرد به خود آمد و دست از دنیا كشید و به تهذیب خویش همّت گماشت تا آنكه آخر الامر در زمره اولیاء اللّه درآمد و به آن پایه رفیع نائل گردید."},{"id":741,"category_id":6,"category_code":"s6","source_id":249,"title":"شیر و دزد","content":"فاضل عراقی در دارالسلام از عالم جلیل‌القدر شیخ طه و او از یکی از همسایه‌های خود که در محله‌ای از محله‌های نجف سکونت داشت نقل کرده است:\r\nروزی شخصی از آشنایان نزد من آمد و از سختی روزگار و تنگی معاش سخن می‌راند و گفت:‌ اگر همراهی با من کنی، در این باب، فکر و تدبیری کرده‌ام.\r\nگفتم: ‌بگو تا اگر صلاح باشد تو را یاری کنم.\r\nگفت: در این روزها پول زیادی نزد شیخ مرتضی آورده‌اند، ما شبانه به خانه او رفته و آن‌ها را آورده، بین خود تقسیم می‌کنیم.\r\nمن چون این را شنیدم، او را منع کردم، ولی سودی نبخشید. بالاخره با اصرار زیاد، مرا با خود موافق کرد، به این شرط که در بیرون منزل بایستم تا او برود و بیاید و من مباشر عملی نباشم.\r\nچون پاسی از شب رفت، به سراغ من آمد و به جانب منزل شیخ روانه شدیم. تا به درب منزل رسیدیم و با تدبیری، وارد دهلیز بیرونی شدیم، من دیگر نرفتم و همان ‌جا توقف کردم.\r\nاو از پله‌های بیرونی بالا رفت تا از پشت بام بیرونی به بام اندرونی در آید و از آن جا داخل خانه شده و به مقصود خود نایل آید.\r\nمدتی نگذشته بود که با حالتی پریشان و شگفت‌آور نزد من آمد. سبب را پرسیدم، گفت: چیزی مشاهده کردم که تا خودت نبینی، ‌تصدیق من نخواهی کرد.\r\nگفتم: مگر چه دیدی؟\r\nگفت:‌ چون از پله بالا رفتم، سایه کسی در مهتابی بیرونی ‌به نظرم آمد. هنگامی که از دیوار بیرونی بالا رفتم تا خود را به پشت بام اندرونی برسانم، ناگاه دیدم شیری مهیب بر کنار بام اندرونی ایستاده و انتظار آن داشت که مرا با چنگال خود پاره کند، من هرچه بالاتر رفتم، خشم او زیادتر می‌‌شد. قدری تامل کردم تا شاید علاجی پیدا کنم، ولی ممکن نشد، ناچار برگشتم.\r\nگوینده حکایت گفته است: ‌وقتی این را شنیدم، با خود گفتم: شیر در شهر، آن هم بالای بام، از کجا آمده؟ ‌شاید این مرد، از عمل خود پشیمان گشته عذر می‌آورد، یا آنکه ترس و واهمه، صورت شیر را در نظر او مجسم کرده است. به او گفتم: شاید ترس به تو این ‌طور وانمود کرده؟!\r\nگفت: چنین نیست و تا خود نبینی، از من باور نخواهی کرد، از پله بالا برو و نظر افکن.\r\nمن بالا رفتم،‌ نزدیک به بام اندرونی شیری عجیب دیدم که از ترسش بدنم به لرزه درآمد و نعره‌ای کشید و به سوی پشت بام بیرونی شد.\r\nچون این امر خارق عادت را دیدم، فهمیدم که از کرامات آن مرد بزرگ بوده و نادم و پشیمان برگشتیم.\r\n"},{"id":742,"category_id":6,"category_code":"s6","source_id":250,"title":"رسم خدایی و بندگی","content":"مرد فقیری، غلامهای عمید خراسانی را دید كه لباسهای بسیار زیبا و پیراهنهای دیبا بر تن دارند. رو به آسمان كرد و گفت: خدایا! بنده پروری را از عمید خراسانی یاد بگیر كه غلامهایش را با لباس زربافت و زیبا می آراید. \r\nاز قضا پس از اندك زمانی، بین عمید و یكی از امیرانش، جنگی در گرفت و عمید شكست خورد و فرار كرد. امیر، غلامهای عمید را دستگیر كرد و هر چه به آنها وعده و وعید داد و هرچه آنها را شكنجه كرد تا جای گنجینه عمید را به او بگویند نگفتند.\r\nوقتی آن مرد فقیر، وفا و همت والای آنها را دید، خودش انصاف داد و گفت: بندگی را هم باید از بندگان عمید خراسانی یاد گرفت.\r\nتو بندگی چو گدایان به شرط مزد مكن // كه خواجه خود روش بنده پروری داند\r\n"},{"id":743,"category_id":6,"category_code":"s6","source_id":251,"title":"بخشش و آرامش","content":"نقل شده، مرحوم شاه آبادی (ره) گاهی به کسانی که به او بی احترامی و یا توهین می کردند به آرامی پاسخ می داد و در واقع توهین آن ها را با توهین پاسخ می داد. البته بدون اینکه طرف مقابل صدای آن مرحوم را بشنود. فرزند مرحوم شاه آبادی علت را از پدر پرسید که شما با این مقام معنوی چرا چنین می کنی؟ گفت: پسرم من از روزی که انتقام خدا را با چشم خود دیدم، بنا را گذاشتم که چنین کنم. ماجرا از این قرار بود که روزی به حمّام (عمومی) رفته بودم. وارد خزینه شدم. آب سرریز شد و کمی به سر روی یکی از افسران پهلوی (شاه ایران) پاشیده شد. وی به شدت بر افروخته و به من توهین کرد. من که در جمع حاضران نخواستم و شاید نتوانستم پاسخ او را بدهم. به آرامی گفتم واگذارت می کنم به خدا. از حمّام بیرون شدم و به منزل آمدم. ساعتی بعد فردی به منزل ما مراجعه کرد و درخواست کرد که به درب حمام بروم. علت را پرسیدم. گفت خود خواهی دید. آن افسر را دیدم که به هنگام بالا آمدن از پله های حمام نقش بر زمین شده و زبانش بند آمده! گویی لال از مادر زاده شده! با ایما و اشاره از من طلب عفو می کرد. دعا کردم و از خدا خواستم او را ببخشد. تا دعای من خاتمه یافت. زبان در کام او به حرکت درآمد و به دست و پای من افتاد. از آن روز وقتی کسی توهینی و یا اساعه ادبی به من می کند. دیگر او را به خدا واگذار نمی کنم. خودم به آرامی پاسخش را می دهم تا خدا انتقام نگیرد که منتقم بزرگی است."},{"id":744,"category_id":6,"category_code":"s6","source_id":252,"title":"عتراض به خداوند و سزاى آن","content":"شيخ بزرگوار ابوالحسن على ، مى گويد: روزى در اتاق خلوت دايى ام شيخ احمد رفاعى بودم و غير او كسى در آنجا نبود. صداى خفيفى شنيدم . ديدم مردى پيش دايى ام نشسته و آنها مشغول صحبت هستند.\r\nپس از مدتى آن مرد از شكاف ديوار همان اتاق خلوت بيرون رفت و ناپديد شد.\r\nنزد دايى ام رفته گفتم : او كه بود؟\r\nگفت : او مردى است كه خدا به وسيله او آبهاى اقيانوس را حفظ مى كند و او يكى از چهار خواص است . اما سه روز است كه از اين سمت بركنار شده است ولى از طرد شدنش خبر ندارد.\r\nاو در جزيره اى اقامت داشت . مدت سه شبانه روز در آنجا باران باريد تا جايى كه در دره ها سيل جارى شد، او با خود گفت : اگر اين باران در آبادى ها مى باريد، چقدر بهتر بود؟ بعد از اين فكر پشيمان شد و استغفار كرد و به خاطر همين فكر، از درگاه رانده شد.\r\nبه دايى ام گفتم : آيا جريان را به او اطلاع دادى ؟\r\nگفت : خير، از او حيا كردم . گفتم : اگر اجازه بدهى من اين مطلب را به او اعلام كنم . گفت : حاضرى ؟ گفتم : آرى . گفت : سرت را پايين بياور و چشمانت را ببند. اطاعت كردم ، آنگاه صدايى شنيدم كه مى گفت : اى على سرت را بالا كن ! سرم را بالا كردم ، ديدم در جزيره بحر محيط هستم و در كارم متحير بودم . ناگهان همان مرد را ديدم به او سلام كرده و جريان را به او گفتم : او گفت : تو را به خدا قسم مى دهم كه آنچه مى گويم آن را عمل كنى. \r\nلطفا خرقه ام را به گردنم بيفكن و مرا بر روى زمين بكش و به من بگو اين جزاى كسى است كه به خدا اعتراض كرده باشد. من هم طبق درخواستش ‍ عمل كردم. \r\nناگهان هاتفى گفت : اى على ! او را رها كن كه خدا از او راضى شده است . از ديدن حال او ملائكه آسمان به گريه افتاده اند.\r\nساعتى در حال بى هوشى بودم . آنگاه كه به هوش آمدم و خود را در پيش ‍ دايى ام در اطاق خلوت ديدم . به خدا قسم نمى دانم كه چگونه رفتم و چگونه آمدم.\r\n"},{"id":745,"category_id":6,"category_code":"s6","source_id":253,"title":"پس برو به جهنم","content":"صدراعظم آقا محمدخان قاجار در مدت صدارتش تمام خویشان و اقوام خود را به حکم فرمایی شهرها گمارد. روزی شخصی نزد وی آمد و از حاکم شیراز که در حق او بی عدالتی کرده بود، شکایت کرد. صدراعظم گفت: حاکم شیراز اقوام من است، به اصفهان برو و آن جا زندگی کن. آن شخص گفت: اصفهان نیز در دست برادرزاده شما است. صدراعظم چندین شهر دیگر را نام برد و آن شخص گفت که حاکم همگی آن ها اقوام صدراعظم هستند. سرانجام صدراعظم عصبانی شد و داد زد: پس برو به جهنم! آن شخص که از جان خود گذشته بود، گفت: قربان آن جا هم مرحوم پدرتان تشریف دارند!"},{"id":746,"category_id":6,"category_code":"s6","source_id":254,"title":"شام و شراب","content":"یك نفر از اهالی اصفهان شراب خورده بود. او را در همان حال مستی، نزد مرحوم آیة اللَّه نجفی اصفهانی بردند. ایشان حكم كردند كه حدّش بزنند. ولی چون مست بود، امر كردند تا فردا صبح صبر كنند تا از حالت مستی خارج شود. بعد هم، شام خوبی به او دادند و فردا هم هشتاد ضربه شلاق خورد و مرخص شد.\r\nدوباره فردا شب، آن شخص با پای خودش خدمت آقای نجفی آمد و عرض كرد: آقا! امشب هم شرابم را خورده ام و آمده ام شامم را بخورم و بعد هم شلاق بزنید و بروم. \r\nالبته، شراب را به شوخی می گفت؛ ولی شامش را خورد و رفت و از همان شب نسیم توفیق بر او وزید و از مستی غفلت به هوش آمد و صدای گریه و مناجاتش هر شب بلند بود.\r\n"},{"id":747,"category_id":6,"category_code":"s6","source_id":255,"title":"استدلالی بسیار قوی! ","content":"شیخ بهائی در مصر با یکی از علمای بزرگ اهل سنت ارتباط دوستانه داشت و به او اظهار می کرد که از اهل سنت است. یک روز آن عالم سنّی به شیخ بهائی گفت: شیعیانی که در ایران با شما هستند، در مورد ابوبکر و عمر چه نظری دارند؟\r\nشیخ فرمود: آنها دو حدیث برای من بیان کردند که از جواب آن عاجز ماندم. آنها می گویند مسلم در صحیح خود روایت می کند که پیامبر(ص) فرموده: «هر کس فاطمه(س) را اذیت کند، مرا اذیت کرده و هر کس که مرا اذیت کند، خدا را اذیت کرده است؛ و هر کس که خدا را اذیت کند کافر است». همچنین در صحیح مسلم، پنج ورق آن طرف تر روایت شده «فاطمه (س) از دنیا رفت در حالی که نسبت به ابوبکر و عمر، غضبناک بود. » و من نتوانستم جواب این شبهه را بدهم.\r\nعالم سنّی گفت: «بگذار من امشب آن کتاب را مطالعه کنم. فردا جواب خواهم داد. » فردا صبح، عالم نزد شیخ آمد و گفت: من همیشه به تو می گفتم که این شیعه ها در نقل حدیث دروغ می گویند. دیشب صحیح مسلم را نگاه کردم؛ ولی دیدم بین این دو حدیث، بیش از پنج ورق فاصله است.\r\n"},{"id":748,"category_id":6,"category_code":"s6","source_id":256,"title":"دعای مادر","content":"بویزید بسطامی را پرسیدند که این پایگاه به دعای مادر یافتی این معروفی (شهرت) به چه یافتی؟ گفت: آن را هم به دعای مادر، که شبی مادر از من آب خواست. بنگریستم در خانه آب نبود، کوزه برداشتم. \r\nبه جوی رفتم آب بیاوردم.چون بر سر مادر آمدم، خوابش برده بود. با خود گفتم که اگر بیدارش کنم من بزهکار باشم. بایستادم تا مگر بیدار شود. تا بامداد بیدار شد. سربلند کرد و گفت: چرا ایستاده ای؟ قصه بگفتم. \r\nبرخاست و نماز کرد و دست بر دعا برداشت و گفت: الهی چنان که این پسر مرا بزرگ و عزیز داشت، اندر میان خلق او را بزرگ و عزیز گردان.\r\n"},{"id":749,"category_id":6,"category_code":"s6","source_id":257,"title":"پندی از سقراط","content":"روزی سقراط حکیم مردی را دید که خیلی ناراحت و متاثر بود.\r\nعلت ناراحتی اش را پرسید. شخص پاسخ داد: \r\nدر راه که می آمدم یکی از آشنایان را دیدم. سلام کردم.\r\nجواب نداد و با بی اعتنایی و خودخواهی گذشت و رفت و من از این طرز رفتار او خیلی رنجیدم.\r\nسقراط گفت : چرا رنجیدی ؟\r\nمرد با تعجب گفت: خوب معلوم است که چنین رفتاری ناراحت کننده است.\r\nسقراط پرسید : اگر در راه کسی را می دیدی که به زمین افتاده و از درد به خود می پیچد.\r\nآیا از دست او دلخور و رنجیده می شدی ؟\r\nمرد گفت : مسلم است که هرگز دلخور نمی شدم. آدم از بیمار بودن کسی دلخور نمی شود.\r\nسقراط پرسید: به جای دلخوری چه احساسی می یافتی و چه می کردی؟\r\nمرد جواب داد : احساس دلسوزی و شفقت و سعی می کردم طبیب یا دارویی به او برسانم.\r\nسقراط گفت : همه این کارها را به خاطر آن می کردی که او را بیمار می دانستی.\r\nآیا انسان تنها جسمش بیمار می شود ؟\r\nو آیا کسی که رفتارش نا درست است، روانش بیمار نیست ؟\r\nاگر کسی فکر و روانش سالم باشد هرگز رفتار بدی از او دیده نمی شود؟\r\nبیماری فکری و روان نامش \"غفلت\" است. و باید به جای دلخوری و رنجش نسبت به کسی که بدی می کند و غافل است دل سوزاند و کمک کرد و به او طبیب روح و داروی جان رساند.\r\nپس از دست هیچ کس دلخور مشو و کینه به دل مگیر و آرامش خود را هرگز از دست مده.\r\nبدان که هر وقت کسی بدی می کند در آن لحظه بیمار است.\r\n"},{"id":750,"category_id":6,"category_code":"s6","source_id":258,"title":"توبه ی سر دسته ی راهزنان","content":"یكی از علماء از كربلا و نجف برمی گشت ولی در راه برگشت در اطراف كرمانشاه و همدان گرفتار دزدان شده و هر چه او و رفقایش داشتند، همه را سارقین غارت نمودند. \r\nآن عالم می گوید : « من كتابی داشتم كه سالها با زحمت و مشقّت زیادی آن را نوشته بودم و چون خیلی مورد علاقه ام بود در سفر و حضر با من همراه بود، اتفاقاً كتاب یاد شده نیز به سرقت رفت، به ناچار به یكی از سارقین گفتم من كتابی در میان اموالم داشتم كه شما آن را به غارت برده اید و اگر ممكن است آن را به من برگردانید زیرا بدرد شما نمی خورد.\r\nآن شخص گفت: ما بدون اجازه رئیس نمی توانیم كتاب شما را پس بدهیم و اصلاً حق نداریم دست به اموال بزنیم.\r\nگفتم: رئیس شما كجا است \r\nگفت: پشت این كوه جایگاه او است \r\nلذا من به همراهی آن دزد به نزد رئیسشان رفتیم، وقتی وارد شدیم دیدم كه رئیس دزدها نماز می خواند. موقعی كه از نماز فارغ شد آن دزد به رئیس خود گفت: \r\nاجازه ی شما نخواستیم به او بدهیم. این عالم یك كتابی بین اموال دارد و آن را می خواهد و ‎ \r\nمن به رئیس دزدها گفتم: اگر شما رئیس راهزنان هستید، پس این نماز خواندن چرا؟ نماز كجا؟ دزدی كجا؟ \r\nگفت: درست است كه من رئیس راهزنان هستم ولی چیزی كه هست، انسان نباید رابطه ی ه‎رابطهی خود را با خدا به كلّی قطع كند و از خدا تماماً روی گردان شود، بلكه باید یك راه آشتی را باقی گذارد. حالا كه شما عالمید به احترام شما اموال را برمی گردانیم \r\nو دستور داد همین كار را كردند و ما هم خوشحال با اموالمان به راهمان ادامه دادیم\r\nپس از مدّتی كه به كربلا و نجف برگشتم، روزی در حرم امام حسین - علیه السّلام - همان مرد را دیدم كه با حال خضوع و خشوع گریه و دعا می كرد. وقتی كه مرا دید شناخت و گفت: \r\n« مرا می شناسی؟ » \r\nگفتم: آری\r\nگفت: « چون نماز را ترك نكردم و رابطه ام با خدا ادامه داشت، خدا هم توفیق توبه داده و از دزدی دست برداشتم و هر چه از اموال مردم نزد من بود، به صاحبانشان برگرداندم و هر كه را نمی شناختم از طرف آنها صدقه دادم و اكنون توفیق توبه و زیارت پیدا كرده‌ام.\r\n"},{"id":751,"category_id":6,"category_code":"s6","source_id":259,"title":"همسایه ها","content":"نقل کرده‌اند که شبانگاهی سیدبحرالعلوم، یکی از شاگردانش را خواست و با تمام خشم و عصبانیّت بر او خروشید و گفت: در همسایگی تو فردی است بینوا که با چند کودک خود گرسنه هستند. چرا به حال آن‌ها رسیدگی نمی‌کنی؟\r\nشاگرد گفت: به خدا سوگند، نمی‌دانستم که آن‌ها چنین مشکلی دارند.\r\nسید گفت: همین که نمی‌دانستی، مرا خشمگین کرده، والّا اگر که می‌دانستی و کاری نمی‌کردی، کافر بودی...\r\n"},{"id":752,"category_id":6,"category_code":"s6","source_id":260,"title":"بخشش خداوند","content":"حضرت آيت الله العظمى نجفى مرعشى مى‌فرمودند: در قم شيخى بود معروف به شيخ ارده شيره جهت معروف شدنش به اين نام آن بود كه او به ارده شيره بسيار علاقه داشت و حتى كتابى در وصف ارده شيره نوشته بود. آدم فقيرى بود خانه و منزلى نداشت. در حقيقت تارك دنيا بود يك شب در زمستان در ميان مقبره ميرزاى قمى در قبرستان شيخان خوابيد صبح براى نماز بلند شد ديد برف زيادى آمده پشت در را گرفته، شيخ هر كارى كرد در باز نشد، ماند در ميان مقبره از طرفى وسيله وضو حتى وسيله تيمم هم نبود چون مقبره با گچ و سيمان و ساير مصالح ساختمانى پوشيده شده بود نزديك طلوع آفتاب شد ديد نمازش قضا مى‌شود با همان حال بدون وضو و تيمم صحيح نماز را خواند بعد از نماز رو كرد به طرف آسمان و دستها را بلند نموده به شوخى به خداوند عرض كرد: خدايا! تا به حال تو به من هر چه دادى من چيزى نگفتم و قبول كردم گاهى نان و ارده شيره دادى شكر كردم، گاهى هم نان دادى و اصلا خورش ندادى باز هم قبول كردم خدايا تو هم امروز اين يك نماز بى‌طهارت را از من قبول كن و مرا مواخذه مكن.   ناقل فرمود بعد از وفات شيخ يكى از دوستان صالحش او را در خواب ديد پرسيد: خداوند با تو چگونه رفتار كرد؟ گفته بود: خدا مرا به واسطه همان يك نماز بخشيد."},{"id":753,"category_id":6,"category_code":"s6","source_id":261,"title":"خنده ی به موقع","content":"بُشربن منصور یکی از عارفان بود. در هنگام مرگش دیدند بسیار خندان است. از او پرسیدند: در این هنگام که درحال مرگ هستی چه جای شادی و خنده است؟ گفت: سبحان الله! من از میان ستم کاران، حسودان و نابه کاران می روم و به زودی با خدای ارحم الراحمین دیدار می کنم؛ با این حال چگونه خندان نباشم."},{"id":754,"category_id":6,"category_code":"s6","source_id":262,"title":"اسم اعظم","content":"در زمان هاى گذشته در شهر مكه مرد فقير و با ايمانى زندگى مى كرد. او هميشه روزه دار بود و روزها را براى رضايت خداوند روزه مى گرفت. \r\nهنگامى كه آفتاب غروب مى كرد و وقت افطار فرا مى رسيد دست در جيبش مى نمود و كاغذى را بيرون مى آورد. به آن نگاه مى كرد و چيزى نمى خورد. زيرا با خواندن آن جمله ، گرسنگى اش برطرف مى شد. پس از مرگ وى كاغذ را از جيبش درآوردند. ديدند روى آن جمله مبارك بسم اللّه الرحمن الرحيم نوشته شده است. \r\nمعلوم شد كه از بركت اسم اعظم پروردگار از او رفع گرسنگى مى شده است . انكار چنين حوادثى نشانه حقارت انديشه است . زيرا چشم و گوش ‍ ما را به قدرى اسباب بازى پر كرده است كه باور اين موضوع كه اسباب معنوى مؤ ثرتر هستند برايمان مشكل است.\r\n"},{"id":755,"category_id":6,"category_code":"s6","source_id":263,"title":"جانشین حاتم","content":"حاتم طایی از دنیا رفت برادرش خواست قائم مقام او شود، با مادرش د ر این مورد مشورت کرد. مادر- هرگز کار حاتم از تو ساخته نیست . ولی برادر حاتم به سخن مادر اعتنا نکرد، بلکه جانشین برادرش شد و بر مسند برادر که در میان قبه و تالاری که هفتاد در داشت، نشست (علت اینکه حاتم برای این تالار هفتاد درب درست کرده بود این بود: تا بینوایان از هر دری که بخواهند وارد شوند و عرض حاجت نمایند- گرچه مکرر باشد – حاجت آنها را بر آورد) مادر خواست پسرش(برادر حاتم) را آزمایش کند ، با لباس مبدل به طوری که پسرش او را نشناسد از دری وارد شد و عرض حاجت کرد پسر به حاجت او رسیدگی نمود. بار دوم مراجعه کرد و نتیجه گرفت بار سوم از درب دیگر وارد شد و عرض حاجت نمود، برادر حاتم از دیدن آن زن ناشناس که سومین بار به او مراجعه کرد ، سخت ناراحت شد و گفت ای «ای عورت» ! امروز دو نوبت از من چیزی گرفتی باز از درب دیگرآمدی؟! برو – برو مادر خود را پیش پسر ظاهر کرد و گفت: پسرم! برادرت حاتم را به همین قیافه ناشناس امتحان کردم و از هفتاد درب در یک روز بر او وارد شدم و عرض حاجت کردم، برادرت حاجتم را برطرف کرد در آن هنگام که شمکا بچه بودید، حاتم به یک پستان قناعت میکرد و پستان دیگر را برای تو می گذاشاشت ولی تو در یک پستان شیر می خوردی و پستان دیگر را با دست نگاه می داشتی!!"},{"id":756,"category_id":6,"category_code":"s6","source_id":264,"title":"دعای فرمانده لشکر","content":"در يكى از جنگها لشكريان اسلام قلعه اى را محاصره كردند تا با نيروى نظامى آنرا بگشايند و بر دشمن پيروز شوند، قلعه بسيار محكم بود و ايام محاصره بدرازا كشيد. با آنكه سربازان مسلمين در طول اين مدت ، مجاهده بسيار كردند و رنج فراوان ديدند ولى به فتح قلعه موفق نشدند. روحيه سربازان رفته رفته ضعيف و ضعيفتر ميشد و تصميمشان بسستى ميگرائيد، فرمانده لشكر كه در شرائط موجود، پيروزى سربازان خود را بعيد ميدانست بخدا متوجه شد و به پناه او رفت . چند روزى روزه گرفت ، از صميم قلب درباره سپاهيان اسلام دعا كرد، و از خداوند غلبه آنان را درخواست نمود. دعاى فرمانده ، مقبول درگاه الهى واقع شد و خليى زود به اجابت رسيد. روزى در نقطه اى نشسته بود مشاهده كرد، سگ سياهى در لشكرگاه مى دويد. توجه فرمانده به آن حيوان جلب شد و در خصوصياتش دقت كرد، چند ساعت بعد ديد همان سگ بالاى ديوار قلعه است ، دانست كه قلعه راهى بخارج دارد و اين سگ براى آنكه طعمه اى به دست آورد از آن راه بعسكرگاه ميآيد و دوباره برميگردد. محرمانه به افرادى ماءموريت داد جستجو كنند و آن راه را بيابند اما موفق نشدند. دستور داد انبانى را با روغن چرب كنند كه براى سگ طعمه مطبوعى باشد، مقدارى ارزن در آن بريزند و جدار انبان را سوراخ سوراخ كنند بطوريكه وقتى سگ آنرا با خود ميبرد با حركت حيوان تدريجا ارزنها بزمين بريزد. طبق دستور، عمل كردند، انبان را در عسكرگاه انداختند فرداى آنروز سگ از قلعه بيرون آمد، در جستجوى غذا به انبان رسيد آنرا بدندان گرفت ، راهى حصار شد، و دانه هاى ارزن كم كم روى زمين ميريخت ، ساعتى بعد ماءمورين ، با علامت ارزن خط سير سگ را دنبال كردند، در پايان به نقب بزرگى رسيدند كه ميشد به آسانى از اين راه به داخل قلعه رفت . بدستور فرمانده ، سربازان مسلمين در ساعت مقرر از آن راه زيرزمينى عبور نمودند و وارد قلعه شدند، دشمن ناچار تسليم گرديد و جنگ با فتح و پيروزى مسلمانان پايان يافت . \r\nاين سگ ، همه روزه بعسكرگاه مسلمين رفت و آمد مينمود و افسران و سربازان توجه نداشتند، و اگر بفرض كسى هم متوجه ميشد هرگز تصور نميكرد كه اين حيوان رمز پيروزى لشكر اسلام و كليد گشودن آن قلعه محكم است . اما خداوند براى آنكه دعاى فرمانده را مستجاب نمايد توجه او را به سگ معطوف نمود و بطور سبب سازى مشكل بزرگ سپاه اسلام را حل كرد، راه پيروزى را بروى آنان گشود و از خطر ذلت و شكست محافظتشان فرمود.\r\n"},{"id":757,"category_id":6,"category_code":"s6","source_id":265,"title":"ریاکار","content":"چادرنشينى مسلمان بشهر آمد داخل مسجد شد، ديد مردى با خشوع نماز ميگذارد. توجهش به وى معطوف گرديد. پس از نماز به او گفت چه خوب نماز ميخواندى ، جواب داد علاوه بر نماز، روزه هم دارم و اجر نمازگزار صائم دو برابر نمازگزار غير صائم است . مرد اعرابى كه مجذوب او شده بود گفت در شهر كارى دارم كه بايد آنرا انجام دهم ، بر من منت بگذار و قبول كن كه شترم را نزد شما بگذارم تا بروم و برگردم . او پذيرفت و چادرنشين با اطمينان خاطر شتر را به وى سپرد و از پى كار خود رفت . نمازگزار رياكار با دور شدن اعرابى بر شتر نشست و با سرعت آن محل را ترك گفت . پس از ساعتى مرد چادرنشين برگشت ولى نه از نمازگزار اثرى ديد و نه از شتر. در اطراف و نواحى مسجد جستجو كرد، نتيجه اى نگرفت . بيچاره سخت ناراحت و متاءثر گرديد و يك شعر گفت كه مفادش اين بود: نمازش بشگفتم آورد و روزه اش مجذوبم ساخت ، اما نمازگزار روزه دار ناقه جوانم را با سرعت راند و برد."},{"id":758,"category_id":6,"category_code":"s6","source_id":266,"title":"گفتگوی شیاطین","content":"\r\nيك روز شيطان چاقى ، شيطان لاغرى را ملاقات كرد.\r\nشيطان چاق ، از شيطان لاغر پرسيد:\r\nچرا تو اينقدر لاغر و ضعيف شده اى ؟\r\nشيطان لاغر، جواب داد:\r\nمن بر شخصى مسلّط و ماءمور شده ام كه او را گمراه كنم . ولى آن شخص ‍ در اوّل هر كار، مانند: خوردن ، آشاميدن ، ...، زبانش به ذكر بسم اللّه الرحمن الرحيم گويا است ، از اين رو از نفوذ در او، و شركت در كارهاى او محروم هستم . و همين سبب و موجب لاغرى من شده است ، حال تو بگو بدانم ، چطور چاق شده اى ؟\r\nشيطان چاق پاسخ داد:\r\nچاقى من به خاطر آن است كه شاد هستم ، زيرا بر شخص غافل و بى خبر و بى تفاوت مسلّط شده ام كه در هيچ كارى بسم اللّه نمى گويد، مثلا هنگام ورود و خروج و هنگام خوردن و نوشيدن ... و در هر كارى ، آنچنان غافل و سرگرم است كه اصلا به ياد خدا نیست.\r\nپس اى مؤ منين در اول هر كارى بسم اللّه الرحمن الرحيم يادتان نرود زيرا با گفتن بسم اللّه شيطان از شما دور مى شود.\r\n"},{"id":759,"category_id":6,"category_code":"s6","source_id":267,"title":"درخواست موسی","content":"حضرت موسي عليه السلام عرض كرد : خداوندا مي خواهم آن مخلوق را كه خود را خالص براي ياد تو كرده باشد و در طاعتت بي آلايش باشد را ببينم. \r\nخطاب رسيد : اي موسي عليه السلام برو در كنار فلان دريا تا به تو نشان بدهم آنكه را مي خواهي . حضرت رفت تا رسيد به كنار دريا : ديد درختي در كنار درياست و مرغي بر شاخه اي از آن درخت كه كج شده به طرف دريا نشسته است و مشغول به ذكر خداست . موسي از حال آن مرغ سو ال كرد . در جواب گفت : از وقتي كه خدا مرا خلق كرده ، است در اين شاخه درخت مشغول عبادت و ذكر او هستم و از هر ذكر من هزار ذكر منشعب مي شود. \r\nغذاي من لذت ذكر خداست . موسي سو ال نمود : آيا از آنچه در دنيا يافت مي شود آرزو داري ؟ عرض كرد : آري ، آرزويم اين است كه يك قطره از آب اين دريا را بياشامم . حضرت موسي تعجب كرد و گفت : اي مرغ ميان منقار تو و آب اين دريا چندان فاصله اي نيست ، چرا منقار را به آب نمي رساني ؟ عرض كرد: \r\nمي ترسم لذت آن آب مرا از لذت ياد خدايم باز دارد . پس موسي از روي تعجب دو دست خود را بر سر زد.\r\n"},{"id":760,"category_id":6,"category_code":"s6","source_id":268,"title":"اشک و شادی","content":"مرد ثروتمندی همراه هشت پسر و دخترش و نوه هایش در یک باغ زندگی می کرد و با اینکه همه چیز داشت نگران فرزندان و نوه هایش بود که بخاطر ثروت او هیچ کدام کار نمی کردند و زحمت نمی کشیدند.\r\nیک روز مرد ثروتمند فکری به سرش زد و... \r\nفردا صبح هر کدام از پسرها و دخترها و عروسها و دامادها و نوه ها که می خواستند از وسط جاده باغ بگذرند چشمشان به تخته سنگ بزرگی افتاد که راه عبور و مرور آنها را سخت کرده بود اما آنها که نمی دانستند مرد ثروتمند از پنجره اتاقش دارد آنها را نگاه می کند بدون اینکه به خودشان زحمت بدهند كه لااقل سنگ را از سر راه بقيه اعضاي خانواده بردارند از كنار تخته سنگ گذشتند و رفتند.\r\nخورشيد داشت كم كم غروب مي كرد و مرد ثروتمند از ديدن آن صحنه ها سخت ناراحت شده بود كه ناگهان متوجه شد پير مرد خدمتكار در حالي كه لوازم زيادي در دست داشت همين كه به تخته سنگ رسيد لوازمش را پايين گذاشت و به هر سختي بود تخته سنگ را برداشت و آن را از سر راه دور كرد و...\r\n كه در همان لحظه چشمش به يك كيسه پر از صد دلاري افتاد پيرمرد باغبان داخل كيسه را نگاه كرد تا صاحبش را پيدا كند كه يادداشتي را وسط بسته هاي صد دلاري ديد كه نوشته شده بود: \r\nهر سد و مانعي كه سر راهتان باشد مي تواند مسير زندگيتان را تغيير بدهد به شرط آنكه سعي كنيد آن مانع را از سر راهتان برداريد!\r\nپيرمرد باغبان خوشحال بود اما پيرمرد ثروتمند به حال فرزندانش اشك مي ريخت.\r\n"},{"id":761,"category_id":6,"category_code":"s6","source_id":269,"title":"حاضر جوابی","content":"يكى از حكما از طفلى پرسيد: اگر به من بگويى كه خدا كجا است ، يك عدد پرتقال به تو مى دهم  آن پسر در جواب گفت : من دو عدد پرتقال به شما مى دهم ، كه بگويى خدا كجا نيست."},{"id":762,"category_id":6,"category_code":"s6","source_id":270,"title":"تفرقه و نفاق","content":"سه گاو به رنگ سياه، زرد، سرخ، نيزاري مشغول چريدن بودند، ناگهان شيري وارد نيزار گرديد و متوجه آن سه گاو شد. با خود فكر كرد كه من قادر نيستم به تنهايي اين سه گاو را از پاي درآورم، از اين رو اول به نزد گاو سرخ و سياه آمده و گفت: اجازه دهيد من اين گاور زرد را بخورم چون رنگش ما را رسوا مي‌كند، آن دو قبول كردند، شير آمد و گاو زرد را دريد و خورد. پس از آن به نزد گاو سياه رفت و گفت: رنگ سرخ ما را رسوا مي‌كند اجازه بده من گاو سرخ را بخورم او هم اجازه داد و شير او را خورد.\r\nپس از آن به سراغ گاو سياه آمد تا حساب او را هم برسد گاو سياه گفت: اجازه بده من يك جمله با تو سخن بگويم بعد تصميم خود را درباره من بگير، و با صداي بلند فرياد زد: همان موقعي كه گاو زرد خورده شد من خورده شدم.\r\n"},{"id":763,"category_id":6,"category_code":"s6","source_id":271,"title":"ما چقدر فقیر هستیم!","content":"روزی یک مرد ثروتمند، پسر بچه کوچکش را به یک روستا برد تا به او نشان دهد مردمی که در آنجا زندگی می کنند، چقدر فقیر هستند. آن دو، یک شبانه روز در خانه محقر یک روستایی مهمان بودند. در راه بازگشت و در پایان سفر، مرد از پسرش پرسید: نظرت در مورد مسافرتمان چه بود؟\r\nپسر پاسخ داد: عالی بود پدر!\r\nپدر پرسید: آیا به زندگی آنها توجه کردی؟\r\nپسر پاسخ داد: بله پدر!\r\nو پدر پرسید: چه چیزی از این سفر یاد گرفتی؟\r\nپسر کمی اندیشید و بعد به آرامی گفت: فهمیدم که ما در خانه یک سگ داریم و آنها چهار تا، ما در حیاطمان یک فواره داریم و آن ها رودخانه ای دارند که نهایت ندارد. ما در حیاطمان فانوسهای تزیینی داریم و آن ها ستارگان را دارند. حیاط ما به دیوارهایش محدود می شود، اما باغ آن ها بی انتهاست!\r\nبا شنیدن حرف های پسر، زبان مرد بند آمده بود. پسر بچه اضافه کرد: متشکرم پدر، تو به من نشان دادی که ما چقدر فقیر هستیم!\r\n"},{"id":764,"category_id":6,"category_code":"s6","source_id":272,"title":"نامه ای به خدا","content":"یک روز کارمند پستی که به نامه‌هایی که آدرس نامعلوم دارند رسیدگی می‌کرد متوجه نامه ای شد که روی پاکت آن با خطی لرزان نوشته شده بود نامه‌ای به خدا! \r\nبا خودش فکر کرد بهتر است نامه را باز کرده و بخواند.در نامه این طور نوشته شده بود:\r\nخدای عزیزم بیوه زنی هشتادوسه ساله هستم که زندگی ام با حقوق نا چیز باز نشستگی می‌گذرد. دیروز یک نفر کیف مرا که صد دلار در آن بود دزدید.\r\n\r\nاین تمام پولی بود که تا پایان ماه باید خرج می‌کردم. یکشنبه هفته دیگر عید است و من دو نفر از دوستانم را برای شام دعوت کرده‌ام، اما بدون آن پول چیزی نمی‌توانم بخرم. هیچ کس را هم ندارم تا از او پول قرض بگیرم . تو ای خدای مهربان تنها امید من هستی به من کمک کن... \r\nکارمند اداره پست خیلی تحت تاثیر قرار گرفت و نامه را به سایر همکارانش نشان داد. نتیجه این شد که همه آنها جیب خود را جستجو کردند و هر کدام چند دلاری روی میز گذاشتند. در پایان نود وشش دلار جمع شد و برای پیرزن فرستادند... \r\nهمه کارمندان اداره پست از اینکه توانسته بودند کار خوبی انجام دهند خوشحال بودند. عید به پایان رسید و چند روزی از این ماجرا گذشت، تا این که نامه دیگری از آن پیرزن به اداره پست رسید که روی آن نوشته شده بود: نامه‌ای به خدا! \r\nهمه کارمندان جمع شدند تا نامه را باز کرده و بخوانند. مضمون نامه چنین بود: \r\nخدای عزیزم، چگونه می‌توانم از کاری که برایم انجام دادی تشکر کنم. با لطف تو توانستم شامی ‌عالی برای دوستانم مهیا کرده و روز خوبی را با هم بگذرانیم. من به آنها گفتم که چه هدیه خوبی برایم فرستادی ... البته چهار دلار آن کم بود که مطمئنم کارمندان اداره پست آن را برداشته‌اند!!\r\n"},{"id":765,"category_id":6,"category_code":"s6","source_id":273,"title":"اعتراض بیجا!","content":"دیوانه نمای عاقلی را نزد معاویه آوردند. معاویه گفت: از قرآن چیزی می دانی؟ گفت: می دانم و بسیار نیکو هم می دانم! گفت: بخوان. چنین خواند: «اذا جاء نصر الله و الفتح و رأیت الناس یخرجون من دینِ الله افواجا»! معاویه فریاد زد: غلط خواندی، «یخرجون» غلط است، «یدخلون» صحیح است. آن مرد بلا فاصله جواب داد: این که می گویی مربوط به زمان پیغمبر بوده است که مردم گروه گروه در دین خدا داخل می شدند، نه زمان تو! که مردم گروه گروه از دین –خدا- خارج می شوند."},{"id":766,"category_id":6,"category_code":"s6","source_id":274,"title":"خدای خر نشناس","content":"مردی، خری داشت که بسیار پیر و لاغر بود و علوفه زیادی می خورد و کاری هم نمی کرد. درعوض، گاوی داشت که بسیار فربه و شیر ده بود. یک شب با خداوند مناجات کرد و گفت: «الهی! این خر را بکش که من از خرج زیاد او به تنگ آمده ام. » صبح که شد، دید گاوش مرده و الاغش زنده مانده است. خیلی دلش سوخت و رو به آسمان کرد و گفت: خدایا! تو بعد از این همه سال خدائی کردن، بین خر و گاو فرق نمی گذاری؟ من مرگ خر را خواستم، تو گاو مرا می کشی؟\r\nشخصی در آنجا حاضر بود. گفت: خدا را شکر کن که دعایت مستجاب نشد. زیرا اگر خداوند می خواست خری را بکشد، باید ابتدا خودِ تو را می کشت. چرا که اگر خر نبودی، خودت آن حیوان زبان بسته را رها می کردی و دیگر مرگش را از خدا طلب نمی کردی.\r\n"},{"id":767,"category_id":6,"category_code":"s6","source_id":275,"title":"خربزه سه روزه","content":"مردی ادعای پیغمبری کرد. او را نزد پادشاه بردند. پادشاه از او پرسید: «معجزه ات چیست؟» گفت: «هر چه بخواهید. » شاه گفت: «خربزه ای برای ما حاضر کن. » گفت: سه روز به من مهلت بدهید. » شاه گفت: «همین حالا حاضر کن وگرنه تو را می کشم.!\r\nگفت: ای پادشاه! انصافت کجا رفته؟ خداوند عالم با آن قدرتی که دارد، خربزه را در مدت سه ماه می آفریند. حال من که پیغمبر او هستم، به من سه روز مهلت نمی دهید؟\r\n"},{"id":768,"category_id":6,"category_code":"s6","source_id":276,"title":"تو نیکی کن تا...","content":"كبوترى را حكايت كنند بر شاخه درختى نشسته، مورى را ديد در آب افتاده، به هيچ وسيله و حيله نمى‏تواند خود را از غرقاب هلاك نجات دهد. دلش بر او بسوخت و حيله‏اى ساخته، برگى از درخت بركند و در آب انداخت. مورچه غريق، خود را به آن كشتى نجات رساند و بر آن سوار شد و در كنار راند؛ ديد صيادى آنجا ايستاده و تير بر چله كمان نهاده، زه كشيده و بغل گشاده و سينه بى كينه كبوتر پاك دل را هدف و آن جان پاك را در شرف تلف قرار داده است. به چالاكى نزد او دويد كه ياور رسيد و به بى باكى چنان پاى او بگزيد كه دستش بلرزيد و تيرش بر خطا و كبوتر از مرگ رها شد."},{"id":769,"category_id":6,"category_code":"s6","source_id":277,"title":"لحظه ی آخر","content":"عبدالرحمن بن غنمه گفت : براي عيادت فرزند معاذ بر او وارد شديم . او را بر بالين فرزندش نشسته ديديم آن جوان در حال احتضار بود ما نتوانستيم خودداري كنيم اشكمان جاري شد و صداي ما به گريه بلند گرديد معاذ با خشونت ما را بازداشت . گفت : ساكت باشيد به خدا سوگند خودش مي داند صبر بر اين پيش آمد محبوبتر است نزد من از تمام جنگهاييكه در خدمت پيغمبر نموده ام ، من شنيدم از پيغمبر صلي الله عليه و آله فرمود: هر كس فرزندي داشته باشد مورد علاقه و مهر او، آن فرزند فوت شود اگر صبر كند در مصيبتش و ناراحت نشود خداوند فوت شده را به مكاني بهتر از محل اولي مي برد. در مقابل اين پيش آمد مصيب زده را مورد رحمت و مغفرت و رضوان خود قرار مي دهد مختصر زماني گذشت صداي مو ذن بلند شد در همين هنگام جوان از دنيا رفت ما براي انجام نماز حركت كرديم ، وقتي كه برگشتيم ديديم او را غسل داده و كفن نموده است مردم جنازه اش را برده اند خود را به آنها رسانديم ، به معاذ گفتيم خداوند ترا رحمت كند چرا صبر نكردي تا ما به جنازه پسر برادرمان حاضر شويم . گفت : به ما دستور داده اند فوت شدگان را تاءخير نياندازيم هر ساعت از شب و روز كه از دنيا رفتند، آنگاه داخل در قبر شد و فرزندش را دفن نمود.\r\nموقعيكه خواست خارج شود دستش را گرفتم تا از قبر بيرونش آورم . امتناع ورزيد گفت : اين امتناع من نه از جهت اينست كه پرقوه و نيرومندم بلكه دوست ندارم شخص ناداني خيال كند دست مرا براي ضعف و سستي كه از مصيبت فرزند بر من وارد شده گرفته اي به منزل خود برگشت روغن استعمال كرد و چشمش را سرمه كشيد لباس خود را عوض نمود در آن روز بيشتر تبسم مي كرد به همان نيتي كه داشت . گفت : ((انا لله و انا اليه راجعون )) در راه خدا عوض آنچه فوت شود هست هر مصيبتي در آن راه آسانست جبران فوت شده در نزد اوست.\r\n"},{"id":770,"category_id":6,"category_code":"s6","source_id":278,"title":"فقدان عقل","content":"سليمان ديلمى گويد: به امام صادق عليه السلام عرض كردم فلانى در عبادت و ديانت و فضيلت چنين و چنانست فرمود: عقلش چگونه است؟ گفتم نمى‏دانم، فرمود، پاداش باندازه عقل است، همانا مردى از بنى اسرائيل در يكى از جزاير دريا كه سبز و خرم و پر آب و درخت بود عبادت خدا مى‏كرد يكى از فرشتگان از آنجا گذشت و عرض كرد پروردگارا مقدار پاداش اين بنده‏ات را به من بنما خداوند باو نشان داد و او آن مقدار را كوچك شمرد، خدا باو وحى كرد همراه او باش پس آن فرشته بصورت انسانى نزد او آمد عابد گفت تو كيستى؟ گفت مردى عابدم چون از مقام و عبادت تو در اين مكان آگاه شدم نزد تو آمدم تا با تو عبادت خدا كنم پس آن روز را با او بود، چون صبح شد فرشته باو گفت: جاى پاكيزه‏اى دارى و فقط براى عبادت خوب است. عابد گفت: اينجا يك عيب دارد. فرشته گفت :چه عيبى؟ عابد گفت: خداى ما چهارپائى ندارد، اگر او خرى مى‏داشت در اينجا مى‏چرانديمش براستى اين علف از بين مى‏رود! فرشته گفت: پروردگار كه خر ندارد، عابد گفت: اگر خرى مى‏داشت چنين علفى تباه نمى‏شد، پس خدا بفرشته وحى كرد: همانا او را باندازه عقلش پاداش مى‏دهم (يعنى حال اين عابد مانند مستضعفين و كودكان است كه چون سخنش از روى ساده دلى و ضعف خرد است مشرك و كافر نيست ليكن عبادتش هم پاداش عبادت) عالم خداشناس را ندارد"},{"id":771,"category_id":6,"category_code":"s6","source_id":279,"title":"ديوانه واقعى","content":"امير المؤ منين عليه السلام فرمود: با پيامبر اكرم صلى الله عليه و آله بر جمعى گذشتيم ، نبى حق فرمود: براى چه گرد هم جمع شديد؟ عرض ‍ كردند: يا رسول الله ، اين مرد ديوانه است كه غش مى كند و ما بر گرد او جمع شديم . پيامبر فرمود: اين ديوانه نيست ، بلكه بيمار است . سپس ‍ فرمود: دوست داريد ديوانه حقيقى را بشناسيد؟ عرض كردند: بلى يا رسول الله ، پيامبر اسلام فرمود: ديوانه آن كس است كه از روى تكبر و غرور راه مى رود، و با گوشه چشمش نگاه مى كند، و شانه هاى خود را از سر بزرگى مى جنباند، و با آنكه گناه خدا را مى ورزد، آرزوى بهشت از خدا دارد.\r\nمردم از شرش آسوده نيستند، و به خيرش اميدى نيست . ديوانه اين است ، ولى اين مرد بيمار و گرفتار است.\r\n"},{"id":772,"category_id":6,"category_code":"s6","source_id":280,"title":"دستبوسى","content":"مردى خواست تا بر دست رسول خدا صلى الله عليه و آله بوسه زند، پيامبر دست خود را كشيد و فرمود: اين كارى است كه عجم ها با پادشاهان خود مى كنند و من شاه نيستم ، من مردى از خودتان هستم."},{"id":773,"category_id":6,"category_code":"s6","source_id":281,"title":"تعليم و تعلم","content":"در مدينه روزى پيامبر صلى الله عليه و آله اسلام صلى الله عليه و آله وارد مسجد گرديد، چشمش به دو اجتماع افتاد كه در دو دسته تشكيل شده بودند و هر دسته اى حلقه اى تشكيل داده و سرگرم بودند؛ يك دسته به عبادت و ذكر خدا، و دسته اى به تعليم و تعلم و ياد دادن و ياد گرفتن سرگرم و مشغول بودند. حضرت از ديدن هر دو دسته مسرور و خرسند گرديد و به همراهانش فرمود:\r\nاين هر دو دسته كار نيك نموده و بر خير و سعادتند. لكن من براى دانا كردن و دانا شدن مردم فرستاده شده و مبعوث گشته ام . پس خودش به طرف همان دسته كه به تعليم و تعلم اشتغال داشتند، رفت و در حلقه آنان نشست.\r\n"},{"id":774,"category_id":6,"category_code":"s6","source_id":282,"title":"ريا کاری","content":"شداد بن اوس گفت : بر رسول خدا صلى الله عليه و آله وارد شدم و چهره مباركش را بدان گونه افسرده ديدم كه مرا ناراحت ساخت . عرض كردم : چه پيش آمده است ؟ فرمودند: بر امتم از شرك مى ترسم . عرض كردم : آيا پس از شما مشرك مى شوند؟ فرمودند: آنان خورشيد و ماه و بت و سنگ نمى پرستند، ولى ريا مى كنند و ريا خود شرك است و سپس آيه 110 سوره كهف را تلاوت فرمودند: فمن كان يرجوا لقاء ربه فليعمل عملا صالحا و لا يشرك بعبادة ربه احدا\r\nهر كس اميد ديدار پروردگار خود دارد، بايد كار شايسته كند و در پرستش ‍ پروردگار خويش ، كسى از شريك نگيرد.\r\n"},{"id":775,"category_id":6,"category_code":"s6","source_id":283,"title":"ذكر و دعا","content":"پيامبر اكرم صلى الله عليه و آله بلند كردن صدا را به ذكر و دعا، كه غالبا شيوه مردم متظاهر و رياكار است، خوش نمى داشت. دريكى از سفرها، يارانش هرگاه كه مشرف به دره مى شدند، صدا با تكبير و تهليل بلند مى كردند، فرمود: آرام بگيريد، كسى كه او را مى خوانيد نه گوشش كر است و نه جاى دورى رفته است . او همه جا با شماست و شنوا و نزديك است."},{"id":776,"category_id":6,"category_code":"s6","source_id":284,"title":"كار و تلاش","content":"روزى پيامبر صلى الله عليه و آله با اصحاب خود نشسته بودند. پيامبر جوان نيرومندى را ديد كه اول صبح مشغول كار و تلاش مى باشد. بعضى از حاضران گفتند: اين شايسته تمجيد و ستايش بود، اگر نيروى جوانى خود را در راه خدا به كار مى انداخت ؟ پيامبر صلى الله عليه و آله فرمود: چنين نگوييد، اگر اين جوان كار مى كند تا نيازمنديهاى خود را تاءمين كند و از ديگران بى نياز گردد، در راه خدا گام برداشته و همچنين اگر به نفع پدر و مادر ناتوان و كودكان خردسالش كار كند و آنها را از مردم بى نياز سازد، باز هم در راه خدا قدم برداشته است."},{"id":777,"category_id":6,"category_code":"s6","source_id":285,"title":"به من بگو پدر!","content":"\r\nبعضی از مردم مدینه، احترام پیامبر (ص) را نگه نمی داشتند، گاهی آن حضرت را با حرف هایشان آزار می دادند و گاه با رفتار بدشان، قلبش را می رنجاندند، اما یک کار بین آن ها خیلی زیاد شده بود. آن ها هر وقت پیامبر خدا (ص) را می دیدند، صدایش می زدند: «یا محمد!» یا می گفتند: «ای پسر عبدالله!»\r\nیا اسم ها و لقب های دیگر ایشان را در حرف هایشان به کار می بردند. خداوند از این کار آن ها خشنود نبود، چون پیامبر بزرگو مهربانش، از بهترین بندگانش به حساب می آمد.\r\nروزی خداوند آیه ای  به پیامبر(ص) وحی کرد. خداوند در آن آیه، به مردم امر کرد که دیگر پیامبر (ص) را به اسم صدا نزنند، بلکه بگویند: «یا رسول الله!»\r\nفاطمه نگران شد، چون او همیشه پیامبر را صدا می زد: «پدر!»\r\nاما آن روز فکر کرد شاید این کارش هم در نظر خداوند خوب نبوده است. پس تصمیم گرفت پیامبر را پدر صدا نکند.\r\nوقتی پدرش را دید، گفت: یا رسول الله!\r\nاین کار فاطمه چند بار تکرار شد. پیامبر گفت: «فاطمه جان! این آیه برای تعلیم مردم عرب است. آن ها اهل جفا و غفلت هستند، اما برای تو و نسل تو نازل نشده است. تو از منی و من از تو. اگر تو بگویی پدر، قلب من با این حرف زنده تر می شود و خدا خشنودتر!» فاطمه شادمان شد.\r\n"},{"id":778,"category_id":6,"category_code":"s6","source_id":286,"title":"شب میلاد ","content":"يوسف، در مكّه زندگى مي كرد. او يهودي بود. شبى مشاهده كرد ستارگان، وضع طبيعى خود را از دست داده اند. با خود گفت: بايد در اين شب پيغمبرى متولد شده باشد. در كتابي خوانده‏ام؛ هر گاه پيغمبر آخر الزمان متولد شود، شياطين از رفتن به آسمان‌ها ممنوع مي شوند.\r\nيوسف، صبح هنگام در اجتماع قريش حاضر شد و پرسيد: آيا در خانواده‏هاى شما فرزندى متولد شده است؟!.\r\nگفتند: آرى ديشب براى عبد اللَّه بن عبد المطلب پسرى متولّد شده است.\r\nپرسيد: او را به من نشان مي دهيد؟!.\r\nوى را به در منزل آمنه بردند. به او گفتند: فرزندت را بيرون آور ... .\r\nآمنه كودك خود را در قماط  پيچيده بود. با احتياط فرزندش را بيرون آورد.\r\nيوسف همواره به چشم‏هاى مولود نگاه مي كرد. پس از آن كتف طفل را باز كرد. خال سياهى كه چند دانه موى ريز در آن ديده مي شد، بين دو كتف حضرت(ص) ديد. يوسف يهودي، هنگامى كه چشمش به خال افتاد، بي هوش نقش روى زمين گرديد.\r\nقريش، خيلي از اين جريان تعجب كردند. به مرد يهودى خنديدند.\r\nيوسف، پس از اين كه به هوش آمد، گفت: اى جماعت قريش، اين مولود در آينده نزديكى شما را به هلاكت خواهد رسانيد. نبوت بنى اسرائيل براى هميشه از بين خواهد رفت. مردم با ناباوري از اطراف او پراكنده شدند. گفته‏هاى او را در محافل و مجالس نقل مي كردند.\r\n"},{"id":779,"category_id":6,"category_code":"s6","source_id":287,"title":"عاطفه پيامبر(ص)","content":"مردى خدمت پيامبر(ص) عرض كرد: يا رسول الله! ما در زمان جاهليّت بت ها را پرستش مى كرديم. فرزندان خود را مى كشتيم. دخترى داشتم، از اين كه او را به مهمانى مى بردم، خيلى خوشحال مى شد. روزى او را به قصد مهمانى بيرون بردم. دخترم دنبال سرم حركت مى كرد. رفتم تا به چاهى رسيدم. آن چاه از خانه من، زياد دور نبود. دست دخترم را گرفتم. او را در چاه انداختم. آخرين چيزى كه از او به ياد دارم، اين است كه با مظلو ميّت تمام فرياد مى زد: پدر!... پدر!...\r\nرسول اكرم(ص) با شنيدن اين ماجراي غم انگيز، آن چنان گريه كرد كه اشك ديدگانش خشك شد.\r\n"},{"id":780,"category_id":6,"category_code":"s6","source_id":288,"title":"دوستی وفادار","content":"عمار ياسر ‏گويد: پيش از بعثت با پيامبر(ص) شبانى مى‏كردم. روزى با ايشان قرار گذاشتم تا در مرتع فخ به چراى گوسفندان مشغول شويم. روز بعد پيامبر(ص) زودتر از من به چراگاه رسيده بود، امّا گوسفندانش را از چرا نگه داشته بود. دليل اين كار را از پيامبر(ص) پرسيدم.\r\nحضرت(ص) پاسخ داد: « ... چون وعده داده بودم، دوست نداشتم زودتر، گوسفندانم از مرتع استفاده كنند ».\r\n"},{"id":781,"category_id":6,"category_code":"s6","source_id":289,"title":"محبت معبود","content":"زيارت رسول اكرم حضرت محمّد صلّي الله عليه و آله و سلّم آرزوی او بود. برای این کار تصميم گرفت به «مدينه» برود. در راه، چند جوجه ی پرنده ديد. آن ها را برداشت تا به عنوان هديه براي پيامبر خدا رسول اكرم صلّي الله عليه و آله و سلّم ببرد. مادرِ جوجه ها پرواز كنان از راه رسيد. جوجه هايش را در دستِ مرد، اسير ديد. به دنبالِ مرد به راه افتاد. پرنده، پرواز کنان او را دنبال مي كرد.\r\nمرد به مدينه رسيد. يك سره به مسجد رفت. پس از زيارت رسول خدا نبيّ اكرم صلّي الله عليه و آله و سلّم، جوجه ها را نزد ايشان گذاشت. پرنده ي مادر كه به دنبالِ جوجه هايش پرواز كرده بود، به سرعت فرود آمد. غذايي را كه به منقار گرفته بود، در دهانِ يكي از جوجه ها گذاشت و دور شد.\r\nرسول خدا نبی اكرم صلّي الله عليه و آله و سلّم و اصحاب ايشان، اين صحنه را مي نگريستند. ساعتي گذشت. جوجه ها در وسط مسجد قرار داشتند. مسلمانان دورِ آن ها را گرفته بودند. در همين لحظه، دوباره پرنده ي مادر رسيد. فرود آمد. غذايي را تهيّه كرده بود. آن را دهانِ جوجه ي ديگر گذاشت. پرواز كرد و دور شد.\r\nدر اين هنگام، رسول گرامي اسلام رسول خدا صلّي الله عليه و آله و سلّم جوجه ها را آزاد فرمود.\r\nآن گاه رو به اصحاب كرده و فرمود: « ... مهر و محبّتِ اين مادر را نسبتِ به جوجه هايش چگونه ديديد؟!».\r\nاصحاب عرض كردند:« بسيار عجيب و شگفت انگيز بود ».\r\nپيامبر خدا رسول اكرم صلّي الله عليه و آله و سلّم فرمود: « ... قسم به خداوندي كه مرا به پيامبري برگزيد، مهر و محبّت خداي عالم به بندگانش، هزارانِ مرتبه از چيزي كه ديديد، بيشتر است ».\r\n"},{"id":782,"category_id":6,"category_code":"s6","source_id":290,"title":"مسيحی و زره علی \"ع\" ","content":"در زمان خلافت علی -عليه‏السلام- در كوفه، زره آن حضرت گم شد. پس‏ از چندی در نزديك مرد مسيحی پيداشد. علی او را به محضر قاضی برد، و اقامه دعوی كرد كه: \"اين زره از آن من است، نه آن را فروخته‏ام و نه‏ \r\nبه كسی بخشيده‏ام. و اكنون آن را در نزد اين مرد يافته‏ام. قاضی به‏ مسيحی گفت: \"خليفه ادعای خود را اظهار كرد، تو چه می‏گويی ؟\" او \r\nگفت: \"اين زره مال خود من است ، و در عين حال گفته مقام خلافت را \r\nتكذيب نمی‏كنم (ممكن است خليفه اشتباه كرده باشد)\". \r\nقاضی رو كرد به علی و گفت: \"تو مدعی هستی و اين شخص منكر است، عليهذا بر تو است كه شاهد برمدعای خود بياوری\". \r\nعلی خنديد و فرمود: \"قاضی راست می‏گويد، اكنون می‏بايست كه من شاهد بياورم، ولی من شاهد ندارم\". \r\nقاضی روی اين اصل كه مدعی شاهد ندارد، به نفع مسيحی حكم كرد، و او هم‏ زره را برداشت و روان شد. ولی مرد مسيحی كه خود بهتر می‏دانست كه زره مال كی است، پس از آنكه‏ چند گامی پيمود وجدانش مرتعش شد و برگشت، گفت: \"اين طرز حكومت و رفتار از نوع رفتارهای بشر عادی نيست، از نوع حكومت انبياست\"، و اقرار كرد كه زره از علی است. \r\nطولی نكشيد او را ديدند مسلمان شده، و با شوق و ايمان در زير پرچم علی‏ در جنگ نهروان می‏جنگد.\r\n"},{"id":783,"category_id":6,"category_code":"s6","source_id":291,"title":"امام باقر و مرد مسیحی","content":"امام باقر، محمد بن علی بن الحسين(ع)، لقبش \"باقر\" است. \r\nباقر يعنی شكافنده. به آن حضرت \"باقر العلوم\" می‏گفتند، يعنی‏\"شكافنده دانشها\". \r\nمردی مسيحی، به صورت سخريه و استهزاء، كلمه \"باقر\" را تصحيف‏ \r\nكرد به كلمه \"بقر\" -يعنی گاو- و به آن حضرت گفت: «انت بقر»؛ يعني«تو گاوی» \r\nامام بدون آنكه از خود ناراحتی نشان بدهد و اظهار عصبانيت كند، با \r\nكمال سادگی گفت: «نه، من بقر نيستم من باقرم». \r\nمسيحی: «تو پسر زنی هستی كه آشپز بود». \r\n- «شغلش اين بود، عار و ننگی محسوب نمی‏شود». \r\n- «مادرت سياه و بی‏شرم و بد زبان بود». \r\n- «اگر اين نسبتها كه به مادرم می‏دهی راست است، خداوند او را \r\nبيامرزد و از گناهش بگذرد. و اگر دروغ است، از گناه تو بگذرد كه دروغ‏ \r\nو افترا بستی». \r\nمشاهده اين همه حلم، از مردی كه قادر بود همه گونه موجبات آزار يك‏ \r\nمرد خارج از دين اسلام را فراهم آورد، كافی بود كه انقلابی در روحيه مرد \r\nمسيحی ايجاد نمايد، و او را به سوی اسلام بكشاند . \r\nمرد مسيحی بعدا مسلمان شد.\r\n"},{"id":784,"category_id":6,"category_code":"s6","source_id":292,"title":"مردی که اندرز خواست","content":"\r\nمردی از باديه به مدينه آمد و به حضور رسول اكرم رسيد. از آن حضرت‏ \r\nپندی و نصيحتی تقاضا كرد. رسول اكرم به او فرمود: \"خشم مگير\" و بيش‏ از اين چيزی نفرمود . \r\nآن مرد به قبيله خويش برگشت. اتفاقا وقتی كه به ميان قبيله خود رسيد،اطلاع يافت كه در نبودن او حادثه مهمی پيش آمده، از اين قرار كه‏ جوانان قوم او دستبردی به مال قبيله‏ای ديگر زده‏اند، و آنها نيز معامله‏ \r\nبه مثل كرده‏اند، و تدريجا كار به جاهای باريك رسيده، و دو قبيله در \r\nمقابل يكديگر صف آرائی كرده‏اند، و آماده جنگ و كارزارند. شنيدن اين‏ \r\nخبر هيجان آور، خشم او را برانگيخت . فورا سلاح خويش را خواست و پوشيد و به صف قوم خود ملحق و آماده همكاری شد . \r\nدر اين بين، گذشته به فكرش افتاد، به يادش آمد كه به مدينه رفته و \r\nچه چيزها ديده و شنيده، به يادش آمد كه از رسول خدا پندی تقاضا كرده‏ است ، و آن حضرت به او فرموده، جلو خشم خود را بگيرد. \r\nدر انديشه فرو رفت كه چرا من تهييج شدم، و به چه موجبی من سلاح پوشيدم‏، و اكنون خود را مهيای كشتن و كشته شدن كرده‏ام؟ چرا بی‏جهت من برا فروخته و خشمناك شده‏ام؟! با خود فكر كرد الان وقت آن است كه آن جمله‏ كوتاه را به كار بندم . \r\nجلو آمد و زعمای صف مخالف را پيش خواند و گفت: \"اين ستيزه برای‏ \r\nچيست ؟ اگر منظور غرامت آن تجاوز است كه جوانان نادان ما كرده‏اند، من‏ حاضرم از مال شخصی خودم اداكنم. علت ندارد كه ما برای همچو چيزی به جان‏ يكديگر بيفتيم و خون يكديگر را بريزيم\". \r\nطرف مقابل كه سخنان عاقلانه و مقرون به گذشت اين مرد را شنيدند، غيرت و مردانگی شان تحريك شد و گفتند: \r\n\"ما هم از تو كمتر نيستيم. حالا كه چنين است ما از اصل ادعای خودصرف‏ نظر می‏كنيم \" \r\nهر دو صف به ميان قبيله خود بازگشتند.\r\n"},{"id":785,"category_id":6,"category_code":"s6","source_id":293,"title":"مرد شامی","content":"\r\nشخصی از اهل شام ، به قصد حج يا مقصد ديگر به مدينه آمد . چشمش افتاد \r\nبه مردی كه در كناری نشسته بود. توجهش جلب شد. پرسيد: «اين مرد كيست ؟» \r\nگفته شد : «حسين بن علی بن ابيطالب است».\r\nسوابق‏ تبليغاتی عجيبی۱ كه در روحش رسوخ كرده بود، موجب شد كه ديگر خشمش به جوش آيد و قربة الی‏ الله آنچه می‏تواند دشنام نثار حسين بن علی بنمايد . همينكه هر چه‏ خواست گفت و عقده دل خود را گشود، امام حسين بدون آنكه خشم بگيرد و \r\nاظهار ناراحتی كند، نگاهی پر از مهر و عطوفت به او كرد، و پس از آنكه‏ \r\nچند آيه از قرآن -مبنی بر حسن خلق و عفو و اغماض- قرائت كرد به او \r\nفرمود: «ما برای هر نوع خدمت و كمك به تو \r\nآماده‏ايم».\r\nآنگاه از او پرسيد: «آيا از اهل شامی؟» جواب داد: \"آری\". فرمود: «من با اين خلق و خوی سابقه دارم و سر چشمه آن را می‏دانم». \r\nپس از آن فرمود: \"تو در شهر ما غريبی، اگر احتياجی داری حاضريم به‏ \r\nتو كمك دهيم، حاضريم در خانه خود از تو پذيرايی كنيم. حاضريم تو را \r\nبپوشانيم، حاضريم به تو پول بدهيم». \r\nمرد شامی كه منتظر بود با عكس العمل شديدی برخورد كند و هرگز گمان‏ نمی‏كرد با يك همچو گذشت و اغماضی روبرو شود، چنان منقلب شد كه گفت: «آرزو داشتم در آن وقت زمين شكافته می‏شد و من به زمين فرو می‏رفتم، و اين چنين نشناخته و نسنجيده گستاخی نمی‏كردم. تا آن ساعت برای من، در \r\nهمه روی زمين كسی از حسين و پدرش مبغوضتر نبود، و از آن ساعت بر عكس‏، كسی نزد من از او و پدرش محبوبتر نيست».\r\n"},{"id":786,"category_id":6,"category_code":"s6","source_id":294,"title":"اعرابی","content":"عربی بيابانی و وحشی ، وارد مدينه شد و يكسره به مسجد آمد ، تا مگر از \r\nرسول خدا سيم و زری بگيرد . هنگامی وارد شد كه رسول اكرم در ميان انبوه‏ \r\nاصحاب و ياران خود بود . حاجت خويش را اظهار كرد و عطائی خواست . \r\nرسول اكرم چيزی به او داد ، ولی او قانع نشد و آن را كم شمرد ، بعلاوه سخن‏ \r\nدرشت و ناهمواری بر زبان آورد ، و نسبت به رسول خدا جسارت كرد . \r\nاصحاب و ياران سخت در خشم شدند ، و چيزی نمانده بود كه آزاری به او \r\nبرسانند ، ولی رسول خدا مانع شد . \r\nرسول اكرم بعدا اعرابی را با خود به خانه برد ، و مقداری ديگر به او \r\nكمك كرد ، ضمنا اعرابی از نزديك مشاهده كرد كه وضع رسول اكرم به وضع رؤسا و حكامی كه‏ \r\nتاكنون ديده شباهت ندارد ، و زر و خواسته‏ای در آنجا جمع نشده . \r\nاعرابی اظهار رضايت كرد و كلمه‏ای تشكر آميز بر زبان راند . در اين‏ \r\nوقت رسول اكرم به او فرمود : \" تو ديروز سخن درشت و ناهمواری برزبان‏ \r\nراندی كه ، موجب خشم اصحاب و ياران من شد . من می‏ترسم از ناحيه آنها به‏ \r\nتو گزندی برسد ، ولی اكنون در حضور من اين جمله تشكر آميز را گفتی ، آيا \r\nممكن است همين جمله را در حضور جمعيت بگويی تا خشم و ناراحتی كه آنان‏ \r\nنسبت به تو دارند ، از بين برود ؟ \" اعرابی گفت : \" مانعی ندارد \" . \r\nروز ديگر اعرابی به مسجد آمد ، در حالی كه همه جمع بودند ، رسول اكرم‏ \r\nرو به جمعيت كرد و فرمود : \" اين مرد اظهار می‏دارد كه از ما راضی شده‏ \r\nآيا چنين است ؟ \" اعرابی گفت : \" چنين است \" و همان جمله تشكر آميز \r\nكه در خلوت گفته بود تكرار كرد . اصحاب و ياران رسول خدا خنديدند . \r\nدر اين هنگام رسول خدا رو به جمعيت كرد ، و فرمود : \" مثل من و اين‏ \r\nگونه افراد ، مثل همان مردی است كه شترش رميده بود و فرار می‏كرد ، مردم‏ \r\nبه خيال اينكه به صاحب شتر كمك بدهند فرياد كردند ، و به دنبال شتر \r\nدويدند . آن شتر بيشتر رم كرد و فراری‏تر شد . صاحب شتر مردم را بانگ زد \r\nو گفت ، خواهش می‏كنم كسی به شتر من كاری نداشته باشد ، من خودم بهتر \r\nمی‏دانم كه از چه راه شتر خويش را رام كنم . \r\n همينكه مردم را از تعقيب بازداشت ، رفت و يك مشت علف برداشت‏ \r\nو آرام آرام از جلو شتر بيرون آمد ، بدون آنكه نعره‏ای بزند و فريادی بكشد \r\nو بدود ، تدريجا در حالی كه علف را نشان می‏داد جلو آمد . بعد باكمال‏ \r\nسهولت مهار شتر خويش را در دست گرفت و روان شد . \r\n\" اگر ديروز من شما را آزاد گذاشته بودم ، حتما اين اعرابی بدبخت به‏ \r\nدست شما كشته شده بود - و در چه حال بدی كشته شده بود ، در حال‏ \r\nكفر و بت پرستی - ولی مانع دخالت شما شدم ، و خودم با نرمی و ملايمت او \r\nرا رام كردم \"\r\n"},{"id":787,"category_id":6,"category_code":"s6","source_id":295,"title":"در رکاب خلیفه","content":"علی(عليه‏السلام) هنگامی كه به سوی كوفه می‏آمد، وارد شهر انبار شد كه‏ \r\nمردمش ايرانی بودند. \r\nكدخدايان و كشاورزان ايرانی خرسند بودند كه خليفه محبوبشان از شهر آنها \r\nعبور می‏كند، به استقبالش شتافتند، هنگامی كه مركب علی به راه افتاد، \r\nآنها در جلو مركب علی (ع) شروع كردند به دويدن. علی آنها را طلبيد و \r\nپرسيد: «چرا می‏دويد، اين چه كاری است كه می‏كنيد؟!». \r\n- «اين يك نوعی احترام است كه ما نسبت به امرا و افراد مورد احترام‏ \r\nخود می‏كنيم . اين سنت و يك نوع ادبی است كه در ميان ما معمول‏ بوده است». \r\n- امام علی: «اينكار شمارا در دنيا به رنج می‏اندازد، و در آخرت به شقاوت‏ \r\nمی‏كشاند. هميشه از اين گونه كارها كه شما را پست و خوار می‏كند، خودداری‏ \r\nكنيد. بعلاوه اين كارها چه فايده‏ای به حال آن افراد دارد؟»\r\n"},{"id":788,"category_id":6,"category_code":"s6","source_id":296,"title":"مسلمان و کتابی","content":"در آن ايام، در تمام قلمرو كشور \r\nوسيع اسلامی، به استثناء قسمت شامات، چشمها به آن شهر دوخته‏ \r\nبود كه، چه فرمانی صادر می‏كند و چه تصميمی می‏گيرد. \r\nدر خارج اين شهر دو نفر، يكی مسلمان و ديگری كتابی (يهودی يامسيحی‏ \r\nيا زردشتی) روزی در راه به هم برخورد كردند. مقصد يكديگر را پرسيدند. \r\nمعلوم شد كه مسلمان به كوفه می‏رود، و آن مرد كتابی درهمان نزديكی، جای‏ \r\nديگری را در نظر دارد كه برود. توافق كردند كه چون در مقداری از مسافرت‏ \r\nراهشان يكی است باهم باشند و بايكديگر مصاحبت كنند. \r\nراه مشترك، با صميميت، در ضمن صحبتها و مذاكرات مختلف طی شد. به‏ \r\nسر دو راهی رسيدند، مرد كتابی با كمال تعجب مشاهده كرد كه رفيق‏ \r\nمسلمانش از آن طرف كه راه كوفه بود نرفت، و از اين طرف كه او می‏رفت،‏ \r\nآمد . \r\nپرسيد : «مگر تو نگفتی من می‏خواهم به كوفه بروم ؟» \r\n-مسلمان: «چرا». \r\n-کتابی: «پس چرا از اين طرف می‏آئی؟ راه كوفه كه آن يكی است». \r\n-مسلمان: «می‏دانم، می‏خواهم مقداری تورا مشايعت كنم. پيغمبر ما فرمود: \"هرگاه دو نفر در يك راه بايكديگر مصاحبت كنند، حقی بريكديگر پيدا \r\nمی‏كنند\". اكنون تو حقی بر من پيدا كردی. من به خاطر اين حق كه به‏ \r\nگردن من داری می‏خواهم چند قدمی تو را مشايعت كنم. و البته بعد به راه‏ \r\nخودم خواهم رفت». \r\n-کتابی: «اوه، پيغمبر شما كه اين چنين نفوذ و قدرتی در ميان مردم پيدا كرد، و باين سرعت دينش در جهان رائج شد، حتما به واسطه همين اخلاق كريمه‏اش بوده». \r\nتعجب و تحسين مرد كتابی در اين هنگام به نهایت درجه رسيد، كه برايش‏ \r\nمعلوم شد، اين رفيق مسلمانش، خليفه وقت، علی ابن ابيطالب(ع)\r\nبوده. طولی نكشيد كه همين مرد مسلمان شد، و در شمار افراد مؤمن و \r\nفداكار اصحاب علی(عليه‏السلام) قرار گرفت».\r\n"},{"id":789,"category_id":6,"category_code":"s6","source_id":297,"title":"غذایی دسته جمعی","content":"همينكه رسول اكرم و اصحاب و ياران از مركبها فرود آمدند، و بارها را \r\nبر زمين نهادند، تصميم جمعيت براين شد كه برای غذا گوسفندی را ذبح و \r\nآماده كنند. \r\nيكی از اصحاب گفت: «سر بريدن گوسفند با من» \r\nديگری: «كندن پوست آن بامن» \r\nسومی: «پختن گوشت آن بامن» \r\nچهارمی: . . . \r\nرسول اكرم : «جمع كردن هيزم از صحرا بامن ». \r\nجمعيت: «يا رسول الله شما زحمت نكشيد و راحت بنشينيد، ما خودمان‏ \r\nبا كمال افتخار همه اينكارها را می‏كنيم» \r\nرسول اكرم: «می‏دانم كه شما می‏كنيد، ولی خداوند دوست نمی دارد \r\nبنده‏اش را در ميان يارانش با وضعی متمايز ببيند كه، برای خود نسبت به‏ \r\nديگران امتيازی قائل شده باشد». \r\nسپس به طرف صحرا رفت. و مقدار لازم خار و خاشاك از صحرا جمع كرد و \r\nآورد.\r\n"},{"id":790,"category_id":6,"category_code":"s6","source_id":298,"title":"قافله ای که به حج می رفت","content":"\r\nقافله‏ای از مسلمان كه آهنگ مكه داشت، مدينه که رسيد چند \r\nروزی توقف و استراحت كرد، و بعد به مقصد مكه به راه افتاد. \r\nدر بين راه مكه و مدينه، در يكی از منازل، اهل قافله با مردی مصادف‏ \r\nشدند كه با آنها آشنا بود. آن مرد در ضمن صحبت با آنها ، متوجه شخصی‏ \r\nدرميان آنها شد كه سيمای صالحين داشت، و با چابكی و نشاط مشغول خدمت و \r\nرسيدگی به كارها و حوائج اهل قافله بود، در لحظه اول او را شناخت. با \r\nكمال تعجب از اهل قافله پرسيد: «اين شخصی را كه مشغول خدمت و انجام‏ \r\nكارهای شماست می‏شناسيد؟»\r\n-اهل قافله: « نه، او را نمی‏شناسيم ، اين مرد در مدينه به قافله ما ملحق شد. مردی‏ \r\nصالح و متقی و پرهيزگار است. ما از او تقاضا نكرده‏ايم كه برای ما كاری‏ \r\nانجام دهد، ولی او خودش مايل است كه در كارهای ديگران شركت كند و به‏ \r\nآنها كمك بدهد.» \r\n-مرد: «معلوم است كه نمی‏شناسيد، اگر می‏شناختيد اين طور گستاخ نبوديد ، \r\nهرگز حاضر نمی‏شديد مانند يك خادم به كارهای شما رسيدگی كند.» \r\n- اهل قافله: «مگر اين شخص كيست ؟»\r\n- مرد: «اين، علی بن الحسين زين العابدين است.» \r\nجمعيت آشفته به پاخاستند و خواستند برای معذرت دست و پای امام را \r\nببوسند. آنگاه به عنوان گله گفتند: «اين چه كاری بود كه شما با ما \r\nكرديد؟! ممكن بود خدای ناخواسته ما جسارتی نسبت به شما بكنيم، و \r\nمرتكب گناهی بزرگ بشويم.» \r\nامام: «من عمدا شمارا كه مرا نمی‏شناختيد برای همسفری انتخاب كردم، زيرا گاهی با كسانی كه مرا می‏شناسند مسافرت‏ \r\nمی‏كنم ، آنها به خاطر رسول خدا زياد به من عطوفت و مهربانی می‏كنند، \r\nنمی‏گذارند كه من عهده‏دار كار و خدمتی بشوم، از اينرو مايلم همسفرانی‏ \r\nانتخاب كنم كه مرا نمی‏شناسند و از معرفی خودم هم خودداری می‏كنم تا \r\nبتوانم به سعادت خدمت رفقا نائل شوم».\r\n"},{"id":791,"category_id":6,"category_code":"s6","source_id":299,"title":"همسفر حج","content":"\r\nمردی از سفر حج برگشته، سرگذشت مسافرت خودش و همراهانش را برای‏ \r\nامام صادق تعريف می‏كرد، مخصوصا يكی از همسفران خويش را بسيار می‏ستود \r\nكه، چه مرد بزرگواری بود، ما به معيت همچو مرد شريفی مفتخر بوديم. \r\nيكسره مشغول طاعت و عبادت بود، همينكه در منزلی فرود می‏آمديم او فورا \r\nبه گوشه‏ای می‏رفت، و سجاده خويش را پهن می‏كرد، و به طاعت و عبادت‏ \r\nخويش مشغول می‏شد. \r\nامام : «پس چه كسی كارهای او را انجام می‏داد؟ و كه حيوان او را \r\nتيمار می‏كرد؟» \r\nمرد: «البته افتخار اين كارها با ما بود. او فقط به كارهای مقدس خويش‏ \r\nمشغول بود و كاری به اين كارها نداشت». \r\nامام: «بنابر اين همه شما از او برتر بوده‏ايد».\r\n"},{"id":792,"category_id":6,"category_code":"s6","source_id":300,"title":"بستن زانوی شتر","content":"\r\nقافله چندين ساعت راه رفته بود. آثار خستگی در سواران و در مركبها \r\nپديد گشته بود. همينكه به منزلی رسيدند كه آنجا آبی بود، قافله فرود \r\nآمد. رسول اكرم نيز كه همراه قافله بود، شتر خويش را خوابانيد و پياده‏ \r\nشد. قبل از همه چيز ، همه در فكر بودند كه خود را به آب برسانند و \r\nمقدمات نماز را فراهم كنند. \r\nرسول اكرم بعد از آنكه پياده شد، به آن سو كه آب بود روان شد، ولی‏ \r\nبعد از آنكه مقداری رفت، بدون آنكه با احدی سخنی بگويد، به طرف مركب‏ \r\nخويش بازگشت. اصحاب و ياران با تعجب باخود می‏گفتند آيا اينجا را \r\nبرای فرود آمدن نپسنديده است و می‏خواهد فرمان حركت بدهد؟! چشمها مراقب و گوشها منتظر شنيدن فرمان بود. تعجب جمعيت‏ \r\nهنگامی زياد شد كه ديدند همينكه به شتر خويش رسيد ، زانوبند را برداشت‏ \r\nو زانوهای شتر را بست ، و دو مرتبه به سوی مقصد اولی خويش روان شد . \r\nفريادها از اطراف بلند شد: «ای رسول خدا! چرا مارا فرمان ندادی كه‏ \r\nاين كار را برايت بكنيم، و به خودت زحمت دادی و برگشتی؟ ما كه با \r\nكمال افتخار برای انجام اين خدمت آماده بوديم ». \r\nدر جواب آنها فرمود: \"هرگز از ديگران در كارهای خود كمك نخواهيد، \r\nو بديگران اتكا نكنيد، ولو برای يك قطعه چوب مسواك باشد».\r\n"},{"id":793,"category_id":6,"category_code":"s6","source_id":301,"title":"خواهش دعا","content":"شخصی باهيجان و اضطراب، به حضور امام صادق(ع) آمد و گفت: «درباره من دعايی بفرماييد تا خداوند به من وسعت رزقی بدهد، كه‏ \r\nخيلی فقير و تنگدستم». \r\nامام : «هرگز دعا نمی‏كنم» . \r\nشخص: «چرا دعا نمی‏كنيد؟!» \r\nامام: «برای اينكه خداوند راهی برای اينكار معين كرده است، خداوند امر \r\nكرده كه روزی را پی‏جويی كنيد، و طلب نماييد. اما تو می‏خواهی در خانه‏ \r\nخود بنشينی، و با دعا روزی را به خانه خود بكشانی!»\r\n"},{"id":794,"category_id":6,"category_code":"s6","source_id":302,"title":"کمک...","content":"\r\nبه گذشته پرمشقت خويش می‏انديشيد، به يادش می‏افتاد كه چه روزهای تلخ‏ \r\nو پر مرارتی را پشت سر گذاشته، روزهايی كه حتی قادر نبود قوت روزانه‏ \r\nزن و كودكان معصومش را فراهم نمايد. با خود فكر می‏كرد كه چگونه يك‏ \r\nجمله كوتاه - فقط يك جمله - كه در سه نوبت پرده گوشش را نواخت ، به‏ \r\nروحش نيرو داد و مسير زندگانيش را عوض كرد ، و او و خانواده‏اش را از \r\nفقر و نكبتی كه گرفتار آن بودند نجات داد. \r\nاو يكی از صحابه رسول اكرم بود. فقر و تنگدستی براو چيره شده بود . در \r\nيك روز كه حس كرد ديگر كارد به استخوانش رسيده، با مشورت و پيشنهاد \r\nزنش تصميم گرفت برود، و وضع خود را برای رسول اكرم شرح دهد، و از آن حضرت استمداد مالی كند. \r\nبا همين نيت رفت، ولی قبل از آنكه حاجت خود را بگويد اين جمله از \r\nزبان رسول اكرم به گوشش خورد: «هرکس ازما كمكی بخواهد ما به او \r\nكمك می‏كنيم، ولی اگر كسی بی‏نيازی بورزد و دست حاجت پيش مخلوقی دراز \r\nنكند، خداوند او را بی‏نياز می‏كند» . آن روز چيزی نگفت، و به خانه‏ \r\nخويش برگشت. باز با هيولای مهيب فقر كه همچنان بر خانه‏اش سايه افكنده‏ \r\nبود روبرو شد، ناچار روز ديگر به همان نيت به مجلس رسول اكرم حاضر شد، آن روز هم همان جمله را از رسول اكرم شنيد: «هر کس ازماكمكی‏ \r\nبخواهد ما به او كمك می‏كنيم، ولی اگر كسی بی نيازی بورزد خداوند او را \r\nبی‏نياز می‏كند». اين دفعه نيز بدون اينكه حاجت خود را بگويد، به خانه‏ \r\nخويش برگشت. و چون خود را همچنان در چنگال فقر ضعيف و بيچاره و \r\nناتوان می‏ديد ، برای سومين بار به همان نيت به مجلس رسول اكرم رفت، \r\nباز هم لبهای رسول اكرم به حركت آمد ، و با همان آهنگ - كه به دل قوت و به روح اطمينان‏ \r\nمی‏بخشيد - همان جمله را تكرار كرد . \r\nاين بار كه آن جمله را شنيد ، اطمينان بيشتری در قلب خود احساس كرد . \r\nحس كرد كه كليد مشكل خويش را در همين جمله يافته است . وقتی كه خارج‏ \r\nشد با قدمهای مطمئنتری راه می‏رفت. با خود فكر می‏كرد كه ديگر هرگز به‏ \r\nدنبال كمك و مساعدت بندگان نخواهم رفت . به خدا تكيه می‏كنم و از نيرو \r\nو استعدادی كه در وجود خودم به وديعت گذاشته شده استفاده می‏كنم ، واز او \r\nمی‏خواهم كه مرا در كاری كه پيش می‏گيرم موفق گرداند و مرا بی نياز سازد . \r\nبا خودش فكر كرد كه از من چه كاری ساخته است؟ به نظرش رسيد عجالة \r\nاين قدر از او ساخته هست كه برود به صحرا و هيزمی جمع كند و بياورد و \r\nبفروشد . رفت و تيشه‏ای عاريه كرد و به صحرا رفت، هيزمی جمع كرد و \r\nفروخت. لذت حاصل دسترنج خويش را چشيد . روزهای ديگر به اينكار ادامه‏ \r\nداد ، تا تدريجا توانست از همين پول برای خود تيشه و حيوان و ساير لوازم كار را بخرد . \r\nباز هم به كار خود ادامه داد تا صاحب سرمايه و غلامانی شد . \r\nروزی رسول اكرم به او رسيد و تبسم كنان فرمود: «گفتم ، هركس از ما \r\nكمكی بخواهد ما به او كمك می‏دهيم ، ولی اگر بی‏نيازی بورزد خداوند او را \r\nبی‏نياز می‏كند.\r\n"},{"id":795,"category_id":6,"category_code":"s6","source_id":303,"title":"جبیر و زلفا","content":"\r\nروزی محمد ص از اصحاب صفه می گذشت\r\n(اصحاب صفه گروهی از مسلمانان فقیر بودند که به دستور پیامبر ص در مسجد به سر می بردند تا آن که به پیامبر ص وحی شد که مسجد جای سکونت نیست اینها باید در خارج از مسجد سکونت کنند پیامبرص در خارج از مسجد محلی را آماده کرد و در آن سایبانی ایجاد کرد به آن صفه میگفتند و فقیرانی که در آن سکونت داشتند به اصحاب صفه معروف بودند) \r\nجیبر را دید \r\nفردی سیاهپوست ، کوتاه قد ، زشت رو \r\nبه وی گفت چرا ازدواج نمیکنی؟\r\nجیبر که از این حرف پیامبر ص سخت شگفت زده شده بود گفت:\r\nیا رسول الله چه کسی حاضر است دخترش را به من بدهد؟ من که نه مال دارم نه جمال ، نه حسب دارم نه نسب ، چه کسی دخترش را به من میدهد. کدام دختر ، همسر سیاه پوست بدشکل و فقیری مثل من میشود؟\r\nپیامبرص به ایشان فرمود : ای جبیر خداوند به وسیله ی اسلام ارزش انسانها را عوض کرد بسیاری افراد در دوره ی جاهلیت بالا بودند و اسلام آنها را پایین کشید ، بسیاری در دوره ی جاهلیت خوار و ذلیل بودند و اسلام آنها را ارزش و منزلت داد.\r\nامروز همه ی مسلمانان با هم برابر و برادرند و...\r\nرسول خدا ص با این جملات جیبر را از اشتباه خود بیرون آورد و به وی پیشنهاد کرد که دختر زیاد بن لبید را که از ثروتمندان مدینه بود ، از وی خواستگاری کند!\r\nجیبر پس از اسرار پیامبر ص نزد زیاد رفت بعد از مدتی کلنجار با خود خواسته خود را به زیاد بن لبید گفت\r\nزیاد بسیار تعجب کرد و گفت : \r\n- واقعا پیامبر به تو چنین حرفی زده ؟\r\n- بله\r\n- ولی در رسم ما دخترانمان را به هم ردیفان خود و هم شانان خود میدهیم\r\nجیبر که این سخنان را شنید بلافاصله از جای برخواست و از خانه خارج شد \r\nزلفا دختر زیاد که این سخنان را شنید نزد پدر آمد و گفت:\r\n- بابا نکند جیبر راست بگوید و واقعا پیامبر ص وی را فرستاده باشد؟\r\n- خب به نظر تو چه کنم؟\r\n- وی را به خانه بیاور و از وی پذیرایی کن و فردا این سخنان را با پیامبر ص در میان بگذار\r\nزیاد چنین کرد .\r\nفردا نزد پیامبر ص رفت :\r\n- یا رسول الله جیبر دیروز نزد من آمد و گفت پیامبر ص فرموده دختر زیاد را برای خود خواستگاری کن ولی ما دخترانمان را به هم شانان خود میدهیم\r\n- ای زیاد جیبر مومن است . این شانیت هایی که گمان میکنی امروز از میان رفته مرد مومن هم شان زن مومنه است .\r\nالخبیثاتُ للخبیثینِ و الخبیثونَ للخبیثاتِ والطیباتُ للطیبین والطیبون للطیباتِ ...\r\nزنان بدکار و ناپاک شایسته ی مردانی بدین وصفند و مردان زشتکار و ناپاک شایسته ی زنانی بدین وصفند و بلعکس زنان پاکیزه ی نیکو لایق مردانی چنین و مردان پاکیزه ی نیکو لایق زنانی چنینند... \r\nسوره ی نور آیه ی ۲۶\r\n\r\nزیاد پس از شنیدن این سخنان به خانه باز گشت و موضوع را برای دخترش نقل کرد:\r\n- دخترم نظر تو چیست:\r\n- پدر به نظر من پیشنهاد رسول خدا را رد نکن .مطلب مربوط به من است و جیبر هرچه هست من باید راضی باشم و...\r\nزیاد زلفا را به عقد جیبر در آورد و از سرمایه ی خود برای آنها منزل و لوازم زندگی تهیه کرد و...\r\n\r\nجویبر و زلفا با هم عروسی کردند و به خوشی سر بردند.\r\nجهادی پیش آمد که جیبر با همان نشاطی که مخصوص اهل ایمان است زیر پرچم اسلام در آن جهاد شرکت کرد و شهید شد.\r\n"},{"id":796,"category_id":6,"category_code":"s6","source_id":304,"title":"زاهد پند آموز","content":"زاهدی روايت كرده كه در عمرم: جواب چهار نفر مرا سخت تکان داد. اول مرد فاسدی از کنار من گذشت و من گوشه لباسم را جمع کردم تا به او نخورد. او گفت ای شیخ خدا میداند که فردا حال ما چه خواهد بود! دوم مستی دیدم که افتان و خیزان راه میرفت به او گفتم قدم ثابت بردار تا نیفتی. گفت تو با این همه ادعا قدم ثابت کرده ای؟ سوم کودکی دیدم که چراغی در دست داشت گفتم این روشنایی را از کجا آورده ای؟ کودک چراغ را فوت کرد و آن را خاموش ساخت و گفت:تو که شیخ شهری بگو که این روشنایی کجا رفت؟ چهارم زنی بسیار زیبا که درحال خشم از شوهرش شکایت میکرد . گفتم اول رویت را بپوشان بعد با من حرف بزن . گفت من که غرق خواهش دنیا هستم چنان از خود بیخود شده ام که از خود خبرم نیست تو چگونه غرق محبت خالقی که از نگاهی بیم داری؟"},{"id":797,"category_id":6,"category_code":"s6","source_id":305,"title":"خداوند و دیدگاه ملاصدرا","content":"خداوند بی نهایت است و لامکان و بی زمان، اما به قدر فهم تو کوچک می شود، و به قدر نیاز تو فرود می آید، و به قدر آرزوی تو گسترده می شود، و به قدر ایمان تو کارگشا می شود، یتیمان را پدر می شود و مادر، محتاجان برادری را برادر می شود، عقیمان را طفل می شود، ناامیدان را امید می شود، گمگشتگان را راه می شود، در تاریکی ماندگان را نور می شود، رزمندگان را شمشیر می شود، پیران را عصا می شود، محتاجان به عشق را عشق می شود.\r\nخداوند همه چیز می شود همه کس را... \r\nبه شرط اعتقاد، به شرط پاکی دل، به شرط طهارت روح، به شرط پرهیز از معامله با ابلیس، بشویید قلب هایتان را از هر احساس ناروا، و مغزهایتان را از هر اندیشه خلاف، و زبان هایتان را از هر گفتار ناپاک، و دست هایتان را از هر آلودگی در بازار، و بپرهیزید از ناجوانمردی ها، ناراستی ها، نامردمی ها... \r\nچنین کنید تا ببینید چگونه بر سفره شما با کاسه ای خوراک و تکه ای نان می نشیند، در دکان شما کفههای ترازویتان را میزان می کند.\r\nو در کوچه های خلوت شب با شما آواز می خواند مگر از زندگی چه می خواهید که در خدایی خدا یافت نمی شود؟؟؟\r\n"},{"id":798,"category_id":6,"category_code":"s6","source_id":306,"title":"70 دلیل","content":"تیمورتاش -وزیر دربار رضا خان - کسی بود که می‌گفت می‌تواند با 70 دلیل ثابت کند که خدا وجود ندارد و دائماً \r\nپدرش را لعنت می‌کرد که اسم او را عبدالحسین گذاشته است!\r\nیک آدم کاملاً بی‌دین بود و آخر سر هم به دست رضاخان به زندان افتاد و کشته شد. می‌گویند در زندان گفته\r\nبود: «به خاطر خدا مرا ببخش».\r\n\r\nرضاخان گفته بود: «مگر تو با 70 دلیل ثابت نکردی خدا وجود ندارد؟ برای کدام خدا تو را ببخشم؟»\r\n"},{"id":799,"category_id":6,"category_code":"s6","source_id":307,"title":"ابلیس و فرعون","content":"روزی ابلیس نزد فرعون رفت. فرعون خوشه‌ای انگور در دست داشت و تناول می‌کرد. ابلیس گفت: آیا می‌توانی \r\nاین خوشه انگور تازه را به مروارید تبدیل کنی؟\r\nفرعون گفت: نه.\r\nابلیس به لطایف‌الحیل و سحر و جادو، آن خوشه انگور را به خوشه‌ای مروارید تبدیل کرد. فرعون تعجب کرد و گفت: \r\nاحسنت! عجب استاد ماهری هستی.\r\nابلیس خود را به فرعون نزدیک کرد و یک پس گردنی به او زد و گفت: مرا با این استادی و مهارت حتی به بندگی \r\nقبول نکردند، آن وقت تو با این حماقت، ادعای خدایی می‌کنی؟\r\n"},{"id":800,"category_id":6,"category_code":"s6","source_id":308,"title":"زن بی وفا","content":"حکیمی جعبه‌اى بزرگ پر از مواد غذایى و سکه و طلا را به خانه زنى با چندین بچه قد و \r\nنیم قد برد.\r\nزن خانه وقتى بسته‌هاى غذا و پول را دید شروع کرد به بدگویى از همسرش و گفت:\r\nشوهر من آهنگرى بود که از روى بى‌عقلى دست راست و نصف صورتش را در یک حادثه \r\nدر کارگاه آهنگرى از دست داد و مدتى بعد از سوختگى علیل و از کار افتاده گوشه خانه \r\nافتاد تا درمان شود.\r\nوقتى هنوز مریض و بى‌حال بود چندین بار در مورد برگشت سر کارش با او صحبت کردم \r\nولى به جاى اینکه دوباره سر کار آهنگرى برود مى‌گفت که دیگر با این بدنش چنین کارى از \r\nاو ساخته نیست و تصمیم دارد سراغ کار دیگر برود.\r\nمن هم که دیدم او دیگر به درد ما نمى‌خورد برادرانم را صدا زدم و با کمک آن‌ها او از خانه و \r\nدهکده بیرون انداختیم تا لااقل خرج اضافى او را تحمل نکنیم.\r\nبا رفتن او ، بقیه هم وقتى فهمیدن وضع ما خراب شده از ما فاصله گرفتند و امروز که شما \r\nاین بسته‌هاى غذا و پول را برایمان آوردید ما به شدت به آنها نیاز داشتیم.\r\nاى کاش همه انسان‌ها مثل شما جوانمرد و اهل معرفت بودند!\r\nحکیم تبسمى کرد و گفت: حقیقتش من این بسته‌ها را نفرستادم. یک فروشنده دوره‌گرد \r\nامروز صبح به مدرسه ما آمد و از من خواست تا اینها را به شما بدهم و ببینم حالتان خوب \r\nهست یا نه!؟ همین!\r\nحکیم این را گفت و از زن خداحافظى کرد تا برود.\r\nدر آخرین لحظات ناگهان برگشت و ادامه داد: راستى یادم رفت بگویم که دست راست و \r\nنصف صورت این فروشنده دوره گردهم سوخته بود…\r\n"},{"id":801,"category_id":6,"category_code":"s6","source_id":309,"title":"ناله","content":"\r\nدرویشی کودکی داشت که از غایت محبّت، شبْ پهلوی خودش خوابانیدی. شبی دید که \r\nآن کودک در بستر می نالد و سر بر بالین می مالد. گفت: ای جان پدر چرا در خواب نمی روی؟\r\nگفت: ای پدر! فردا روزِ پنج شنبه است و مرا متعلّما (درس های) یک هفته پیشِ استاد \r\nعرضه می باید که از بیم در خواب نمی روم.مبادا که درمانم.\r\nآن درویش صاحب حال بود. این سخن بشنید نعره ای زد و بیهوش شد. چون با خود آمد \r\nگفت: واویلا، وا حَسْرَتا؛ کودکی که درسِ یک هفته پیش معلّم عرض باید کرد شب در \r\nخواب نمی رود پس مرا که اعمالِ هفتاد ساله پیش عرشِ خدا در روز مظالم (قیامت) بر \r\nخدایِ عالم الاَسرار عرض باید کرد حال چگونه باشد؟\r\n"},{"id":802,"category_id":6,"category_code":"s6","source_id":310,"title":"آهنگر","content":"آهنگری بود که پس از گذران جوانی پر شر و شور،تصمیم گرفت روحش را وقف خدا کند. \r\nسالها با علاقه کار کرد، اما با تمام پرهیزگاری، در زندگیش چیزی درست به نظر نمی آمد، \r\nحتی مشکلاتش مدام بیشتر می شد!\r\n\r\nروزی دوستی به دیدنش آمده بود پس از اطلاع از وضعیت دشوارش به او گفت:\r\n“واقعا عجیب است! درست بعد از اینکه تصمیم گرفتی مرد خدا ترسی بشوی، زندگیت \r\nبدتر شده. نمی خواهم ایمانت را تضعیف کنم اما با وجود تمام تلاشهایت در مسیر \r\nروحانی، هیچ چیز بهتر نشده!”\r\nآهنگر بلافاصله پاسخ نداد. او هم بارها همین فکر را کرده بودو نمی فهمید چه بر سر زندگیش آمده است!\r\nاما نمی خواست سؤال دوستش را بدون پاسخ بگذارد، کمی فکر کرد و ناگهان پاسخی را که می خواست یافت.\r\nاین پاسخ آهنگر بود:\r\nدر این کارگاه، فولاد خام برایم می آورند که باید از آن شمشیر بسازم. میدانی چه طور این \r\nکار را میکنم؟ اول فولاد را به اندازه جهنم حرارت میدهم تا سرخ شود. بعد با بی رحمی، \r\nسنگین ترین پتک را بر میدارم و پشت سر هم به آن ضربه میزنم تا اینکه فولاد شکلی را \r\nبگیرد که میخواهم. بعد آن را در ظرف آب سرد فرو میکنم، بطوریکه تمام این کارگاه را بخار فرا می گیرد. فولاد به خاطر این تغییر ناگهانی دما، ناله میکند و رنج می برد. یک بار کافی نیست، باید این کار را آن قدر تکرار کنم تا به شمشیر مورد نظرم دست بیابم…\r\nآهنگر لحظه ای سکوت کرد. سپس ادامه داد:\r\nگاهی فولاد نمی تواند تاب این عملیات را بیاورد. حرارت، ضربات پتک و آب سرد باعث ترک \r\nخوردنش میشود. میدانم که از این فولاد هرگز شمشیر مناسبی در نخواهد آمد لذا آن را \r\nکنار می گذارم.\r\nآهنگر باز مکث کرد و بعد ادامه داد:\r\nمی دانم که خدا دارد مرا در آتش رنج فرو می برد. ضربات پتکی را که بر زندگی من وارد \r\nکرده پذیرفته ام و گاهی به شدت احساس سرما میکنم، انگار فولادی باشم که از آب دیده \r\nشدن رنج می برد. اما تنها چیزی که می خواهم این است:\r\n“خدای من، از کارت دست نکش، تا شکلی که تو میخواهی، به خود بگیرم…\r\nبا هر روشی که می پسندی، ادامه بده،هر مدت که لازم است، ادامه بده…اما هرگز مرا \r\nبه میان فولادهای بی فایده پرتاب نکن!”\r\n"},{"id":803,"category_id":6,"category_code":"s6","source_id":311,"title":"لج بازی","content":"دو گدا در خیابانی نزدیک واتیکان کنار هم نشسته بودند. یکی صلیب گذاشته بود و دیگری الله... \r\nمردم زیادی که از آنجا رد می شدند، به هر دو نگاه می کردند و فقط در کلاه اونی که پشت صلیب نشسته بود .\r\nپول میانداختند.\r\nکشیشی از آنجا می گذشت، مدتی ایستاد و دید که مردم فقط به گدایی که صلیب دارد پول می دهند و هیچ \r\nکس به گدای پشت الله چیزی نمی دهد. رفت جلو و گفت:\r\nرفیق بیچاره من، متوجه نیستی؟ اینجا مرکز مذهب کاتولیک است.\r\nپس مردم به تو که الله گذاشتی پول نمی دهند، به خصوص که درست نشستی کنار یه گدای دیگری که صلیب \r\nدارد. در واقع از روی لجبازی هم که باشد مردم به اون یکی پول میدهند نه تو.\r\nگدای پشت الله بعد از شنیدن حرفهای کشیش رو کرد به گدای پشت صلیب و گفت:\r\nهی \"اسدالله\" نگاه کن کی اومده به ما بازاریابی یاد بده؟\r\nمراقب باشید به لجبازی با یکی، سکه تان را در کلاه دیگری نیاندازید.\r\n"},{"id":804,"category_id":6,"category_code":"s6","source_id":312,"title":"امتحان مرد مسلمان","content":"\r\nمقیم لندن بود. تعریف می کرد که یک روز سوار تاکسی می شود و کرایه را می \r\nپردازد. راننده بقیه پول را که بر می گرداند 20 پنی اضافه تر می دهد! می گفت: \r\n«چند دقیقه ای با خودم کلنجار رفتم که بیست پنی اضافه را برگردانم یا نه؟ آخر سر \r\nبر خودم پیروز شدم و بیست پنی را پس دادم و گفتم آقا این را زیاد دادی.»\r\nگذشت و به مقصد رسیدیم. موقع پیاده شدن راننده سرش را بیرون آورد و گفت: «آقا \r\nاز شما ممنونم.»\r\nپرسیدم: «بابت چی؟»\r\nگفت: «می خواستم فردا بیایم مرکز شما مسلمانان و مسلمان شوم اما هنوز کمی \r\nمردد بودم. وقتی دیدم سوار ماشینم شدید خواستم شما را امتحان کنم. با خودم \r\nشرط کردم اگر بیست پنی را پس دادید بیایم. فردا خدمت می رسیم!»\r\nتعریف می کرد: «تمام وجودم دگرگون شد. حالی شبیه غش به من دست داد. من \r\nمشغول خودم بودم در حالی که داشتم تمام اسلام را به بیست پنی می فروختم!»\r\n"},{"id":805,"category_id":6,"category_code":"s6","source_id":313,"title":"قربانی شدن یک عشق","content":"آرزو داشتم تنها پسرم با دختر خواهرم ازدواج کند، اما او در دوران دانشجویی به دختری از خانواده ای مستضعف که با هم همکلاسی بودند علاقه مند شد و دختر مورد علاقه اش را به عقد خود درآورد. زن ۶۵ ساله با لهجه جنوبی خود در دایره اجتماعی کلانتری امام رضا(ع) مشهد افزود: سلیم از ازدواج با سکینه خیلی خوشحال بود اما هر موقع نامزد او به خانه ما می آمد دچار سردرد می شدم و احساس می کردم این عروس یک لاقبا در شأن خانوادگی ما نیست. من هرچه با خودم کلنجار رفتم تا مهر و محبت این دختر را در دلم جای دهم فایده ای نداشت و خواهرم نیز با نیش و کنایه هایش آتش بیار این معرکه شده بود. متاسفانه پس از گذشت مدتی، نقشه شومی کشیدم و با کمک پسر خواهرم فردی را اجیر کردیم تا ادعا کند قبلا با عروسم آشنایی و رابطه داشته است. ما با این تهمت های ناروا توانستیم سلیم را نسبت به همسرش بدبین کنیم و او نامزدش را طلاق داد. من بلافاصله دختر خواهرم را به عقد پسرم درآوردم اما سلیم و دخترخاله اش خیری از زندگیشان ندیدند چون آن ها صاحب دو فرزند معلول شدند و عروسم که تاب و تحمل مشکلات زندگی و جمع و جور کردن این دو طفل بی گناه را نداشت پس از گذشت ۱۵ سال به پسرم خیانت کرد و دنبال سرنوشت خودش رفت.از آن به بعد من و پسرم خودمان را به پرستاری از این دو بچه معلول سرگرم کردیم. ولی هر روز که می گذشت من به خاطر ظلم و خیانتی که در حق عروس قبلی ام کرده بودم عذاب وجدان بیشتری پیدا می کردم و خیلی دنبال سکینه گشتم تا او را پیدا کنم و حلالیت بطلبم. ولی هیچ آدرس و نشانی از او پیدا نکردم. تا این که برای سفر زیارتی به مشهد آمدیم.\r\nدر این جا هنگام عبور از خیابان با یک موتورسیکلت تصادف کردم و وقتی که برای مداوا به بیمارستان انتقال یافتم باورم نمی شد پرستار مرکز درمانی همان کسی باشد که سال ها دنبالش می گشتم. سکینه با مهربانی از من پرستاری و مراقبت کرد و زمانی که دست هایش را محکم گرفتم و با شرمندگی برایش تعریف کردم مرتکب چه گناه بزرگی شده ام، او با لبخندی معصومانه دستم را بوسید و گفت: مادرجان حتما قسمت این طوری بوده است و من از شما هیچ دلخوری و ناراحتی به دل ندارم و همین جا شما را بخشیدم. زن ۶۵ ساله گفت: از این که می بینم سکینه با فردی شایسته ازدواج کرده است و ۲ دختر زیبا و دوست داشتنی دارد خیلی خوشحالم و برایشان دعا می کنم خوشبخت و سعادتمند بشوند. امیدوارم خدا هم از خطاهایم بگذرد.\r\n"},{"id":806,"category_id":6,"category_code":"s6","source_id":314,"title":"کیفر خیانت","content":"در یکی از دهات های فارس، دهقان با تجربه ای زندگی می کرد. او مردی هوشمند و عارف بود و از عبادت و بندگی خدا بهره تامّی داشت ولی فقیر و تنگدست بود و زندگی بسیار سختی داشت. دست به هر کاری دراز می کرد تا شاید بتواند از فقر و تنگدستی نجات یابد، ولی موفق نمی شد و پیش آمدهای پی در پی و ناگوار بر او وارد می شد و بیش از پیش او را به سختی و رنج می انداخت.\r\nاو زنی داشت که در حسن و زیبایی و جمال نظیر نداشت ولی در مقابل فقر و تنگدستی شوهرش، بسیار اعتراض می کرد و به او زخم زبان و طعنه می زد.\r\nروزی زن به مردش گفت: «بیا از این جا هجرت کنیم، شاید در دیار دیگری بتوانی خود را از فقر و تنگدستی نجات دهی.»\r\nمرد گفت: «من با این پیشنهاد موافق هستم زیرا بسیار کسانی بودند که از وطن خود هجرت کردند و در نتیجه به مقام و ثروت رسیدند ولی من از یک چیز می ترسم و آن است که می ترسم راه بی وفایی در پیش\r\nبگیری و فریب دیگران را بخوری.»\r\nزن، سوگندها یاد کرد و گفت: «من به عهدی که در شب عروسی و هنگام ازدواج با تو بستم تا آخر عمر وفا خواهم کرد و برای همیشه با تو خواهم بود. این اندیشه ها را از سر بدر کن و خیالت راحت و آسوده باشد.»:\r\nمرد به پیشنهاد زن، از وطن خود به جای نامعلومی سفر کرد. در بین راه، گه گاهی در بعضی از منازل پیاده شده و استراحت می کردند و دوباره به حرکت خود ادامه می دادند تا اینکه در منزلی، مرد به خواب عمیقی فرو رفت.\r\nدر همین حین، امیر زاده ای که به عنوان شکار به آن اطراف آمده بود گذارش به همان جا افتاد. وقتی که چشمش به زن زیبای آن مرد افتاد، شیفته او شد و به او اظهار عشق و علاقه کرد و گفت: «اگر از آن مرد جدا شوی، به زندگی خوبی خواهی رسید و در ناز و نعمت بسر خواهی برد.»\r\nزن نیز بر خلاف عهد و پیمانش، راه بی وفایی را در پیش گرفت و آهسته از جای برخاست و از شوهرش که خوابیده بود جدا شد و با آن جوان سوار بر اسب گردید و رفت، تا اینکه به چشمه ای رسیدند و برای قضای حاجت پیاده شدند. زن همین که کمی از چشمه دور شد شیری از راه رسید و آن زن را درید و مقداری از گوشت او را خورد و رفت. امیر زاده چون دید که زن جوان دیر کرده است بدنبال او رفت و دید که بدن پاره پاره او بر روی زمین است.\r\nاز طرفی، دهقان از خواب بیدار شد و زنش را ندید. برای پیدا کردن وی، شتابان به هر سو می دوید تا اینکه به همان چشمه رسید و آن جوان را دید و حال عیال خود را از او پرسید.\r\nجوان گفت: «زنی را در اینجا دیدم که شیر او را پاره پاره کرده است.»\r\nدهقان وقتی که زن خود را به آن حال دید و حقیقت ماجرا را فهمید گفت: «این است کیفر خیانت و بی وفایی.»\r\n"},{"id":807,"category_id":6,"category_code":"s6","source_id":315,"title":"تصمیمات خداوند","content":"\r\nشوالیه ای به دوستش گفت: بیا به کوهستانی برویم که خداوند در آنجا \r\nسکنی دارد. می خواهم ثابت کنم که خداوند فقط بلد است که از ما چیزی \r\nبخواهد، در حالی که خودش برای سبک کردن بار ما کاری نمی کند.\r\nدیگری گفت: خوب، من هم می آیم تا ایمانم را نشان دهم. همان شب به \r\nقله کوه رسیدند... و از درون تاریکی آوایی را شنیدند که گفت: سنگ های \r\nروی زمین را بر پشت اسبان تان بگذارید!!!\r\nشوالیه اول گفت: دیدی؟! بعد از این کوهنوردی، می خواهد بار سنگین تری \r\nرا هم با خود ببریم! من که اطاعت نمی کنم. اما شوالیه دوم به دستور آوا \r\nعمل کرد.\r\nوقتی پای کوه رسید، سپیده دم بود، و نخستین پرتوهای آفتاب بر سنگ \r\nهای شوالیه پارسا تابید: الماس های ناب بودند که می درخشیدند!!!\r\nاستاد می گوید: تصمیم های خداوند اسرارآمیز، اما همواره به سود ماست.\r\n"},{"id":808,"category_id":6,"category_code":"s6","source_id":316,"title":"آن طرف خیابان","content":"\r\nپیرمرد ایستاده بود دم در و پسر جوان را جلوی همه، بلند بلند نصیحت می \r\nکرد. وسط حرف هایش هم به مردمی که برای روضه آمده بودند، خوش آمد \r\nمی گفت. پسر سرش را انداخته بود پایین و به حرف های پیرمرد گوش می داد. \r\nپیرمرد: نمی گویم ننداز، بنداز، ولی آخه این چیه؟ خب حداقل اسم \r\nمعصومی، قرآنی، دعایی، چیزی می انداختی دور گردنت، نه این. حیف \r\nنیست تویی که آمده ای مجلس امام حسین، ادای یه عده اجنبی را در \r\nبیاری؟ بچه مسلمان را چه به این رفتارها؟ \r\nموبایل پیرمرد زنگ خورد و مشغول صحبت شد. پسر جوان آرام از مجلس \r\nبیرون آمد. گوشی ام پی تری پلیر را در گوشش گذاشت. صدای مداحی را \r\nزیاد کرد و با چشمی گریان وارد کلیسای آنطرف خیابان شد.\r\n"},{"id":809,"category_id":6,"category_code":"s6","source_id":317,"title":"تلخ","content":"توی قصابی بودم که یه پیرزن اومد تو و یه گوشه وایستاد .....\r\nیه آقای خوش تیپی هم اومد تو گفت: ابرام آقا قربون دستت پنج کیلو فیله گوساله بکش عجله دارم .....\r\nآقای قصاب شروع کرد به بریدن فیله و جدا کردن اضافه‌هاش .....\r\nهمینجور که داشت کارشو می‌کرد رو به پیرزن کرد گفت: چی مِخی نِنه ؟\r\nپیرزن اومد جلو یک پونصد تومنی مچاله گذاشت تو ترازو گفت: هَمینو گُوشت بده نِنه .....\r\nقصاب یه نگاهی به پونصد تومنی کرد گفت: پُونصَد تُومَن فَقَط اّشغال گوشت مِشِه نِنه بدم؟\r\nپیرزن یه فکری کرد گفت بده نِنه!\r\nقصاب اشغال گوشت‌های اون جوون رو می‌کند می‌ذاشت برای پیره زن .....\r\nاون جوونی که فیله سفارش داده بود همین جور که با موبایلش بازی می‌کرد گفت: اینارو واسه سگت می‌خوای مادر؟\r\nپیرزن نگاهی به جوون کرد گفت: سَگ؟\r\nجوون گفت اّره ..... سگ من این فیله‌ها رو هم با ناز می‌خوره ..... سگ شما چجوری اینا رو می‌خوره؟\r\nپیرزن گفت: مُخُوره دیگه نِنه ..... شیکم گشنه سَنگم مُخُوره .....\r\nجوون گفت نژادش چیه مادر؟ پیرزنه گفت بهش مِگن تُوله سَگِ دوپا نِنه ..... اینا رو برا بچه‌هام می‌خام اّبگوشت بار بیذارم!\r\nجوونه رنگش عوض شد ..... یه تیکه از گوشتای فیله رو برداشت گذاشت رو اشغال گوشتای پیرزن .....\r\nپیرزن بهش گفت: تُو مَگه ایناره بره سَگِت نگرفته بُودی؟\r\nجوون گفت: چرا\r\nپیرزن گفت ما غِذای سَگ نِمُخُوریم نِنه .....\r\nبعد گوشت فیله رو گذاشت اون طرف و اشغال گوشتاش رو برداشت و رفت.\r\n"},{"id":810,"category_id":6,"category_code":"s6","source_id":318,"title":"آن درخت","content":"در میان بنی اسرائیل عابدی بود. وی را گفتند:« فلان جا درختی است و قومی آن را می پرستند» عابد خشمگین شد، برخاست و تبر بر دوش نهاد تا آن درخت را برکند. ابلیس به صورت پیری ظاهر الصلاح، بر مسیر او مجسم شد، و گفت:« ای عابد، برگرد و به عبادت خود مشغول باش!» عابد گفت:« نه، بریدن درخت اولویت دارد» مشاجره بالا گرفت و درگیر شدند.\r\nعابد بر ابلیس غالب آمد و وی را بر زمین کوفت و بر سینه اش نشست. ابلیس در این میان گفت:\r\n«دست بدار تا سخنی بگویم، تو که پیامبر نیستی و خدا بر این کار تو را مامور ننموده است، به خانه برگرد، تا هر روز دو دینار زیر بالش تو نهم؛ با یکی معاش کن و دیگری را انفاق نما و این بهتر و صوابتر از کندن آن درخت است»؛ عابد با خود گفت :« راست می گوید، یکی از آن به صدقه دهم و آن دیگر هم به معاش صرف کنم» و برگشت.\r\nبامداد دیگر روز، دو دینار دید و بر گرفت. روز دوم دو دینار دید و برگرفت. روز سوم هیچ نبود. خشمگین شد و تبر برگرفت. باز در همان نقطه، ابلیس پیش آمد و گفت:«کجا؟» عابد گفت:«تا آن درخت برکنم»؛ گفت«دروغ است، به خدا هرگز نتوانی کند» در جنگ آمدند. ابلیس عابد را بیفکند چون گنجشکی در دست! عابد گفت: « دست بدار تا برگردم. اما بگو چرا بار اول بر تو پیروز آمدم و اینک، در چنگ تو حقیر شدم؟»\r\nابلیس گفت:« آن وقت تو برای خدا خشمگین بودی و خدا مرا مسخر تو کرد، که هرکس کار برای خدا کند، مرا بر او غلبه نباشد؛ ولی این بار برای دنیا و دینار خشمگین شدی، پس مغلوب من گشتی»\r\n"},{"id":811,"category_id":6,"category_code":"s6","source_id":319,"title":"مصلحت","content":"سالهای بسیار دور پادشاهی زندگی میکرد که وزیری داشت. وزیر همواره میگفت : هر اتفاقی که رخ میدهد به صلاح ماست. روزی پادشاه برای پوست کندن میوه کارد تیزی طلب کرد اما در حین بریدن میوه انگشتش را برید، وزیر که در آنجا بود گفت : نگران نباشید تمام چیزهایی که رخ میدهد در جهت خیر و صلاح شماست ! پادشاه از این سخن وزیر برآشفت و از رفتار او در برابر این اتفاق آزرده خاطر شد و دستور زندانی کردن وزیر را داد…\r\nچند روز بعد پادشاه با ملازمانش برای شکار به نزدیکی جنگلی رفتند. پادشاه در حالی که مشغول اسب سواری بود راه را گم کرد و وارد جنگل انبوهی شد و از ملازمان خود دور افتاد، در حالی که پادشاه به دنبال راه بازگشت بود به محل سکونت قبیله ای رسید که مردم آن در حال تدارک مراسم قربانی برای خدایانشان بودند، زمانی که مردم پادشاه خوش سیما را دیدند خوشحال شدند زیرا تصور کردند وی بهترین قربانی برای تقدیم به خدای آنهاست!!!آنها پادشاه را در برابر تندیس الهه خود بستند تا وی را بکشند، اما ناگهان یکی از مردان قبیله فریاد کشید : چگونه میتوانید این مرد را برای قربانی کردن انتخاب کنید در حالی که وی بدنی ناقص دارد، به انگشت او نگاه کنید !!! به همین دلیل وی را قربانی نکردند و آزاد شد.\r\nپادشاه که به قصر رسید وزیر را فراخواند و گفت : ا کنون فهمیدم منظور تو از اینکه میگفتی هر چه رخ میدهد به صلاح شماست چه بوده زیرا بریده شدن انگشتم موجب شد زندگی ام نجات یابد اما در مورد تو چی؟ تو به زندان افتادی این امر چه خیر و صلاحی برای تو داشت؟!! وزیر پاسخ داد: پادشاه عزیز مگر نمیبینید، اگر من به زندان نمی افتادم مانند همیشه در جنگل به همراه شما بودم در آنجا زمانی که شما را قربانی نکردند مردم قبیله مرا برای قربانی کردن انتخاب میکردند، بنابراین میبینید که حبس شدن نیز برای من مفید بود!!! ایمان قوی داشته باشید و بدانید هر چه رخ میدهد خواست خداوند است تصمیمات خداوند از قدرت درک ما خارج است اما همیشه به سود ما می باشد.\r\n"},{"id":812,"category_id":6,"category_code":"s6","source_id":320,"title":"امانت","content":"استاد فرزانه ای به خوبی و خوشی با خانواده اش زندگی می کرد، زنی بسیار وفادار و دو پسر عزیز داشت. زمانی به خاطر کارش مجبور شد چندین روز از خانه دور بماند. در آن مدت هر دو فرزندش در یک تصادف اتومبیل کشته شدند. مادر بچّه ها در تنهایی رنج فقدان فرزندانش را تحمّل کرد. امّا از آنجا که زن نیرومندی بود و به خدا ایمان و اعتقاد داشت، با متانت و شجاعت این ضربه را تحمّل کرد. اما چطور می توانست این خبر هولناک را به شوهرش بدهد. شوهرش هم به اندازه ی او مؤمن بود، امّا او مدّتی پیش بر اثر بیماری قلبی در بیمارستان بستری شده بود و همسرش می ترسید خبر این فاجعه، باعث مرگ او بشود. تنها کاری که از دست زن بر می آمد، این بود که به درگاه خدا دعا کند تا بهترین راه را نشانش بدهد. شبی که قرار بود شوهرش برگردد، باز هم دعا کرد و سرانجام دعایش اجابت شد و پاسخی گرفت.\r\nروز بعد، استاد به خانه برگشت، همسرش را در آغوش گرفت و سراغ بچّه ها را گرفت. زن به او گفت فعلا نگران آن ها نباشد و حمّام بگیرد و استراحت کند.\r\nکمی بعد، نشستند تا ناهار بخورند. زن احوال سفر شوهرش را پرسید و او هم برای همسرش از لطف خدا گفت و باز سراغ بچّه ها را گرفت. همسرش با حالت عجیبی گفت: نگران بچّه ها نباش، بعدا به آن ها می رسیم. اوّل برای حل مشکلی جدّی، به کمکت احتیاج دارم.\r\nاستاد با اضطراب پرسید: چه اتّفاقی افتاده؟ به نظرم رسید که مضطربی، بگو در چه فکری، مطمئنّم به لطف خدا می توانیم هر مشکلی را با هم حل کنیم. زن گفت: در مدّتی که نبودی، دوستی سراغمان آمد و دو جواهر بسیار با ارزش پیش ما گذاشت تا نگه داریم. جواهرات بسیار زیباییست! تا حالا چیزی به این قشنگی ندیدم. حالا آمده تا جواهراتش را پس بگیرد و من نمی خواهم آن ها را پس بدهم. خیلی دوستشان دارم. چکار باید بکنم؟\r\nاستاد گفت: اصلا رفتارت را درک نمی کنم! تو هیچ وقت زن بی تعهدّی نبوده ای.\r\nزن گفت: آخر تا حالا جواهری به این زیبایی ندیده ام! فکر جداشدن از آن ها برایم سخت است.\r\nاستاد با قاطعیت گفت: هیچ کس چیزی را که صاحبش نباشد، از دست نمی دهد. نگهداشتن این جواهرات یعنی دزدیدن آن ها، جواهرات را پس می دهیم و بعد کمکت می کنم تا فقدانش را تحمّل کنی. همین امروز اینکار را با هم می کنیم.\r\nزن گفت: هرچه تو بگویی عزیزم، جواهرات را بر می گردانیم. در واقع، قبلا آن ها را پس گرفته اند. این دو جواهر ارزشمند، پسران ما بودند. خدا آن ها را به ما امانت داد، وقتی تو در سفر بودی، آن ها را پس گرفت.\r\nاستاد قضیه را فهمید، همسرش را در آغوش کشید و با هم گریه کردند. او پیام را دریافته بود و از آن روز به بعد، سعی کردند فقدان فرزندانشان را با هم تاب بیاورند.\r\n"},{"id":813,"category_id":6,"category_code":"s6","source_id":321,"title":"شکست شیطان","content":"روزی شیطان لعنت الله علیه در گوشه مسجد الحرام ایستاده بود. حضرت رسول صلی الله علیه و آله هم سرگرم طواف خانه کعبه بودند. وقتی آن حضرت از طواف فارغ شد، دیدند ابلیس (لاعنت الله علیه) ضعیف و نزار و رنگ پریده ، کناری ایستاده است ، فرمودند :ای ملعون ! تو را چه می شود که چنین ضعیف و رنجوری ؟! \r\nگفت : ازدست امت تو به جان آمده وگداخته شدم \r\nفرمودند: مگر امت من با تو چه کرده اند؟ \r\nگفت : یا رسول الله ! چند خصلت نیکو در ایشان است ، من هر چه تلاش ‍ می کنم این خوی را از ایشان بگریم نمی توانم .\r\nفرمودند: آن خصلت ها که تو را ناراحت کرده کدامند؟\r\nگفت : اول این که ، هرگاه به یک دیگر می رسند سلام می کنند، و سلام یکی از نام های خداوند است . پس هر که سلام کند حق تعالی او را از هر بلا و رنجی دور می کند. و هر که جواب سلام دهد، خداوند متعال رحمت خود را شامل حال او می گرداند. \r\nدوم این که ، وقتی با هم ملاقات کنند به هم دست می دهند. و آن را چندان ثواب است که هنوز دست از یک دیگر برنداشته حق تعالی هر دو را رحمت می کند. \r\nسوم ، وقت غذا خوردن و شروع کارها بسم الله می گویند و مرا از خوردن آن طعام و شرکت در آن دور می کنند. \r\nچهارم ، هر وقت سخن می گویند: ان شاءالله بر زبان می آورند و به قضای خداوند راضی می شوند و من نمی توانم کار آنها را از هم بپاشم ، آنان رنج و رحمت مرا ضایع می کنند.\r\nپنجم ، از صبح تا شام تلاش می کنم تا اینان را به معصیت بکشانم . باز چون شام می شود، توبه می کنند و زحمات مرا از بین می برند و خداوند به این وسیله گناهان آنان را می آمرزد. \r\nششم ، از همه این ها مهم تر این است که وقتی نام تو را می شنوند با صدای بلند صلوات می فرستند و من چون صواب صلوات را می دانم ، از ناراحتی فرار می کنم ؛ زیرا طاقت دیدن ثواب آن را ندارم . \r\nهفتم : ایشان وقتی اهل بیت تو را می بینند، به ایشان مهر می ورزند و این بهترین اعمال است . \r\nپس حضرت روی به اصحاب کرده و فرمودند: هر کس ‍ یکی از این خصلت ها را داشته باشد از اهل \r\nبهشت است.\r\n"},{"id":814,"category_id":6,"category_code":"s6","source_id":322,"title":"ناکامی شیطان","content":"روزي حضرت موسي براي مناجات به كوه طور مي رفت و شيطان هم در پي او رفت. يكي از فرشتگان شيطان را نهيب زد و گفت: از دنبال موسي برگرد كه او كليم خداست مگر اميد داري كه بتواني او را بفريبي؟ شيطان گفت: آري. چنان كه پدر او حضرت آدم را به خوردن گندم فريفتم از موسي هم اميد دارم كه چنين شود حضرت موسي متوجه شد .\r\nشيطان گفت: اي موسي كليم مي خواهي تو را شش پند بياموزم؟ حضرت موسي فرمود: خير. من احتياج ندارم از من دور شو. جبرئيل نازل شد و گفت: ای موسی صبر کن و گوش بده ، او الان نمیخواهد که تو را فریب دهد . موسی ایستاد و فرمود هر چه میخواهی بگو ،شيطان گفت: آن شش پند اين است: \r\nاول : در وقت دادن صدقه به يادم باش و زود صدقه بده كه ممكن است زود پشيمانت كنم گرچه آن صدقه كم و كوچك باشد چون ممكن است همان صدقه كم تو را از هلاكت نجات دهد و از خطر حفظ نمايد.\r\nدوم : اي موسي با زن بيگانه و نامحرم خلوت نكن چون در آن صورت من نفر سوم هستم و تو را فريفته و به فتنه مي اندازم و وادار به زنا مي كنم. \r\nسوم : اي موسي در حال غضب به يادم باش زيرا در حال غضب تو را به امر خلاف وادار مي نمايم و آرزو مي كنم كه اولاد آدم غضب كند تا من مقصودم را عملي سازم.\r\nچهارم : چيزهايي كه خداوند ازآنها نهي كرده نزديك نشو چون هر كس به آنها نزديك شود من او را به حرام و گناه مي اندازم. \r\nپنجم : در دل خود فكر گناه وكار خلاف راه مده چون اگر من دلي را چرکین ديدم به طرف صاحبش دست دراز میکنم و او را اغوا میکنم ، تا آن کار خلاف را انجام دهد . \r\nششم :تا خواست كه ششم را بگويد جبرئيل حضرت موسي(ع) را نهيب زد و فرمود: اي موسي حركت كن و گوش مده كه او مي خواهد در نصيحت ششم تو را بفريبد. لذا موسي حركت كرد و رفت. شيطان فرياد زد و گفت: واي بر من پنج موعظه را كه اساس كارم در آنها بود شنيد و رفت مي ترسم كه آنها را به ديگران بگويد و آنان هدايت شوند. من مي خواستم پس از پنج کلمه حق ، او را به دام اندازم و او و ديگران را فريب دهم ولي از دستم رفت.\r\n"},{"id":815,"category_id":6,"category_code":"s6","source_id":323,"title":"در جستجوی خدا","content":"كودك نجوا كرد: « خدایا با من صحبت كن » و یك چكاوك آواز خواند، ولی كودك نشنید. پس كودك با صدای بلند گفت : « خدایا با من صحبت كن » و آذرخش در آسمان غرید، ولی كودك متوجه نشد. كودك فریاد زد: « خدایا یك معجزه به من نشان بده » و یك زندگی متولد شد، ولی كودك نفهمید. كودك ناامیدانه گریه كرد و گفت: « خدایا مرا لمس كن و بگذار تو را بشناسم »، پس خدا نزد كودك آمد و او را لمس كرد. ولی كودك بالهای پروانه را شكست و در حالی كه خدا را درك نكرده بود از آنجا دور شد!"},{"id":816,"category_id":6,"category_code":"s6","source_id":324,"title":"جواب خدا","content":"روزی مردی خواب عجیبی دید. دید که پیش فرشته هاست و به کارهای آن ها نگاه می کند. هنگام ورود ، دسته بزرگی از فرشتگان را دید که سخت مشغول کارند و تند تند نامه هایی را که توسط پیک ها از زمین می رسند ، باز می کنند و آنها را داخل جعبه می گذارند. مرد از فرشته ای پرسید: شما چه کار می کنید؟\r\nفرشته در حالی که داشت نامه ای را باز می کرد ، گفت: اینجا بخش دریافت است و ما دعا ها و تقاضاهای مردم از خداوند را تحویل می گیریم. \r\nمرد کمی جلوتر رفت و باز تعدادی از فرشتگان را دید که کاغذهایی را داخل پاکت می گذارند و آن ها را توسط پیک هایی به زمین می فرستند. مرد پرسید: شماها چه کا رمی کنید؟یکی از فرشتگان با عجله گفت:اینجا بخش ارسال است. ما الطاف و رحمت های خداوند را برای بندگان به زمین می فرستیم. مرد کمی جلوتر رفت و یک فرشته را دید که بیکار نشسته است. مرد با تعجب از فرشته پرسید: شما چرا بیکارید؟ فرشته گفت: اینجا بخش تصدیق است. مردمی که دعاهایشان مستجاب شده ، باید جواب بفرستند ولی فقط عده بسیار کمی جواب می هند. مرد از فرشته پرسید: مردم چگونه می توانند جواب بفرستند؟ فرشته پاسخ داد: بسیار ساده است فقط کافیست بگویند: خدایا شکر !\r\n"},{"id":817,"category_id":6,"category_code":"s6","source_id":325,"title":"جهنمی یا بهشتی ؟","content":"فردی از پروردگار در خواست کرد تا به او بهشت و جهنم را نشان دهد خداوند پذیرفت او را وارد اتاقی نمود که جمعی از مردم در اطراف دیگ بزرگ غذا نشسته بودند همه گرسنه نا امید و در عذاب بودند هر کدام قاشقی داشت که به دیگ می رسید ولی دسته قاشقها بلند تر از بازوی آنها بود به طوری که نمی توانستند قاشق را به دهانشان برسانند عذاب آنها وحشتناک بود !\r\nآنگاه خداوند گفت :اکنون بهشت را به تو نشان می دهم و او به اتاق دیگری که درست مانند اولی بود وارد شد دیگ غذا ... جمعی از مردم ... همان قاشقهای دسته بلند ... ولی در آنجا همه شاد و سیر بودند آن مرد گفت : نمی فهمم !!!\r\nچرا مردم اینجا شادند در حالی که در اتاق دیگر بد بختند؟ با آنکه همه چیزشان یکسان است؟\r\nخداوند تبسمی کرد و گفت :خیلی ساده است در اینجا آنها یاد گرفته اند که یکدیگر را تغذیه کنند و هر کسی با قاشقش غذا در دهان دیگری می گذارد چون ایمان دارد که کسی هست که در دهانش غذایی بگذارد.\r\n"},{"id":818,"category_id":6,"category_code":"s6","source_id":326,"title":"معنای توکل","content":"\r\nکشیش سوار هواپیما شد. کنفرانسی تازه به پایان رسیده بود و او می‎رفت تا در کنفرانس دیگری شرکت کند؛ می‎رفت تا خلق خدا را هدایت کند و به سوی خدا بخواند و به رحمت الهی امیدوار سازد. در جای خویش قرار گرفت. اندکی گذشت، ابری آسمان را پوشانده بود، اما زیاد جدی به نظر نمی‎رسید. مسافران شادمان بودند که سفرشان به زودی شروع خواهد شد.\r\nهواپیما از زمین برخاست. اندکی بعد، مسافران کمربندها را گشودند تا کمی بیاسایند. پاسی گذشت. همه به گفتگو مشغول؛ کشیش در دریای اندیشه غوطه‌ور که در جمع بعد چه‎ها باید گفت و چگونه بر مردم تأثیر باید گذاشت. ناگاه، چراغ بالای سرش روشن شد: «کمربندها را ببندید!» همه با اکراه کمربندها را بستند؛ اما زیاد موضوع را جدی نگرفتند. اندکی بعد، صدای ظریفی از بلندگو به گوش رسید،«از دادن نوشابه فعلاً معذوریم؛ طوفان در پیش است»\r\nموجی از نگرانی به دلها راه یافت، اما همانجا جا خوش کرد و در چهره‌ها اثری ظاهر نشد، گویی همه می‌کوشیدند خود را آرام نشان دهند. باز هم کمی گذشت و صدای ظریف دیگربار بلند شد، «با پوزش فعلاً غذا داده نمی‌شود؛ طوفان در راه است و شدت دارد». نگرانی، چون دریایی که بادی سهمگین به آن یورش برده باشد، از درون دل ها به چهره‌ها راه یافت و آثارش اندک اندک نمایان شد.\r\nطوفان شروع شد؛ صاعقه درخشید، نعره رعد برخاست و صدای موتورهای هواپیما را در غرش خود محو و نابود ساخت؛ کشیش نیک نگریست؛ بعضی دستها به دعا برداشته شد؛ اما سکوتی مرگبار بر تمام هواپیما سایه افکنده بود؛ طولی نکشید که هواپیما همانند چوب‎پنبه بر روی دریایی خروشان بالا رفت و دیگر بار فرود افتاد، گویی هم‌اکنون به زمین برخورد می‎کند و از هم متلاشی می‎گردد. کشیش نیز نگران شد؛ اضطراب به جانش چنگ انداخت؛ از آن همه که برای گفتن به مردم در ذهن اندوخته بود، هیچ باقی نماند؛ گویی حبابی بود که به نوک خارک ترکیده بود؛ پنداری خود کشیش هم به آنچه که می‌خواست بگوید ایمانی نداشت. سعی کرد اضطراب را از خود برهاند؛ اما سودی نداشت. همه آشفته بودند و نگران رسیدن به مقصد و از خویش پرسان که آیا از این سفر جان به سلامت به در خواهند برد؟!\r\nنگاهی به دیگران انداخت؛ نبود کسی که نگران نباشد و به گونه‎ای دست به دامن خدا نشده باشد.\r\nناگاه نگاهش به دخترکی افتاد خردسال؛ آرام و بی‎صدا نشسته بود و کتابش را می‌خواند؛ یک پایش را جمع کرده، زیر خود قرار داده بود. ابداً اضطراب در دنیای او راه نداشت؛ آرام و آسوده‌خاطر نشسته بود.\r\nگاهی چشمانش را می‎بست، و سپس می‎گشود و دیگربار به خواندن ادامه می‎داد. پاهایش را دراز کرد، اندکی خود را کش و قوس داد، گویی می‎خواهد خستگی سفر را از تن براند؛ دیگربار به خواندن کتاب پرداخت؛ آرامشی زیبا چهره‌اش را در خود فرو برده بود.\r\nهواپیما زیر ضربات طوفان مبارزه می‎کرد، گویی طوفان مشت‎های گره کرده ی خود را به بدنه هواپیما می‎کوفت، یا می‎خواست مسافران را که مشتاق زمین سفت و محکمی در زیر پای بودند، بترساند. هواپیما را چون توپی به بالا پرتاب می‎کرد و دیگربار فرود می‎آورد. اما این همه در آن دخترک خردسال هیچ تأثیری نداشت، گویی در گهواره نشسته و آرام تکان می‎خورد و در آن آرامش بی‎مانند به خواندن کتابش ادامه می‎داد…\r\nکشیش ابداً نمی‎توانست باور کند؛ در جایی که هیچیک از بزرگسالان از امواج ترس در امان نبود، او چگونه می‎توانست چنین ساکن و خاموش بماند و آرامش خویش حفظ کند. بالاخره هواپیما از چنگ طوفان رها شد، به مقصد رسید، فرود آمد.\r\nمسافران، گویی با فرار از هواپیما از طوفان می‎گریزند، شتابان هواپیما را ترک کردند، اما کشیش همچنان بر جای خویش نشست. او می‎خواست راز این آرامش را بداند. همه رفتند؛ او ماند و دخترک. کشیش به او نزدیک شد و از طوفان سخن گفت و هواپیما که چون توپی روی امواج حرکت می‌کرد.\r\nسپس از آرامش او پرسید و سببش؛ سؤال کرد که چرا هراس را در دلش راهی نبود آنگاه که همه هراسان بودند…؟!\r\nدخترک به سادگی جواب داد : چون پدرم خلبان بود؛ او داشت مرا به خانه می‎برد؛ اطمینان داشتم که هیچ نخواهد شد و او مرا در میان این طوفان به سلامت به مقصد خواهد رساند؛ ما عازم خانه بودیم؛ پدرم مراقب بود؛ او خلبان ماهری است.\r\nجواب دخترک گویی آب سردی بود بر بدن کشیش؛ سخن از اطمینان گفتن و خود به آن ایمان داشتن؛ این است راز آرامش و فراغت از اضطراب!!\r\n‏توکلت علی الله – توکل بر خدا - یعنی همین! ؛ ایمان قلبی به خدا و این که هرگز جز لطف به بنده روا نمی دارد. هرچه او برای بنده اش بخواهد حتما همان بهترین است!!!!!\r\n"},{"id":819,"category_id":6,"category_code":"s6","source_id":327,"title":"ایمان واقعی","content":"روزی بازرگان موفقی از مسافرت بازگشت و متوجه شد خانه و مغازه اش در غیاب او آتش گرفته و کالا های گرانبهایش همه سوخته و خاکستر شده اند و خسارت هنگفتی به او وارد امده است .\r\nفکر می کنید آن مرد چه کرد؟! خدا را مقصر شمرد و ملامت کرد؟ و یا اشک ریخت ؟\r\nاو با لبخندی بر لبان و نوری بر دیدگان سر به سوی آسمان بلند کرد و گفت : \"خدایا ! می خواهی که اکنون چه کنم؟\"\r\nمرد تاجر پس از نابودی کسب پر رونق خود ، تابلویی بر ویرانه های خانه و مغازه اش آویخت که روی آن نوشته بود : مغازه ام سوخت ! اما ایمانم نسوخته است ! فردا شروع به کار خواهم کرد!\r\n"},{"id":820,"category_id":6,"category_code":"s6","source_id":328,"title":"طلبه و دختر فراری","content":"شب طلبه جوانی به نام محمد باقر در اتاق خود در حوزه علمیه مشغول مطالعه بود به ناگاه دختری وارد اتاق او شد در را بست و با انگشت به طلبه بیچاره اشاره کرد که ساکت باشد. دختر گفت: شام چه داری؟ طلبه آنچه را که حاضر کرده بود آورد و سپس دختر در گوشه ای از اتاق خوابید و محمد به مطالعه خود ادامه داد. \r\nاز آن طرف چون این دختر فراری شاهزاده بود و بخاطر اختلاف با زنان دیگر از حرمسرا فرار کرده بود لذا شاه دستور داده بود تا افرادش شهر را بگردند ولی هر چه گشتند پیدایش نکردند. \r\nصبح که دختر از خواب بیدار شد و از اتاق خارج شد ماموران شاهزاده خانم را همراه محمد باقر به نزد شاه بردند شاه عصبانی پرسید چرا شب به ما اطلاع ندادی و ... . محمد باقر گفت: شاهزاده تهدید کرد که اگر به کسی خبر دهم مرا به دست جلاد خواهد داد. شاه دستور داد که تحقیق شود که آیا این جوان خطائی کرده یا نه؟ و بعد از تحقیق از محمد باقر پرسید چطور توانستی در برابر نفست مقاومت نمائی؟ محمد باقر 10 انگشت خود را نشان داد و شاه دید که تمام انگشتانش سوخته و ... . لذا علت را پرسید طلبه گفت: چون او به خواب رفت نفس اماره مرا وسوسه می نمود هر بار که نفسم وسوسه می کرد یکی از انگشتان را بر روی شعله سوزان شمع می گذاشتم تا طعم آتش جهنم را بچشم و بالاخره از سر شب تا صبح بدین وسیله با نفس مبارزه کردم و به فضل خدا، شیطان نتوانست مرا از راه راست منحرف کند و ایمان و شخصیتم را بسوزاند. \r\nشاه عباس از تقوا و پرهیز کاری او خوشش آمد و دستور داد همین شاهزاده را به عقد میر محمد باقر در آوردند و به او لقب میرداماد داد و امروزه تمام علم دوستان از وی به عظمت و نیکی یاد کرده و نام و یادش را گرامی می دارند. از مهمترین شاگران وی می توان به ملا صدرا اشاره نمود. \r\nنفس اماره یکی از عواملی است که انسان را به ارتکاب گناه وسوسه می کند. قران کریم می فرماید: نفس اماره به سوی بدیها امر می کند مگر در مواردی که پروردگار رحم کند «سوره یوسف آیه 53» انسانهایی که در چنین مواردی به خدا پناه میبرند خداوند متعال آنها را از گزند نفس اماره حفط می کند و به جایگاه ارزشمندی می رساند .\r\n"},{"id":821,"category_id":6,"category_code":"s6","source_id":329,"title":"بزرگترین افتخار","content":"پسر کوچولو به مادر خود گفت : مادر داری به کجا می روی؟ مادر گفت:عزیزم بازیگری معروف که از محبوبیت زیادی برخوردار است به شهر ما آمده است.این طلایی ترین فرصتی است که می توانم او را ببینم وبا او حرف بزنم،خیلی زود برمیگردم. اگر او وقت آن را داشته باشد که با من حرف بزند چه محشری می شود.\r\nو در حالی که لبخندی حاکی از شادی به لب داشت با فرزندش خداحافظی کرد....\r\nحدود نیم ساعت بعد مادرش با عصبانیت به خانه برگشت. پسر به مادرش گفت:مادر چرا چهره ی پریشانی داری؟ آیا بازیگر محبوبت را ملاقات کردی؟\r\nمادر با لحنی از خستگی و عصبانیت گفت:من و جمعیت زیادی از مردم بسیار منتظر ماندیم اما به ما خبر رساندند که او نیم ساعت است که این شهر را ترک کرده است.ای کاش خدا شهرت و محبوبیتی را که به این بازیگر داده است به ما داده بود.\r\nکودک پس از شنیدن حرف های مادر به اتاق خود رفت ولباس های خود رابیرون آورد و گفت:مادر آماده شو با هم به جایی برویم من می توانم این آرزوی تو را برآورده کنم.\r\nاما مادر اعتنایی نکرد و گفت:این شوخی ها چیست او بیش از نیم ساعت است که این شهر را ترک کرده است. حرف های تو چه معنی ای میدهد؟\r\nپسر ملتمسانه گفت:مادرم خواهش می کنم به من اعتماد کن،فقط با من بیا.\r\nمادر نیز علیرغم میل باطنی خود درخواست فرزند خود را پذیرفت زیرا او را بسیار دوست می داشت. بنابراین آن دو به بیرون از خانه رفتند. پس از چندی قدم زدن پسر به مادرش گفت:رسیدیم.\r\nدر حالی که به مسجد بزرگ شهر اشاره می کرد. مادر که از این کار فرزندش بسیار دلخور شده بود با صدایی پر از خشم گفت:من به تو گفتم که الان وقت شوخی نیست. این رفتار تو اصلا زیبا نبود.\r\nکودک جواب داد:مادر تو در سخنان خود دقیقا این جمله را گفتی که ای کاش خدا شهرتی و محبوبیتی را که به این بازیگر داده است به ما داده بود پس آیا افتخاری از این بزرگ تر است که با کسی که این شهرت و محبوبیت را داده است نه آن کسی که آن را دریافت کرده است حرف بزنی؟ آیا سخن گفتن با خدا لذت بخش تر از آن نیست که با آن بازیگر محبوب حرف بزنی؟ وقتی خدا همیشه در دسترس ماست پس چه نیاز به بنده ی خدا...\r\n"},{"id":822,"category_id":6,"category_code":"s6","source_id":330,"title":"کرم شب تاب","content":"روز قسمت بود. خدا هستی را قسمت می كرد. خدا گفت : چیزی از من بخواهید. هر چه كه باشد‚ شما را خواهم داد. سهمتان را از هستی طلب كنید زیرا خدا بسیار بخشنده است. و هر كه آمد چیزی خواست. یكی بالی برای پریدن و دیگری پایی برای دویدن. یكی جثه ای بزرگ خواست و آن یكی چشمانی تیز. یكی دریا را انتخاب كرد و یكی آسمان را. \r\nدر این میان كرمی كوچك جلو آمد و به خدا گفت : من چیز زیادی از این هستی نمی خواهم. نه چشمانی تیز و نه جثه ای بزرگ. نه بالی و نه پایی ‚ نه آسمان ونه دریا. تنها كمی از خودت‚ تنها كمی از خودت را به من بده. و خدا كمی نور به او داد. نام او كرم شب تاب شد.\r\nخدا گفت : آن كه نوری با خود دارد‚ بزرگ است‚ حتی اگربه قدر ذره ای باشد. تو حالا همان خورشیدی كه گاهی زیر برگی كوچك پنهان می شوی. و رو به دیگران گفت : كاش می دانستید كه این كرم كوچك ‚ بهترین را خواست. زیرا كه از خدا جز خدا نباید خواست.\r\nهزاران سال است كه او می تابد. روی دامن هستی می تابد. وقتی ستاره ای نیست چراغ كرم شب تاب روشن است و كسی نمی داند كه این همان چراغی است كه روزی خدا آن را به كرمی كوچك بخشیده است.\r\n"},{"id":823,"category_id":6,"category_code":"s6","source_id":331,"title":"موهبت الهی","content":"روزی مردی خواب دید که مرده و پس از گذشتن از پلی به دروازه بهشت رسیده است.\r\nدربان بهشت به مرد گفت: برای ورود به بهشت باید صد امتیاز داشته باشید، کارهای خوبی را که در دنیا انجام داده اید، بگوئید تا من به شما امتیاز بدهم. مرد گفت: من با همسرم ازدواج کردم، 50 سال با او به مهربانی رفتار کردم و هرگز به او خیانت نکردم.فرشته گفت: این سه امتیاز. \r\nمرد اضافه کرد: .... من در تمام طول عمرم به خداوند اعتقاد داشتم و حتی دیگران را هم به راه راست هدایت می کردم. فرشته گفت: این هم یک امتیاز. مرد باز ادامه داد: در شهر نوانخانه ای ساختم و کودکان بی خانمان را آنجا جمع کردم و به آنها کمک کردم. فرشته گفت: این هم دو امتیاز.\r\nمرد در حالی که گریه می کرد گفت: با این وضع من هرگز نمی توانم داخل بهشت شوم مگر اینکه خداوند لطفش را شامل حال من کند. فرشته لبخندی زد و گفت : بله، تنها راه ورود بشر به بهشت موهبت الهی است و اکنون این لطف شامل حال شما شد و اجازه ورود به بهشت برایتان صادر شد !\r\n"},{"id":824,"category_id":6,"category_code":"s6","source_id":332,"title":"قحطی و خشک سالی","content":"در سالی که قحطی بیداد کرده بود و مردم همه زانوی غم به بغل گرفته بودند مرد عارفی از کوچه ای می گذشت غلامی را دید که بسیار شادمان و خوشحال است .\r\nبه او گفت :چه طور در چنین وضعی می خندی و شادی می کنی ؟\r\nجواب داد که : من غلام اربابی هستم که چندین گله و رمه دارد و تا وقتی برای او کار می کنم روزی مرا می دهد پس چرا غمگین باشم در حالی که به او اعتماد دارم؟\r\nآن مرد عارف که از عرفای بزرگ ایران بود گفت: از خودم شرم کردم که غلام به اربابی با چند گوسفند توکل کرده و غم به دل راه نمی دهد و من خدایی دارم که مالک تمام دنیاست و نگران روزی خود هستم.\r\n"},{"id":825,"category_id":6,"category_code":"s6","source_id":333,"title":"آتش امید","content":"تنها بازمانده يك كشتي شكسته به جزيرهٌ كوچك خالي از سكنه اي افتاد. او با دلي لرزان دعا كرد كه خدا نجاتش دهد؛ اگر چه روزها افق را به دنبال ياري رساني از نظر مي گذراند؛ كسي نمي آمد. \r\nسر انجام خسته و از پا افتاده موفق شد از تخته پاره ها كلبه اي بسازد تا خود را از عوامل زيان بار محافظت كند و دارايي هاي اندكش را در آن نگه دارد. اما روزي كه براي جستجوي غذا بيرون رفته بود؛ به هنگام برگشتن ديد كه كلبه اش در حال سوختن است و دودي از آن به آسمان مي رود . متاسفانه بدترين اتفاق ممكن افتاده و همه چيز از دست رفته بود. از شدت خشم و اندوه در جا خشك اش زد. فرياد زد: ((خدايا چطور راضي شدي با من چنين كاري بكني؟))\r\nصبح روز بعد؛ با صداي بوق كشتي اي كه به ساحل نزديك مي شد از خواب پريد. كشتي اي آمده بود تا نجاتش دهد. مرد خسته؛ از نجات دهندگانش پرسيد: ((شماها از كجا فهميديد من در اينجا هستم؟ آن ها جواب دادند: ((ما متوجه علائمي كه با دود مي دادي شديم ))\r\nوقتي كه اوضاع خراب مي شود؛ نا اميد شدن آسان است. ولي ما نبايد دل مان را ببازيم؛ حتي در ميان درد و رنج؛ دست خدا در كار زندگيمان است.\r\nپس به ياد داشته باش دفعه ديگر اگر كلبه ات سوخت و خاكستر شد؛ ممكن است دودهاي برخاسته از آن علائمي باشد كه عظمت و بزرگي خدا را به كمك مي خواند.\r\n"},{"id":826,"category_id":6,"category_code":"s6","source_id":334,"title":"گنجشک و خدا","content":"روزها گذشت و گنجشك با خدا هیچ نگفت. فرشتگان سراغش را از خدا می گرفتند و خدا هر بار به فرشتگان این گونه می گفت : \" می آید. من تنها گوشی هستم كه غصه هایش را می شنود و یگانه قلبی ام كه دردهایش را در خود نگه می دارد. \" و سرانجام گنجشك روی شاخه ای از درخت دنیا نشست. فرشتگان چشم به لب هایش دوختند ، گنجشك هیچ نگفت و خدا لب به سخن گشود : \" با من بگو از آنچه سنگینی سینه توست ! \" گنجشك گفت : \" لانه كوچكی داشتم، آرامگاه خستگی هایم بود و سر پناه بی كسی ام. تو همان را هم از من گرفتی. این توفان بی موقع چه بود ؟ چه می خواستی از لانه محقرم،‌ كجای دنیا را گرفته بود ؟ \" و سنگینی بغضی راه بر كلامش بست. سكوتی در عرش طنین انداز شد. فرشتگان همه سر به زیر انداختند.خدا گفت : \" ماری در راه لانه ات بود. خواب بودی. باد را گفتم تا لانه ات را واژگون كند. آنگاه تو از كمین مار پر گشودی. \" گنجشك خیره در خدایی خدا مانده بود. خدا گفت : \" و چه بسیار بلاها كه به واسطه محبتم از تو دور كردم و تو ندانسته به دشمنی ام برخاستی...\" اشك در دیدگان گنجشك نشسته بود. ناگاه چیزی در درونش فرو ریخت. های های گریه هایش ملكوت خدا را پر كرد...!"},{"id":827,"category_id":6,"category_code":"s6","source_id":335,"title":"خدا هست ؟","content":"دانشجویی سر کلاس فلسفه نشسته بود. موضوع درس درباره خدا بود. استاد پرسید: آیا در این کلاس کسی هست که صدای خدا را شنیده باشد؟ کسی پاسخ نداد. استاد دوباره پرسید: آیا در این کلاس کسی هست که خدا را لمس کرده باشد؟ دوباره کسی پاسخ نداد. استاد برای سومین بار پرسید: آیا در این کلاس کسی هست که خدا را دیده باشد؟ برای سومین بار هم کسی پاسخ نداد. استاد با قاطعیت گفت: با این وصف خدا وجود ندارد. \r\nدانشجو به هیچ روی با استدلال استاد موافق نبود و اجازه خواست تا صحبت کند. استاد پذیرفت. دانشجو از جایش برخواست و از همکلاسی هایش پرسید: آیا در این کلاس کسی هست که صدای مغز استاد را شنیده باشد؟ همه سکوت کردند.آیا در این کلاس کسی هست که مغز استاد را لمس کرده باشد؟ همچنان کسی چیزی نگفت.آیا در این کلاس کسی هست که مغز استاد را دیده باشد؟ وقتی برای سومین بار کسی پاسخی نداد، دانشجو چنین نتیجه گیری کرد که استادشان مغز ندارد.\r\n"},{"id":828,"category_id":6,"category_code":"s6","source_id":336,"title":"آیا شیطان وجود دارد ؟","content":"استاد دانشگاه با اين سوال ها شاگردانش را به چالش ذهني کشاند. آيا خدا هر چيزي که وجود دارد را خلق کرد؟ شاگردي با قاطعيت پاسخ داد: \"بله او خلق کرد\" استاد پرسيد: \"آيا خدا همه چيز را خلق کرد؟\" شاگرد پاسخ داد: \"بله آقا\"استاد گفت: \"اگر خدا همه چيز را خلق کرد، پس او شيطان را نيز خلق کرد. چون شيطان نيز وجود دارد و مطابق قانون که کردار ما نمايانگر ماست، خدا نيز شيطان است\"شاگرد آرام نشست و پاسخي نداد. استاد با رضايت از خودش خيال کرد بار ديگر توانست ثابت کند که عقيده به مذهب افسانه و خرافه اي بيش نيست. \r\nشاگرد ديگري دستش را بلند کرد و گفت: \"استاد ميتوانم از شما سوالي بپرسم؟\" استاد پاسخ داد: \"البته\" شاگرد ايستاد و پرسيد: \"استاد، سرما وجود دارد؟\"استاد پاسخ داد: \"اين چه سوالي است البته که وجود دارد. آيا تا کنون حسش نکرده اي؟ \" شاگردان به سوال مرد جوان خنديدند. مرد جوان گفت: \"در واقع آقا، سرما وجود ندارد. مطابق قانون فيزيک چيزي که ما از آن به سرما ياد مي کنيم در حقيقت نبودن گرماست. هر موجود يا شي را ميتوان مطالعه و آزمايش کرد وقتيکه انرژي داشته باشد يا آنرا انتقال دهد. و گرما چيزي است که باعث ميشود بدن يا هر شي انرژي را انتقال دهد يا آنرا دارا باشد. صفر مطلق نبود کامل گرماست. تمام مواد در اين درجه بدون حيات و بازده ميشوند. سرما وجود ندارد. اين کلمه را بشر براي اينکه از نبودن گرما توصيفي داشته باشد خلق کرد.\" \r\nشاگرد ادامه داد: \"استاد تاريکي وجود دارد؟\" استاد پاسخ داد: \"البته که وجود دارد\"شاگرد گفت: \"دوباره اشتباه کرديد آقا! تاريک هم وجود ندارد. تاريکي در حقيقت نبودن نور است. نور چيزي است که ميتوان آنرا مطالعه و آزمايش کرد. اما تاريکي را نميتوان. در واقع با استفاده از قانون نيوتن ميتوان نور را به رنگهاي مختلف شکست و طول موج هر رنگ را جداگانه مطالعه کرد. اما شما نمي توانيد تاريکي را اندازه بگيريد. يک پرتو بسيار کوچک نور دنيايي از تاريکي را مي شکند و آنرا روشن مي سازد. شما چطور مي توانيد تعيين کنيد که يک فضاي به خصوص چه ميزان تاريکي دارد؟ تنها کاري که مي کنيد اين است که ميزان وجود نور را در آن فضا اندازه بگيريد. درست است؟ تاريکي واژه اي است که بشر براي توصيف زماني که نور وجود ندارد بکار ببرد.\"\r\nدر آخر مرد جوان از استاد پرسيد: \"آقا، شيطان وجود دارد؟\" زياد مطمئن نبود. استاد پاسخ داد: \"البته همانطور که قبلا هم گفتم. ما او را هر روز مي بينيم. او هر روز در مثال هايي از رفتارهاي غير انساني بشر به همنوع خود ديده ميشود. او در جنايتها و خشونت هاي بي شماري که در سراسر دنيا اتفاق مي افتد وجود دارد. اينها نمايانگر هيچ چيزي به جز شيطان نيست.\"\r\nو آن شاگرد پاسخ داد: \"شيطان وجود ندارد آقا. يا حداقل در نوع خود وجود ندارد. شيطان را به سادگي ميتوان نبود خدا دانست. درست مثل تاريکي و سرما. کلمه اي که بشر خلق کرد تا توصيفي از نبود خدا داشته باشد. خدا شيطان را خلق نکرد. شيطان نتيجه آن چيزي است که وقتي بشر عشق به خدا را در قلب خودش حاضر نبيند. مثل سرما که وقتي اثري از گرما نيست خود به خود مي آيد و تاريک که در نبود نور مي آيد. نام آن مرد جوان آلبرت انيشتن بود .\r\n"},{"id":829,"category_id":6,"category_code":"s6","source_id":337,"title":"وجود خدا","content":"مردی برای اصلاح سر و صورتش به آرایشگاه رفت. در حال کار گفتگوی جالبی بین آنها در گرفت. آنها درباره موضوعات و مطالب مختلف صحبت کردند. وقتی به موضوع « خدا » رسیدند. \r\nآرایشگر گفت: من باور نمی کنم خدا وجود داشته باشد. مشتری پرسید: چرا باور نمی کنی؟ \r\nآرایشگر جواب داد: کافی است به خیابان بروی تا ببینی چرا خدا وجود ندارد. به من بگو، اگر خدا وجود داشت آیا این همه مریض می شدند؟ بچه های بی سرپرست پیدا می شد؟ اگر خدا وجود می داشت، نباید درد و رنجی وجود داشته باشد. نمی توانم خدای مهربانی را تصور کنم که اجازه می دهد این چیزها وجود داشته باشد. مشتری لحظه ای فکر کرد، اما جوابی نداد، چون نمی خواست جر و بحث کند. آرایشگر کارش را تمام کرد و مشتری از مغازه بیرون رفت. \r\nبه محض این که از آرایشگاه بیرون آمد، در خیابان مردی دید با موهای بلند و کثیف و به هم تابیده و ریش اصلاح نکرده. ظاهرش کثیف و ژولیده بود. مشتری برگشت و دوباره وارد آرایشگاه شد و به آرایشگر گفت: می دانی چیست، به نظر من آرایشگرها هم وجود ندارند. \r\nآرایشگر با تعجب گفت: چرا چنین حرفی می زنی؟ من این جا هستم، من آرایشگرم. من همین الان موهای تو را کوتاه کردم. مشتری با اعتراض گفت: نه! آرایشگرها وجود ندارند، چون اگر وجود داشتند، هیچ کس مثل مردی که آن بیرون است، با موهای بلند و کثیف و ریش اصلاح نکرده پیدا نمی شد. \r\nآرایشگر جواب داد: نه بابا، آرایشگرها وجود دارند! موضوع این است که مردم به ما مراجعه نمی کنند. \r\nمشتری تائید کرد: دقیقاً ! نکته همین است. خدا هم وجود دارد! فقط مردم به او مراجعه نمی کنند و دنبالش نمی گردند. برای همین است که این همه درد و رنج در دنیا وجود دارد.\r\n"},{"id":830,"category_id":6,"category_code":"s6","source_id":338,"title":"دزد و عارف","content":"دزدي وارد کلبه فقيرانه عارفي شد. اين کلبه درخارج شهر واقع شده بود عارف بيدار بود.. او جز يک پتو چيزي نداشت. او شب ها نيمي از پتو را زير خود مي انداخت ونيمي ديگر را روي خود مي کشيد روزها نيز بدن برهنه خويش را با آن مي پوشاند.عارف پير دزد را ديد و چشمان خود را بست ، مبادا دزد را شرمنده کرده باشد.\r\nآن دزد راهي دراز را آمده بود، به اميد آنکه چيزي نصيبش شود. اوبايد درفقري شديد بوده باشد، زيرا به خانه محقرانه اين پير عارف زده بود. عارف پتو را برسرکشيد و براي حال زار آن دزد و نداري خويش گريست.\r\n“خدايا چيزي در خانه من نيست و اين دزد بينوا بادست خالي و نااميد ازاين جا خواهد رفت. اگر او دوسه روز پيش مرا از تصميم خويش باخبر ساخته بود ، مي رفتم ، پولي قرض مي گرفتم، وبراي اين مردک بينوا روي تاقچه مي گذاشتم”\r\nآن عارف فرزانه نگران نبود که دزد اموال او را خواهد برد او نگران بود که چيزي در خور ندارد تا نصيب دزد شود و او را خوشحال کند. داخل خانه عارف تاريک بود . پيرمرد شمعي روشن کرد تا دزد بتواند در پرتو آن زمين نخورد و خانه را بهتر وارسي کند. استاد شمع را برد تا روي تاقچه بگذارد که ناگهان با دزد چهره به چهرهبرخورد کرد دزد بسيار ترسيده بود. او مي دانست که اين مرد مورد اعتماداهالي شهر است بنابر اين اگر به مردم موضوع دزدي او را بگويد همه باورخواهند کرد.\r\nاما آن پير عارف گفت:\r\nنترس آمده ام تا کمکت کنم داخل خانه تاريک است . وانگهي من سي سال استکه در اين خانه زندگي مي کنم و هنوز هيچ چيز در آن پيدا نکرده ام بيا با هم بگرديم اگر چيزي پيدا کرديم پنجاه پنجاه تقسيمش مي مي کنيم.\r\nالبته اگر تو راضي باشي. اگر هم خواستي مي توني همه اش را برداري زيرامن سالها گشته ام و چيزي پيدا نکرده ام. پس همه آن مال تو. بالاخره يابندهتو بودي. دل دزد نرم شد. استاد نه او را تحقير کرد نه سرزنش.\r\nدزد گفت: مرا ببخشيد استاد. نمي دانستم که اين خانه شماست و گرنه جسارت نمي کردم.\r\nعارف گفت: اما درست نيست که دست خالي از اين جابروي. من يک پتو دارم هوا دارد سرد مي شود لطف کن و اين پتو را از من قبول کن.\r\nاستاد عارف پتو را به دزد داد دزد از اينکه مي ديد در آن خانه چيزي جز پتووجود ندارد شگفت زده شد سعي کرد استاد را متقاعد کند تا پتو را نزد خود نگه دارد.\r\nاستادگفت: احساسات مرا بيش از اين جريحه دارنکن دفعه ديگر پيش از اين کهبه من سري بزني مرا خبر کن. اگر به چيزي خاص هم نياز داشتي بگو تا همان رابرايت آماده کنم تو مرا غافلگير و شرمنده کردي. مي دانم که اين پتوي کهنه ارزشي ندارد اما دلم نمي آيد تو را بادست خالي روانه کنم لطف کن وآن را ازمن بپذير .تا ابد ممنون تو خواهم بود .\r\nدزد گيج شده بود او نمي دانست چه کار کند . تا کنون به چنين آدمي برخوردنکرده بود. خم شد پاهاي استاد را بوسيد پتو را تا کرد و بيرون رفت.\r\nاو وزير و وکيل و فرماندار ديده بود ولي انسان نديده بود. پيش از انکه دزد از خانه بيرون رود استاد صدايش کرد و گفت:\r\nفراموش نکن که امشب مرا خوشحال کردي من همه عمرم را مثل يک گدا زندگي کرده ام. من چون چيزي نداشتم از لذت بخشيدن نيز محروم بوده ام اما امشب توبه من لذت بخشيدن را چشاندي ممنونم.\r\nهوا سرد شده بود . استادمي لرزيد. استاد نشست وشعري سرود:\r\nدلي دارم خواهان بخشيدن به همه چيز\r\nاما دستاني دارم به غايت تهي\r\nکسي به قصد تاراج سرمايه ام آمده بود\r\nخانه خالي بود و او بادلي شکسته باز گشت.\r\nاي ماه کاش امشب از آن من بودي ، تو را به دزد خانه ام مي\r\nبخشيدم.\r\n"}];
